-- Italian texts of the regional pack kalimdor_darnassus (content wave W01). The rules are in AzerothUnspoken_Kalimdor/Darnassus.lua.
local AU = AzerothUnspoken

AU:RegisterRegionalTexts("teldrassil", "itIT", "kalimdor_darnassus", [==[
	["dar.journey.arrival.01"] = {
		"esce dal bagliore del portale ai margini di Darnassus; il volo in ippogrifo laggiù sembra già appartenere a un altro giorno.",
		"attraversa il luccichio del portale di Rut'theran, sbattendo le palpebre, e si ritrova davanti la città distesa sotto le foglie.",
		"arriva in cima all'albero in un'onda di luce rosata, le gambe che ondeggiano ancora per il volo, e si sofferma sulle torri chiare.",
	},
	["dar.journey.arrival.02"] = {
		"Un ippogrifo fino alle radici, un portale fino alla chioma. Dal mare alla cima di un albero in un respiro, e la città che aspettava come se non ci fossero mai stati dubbi.",
		"Laggiù c'erano onde e salsedine. Quassù ci sono lanterne e foglie, e il volo sembra già un sogno raccontato da qualcun altro.",
		"Il volo è finito ai piedi dell'albero, ma il viaggio finisce solo qui, fra le terrazze bianche. La salita è stata la parte più breve.",
	},
	["dar.journey.arrival.03"] = {
		"Un volo, un portale, e alla banca devo comunque arrivarci a piedi.",
		"Ippogrifo, poi una porta luminosa, poi una bella passeggiata sotto le foglie. Darnassus te la devi guadagnare.",
		"Ce l'ho fatta. Lo stomaco è rimasto tra Rut'theran e qui; mi raggiungerà.",
	},
	["dar.journey.arrival.04"] = {
		"Giù dall'ippogrifo, attraverso il portale, e sotto i nostri rami. Perfino l'aria sa di casa.",
		"L'ippogrifo alle radici, il portale fino in cima. Casa è il silenzio che viene dopo le ali, con le foglie sopra la testa.",
	},
	["dar.journey.arrival.05"] = {
		"resta immobile un istante dopo la lunga salita, lasciando che la quiete di Darnassus e il suo scorrere d'acqua prendano il posto della corsa del volo.",
		"indugia accanto al portale, mentre il battito delle ali svanisce dalle orecchie e il mormorio dell'acqua ne prende il posto.",
	},
	["dar.journey.arrival.06"] = {
		"Un volo, un portale e una città in cima a un albero. Continuo ad aspettare che qualcuno mi dica che è uno scherzo per i forestieri.",
		"Ogni capitale che conosco ha una porta. Questa ha un ippogrifo, un anello luminoso e un mare di foglie.",
	},
	["dar.muse.calm.01"] = {
		"In questa città l'acqua scorre ovunque, lenta e limpida, e le lanterne vi si specchiano. Darnassus è quieta come un respiro trattenuto.",
		"Pietra chiara, specchi d'acqua immobili, lanterne viola tra i salici. Qui nessuno ha fretta; forse nessuno ha mai imparato.",
		"La città beve la luce delle foglie lassù e la restituisce più morbida. Mi accorgo di rallentare il passo senza averlo deciso.",
	},
	["dar.muse.distance.01"] = {
		"La banca è proprio lì, mi hanno detto. È stato un bel po' fa.",
		"Città splendida. Città immensa. Ho già detto immensa?",
		"Ho attraversato Darnassus da un capo all'altro. I miei stivali vorrebbero scambiare due parole con l'architetto.",
	},
	["dar.muse.druids.01"] = {
		"I druidi del Cenarion Enclave parlano di quest'albero come i guaritori parlano di un malato: con affetto, con prudenza, e mai davanti a lui.",
		"Mi è passata accanto una druida con foglie nei capelli e terra sulle mani, immersa in una discussione con qualcuno che non vedevo. Forse l'albero.",
	},
	["dar.muse.guest.01"] = {
		"I kaldorei sono alleati, ma anche stranieri. Nella loro città mi muovo con educazione, e mi fermo di continuo a guardare tutto a bocca aperta.",
		"Nemmeno un grido in tutto il mercato. Da dove vengo io, vorrebbe dire che è successo qualcosa di terribile.",
	},
	["dar.muse.home.01"] = {
		"Una città giovane su un albero giovane. Impariamo a viverci come impariamo a invecchiare: piano, e con un certo stupore.",
		"Tanto di ciò che eravamo se n'è andato con le foreste di un tempo. Ma a Darnassus le lanterne sono accese, e sono nostre.",
		"Su ogni terrazza sento parlare la nostra lingua, senza fretta, e qualcosa nel petto, teso da anni, si allenta un poco.",
	},
	["dar.muse.owls.01"] = {
		"alza lo sguardo verso un gufo appollaiato su un arco intagliato; il gufo ricambia, per nulla impressionato.",
		"sente un verso sommesso tra i rami sopra la città e si ferma a cercare il gufo, che a quanto pare osservava già da un pezzo.",
	},
	["dar.muse.sentinels.01"] = {
		"si fa da parte per una Sentinella in sella a un grande felino striato, le cui zampe non fanno alcun rumore sulla pietra della terrazza.",
		"osserva due Sentinelle passare di ronda, i glaive sulla schiena, parlando con la voce bassa di chi ha montato molte guardie.",
	},
	["dar.muse.temple.01"] = {
		"Dal Tempio della Luna viene un silenzio che non è vuoto. Le sacerdotesse di Elune ci si muovono dentro come in una veste.",
		"Le sacerdotesse di Elune camminano piano, e vicino al tempio anche gli stranieri abbassano la voce. Mi accorgo di volerlo anch'io.",
	},
	["dar.muse.trade.01"] = {
		"Anche le contrattazioni qui si fanno a mezza voce. Ho abbassato il tono per fare un'offerta e mi è sembrato comunque di essere scortese.",
		"Mercanti che non chiamano i passanti. Per pura abitudine continuo a controllare che il borsellino delle monete ci sia ancora.",
	},
	["dar.npc.banker.01"] = {
		"Tutto quello che possiedo, per favore. Pesa meno di quanto sembri, e le monete ancora meno.",
		"Vorrei lasciare le mie monete in un posto dove non debbano più attraversare questa città a piedi.",
	},
	["dar.npc.innkeeper.01"] = {
		"riceve dall'oste una parola gentile e un cenno verso un angolo tranquillo.",
		"saluta con un cenno l'oste, che risponde con un sorriso che non chiede nulla e promette un letto caldo.",
	},
	["dar.npc.trainer.01"] = {
		"Un maestro kaldorei. Secoli di pratica dietro ogni piccola correzione, e nemmeno una parola sprecata, come un vecchio albero che cresce senza fretta.",
		"Il maestro mi osserva come un vecchio albero osserverebbe un germoglio: con pazienza, e da molto in alto.",
	},
	["dar.quest.01"] = {
		"Fatto, e il grazie è arrivato con una voce così bassa che per poco non lo sentivo. A Darnassus vale come una festa.",
		"Un altro incarico chiuso. I kaldorei hanno la memoria lunga; ho idea che si ricorderanno anche di questo.",
		"Finito. La città va avanti calma come sempre, e forse ho dato una mano a tenerla così.",
	},
	["dar.quest.02"] = {
		"riceve la ricompensa con entrambe le mani, così come è stata offerta.",
		"china il capo davanti a chi aveva affidato l'incarico, e riceve in risposta lo stesso piccolo gesto.",
		"posa la prova del lavoro sulla pietra chiara della terrazza, poi si ritira nella quiete.",
	},
	["dar.quest.03"] = {
		"Fatto. E ora, se qualcuno conosce una scorciatoia per un posto qualsiasi di questa città, sono tutt'orecchi.",
		"Ecco. E mi è bastato attraversare la città solo tre volte.",
	},
	["dar.rest.01"] = {
		"lascia finalmente cadere le spalle, con il rumore dell'acqua corrente lì accanto.",
		"posa lo zaino, siede su una panca di legno chiaro e, per un po', non fa proprio niente.",
	},
	["dar.rest.inn.01"] = {
		"Una stanza bassa, luci morbide, profumo di erbe. A Darnassus perfino la locanda parla sottovoce.",
		"Finalmente un posto dove sedersi, e nemmeno una voce alta nella stanza. Potrei dormire una settimana.",
		"Al chiuso, lontano dalla luce verde. Il letto sembra cresciuto, più che fatto.",
	},
	["dar.ret.01"] = {
		"Gli stessi specchi d'acqua, le stesse lanterne viola, le stesse voci senza fretta. Darnassus non si è mossa di un passo dall'ultima volta; se qualcosa è cambiato, sono io.",
		"Mi ricordo di queste terrazze. La città di me non ricorda nulla, e la cosa, chissà perché, mi riposa.",
	},
	["dar.sub.enclave.01"] = {
		"Il Cenarion Enclave. Qui gli edifici sembrano cresciuti più che costruiti, radici comprese, e i druidi si parlano a colpi di pause.",
		"Le radici si arrampicano sui muri dell'Enclave, come se il luogo stesse ancora decidendo che forma prendere.",
	},
	["dar.sub.temple.01"] = {
		"passa sotto gli archi del Tempio della Luna, dove una luce pallida riposa sull'acqua ferma del pozzo.",
		"entra nel Tempio della Luna: il rumore della città si ferma sulla soglia, e restano solo passi leggeri e un'acqua che trattiene la luna.",
	},
	["dar.sub.trade.01"] = {
		"La terrazza dei mercanti. Banchi sotto i salici, monete che passano di mano senza un suono.",
		"Merci, monete, un prezzo onesto detto a bassa voce. Qui, sulla terrazza dei mercanti, Darnassus si avvicina più che altrove alla confusione.",
	},
	["dar.sub.warrior.01"] = {
		"La terrazza dei guerrieri. Perfino gli allenamenti qui sono eleganti. Povere lame, non è giusto.",
		"Ah, il cozzare delle lame d'allenamento. Allora in questa città qualcuno il rumore lo fa.",
	},
	["dar.wc.rain.01"] = {
		"guarda la pioggia punteggiare gli specchi d'acqua della città, ogni cerchio che si allarga finché non ne incontra un altro.",
		"alza il viso mentre la pioggia filtra lenta e leggera tra le grandi foglie, fino alla pietra chiara.",
		"ascolta la pioggia sussurrare sui ruscelli della città; Darnassus sembra appena accorgersene.",
	},
	["dar.greet.w02.01"] = {
		"Pace a te, sotto le foglie.",
		"Salute. Strade quiete e acqua limpida per te.",
	},
	["dar.muse.w02.01"] = {
		"Sopra la testa, foglie grandi come vele. Oltre di esse c'è il cielo, ma quaggiù il cielo è verde.",
		"Non avevo mai visto foglie così grandi. Quando il vento passa tra le fronde, la città intera si riempie di un suono simile a una marea lontana.",
	},
	["dar.muse.w02.02"] = {
		"Ho augurato buona giornata a una Sentinella. Ci ha riflettuto con cura, e credo ci stia riflettendo ancora.",
		"Qui tutti camminano come se avessero tutto il tempo del mondo. Alcuni ne hanno già visti passare diecimila anni.",
	},
	["dar.muse.w02.03"] = {
		"si ferma su un ponte curvo di legno chiaro e guarda la luce delle lanterne tremare sull'acqua di sotto.",
		"segue il sentiero lungo la riva del lago, dove i salici lasciano pendere i rami in un'acqua così limpida da sembrare assente.",
		"si ferma sulla riva, dove il riflesso delle torri bianche giace così immobile che ci si potrebbe camminare sopra.",
	},
	["dar.muse.w02.04"] = {
		"I kaldorei hanno costruito questa città in pochi anni, dopo aver perso tanto nella guerra. È bellissima, ed è nuovissima, e lo sanno.",
		"Dietro la calma di queste terrazze c'è un popolo intero che ha dovuto ricominciare da capo. Si vede dalla cura che mettono in ogni cosa.",
	},
	["dar.quest_complete.w02.01"] = {
		"Fatto. Il grazie è arrivato con un lungo sguardo, come se qualcuno stesse decidendo di ricordarsi di me.",
		"Finito. In una città dalla memoria così lunga, anche un piccolo favore può essere ricordato più a lungo di quanto immagini.",
	},
	["dar.quest_complete.w02.02"] = {
		"Tutto fatto. Lo dirò ai gufi: qui sembrano tenere loro i registri.",
		"Finito. Devo dirlo sottovoce? In questa città tutto il resto si dice sottovoce.",
	},
	["dar.weather_change.w02.01"] = {
		"alza gli occhi mentre le nuvole si diradano sopra la chioma dell'albero, e una luce più chiara scivola tra le foglie fino alle terrazze.",
		"si accorge che la luce verde della città si schiarisce di un tono mentre il cielo si apre, in alto, molto oltre le foglie.",
	},
	["dar.dawn.w05.001"] = {
		"guarda l'alba farsi strada tra le foglie, un raggio pallido alla volta, finché il lago non ne trattiene un po' di ciascuno.",
		"vede le lanterne impallidire contro l'alba che arriva, mentre le Sentinelle dell'ultimo turno cedono il posto a quelle fresche.",
		"sente gli uccelli della chioma cominciare prima che la luce raggiunga le terrazze: quassù l'alba comincia come un suono.",
	},
	["dar.dusk.w05.001"] = {
		"Il crepuscolo a Darnassus. Le lanterne in realtà non erano mai spente, e adesso semplicemente vincono.",
		"Al crepuscolo la luce sotto le foglie passa dal verde al viola, e la città sembra sistemarsi più comoda dentro se stessa.",
		"Il crepuscolo. Per i kaldorei è adesso che la giornata comincia davvero: sento la città svegliarsi proprio mentre io comincio a stancarmi.",
	},
	["dar.farewell.w05.001"] = {
		"Va' piano. I sentieri di qui custodiranno i tuoi passi.",
		"Buona strada giù dall'albero, e anche oltre.",
		"Passo leggero, e torna quassù quando la strada lo permette.",
	},
	["dar.farewell.w05.002"] = {
		"Addio. Prendi il portale, non la scorciatoia: la scorciatoia non esiste.",
		"Vai pure. Se trovi un modo più rapido per attraversare questa città, scrivimi.",
	},
	["dar.farewell.w05.003"] = {
		"Abbi cura di te, là fuori. La discesa è lunga, il ritorno ancora di più.",
		"Alla prossima. Mi troverai dalle parti dell'acqua, con ogni probabilità.",
	},
	["dar.greet.w05.001"] = {
		"Salve! Hai perso la strada, o stai solo ammirando il panorama? Qui sono permesse entrambe le cose.",
		"Ciao. Anche tu hai fatto il giro lungo per attraversare la città?",
		"Salute! Non è strano parlare ad alta voce in un posto così silenzioso?",
	},
	["dar.greet.w05.002"] = {
		"Che il tuo cammino qui sia lieve, e il tuo riposo lungo.",
		"Che questi rami ti accolgano.",
		"Salute a te, nella città della luna.",
	},
	["dar.jest.w05.001"] = {
		"Come capisci di essere a Darnassus da troppo tempo? Quando cominci a chiamare cento anni 'un attimo'.",
		"In questa città, 'arrivo subito' vuol dire la prossima stagione. Portati un libro.",
		"Un druido, una sacerdotessa e una Sentinella entrano nella locanda. Dopo un'ora, finalmente, qualcuno saluta.",
	},
	["dar.journey.w05.001"] = {
		"strizza gli occhi per scacciare il riverbero del portale e trova una Sentinella al margine del sentiero, che guarda già da questa parte.",
		"si allontana dal portale e incrocia lo sguardo fermo della Sentinella di guardia lì accanto, una che di arrivi ne ha visti parecchi.",
	},
	["dar.journey.w05.002"] = {
		"Le orecchie mi fischiano ancora per il portale. Un passo alle radici, quello dopo in cima alla chioma; il mio corpo non ha dato il consenso a niente di tutto questo.",
		"Laggiù, un tronco alto come una scogliera. Quassù, nemmeno un tronco in vista, solo sentieri e acqua. Le gambe non hanno ancora digerito una salita che non hanno mai fatto.",
		"Il portale si è preso la salita e in cambio mi ha lasciato un cerchio alla testa. Scambio onesto, direi.",
	},
	["dar.journey.w05.003"] = {
		"Ho ancora il sale della traversata nel mantello, e quassù, fra il muschio e i fiori, ha un odore fuori posto. Dagli un'ora.",
		"Il mare me lo sono portato dietro: sale sulle maniche, vento fra i capelli. Darnassus ci metterà poco a lavarmelo via.",
	},
	["dar.journey.w05.004"] = {
		"Qualcuno dica al portale che non avevo ancora finito di avere le vertigini per l'ippogrifo.",
		"Ali, e poi magia, per arrivare fin qui: tutte e due mi hanno rimescolato lo stomaco. Bella città, però.",
		"Prima le piume, poi le scintille. La prossima volta mi accontenterei di una banale scala.",
	},
	["dar.journey.w05.005"] = {
		"si toglie dalla spalla una piuma d'ippogrifo rimasta impigliata, la rigira una volta nella luce del portale e la lascia alla brezza.",
		"trova una lunga piuma del volo infilata in una cinghia e la mette via, piuttosto che lasciarla cadere su una pietra così pulita.",
	},
	["dar.journey.w05.006"] = {
		"Da Rut'theran l'albero è un muro di corteccia senza fine. Dalla chioma non si vede affatto. Forse è così che i kaldorei riescono a conviverci.",
		"Tutta quell'altezza sotto gli stivali, e a vederla restano solo un sentiero e una pozza. L'albero si nasconde meglio proprio a chi ci abita.",
		"Sotto questo sentiero, chissà dove, il tronco scende e scende fino al mare. Cerco di non pensarci, invano.",
	},
	["dar.journey.w05.007"] = {
		"Un volo lungo, e me lo sento tutto nella schiena, piuma per piuma. Arrivare in una città fatta per camminare è una piccola crudeltà.",
		"Un bel pezzo in sella, sopra acqua e foreste. Poi il portale, e adesso Darnassus che mi chiede di attraversarla su gambe convinte di volare ancora.",
	},
	["dar.journey.w05.008"] = {
		"esce dal portale nell'aria notturna di Darnassus, fresca e immobile, e aspetta che gli occhi imparino il buio.",
		"arriva di notte, con il bagliore del portale che svanisce alle spalle; davanti, la città è tutta luce violetta e la quiete di chi dorme o monta la guardia.",
		"arriva nel buio fra due lanterne, e per un attimo l'unica cosa nitida è l'anello del portale che si spegne alle sue spalle.",
	},
	["dar.journey.w05.009"] = {
		"L'alba, appena oltre il portale. La prima luce scende tra le foglie in lunghi fili, e la città comincia appena a muoversi.",
		"Arrivo insieme all'alba. Quassù il mattino viene piano, filtrato da un tetto di foglie, come se chiedesse il permesso.",
	},
	["dar.journey.w05.010"] = {
		"attraversa il portale ancora {g:bagnato|bagnata} dal volo, e scopre che sotto le grandi foglie la pioggia arriva solo a gocce lente e pesanti.",
		"si scrolla dal mantello la pioggia della traversata; qui, sotto la volta di foglie, cade più piano, una goccia alla volta sulla pietra chiara.",
	},
	["dar.journey.w05.011"] = {
		"Di nuovo dove c'è il mio focolare. Il portale ronza alle mie spalle, e i sentieri davanti conoscono i miei passi, anche se non lo ammetterebbero mai.",
		"Il posto che chiamo casa, o quello che più ci somiglia. La strada si tenga la sua polvere: io vado a sedermi accanto all'acqua a non fare proprio niente.",
	},
	["dar.journey.w05.012"] = {
		"Alle radici nessuno mi ha chiesto cosa venissi a fare. Quassù nemmeno, ma la domanda la sento in ogni sguardo senza fretta.",
		"Sono ospite nell'albero stesso dei kaldorei. Al portale sono stati cortesi; io lo sarò il doppio.",
	},
	["dar.journey.w05.013"] = {
		"Darnassus! Allora: banca, poi maestro, poi una panchina in riva al lago. In quest'ordine, piedi permettendo.",
		"Eccomi in cima al mondo. Be', in cima a un albero. Quasi uguale.",
	},
	["dar.journey.w05.014"] = {
		"lascia subito libero il passaggio del portale per chi arriverà dopo, e solo allora si guarda intorno.",
		"si scosta dal portale per semplice cortesia, mentre qualcun altro prende forma, scintillando, proprio dove un attimo prima c'era {g:lui|lei}.",
	},
	["dar.journey.w05.015"] = {
		"Gabbiani e moli che scricchiolano alle radici; quassù, un silenzio così fitto che sento i miei stessi stivali. Il portale scambia un mondo con un altro.",
		"Laggiù, le grida dei marinai e lo sciabordio delle onde. Qui, canto d'uccelli e acqua. È bastato un passo per fare cambio.",
		"Un passo, e l'odore di pece e di pesce sparisce: al suo posto, muschio e acqua ferma.",
	},
	["dar.journey.w05.016"] = {
		"Qualunque notizia porti dal continente può aspettare il tempo di attraversare questa città a piedi. I kaldorei non se la prenderanno: nessuno sa aspettare meglio di loro.",
		"Mi porto dietro la fretta del continente, e Darnassus, con garbo, si rifiuta di prenderla. Va bene. Avrò fretta più tardi.",
	},
	["dar.journey.w05.017"] = {
		"lancia un'ultima occhiata al portale, come per assicurarsi che ci sarà ancora per la discesa.",
		"si volta a guardare l'anello scintillante, misurandolo come si misura una porta prima di fidarsene una seconda volta.",
	},
	["dar.journey.w05.018"] = {
		"Al di là dell'acqua, la costa grigia di Darkshore e le sue rovine. Quassù è tutto curato, spazzato, illuminato. Difficile non sentire la distanza fra le due cose.",
		"Il continente che ho sorvolato è pieno di pietra elfica in frantumi. Qui la pietra è nuova e intera, e la gente ci cammina sopra come per non svegliare un vecchio dolore.",
		"Dietro di me e più in basso, una costa piena di ciò che i kaldorei hanno perduto. Davanti, ciò che hanno costruito da allora. Il portale sta proprio nel mezzo.",
	},
	["dar.journey.w05.019"] = {
		"Ci siamo tutti? Contate le teste: il portale non lo fa.",
		"Nessuno manca? Bene. Non disperdetevi: questa città è più grande di quanto sembri.",
	},
	["dar.journey.w05.020"] = {
		"Un popolo che misura la vita in secoli, eppure ai piedi del loro albero hanno messo un portale per risparmiarsi la salita. Anche i pazienti hanno un limite.",
		"Diecimila anni di pazienza, e comunque si sono costruiti una scorciatoia fino in cima. Me li rende più simpatici.",
		"Hanno visto imperi sorgere e affondare, eppure arrampicarsi su un albero tutti i giorni non gli andava. Gente assennata.",
	},
	["dar.journey.w05.021"] = {
		"china appena il capo verso la città mentre esce dal portale, una piccola cortesia per un luogo che sembra aspettarsela.",
		"si ferma sulla soglia di Darnassus e accenna un inchino, senza sapere bene a chi.",
	},
	["dar.journey.w05.022"] = {
		"Muschio, corteccia umida, una dolcezza a cui non so dare un nome. Un respiro di quest'aria, e quella della strada sembra presa in prestito.",
		"Il primo respiro di qua dal portale è verde. È l'unica parola che ho per dirlo.",
	},
	["dar.journey.w05.023"] = {
		"Bene. Da che parte è tutto quanto? Qui ogni sentiero curva con garbo lontano da dove voglio andare.",
		"Splendido. Ora, quale di questi sentieri tortuosi porta in un posto dove mi serve davvero andare?",
	},
	["dar.memory_return.w05.001"] = {
		"Torno a Darnassus, e i piedi trovano i sentieri prima della testa. Qualcosa di questo posto mi era rimasto addosso.",
		"Lo stesso silenzio, la stessa acqua sotto i passi. Avevo dimenticato quanto in fretta questa città mi rallenti, ed eccola che lo rifà.",
	},
	["dar.memory_return.w05.002"] = {
		"rientra a Darnassus con un po' più di cautela di prima, come se la calma del posto fosse qualcosa che si può rompere.",
		"torna in città con passo guardingo, anche se nulla, su queste terrazze quiete, sembra ricordare com'è finita la visita precedente.",
		"torna fra le terrazze chiare e lascia che l'immobilità si posi su qualunque cosa sia andata storta la volta prima.",
	},
	["dar.muse.w05.001"] = {
		"Ogni tanto scordo che qui sotto i piedi ho un ramo, e che sotto tutto questo muschio e questa pietra il mare è laggiù, lontanissimo.",
		"Erba, sentieri, un lago con le sue isolette. Bisogna fare uno sforzo per ricordarsi che sta tutto in cima a un albero.",
		"Darnassus ha i prati. Su un albero. Ho smesso di cercare di capirci qualcosa.",
	},
	["dar.muse.w05.002"] = {
		"Ogni tanto l'aria porta su un filo di salsedine dal mare che bagna le radici. Mi ricorda che tutta la città è un'isola sopra un'isola.",
		"Un odore di sale, tenue e fuori posto tra le foglie. Il mare è ancora laggiù, tutto intorno a Teldrassil, ad aspettare ai piedi dell'albero.",
		"Quando l'aria gira nel verso giusto sento il mare, sale e freddo, salito lungo tutto il tronco fin quassù a cercarmi.",
	},
	["dar.muse.w05.003"] = {
		"A Darnassus nessun mago appende un'insegna. I kaldorei ricordano quanto è costato loro l'arcano, un tempo, e hanno avuto diecimila anni per pensarci.",
		"Chiedi a Darnassus dove si studia l'arcano e ricevi un lungo silenzio cortese. Qualunque cosa sia toccata a questo popolo nei tempi antichi, la magia ne era il cuore, e non l'hanno dimenticato.",
		"Archi, lame, erbe, i riti del tempio: Darnassus insegna tutto questo. I libri di incantesimi bisogna cercarseli altrove, e qui nessuno se ne dispiacerà.",
	},
	["dar.muse.w05.004"] = {
		"I druidi parlano ancora di Malfurion Stormrage come se fosse appena uscito dalla stanza. Lui sogna chissà dove, e intanto Fandral Staghelm gli tiene calda la sedia.",
		"Il loro druido più grande dorme nel Sogno, dicono, e da parecchio tempo. Al Cenarion Enclave, quando pronunciano il suo nome, abbassano la voce come si fa accanto a chi dorme.",
		"Ora è Fandral Staghelm a guidare i druidi, nella lunga assenza del loro maestro. Il suo nome lo pronunciano con rispetto; quello di Malfurion con nostalgia.",
	},
	["dar.muse.w05.005"] = {
		"Per secoli i druidi hanno dormito e le Sentinelle hanno vegliato da sole sulle foreste. Lo si vede da come stanno di guardia: come chi non si è mai aspettato che lo facesse qualcun altro.",
		"Le donne in armatura che si vedono a ogni angolo montano la guardia da prima che la maggior parte dei regni avesse un nome. Non sembrano stanche. Sembrano abituate.",
		"Le Sentinelle non sembrano riposare mai: si danno soltanto il cambio. Non ne ho ancora vista una sedersi.",
	},
	["dar.muse.w05.006"] = {
		"guarda un grosso felino scuro salire i gradini dell'Enclave e, in cima, alzarsi in piedi trasformato in un'elfa che si spolvera le maniche.",
		"si scansa per lasciar passare un felino di gran fretta, poi si volta giusto in tempo per vederlo scrollarsi e diventare un druido a metà del sentiero.",
		"vede un orso uscire dal Cenarion Enclave con passo pesante, sedersi sull'erba e diventare un vecchio druido che si massaggia le ginocchia.",
	},
	["dar.muse.w05.007"] = {
		"vede una sagoma grigia e liscia scivolare nel lago, riaffiorare vicino alla riva e uscire dall'acqua su due gambe, strizzandosi una lunga treccia.",
		"osserva una specie di foca bucare la superficie del lago, guardarsi intorno e trasformarsi in un druido che se ne va gocciolando, come se niente fosse.",
	},
	["dar.muse.w05.008"] = {
		"Un druido ha appena provato a entrare in banca in forma d'orso. Ha vinto la porta.",
		"Regola dell'Enclave, immagino: niente orsi al chiuso. Qualcuno l'ha dovuto imparare a sue spese.",
	},
	["dar.muse.w05.009"] = {
		"Dalla Warrior's Terrace arriva il colpo secco delle frecce nei bersagli di paglia, uno dopo l'altro, quasi senza respiro in mezzo. Sembra che lassù nessuno sbagli.",
		"Gli arcieri sulla terrazza tirano, vanno a riprendersi le frecce, tornano indietro e tirano ancora. Lo fanno da così tanto che il gesto sembra un respiro.",
		"Toc, toc, toc: frecce che si piantano in un bersaglio, più su del sentiero. Esercizio paziente, l'unico che resta.",
	},
	["dar.muse.w05.010"] = {
		"C'è l'orso di un cacciatore che dorme di traverso sul sentiero, e tutta la città gli gira intorno con educazione.",
		"Metà degli animali di questa città sono più grossi dei padroni. E più curati.",
		"Un felino grosso come un pony mi ha dato un'annusata e ha deciso che non sono cibo. Lo prendo come un benvenuto.",
	},
	["dar.muse.w05.011"] = {
		"Alla casa d'aste di qui la gente fa offerte come se avesse un secolo per aspettare che il prezzo scenda. Alcuni ce l'hanno davvero.",
		"Una compratrice kaldorei alla casa d'aste ha guardato a lungo lo stesso mantello, ha annuito e se n'è andata. Sospetto che tornerà la prossima stagione.",
		"I prezzi della casa d'aste di qui si muovono come cresce l'albero: piano, e in una direzione con cui nessuno può discutere.",
	},
	["dar.muse.w05.012"] = {
		"I miei risparmi sono custoditi dentro un albero. Mi assicurano che è il posto più sicuro di Kalimdor.",
		"Le monete in una cassaforte, la cassaforte in un albero, l'albero in mezzo al mare. Questa banca non la rapina nessuno in fretta.",
		"Se un giorno la banca perde la mia roba, dovrò prendermela con un albero.",
	},
	["dar.muse.w05.013"] = {
		"Mi è caduta una padella. Si sono girati tutti gli elfi della terrazza. Forse dovrò lasciare la città.",
		"Ho starnutito sul ponte. Una Sentinella mi ha lanciato un'occhiata come se avessi suonato un corno di guerra.",
		"Ho riso forte sulla terrazza. Un gufo se n'è andato.",
	},
	["dar.muse.w05.014"] = {
		"I kaldorei: gli ultimi arrivati nell'Alleanza, e di gran lunga il popolo più vecchio che ci sia dentro.",
		"Stormwind firma trattati. Darnassus ricorda il mondo di prima, quando non c'era niente da firmare.",
	},
	["dar.muse.w05.015"] = {
		"Mentre la città sonnecchia accanto alle sue vasche, in Ashenvale le Sentinelle guardano le asce degli orchi mordere gli alberi antichi. La pace di qui si paga altrove.",
		"A Darnassus nessuno parla di Ashenvale a tavola, ma ogni Sentinella che incrocio potrebbe essere in partenza per laggiù. La guerra con i Warsong non si allontana mai dai loro volti.",
		"Le Sentinelle ferite salgono sull'albero a guarire e ridiscendono troppo presto. Ashenvale continua a chiamarle, una dopo l'altra.",
	},
	["dar.muse.w05.016"] = {
		"I druidi dicono che Teldrassil è cresciuto in fretta, molto in fretta. Alcuni lo dicono come si loda un bambino; qualcuno come si accenna a una febbre.",
		"Chiedi a un druido quanti anni ha Teldrassil e la risposta è orgogliosa. Chiedi come abbia fatto a crescere così presto e ricevi una pausa, e poi si cambia discorso.",
	},
	["dar.muse.w05.017"] = {
		"In una città così silenziosa i miei pensieri sembrano gridare. Non sapevo di portarmene dietro tanti.",
		"Qui non c'è rumore dietro cui nascondersi. Ogni preoccupazione che ho trascinato fin quassù mi siede accanto sulla panchina.",
		"Darnassus non copre niente. Qualunque cosa abbia portato con me, mi toccherà ascoltarla.",
	},
	["dar.muse.w05.018"] = {
		"percorre la lunga curva della terrazza e si accorge che i suoi passi non fanno alcuna eco, come se il legno vivo li inghiottisse.",
		"ascolta i propri passi sul sentiero e non sente quasi nulla: la città accoglie ogni suono e non ne restituisce nessuno.",
	},
	["dar.muse.w05.019"] = {
		"Dal portale in poi non ho visto una sola linea dritta. I tetti si arricciano, i sentieri girano, perfino le ringhiere sembrano cresciute così per abitudine.",
		"Qui tutto si incurva: gli archi, le scale, le gronde come foglie ripiegate. Un nano con la squadra da muratore si metterebbe a piangere.",
		"Gli spigoli, a Darnassus, sono una rarità. Comincio a rimpiangerli, e non avrei mai detto di poter rimpiangere uno spigolo.",
	},
	["dar.muse.w05.020"] = {
		"Un nano mi ha appena chiesto dov'è la taverna rumorosa. Non ho avuto cuore di dirgli la verità.",
		"Ho visto un nano ordinare una birra, qui. Gli hanno portato qualcosa di chiaro e profumato. La sua faccia valeva un poema.",
		"Un nano sul ponte sta spiegando a un druido quanto renderebbe quest'albero in legname. Il druido ha smesso di sbattere le palpebre.",
	},
	["dar.muse.w05.021"] = {
		"Uno gnomo stava mostrando un aggeggio ticchettante sulla Tradesmen's Terrace. I kaldorei lo guardavano come si guarda una vespa posata sulla manica.",
		"Ingranaggi e vapore non sono molto amati a Darnassus. Il giocattolo di uno gnomo ha fischiato sulla terrazza e tre persone hanno fatto un passo indietro tutte insieme, con grande educazione.",
	},
	["dar.muse.w05.022"] = {
		"Tyrande Whisperwind guida questo popolo da un tempio, e non perché sia mite. È andata in guerra diecimila anni fa ed è tornata con l'arco in mano.",
		"L'Alta Sacerdotessa non è una figura tranquilla persa nella preghiera. Ogni soldato di Darnassus sembra stare un po' più dritto quando ha il suo tempio sotto gli occhi.",
	},
	["dar.muse.w05.023"] = {
		"L'acqua del pozzo lunare non sembra acqua. Sembra qualcosa da cui una sacerdotessa potrebbe versare luce, e immagino sia proprio questo il punto.",
		"Le sacerdotesse si inginocchiano al pozzo lunare come per ascoltarlo. Non sento cosa dice, ma smetto di parlare lo stesso.",
	},
	["dar.muse.w05.024"] = {
		"resta immobile dove un varco tra le foglie lascia scendere la luce della luna, e guarda la città farsi d'argento tutt'intorno.",
		"alza gli occhi tra le fronde verso uno spicchio di luna, piccolo e lontanissimo, e i kaldorei sul sentiero alzano lo sguardo nella stessa direzione.",
	},
	["dar.muse.w05.025"] = {
		"È l'alba, e i kaldorei rallentano come tutti gli altri rallentano a fine giornata. Mi sa che sono {g:sveglio|sveglia} dalla parte sbagliata della loro giornata.",
		"Prima luce tra le foglie, e mezza città che sbadiglia sulla via di casa. Per un popolo che vive le ore buie il mattino è la fine del turno.",
	},
	["dar.muse.w05.026"] = {
		"Mentre la luce se ne va, Darnassus si risveglia. Voci rimaste assonnate per tutto il pomeriggio si fanno nitide, e le Sentinelle si danno il cambio con qualcosa di simile al sollievo.",
		"Crepuscolo, e la città si stiracchia. È l'ora che i kaldorei sembrano aver aspettato tutto il giorno.",
	},
	["dar.muse.w05.027"] = {
		"Mezzogiorno, e le terrazze sono mezze addormentate. Perfino i mercanti hanno lo sguardo appesantito dei gatti davanti a una finestra al sole.",
		"Pieno giorno, e i kaldorei lo trattano come altri trattano le ore piccole: qualche commissione, e molto tempo seduti immobili.",
		"Il sole è alto, e i kaldorei lo attraversano come una corrente d'aria che sono troppo educati per far notare.",
	},
	["dar.muse.w05.028"] = {
		"La pioggia se la prende comoda per arrivare quaggiù. Cade sulla chioma, scivola di foglia in foglia a lungo e mi atterra sulle spalle a gocce grosse, lente, ponderate.",
		"Lassù tra le fronde dev'essere un diluvio. Quaggiù la pioggia passa una goccia grassa dopo l'altra, come se l'albero la razionasse.",
		"Piove, molto più in alto, e tutta la città sta sotto un picchiettio lento, come dita che tamburellano su un tavolo mentre la testa pensa ad altro.",
	},
	["dar.muse.w05.029"] = {
		"guarda la nebbia stesa sul lago, così fitta che la riva opposta sembra galleggiare sul nulla, con i suoi archi chiari unica cosa solida in vista.",
		"segue un sentiero dentro la nebbia scesa tra le terrazze, e sente voci a pochi passi senza riuscire a vedere chi parla.",
	},
	["dar.muse.w05.030"] = {
		"Kaldorei, si chiamano: figli delle stelle. A vederli camminare, senza fretta e un poco in disparte da tutto, ci credo.",
		"Un popolo che prende il nome dalle stelle e vive su un albero. Spiega perché alzano lo sguardo ogni volta che si fermano.",
		"Figli delle stelle, vuol dire il nome. Guardando il lieve bagliore nei loro occhi, mi viene quasi da prenderlo alla lettera.",
	},
	["dar.muse.w05.031"] = {
		"Hyjal è bruciato, le foreste antiche se ne sono andate, eppure abbiamo piantato qualcosa. Ogni volta che passo sotto questi rami provo un po' d'orgoglio e un po' di paura, insieme.",
		"Dopo la guerra avremmo potuto vagare per sempre. Invece abbiamo fatto sorgere un albero dal mare e gli abbiamo insegnato a reggere una città. Gente testarda, la mia.",
		"Sotto queste foglie non devo spiegarmi con nessuno. È un riposo più profondo di qualunque letto.",
	},
	["dar.muse.w05.032"] = {
		"Darnassus. Qualunque cosa faccia il resto del mondo, questo pezzo è nostro.",
		"Per quanto lontano porti la strada, quest'albero un posto per me lo tiene.",
	},
	["dar.muse.w05.033"] = {
		"I kaldorei mi guardano con gentilezza e un filo di tristezza, come si guarda un'effimera. Accanto a loro, immagino di esserlo.",
		"Qui c'è chi era già vecchio prima che la mia gente sapesse scrivere. A Darnassus è difficile sentirsi importanti, ed è stranamente piacevole.",
		"Qui tutti hanno tempo. Sono {g:l'unico|l'unica} a camminare come se la giornata potesse finire da un momento all'altro.",
	},
	["dar.muse.w05.034"] = {
		"I druidi qui vanno e vengono con l'aria di chi è appena stato in un posto verdissimo e lontanissimo. Moonglade, ha detto qualcuno, ma nessuno ha detto come.",
		"Un druido è sbucato da dietro un albero con addosso l'odore di terra bagnata sotto un altro cielo. I druidi hanno strade tutte loro, e le mappe non le prestano.",
	},
	["dar.muse.w05.035"] = {
		"si ferma alla Craftsmen's Terrace a guardare un sarto alzare una pezza di stoffa controluce, girarla una volta e metterla da parte senza una parola.",
		"indugia accanto a un banco dove un'elfa cuce il cuoio con punti così piccoli da sparire nella pelle.",
		"osserva un'alchimista della Craftsmen's Terrace sbriciolare una foglia fra due dita, annusarla e annuire, come se la foglia le avesse detto qualcosa.",
	},
	["dar.muse.w05.036"] = {
		"Erbe buone che crescono agli angoli dei sentieri, e nessuno che le raccolga. In qualunque altra città sparirebbero nel giro di un'ora.",
		"Le dita mi prudono davanti a ogni aiuola. Raccogliere qualcosa qui mi sembrerebbe di rubare in un tempio.",
	},
	["dar.muse.w05.037"] = {
		"Ma quest'albero le perde mai, le foglie? Non riesco a immaginare un autunno quassù. Darnassus sembra vivere in un unico lungo pomeriggio verde, sempre uguale.",
		"Niente foglie che cadono, niente rami spogli, nessun segno dell'anno che gira. Mi chiedo se ai kaldorei manchino le stagioni, o se diecimila anni di stagioni siano bastati.",
		"Teldrassil tiene una sola stagione, e mite. Non so se mi fiderei di un posto che non si spoglia mai di niente.",
	},
	["dar.muse.w05.038"] = {
		"passa accanto a un'anziana sacerdotessa seduta sull'erba a occhi chiusi, e quando ripassa molto più tardi lei non si è mossa di un dito.",
		"nota un elfo su una panchina che fissa lo stesso ramo chissà da quanto, con la calma di chi ha deciso che non c'è fretta, mai.",
	},
	["dar.muse.w05.039"] = {
		"Basta restare immobili abbastanza a lungo per sentirlo: un cigolio lento nel profondo del legno, tutta la città che si assesta appena, come una nave all'ancora.",
		"Ogni tanto la corteccia sotto gli stivali manda un lungo gemito sordo, troppo profondo per essere altro che l'albero stesso che sposta il suo peso.",
		"Sotto tutto questo l'albero è vivo. A volte, nel silenzio, mi sembra di sentirlo pensare.",
	},
	["dar.muse.w05.040"] = {
		"Ishnu-alah. Credo. Se ho appena insultato l'albero di qualcuno, chiedo scusa.",
		"Ogni volta che provo il saluto di qui, l'elfo di turno mi risponde in lingua comune. Con gentilezza. Che è peggio.",
	},
	["dar.muse.w05.041"] = {
		"Un passo dentro quel bagliore rosato e sarei alle radici, tra salsedine, barche e ippogrifi. Sembra una porta che non dovrebbe avere il permesso di essere così facile.",
		"Il portale per Rut'theran ronza ai margini della città. Darnassus tiene il mare a un passo di distanza e non ne parla mai.",
	},
	["dar.muse.w05.042"] = {
		"fa scorrere una mano lungo un muro e scopre che non è pietra ma corteccia, levigata come un corrimano da tante mani prima della sua.",
		"posa il palmo su una colonna di legno vivo e sente, o crede di sentire, qualcosa di lento che si muove all'interno.",
	},
	["dar.muse.w05.043"] = {
		"Al chiuso, qui, vuol dire dentro l'albero, più o meno. Le pareti si curvano, il pavimento ha le venature, e tutta la stanza sa appena di linfa.",
		"Ogni stanza di Darnassus sembra l'interno di un seme: liscia, tondeggiante, e sicura di ciò che diventerà.",
	},
	["dar.muse.w05.044"] = {
		"Tetti viola, stendardi viola, vesti viola. Se resto {g:fermo|ferma} abbastanza, divento viola anch'io.",
		"Da colazione ho contato undici sfumature di viola. I kaldorei hanno idee precise sui colori.",
		"Darnassus ha un colore, e non è il verde. È quello che il viola sogna di diventare.",
	},
	["dar.muse.w05.045"] = {
		"Alcuni anziani di qui hanno percorso il mondo di prima, prima che si spezzasse, quando il mare non stava dov'è adesso. Ogni costa deve sembrare loro una ferita rimarginata male.",
		"Diecimila anni fa questo popolo ha visto la propria terra sprofondare nel mare. Poi in quello stesso mare ha piantato un albero. Non so se sia coraggio o lutto, e forse non lo sanno neanche loro.",
	},
	["dar.muse.w05.046"] = {
		"Fra tutte le capitali dell'Alleanza, questa è quella in fondo alla strada più lunga: una nave oltre il mare, un ippogrifo, un portale, e poi una camminata. Alleati a distanza, in ogni senso.",
		"Fra Darnassus e Stormwind c'è un mare, e fra i loro modi di fare anche più di un mare. L'Alleanza si tiene insieme sopra un bel po' d'acqua.",
	},
	["dar.muse.w05.047"] = {
		"Pace, quassù. Bene. I guai aspettano ai piedi dell'albero, e so dove andarli a cercare.",
		"Riposa finché la città te lo concede. Darkshore non sarà così gentile.",
	},
	["dar.muse.w05.048"] = {
		"Troppo bello, tutto quanto. Un posto così calmo mi fa controllare dietro i salici in cerca del tranello.",
		"Qui tutto è aggraziato, senza età e sereno. Ne darei volentieri un po' in cambio di una taverna rumorosa e di una panca che traballa.",
		"Serena. Aggraziata. Infinita. Darei una moneta d'argento per una buca onesta in mezzo alla strada.",
	},
	["dar.muse.w05.049"] = {
		"Le voci dei kaldorei hanno una lieve risonanza, come se ogni parola venisse pronunciata in una stanza più grande di quella in cui si trova.",
		"Perfino un mercante che dice un prezzo, alle mie orecchie, sembra parlare dal fondo di un pozzo di luce lunare.",
	},
	["dar.muse.w05.050"] = {
		"fa strada a una giovane sacerdotessa che corre verso il tempio con una bracciata di bende pulite, l'unica persona a Darnassus che sembri avere fretta.",
		"osserva una sacerdotessa inginocchiarsi accanto a una Sentinella zoppicante sul sentiero, posarle una mano sulla ferita e rimandarla per la sua strada senza una parola.",
		"si scosta dal sentiero per lasciar passare due sacerdotesse che portano una barella verso il tempio, il volto calmo e il passo tutt'altro che lento.",
	},
	["dar.muse.w05.051"] = {
		"I druidi lasciano l'Enclave diretti a Silithus con la faccia scura. Qualcosa sotto la sabbia, laggiù, preoccupa il Cenarion Circle, e non è gente che si preoccupa ad alta voce.",
		"Ogni tanto un druido di qui nomina lo Scarab Wall, e la conversazione si spegne. Qualunque cosa dorma là dietro, la ricordano meglio di quanto vorrebbero.",
	},
	["dar.muse.w05.052"] = {
		"Una giardiniera sulla terrazza affonda un germoglio nella terra con grande cura. Crescerà ancora quando tutti quelli che conosco saranno polvere, e lei sembra contenta così.",
		"I kaldorei piantano cose che non vedranno cresciute. Qui non è triste. È semplicemente il modo di costruire.",
	},
	["dar.muse.w05.053"] = {
		"Un nano, uno gnomo e un umano in fila a una banca kaldorei, tutti a bisbigliare per rispetto. L'Alleanza nella sua versione più educata.",
		"Visitatori di ogni razza dell'Alleanza camminano su questi sentieri in punta di piedi, come per paura di svegliare l'albero. Non li ho mai visti così uniti.",
		"Kaldorei, umani, nani, gnomi, tutti chini sulla stessa mappa vicino alla banca. Qualunque altra cosa sia l'Alleanza, è un sacco di gente che si chiede indicazioni a vicenda.",
	},
	["dar.muse.w05.054"] = {
		"scorge due occhi chiari che brillano sotto i salici, nel buio, e un istante dopo una Sentinella sbuca sul sentiero, fa un cenno e sparisce.",
		"nota che di notte, sulla terrazza, metà dei volti hanno occhi che brillano appena, come braci coperte per il mattino.",
	},
	["dar.muse.w05.055"] = {
		"Il cibo qui è bellissimo. Piccolo, profumato, disposto come un giardino. Potrei mangiarne quattro piatti e poi andare comunque a cercare del pane.",
		"Frutta, pesce, qualcosa di verde con un fiore in cima. La cucina kaldorei sazia prima gli occhi, e lo stomaco un po' più tardi.",
		"Un pasto kaldorei: una foglia, tre bacche e la vista più bella di Kalimdor. Me ne servirà un secondo.",
	},
	["dar.muse.w05.056"] = {
		"Una città così calma è il posto giusto per sussurrare qualche nome.",
		"Abbastanza silenzio, qui, da sentire i nomi che altrove non dico ad alta voce.",
	},
	["dar.muse.w05.057"] = {
		"prova a camminare piano come i kaldorei intorno, e riesce solo a sembrare un carretto di pentole guidato con prudenza.",
		"imita per qualche passo l'andatura senza fretta dei kaldorei, poi ci rinuncia e torna alla propria.",
	},
	["dar.muse.w05.058"] = {
		"Darnassus sembra una città in ascolto. Non di me in particolare. In ascolto e basta, sempre, di qualcosa sotto il silenzio.",
		"In questo posto c'è un'attenzione, come se gli alberi, l'acqua e i volti antichi aspettassero tutti un suono che ancora non è arrivato.",
		"Qui niente è rumoroso, ma niente dorme. Tutta la città ha l'immobilità di un cervo che ha sentito qualcosa.",
	},
	["dar.muse.w05.059"] = {
		"In tutto il giorno nessuno mi ha dato una spinta. A Darnassus potrei farci l'abitudine.",
		"Niente calca, niente spintoni, nessuno che mi venda la stessa cosa due volte. Questa città vizia chi viaggia.",
	},
	["dar.muse.w05.060"] = {
		"Non bisogna scambiare questo silenzio per mollezza. Ognuno di quei volti tranquilli ha una freccia pronta, e sa esattamente dove piantarla.",
		"Città gentile, gente dura. I kaldorei hanno respinto la Burning Legion quando il mondo era giovane; parlare sottovoce non li rende deboli.",
		"Voci morbide, frecce affilate. Ecco Darnassus in quattro parole.",
	},
	["dar.muse.w05.061"] = {
		"sente per caso un druido e una Sentinella che litigano a bisbigli furiosi lungo il sentiero, sorridendo entrambi con garbo a chiunque passi.",
		"osserva due kaldorei che hanno chiaramente un litigio furibondo senza mai alzare la voce, e che poi si separano con un inchino impeccabile.",
	},
	["dar.muse.w05.062"] = {
		"Di notte le sacerdotesse sembrano più a loro agio, più loro stesse, come se la luna sopra le foglie fosse una vecchia amica che si affaccia alla finestra.",
		"I kaldorei dicono che Elune veglia di notte. Sotto questi rami, con la città muta e argentata, potrei quasi credere che stia facendo attenzione.",
	},
	["dar.muse.w05.063"] = {
		"si inginocchia per stringere una cinghia e scopre che il gradino sotto il ginocchio è intagliato con un motivo di foglie così fine da aver richiesto una vita intera.",
		"si ferma a guardare da vicino una ringhiera e vede che ogni pollice è stato modellato a forma di tralci: un lavoro paziente che nessuno dei passanti sembra notare.",
		"passa il pollice su un arco intagliato e scopre gufi, lune e foglie nascosti nelle venature, così fini che svaniscono appena fa un passo indietro.",
	},
	["dar.npc_meet.w05.001"] = {
		"Una Sentinella, il glaive sulla schiena, così immobile che l'avevo presa per una statua finché non ha mosso gli occhi.",
		"Una Sentinella di guardia, ferma come il tronco di un albero. Chissà quanti secoli di turni ci sono dentro quella immobilità.",
		"La Sentinella non mi ferma, non mi saluta, e nemmeno distoglie lo sguardo. Di rado qualcuno mi ha tenuto d'occhio con tanta educazione.",
	},
	["dar.npc_meet.w05.002"] = {
		"Che la tua guardia sia tranquilla. Non che questa città sembri conoscerne di altro tipo.",
		"Buona guardia, Sentinella. Cercherò di non essere la cosa più interessante che vedrai oggi.",
		"Non badare a me. Mi sono solo {g:perso|persa} nel modo più bello possibile.",
	},
	["dar.npc_meet.w05.003"] = {
		"rallenta il passo quando una Sentinella si volta a guardare, e riceve un breve cenno che riesce a dire benvenuto, attenzione e puoi andare, tutto insieme.",
		"incrocia per un attimo lo sguardo di una Sentinella e ne riceve in cambio un'occhiata misurata, di quelle riservate a chiunque passi e poi archiviate.",
	},
	["dar.npc_meet.w05.004"] = {
		"Chi sta al banco alza gli occhi da un registro tenuto con una grafia fluida e aspetta, senza fretta, come se questa vendita potesse durare dieci anni e andasse bene così.",
		"Merci disposte con ordine su un telo, prezzi detti a voce bassa, nessuno che mi tira per la manica. Ho il sospetto che qui spenderò di più, non di meno.",
		"Perfino la merce è disposta come un'offerta votiva. I prezzi, purtroppo, sono disposti come prezzi.",
	},
	["dar.npc_meet.w05.005"] = {
		"Hai qualcosa che tenga lontana l'umidità? In questa città tutto sembra stare proprio accanto all'acqua.",
		"Prendo quello che comprano le Sentinelle. Hanno l'aria di sapere cosa dura.",
	},
	["dar.npc_meet.w05.006"] = {
		"L'oste ha la calma di chi da qualche secolo non si stupisce più di nulla, e non toccherà certo a me fare eccezione.",
		"Un oste che parla piano e si ricorda di tutto. Mi comporterò al meglio.",
		"Un oste il cui benvenuto è un piccolo cenno e una mano aperta verso la sala. Credo mi sia appena stato offerto tutto.",
	},
	["dar.npc_meet.w05.007"] = {
		"osserva il deposito che viene annotato in un registro, con lettere lente e bellissime, come se le monete meritassero la calligrafia.",
		"aspetta al banco mentre dita lunghe e attente contano le monete, e nessuno alza gli occhi finché la somma non torna.",
		"si guarda intorno nella banca silenziosa mentre le monete vengono contate, quasi in attesa che qualcuno chieda di respirare più piano.",
	},
	["dar.npc_meet.w05.008"] = {
		"Sono {g:pronto|pronta} a imparare. Con calma, se qui si fa così.",
		"Insegnami qualcosa. Prometto di metterci meno di un secolo.",
		"Sono qui per imparare. Correggimi tutte le volte che vuoi: mi dicono che il tempo non ti manca.",
	},
	["dar.npc_meet.w05.009"] = {
		"Qualcuno qui ha un incarico, e ha chiaramente aspettato con pazienza le mani giuste. Dovranno bastare le mie.",
		"C'è del lavoro da affidare. La richiesta arriverà con garbo, con cura, e sarà più difficile di quanto sembri.",
		"Qualcuno mi fa cenno di avvicinarmi, con un gesto lento e ponderato. Qualunque cosa sia, ci hanno pensato a lungo.",
	},
	["dar.npc_meet.w05.010"] = {
		"ascolta la richiesta senza interrompere, adeguandosi al passo lento di chi parla, e annuisce solo quando l'ultima parola si è posata.",
		"resta ad ascoltare con pazienza una spiegazione lunga e accurata di ciò che serve, e non vi trova una sola parola sprecata.",
	},
	["dar.npc_meet.w05.011"] = {
		"Qualcuno della città si ferma per lasciarmi passare, con un piccolo inchino. Ricambio, un po' troppo in basso.",
		"Chi abita qui risponde alla mia domanda con grande cura, poi aggiunge una seconda risposta a una domanda che non avevo ancora fatto.",
	},
	["dar.npcd_flightmaster_open.w05.001"] = {
		"Gli ippogrifi sono irrequieti, oggi. Parla piano vicino a loro, e ti porteranno ovunque lungo questa costa.",
		"Ali per il continente? Attenzione al becco, e tieniti forte quando virano sopra l'acqua.",
	},
	["dar.npcd_guard_bye.w05.001"] = {
		"Va' in pace. I sentieri ti riporteranno qui, se glielo permetti.",
		"Buon cammino. E non indugiare sul bordo del portale: non è un posto dove fermarsi.",
	},
	["dar.npcd_guard_directions.w05.001"] = {
		"Banca e casa d'aste? Sulla Tradesmen's Terrace, vicino al lago. Segui le tende dei mercanti.",
		"I guerrieri si addestrano sulla Warrior's Terrace, fra le Sentinelle. I druidi stanno al Cenarion Enclave; i sacerdoti, al Temple of the Moon.",
		"Conciatori, sarti, alchimisti: la Craftsmen's Terrace. Chiedi a chiunque, lì; ti risponderanno con calma, ma bene.",
	},
	["dar.npcd_guard_open.w05.001"] = {
		"Darnassus ti accoglie. Cammina piano, e lascia la lama dove riposa.",
		"Pace a te, viandante. Qui la guardia la montano le Sentinelle; a te basta non turbare la quiete.",
	},
	["dar.npcd_guard_open.w05.002"] = {
		"Il continente è lontano da qui. Chiedi pure, se ti serve la strada: preferiamo indicartela adesso che venirti a cercare dopo.",
		"La luce di Elune su di te. Attenzione al bordo dell'acqua: il lago è più profondo di quanto sembri.",
	},
	["dar.npcd_innkeeper_bye.w05.001"] = {
		"Buon viaggio. Il letto conserverà la tua forma per un po', e la porta resta aperta.",
		"Sentieri sicuri. Torna quando la strada ti avrà tolto di nuovo le forze.",
	},
	["dar.npcd_innkeeper_news.w05.001"] = {
		"Da Auberdine è arrivata una barca carica di viaggiatori. Metà di loro non ha ancora trovato la banca.",
		"I druidi dell'Enclave discutono da giorni. Di cosa, non lo dicono, ma hanno smesso di venire qui per cena.",
	},
	["dar.npcd_innkeeper_open.w05.001"] = {
		"Entra, e lascia la strada fuori dalla porta. I letti sono morbidi, e la stanza è tranquilla.",
		"Accomodati dove preferisci: qui nessuno ti metterà fretta.",
	},
	["dar.npcd_innkeeper_open.w05.002"] = {
		"Hai l'aria di chi ha trovato lunga la salita dell'albero. Riposa: ci sono acqua, pane e una coperta per te.",
		"Ah, gente di passaggio. In tavola c'è succo di bacche di luna, e un letto ti aspetta, se le gambe ti reggono ancora.",
	},
	["dar.npcd_merchant_bye.w05.001"] = {
		"Buona strada, e che quel che hai comprato duri più del viaggio.",
		"Arrivederci. Se si rompe, riportalo; se non si rompe, dillo ai tuoi amici.",
	},
	["dar.npcd_merchant_news.w05.001"] = {
		"Il cuoio di Ashenvale scarseggia: gli orchi dei campi di taglio rendono difficile la caccia.",
		"La barca per il continente è piena a ogni traversata. Tutti vogliono venire a Darnassus, e poi tutti vogliono andarsene.",
	},
	["dar.npcd_merchant_open.w05.001"] = {
		"Guarda pure quanto vuoi. Le cose buone vanno scelte con calma.",
		"Tutto quello che vedi è stato fatto a Darnassus, da mani che hanno moltissima pratica.",
	},
	["dar.npcd_merchant_open.w05.002"] = {
		"Clientela da lontano, a giudicare da quegli stivali. Che cosa ti serve per la strada?",
		"Prenditi il tuo tempo. Sto a questo banco da più tempo di quanto siano in piedi certi regni.",
	},
	["dar.npcd_merchant_wares.w05.001"] = {
		"Archi di buon legno, frecce impennate con piume di gufo, e mantelli che tengono lontana l'umidità della costa.",
		"Erbe delle radure di Teldrassil, seccate con calma. Buone per il viaggio, ancora meglio per la febbre.",
	},
	["dar.npcd_trainer_open.w05.001"] = {
		"Sei qui per imparare. Bene. Prima la pazienza, poi il resto.",
		"Non muoverti un momento, lascia che ti guardi. Mm. C'è più di quanto pensi, in te, e meno di quanto speri.",
	},
	["dar.pray.w05.001"] = {
		"Elune, la cui luce questa città custodisce: veglia sulle Sentinelle lungo la riva, e su chiunque sia ancora in viaggio.",
		"Elune, custodisci la pace di quest'albero, e prestamene un poco.",
		"Qualunque luce vegli su Teldrassil: tieni sane le sue radici e al sicuro la sua gente.",
	},
	["dar.quest_complete.w05.001"] = {
		"riceve un ringraziamento prima nella lingua dei kaldorei, poi di nuovo nella lingua comune, lentamente, perché nulla vada perduto.",
		"ascolta il grazie pronunciato nell'antica lingua degli elfi della notte, e non ha bisogno di capire le parole per coglierne il senso.",
	},
	["dar.quest_complete.w05.002"] = {
		"Per chi conta la propria vita in secoli, il mio incarico è durato quanto un respiro. Per me è stato tutta la giornata. Eppure sembriamo soddisfatti entrambi.",
		"Il mio giorno di gambe, un loro attimo qualunque. Strano come la gratitudine riesca comunque a colmare la distanza.",
	},
	["dar.quest_complete.w05.003"] = {
		"Fatto. Prenditi pure il tuo tempo per la ricompensa: mi dicono che la pazienza sia una specialità del posto.",
		"Tutto finito. Nessuna fretta per il compenso. A quanto pare qui nessuno ha più avuto fretta da qualche migliaio d'anni.",
		"Ecco qua. Pagami quando vuoi. Entro questo secolo, magari.",
	},
	["dar.quest_complete.w05.004"] = {
		"I kaldorei hanno rinunciato all'immortalità a Hyjal, e hanno perso molto altro ancora. Aiutarli a tenersi quel che resta non mi sembra un lavoro da poco.",
		"Un popolo che ha barattato l'eternità con una sola vittoria. Qualunque cosa abbia appena fatto per loro, sono {g:contento|contenta} di averla fatta bene.",
	},
	["dar.quest_complete.w05.005"] = {
		"prende la ricompensa mentre il felino di una Sentinella, disteso lì vicino, fa uno sbadiglio smisurato, come a chiudere la faccenda.",
		"accetta il compenso sotto lo sguardo pigro di un grande felino striato steso sulla terrazza, l'unico testimone per nulla colpito.",
	},
	["dar.quest_complete.w05.006"] = {
		"Un lavoro piccolo, e la mia strada è appena cominciata. Anche qui, tra gente con secoli alle spalle, tutti un tempo hanno cominciato dai lavori piccoli.",
		"Un incarico modesto per una borsa modesta. Tutti, in questa città, hanno cominciato da qualche parte; alcuni solo molto, molto tempo fa.",
		"Non una grande impresa. D'altra parte, anche l'Albero del Mondo un tempo era un seme.",
	},
	["dar.quest_complete.w05.007"] = {
		"Il lavoro di questo peso porta con sé del silenzio. Chi l'aveva affidato ha chiesto solo se fosse fatto, non quanto fosse costato.",
		"Nessuno mi ha chiesto com'è andata. Superato un certo punto, la risposta ce l'hai scritta addosso, e qui la sanno leggere.",
	},
	["dar.quest_complete.w05.008"] = {
		"Consegnato alla luce delle lanterne, con mezza città addormentata. Ho contato le monete senza farle tintinnare.",
		"Un incarico chiuso nel cuore della notte. Perfino la ricompensa è passata di mano in silenzio, per non svegliare nessuno.",
	},
	["dar.quest_complete.w05.009"] = {
		"chiude la faccenda mentre la prima luce scende fra le foglie, e si allontana in una città che si sta appena svegliando.",
		"riceve la ricompensa all'alba, quando le terrazze sono ancora vuote e l'acqua conserva il colore pallido del cielo.",
	},
	["dar.quest_complete.w05.010"] = {
		"prende la ricompensa sotto le foglie che gocciolano e la mette via in fretta, prima che la pioggia trovi la strada per la borsa.",
		"conclude l'incarico al riparo di un arco, mentre la pioggia picchietta sugli specchi d'acqua della città.",
		"si ripara sotto la foglia più vicina, grande abbastanza da fare da tetto, per ricevere il grazie, mentre la pioggia tamburella piano là sopra.",
	},
	["dar.quest_complete.w05.011"] = {
		"Le monete con cui pagano qui sono monete normali. Non so perché mi aspettassi qualcosa d'argento a forma di foglia.",
		"Monete qualunque, come ovunque. Chissà perché, mi aspettavo quasi di essere {g:pagato|pagata} in raggi di luna.",
		"Pagano in buon rame e buon argento, come chiunque altro. Stranamente, è la cosa più sorprendente che abbia visto in questa città.",
	},
	["dar.quest_complete.w05.012"] = {
		"Qui i ringraziamenti arrivano dopo una pausa, come se le parole venissero prese da uno scaffale lungo e spolverate prima dell'uso.",
		"Prima del grazie c'è stato un silenzio, abbastanza lungo da preoccuparmi. Poi ho capito: era attenzione, non dubbio.",
		"Qui ogni parola di ringraziamento sembra pesata prima di essere detta. Così quelle che arrivano pesano di più, nel senso buono.",
	},
	["dar.quest_complete.w05.013"] = {
		"È fatto. Che serva bene al tuo popolo.",
		"Finito, e volentieri. Che la vostra città conservi la sua quiete.",
		"Il lavoro ora è tuo. Fanne buon uso.",
	},
	["dar.quest_complete.w05.014"] = {
		"Non so mai dove vada a finire il lavoro, una volta uscito dalle mie mani. Qui mi piace pensare che si posi da qualche parte, come una foglia che trova la terra.",
		"Quello che ho portato verrà sistemato da qualche parte, piano e con cura. In questa città ogni cosa sembra trovare il suo posto così.",
	},
	["dar.quest_complete.w05.015"] = {
		"Ecco. Tutto quanto, tutto intero. Quasi tutto intero.",
		"Tutto quello che avevi chiesto. Controlla pure: mi dispiacerebbe deludere qualcuno che si ricorda le cose per mille anni.",
		"Ecco, tutto quello che volevi. Niente è finito nel lago, lo giuro.",
	},
	["dar.quest_complete.w05.016"] = {
		"Non al primo tentativo, ma è fatta. Qui nessuno ha nemmeno alzato un sopracciglio per il ritardo. Per loro il tempo ha un altro peso.",
		"Mi ci è voluto più di un tentativo. In questa città, a quanto pare, vale come puntualità perfetta.",
	},
	["dar.quest_complete.w05.017"] = {
		"Bel lavoro, tutti quanti. Dividiamoci il bottino sotto un albero: qui non mancano.",
		"È stato un buon lavoro, fatto insieme. Sediamoci, riposiamo, facciamo le parti. La città non scappa.",
	},
	["dar.quest_complete.w05.018"] = {
		"si siede un momento sul muretto in riva all'acqua, chiusa la faccenda, e lascia che la quiete della città smussi gli spigoli della giornata.",
		"scende fino alla riva del lago dopo aver ricevuto la ricompensa, e prima di andarsene fa rimbalzare un sasso piatto sull'acqua.",
	},
	["dar.quest_complete.w05.019"] = {
		"Un filo in più fra la città più lontana dell'Alleanza e il resto di noi. Sottile, ma i fili si sommano.",
		"Darnassus sta all'estremo margine dell'Alleanza, in cima a un albero, oltre il mare. Ogni incarico svolto qui la avvicina un poco.",
		"Ogni incarico portato a termine qui è un punto di cucito fra quest'albero e i regni oltre il mare. Ci ho messo anche il mio.",
	},
	["dar.quest_complete.w05.020"] = {
		"lascia che il grazie si posi, poi si avvia lungo il sentiero curvo, con la borsa che pesa piacevolmente alla cintura.",
		"risponde con un cenno alle parole di ringraziamento e si allontana lungo l'acqua, sentendo finalmente nelle gambe tutto il cammino della giornata, ora che è finito.",
		"fa ruotare le spalle una volta consegnato il lavoro, e si incammina lungo il sentiero della riva senza voltarsi.",
	},
	["dar.quest_complete.w05.021"] = {
		"Ricompensa in mano. Adesso: cibo, una cote, e quello che la terrazza dei mercanti mi darà per il resto della roba nello zaino.",
		"Pagato. La terrazza dei mercanti sta per ricevere una mia visita, con le borse più leggere e il borsellino più pesante.",
	},
	["dar.quest_complete.w05.022"] = {
		"Fatto! Se qualcuno ha un altro incarico, mi sento stranamente {g:leggero|leggera}. Dev'essere l'aria di quassù.",
		"Finito, e non sono nemmeno {g:stanco|stanca}. Dev'essere l'acqua di questa città.",
		"Fatto! Chi l'avrebbe detto che una città così calma potesse mettermi tanta energia nelle gambe?",
	},
	["dar.quest_complete.w05.023"] = {
		"conta le monete della ricompensa una volta, poi una seconda, perché in una città così quieta non c'è niente che metta fretta.",
		"conta la ricompensa sul bordo di una vasca di pietra, dove le monete brillano contro la roccia chiara.",
	},
	["dar.quest_complete.w05.024"] = {
		"Nella città della luna perfino una commissione qualunque sembra svolta sotto lo sguardo di qualcuno. Ho tenuto la schiena più dritta per tutto il tragitto.",
		"Il tempio di Elune è a pochi passi. Strano come questo mi abbia fatto venir voglia di fare bene anche un compito così piccolo.",
	},
	["dar.quest_complete.w05.025"] = {
		"Niente discorsi, niente folla, niente storie. Un cenno, il pagamento, e la faccenda è chiusa. Potrei farci l'abitudine.",
		"Nemmeno un discorso su quanto siano tutti grati. Solo la ricompensa e un cenno discreto. Una città che fa per me.",
	},
	["dar.reputation_change.w05.001"] = {
		"Qualcuno ha deciso di avere un'opinione migliore di me. Qui decisioni così si prendono con calma, e si mantengono a lungo.",
		"Il mio nome sale un poco in una memoria che ragiona in secoli. Cercherò di meritarmene la durata.",
	},
	["dar.rest_enter.w05.001"] = {
		"Dentro, le pareti si incurvano come l'interno di un baccello, e la luce è bassa e violetta. Il sonno arriverà senza fatica.",
		"Una stanza modellata nel legno vivo, una coperta che sa di erbe. Qualunque cosa mi abbia fatto la strada oggi, si ferma a questa porta.",
		"Il letto è basso, la stanza è calda, e l'unico suono è l'acqua che scorre da qualche parte oltre la finestra. Non resisterò a lungo.",
	},
	["dar.rest_enter.w05.002"] = {
		"si sistema sull'erba in riva all'acqua, la schiena contro una radice liscia, e lascia che la quiete della città faccia il resto.",
		"si stende sotto uno dei grandi alberi della città, senza stivali, ad ascoltare le foglie, molto in alto, che si sfiorano tra loro.",
		"slaccia le cinghie più pesanti e si sdraia sul muschio accanto a una pozza, un braccio sugli occhi.",
	},
	["dar.rest_enter.w05.003"] = {
		"Notte su Darnassus. La città cambia appena: si fa solo più silenziosa, e io con lei.",
		"Qui la notte è morbida, illuminata piano, mai buia davvero. Una buona notte per posare lo zaino e non riprenderlo fino al mattino.",
	},
	["dar.rest_enter.w05.004"] = {
		"Basta, ho finito di camminare. Svegliatemi se l'albero si sposta.",
		"Un posto morbido, per favore. Le mie gambe hanno sporto reclamo contro l'intera città.",
		"Riposo, finalmente. Se qualcuno mi cerca, sarò quel mucchietto sotto una foglia enorme.",
	},
	["dar.rest_enter.w05.005"] = {
		"Acqua lì vicino, un filo di vento tra le foglie, e nessuno che abbia bisogno di me. Potrei restare esattamente così.",
		"Per una volta niente mi tira da nessuna parte. La città respira piano, e mi accorgo che il mio respiro si accorda al suo.",
		"L'acqua continua a parlare da sola, e io ho smesso di interromperla. Credo che sia questo, riposare.",
	},
	["dar.rest_enter.w05.006"] = {
		"si siede con la schiena al muro e l'ingresso ben in vista, anche qui, e solo a poco a poco lascia che la mano si allontani dall'impugnatura dell'arma.",
		"si riposa, ma continua a lanciare occhiate verso il sentiero, come se la strada fosse passata dal portale insieme a {g:lui|lei}.",
	},
	["dar.subzone_enter.w05.001"] = {
		"La terrazza degli artigiani. Pelli tese sui telai, erbe appese a seccare, e l'incudine di qualcuno che fa del suo meglio per essere educata.",
		"La terrazza degli artigiani: conciatori, sarti, alchimisti, ciascuno al lavoro senza alzare la voce. Perfino le martellate qui sembrano ponderate.",
	},
	["dar.subzone_enter.w05.002"] = {
		"entra nella terrazza degli artigiani, passando accanto a rastrelliere di cuoio a seccare e al vago odore verde del lavoro di un alchimista.",
		"attraversa la terrazza degli artigiani, dove ogni banco da lavoro è in ordine e chi ci lavora sembra avere tutto il tempo che esiste.",
	},
	["dar.subzone_enter.w05.003"] = {
		"sale sulla terrazza dei guerrieri, dove i maestri di più di un'arte del combattimento tengono ciascuno il proprio angolo, e un occhio attento sul sentiero.",
		"arriva sulla terrazza dei guerrieri e passa sotto lo sguardo delle Sentinelle, la cui guardia qui sembra più vigile che in qualunque altro punto della città.",
	},
	["dar.subzone_enter.w05.004"] = {
		"La terrazza dei mercanti. La banca, la casa d'aste, e prima o poi tutti i borsellini della città.",
		"Ah, la terrazza dei mercanti. Se Darnassus alzerà mai la voce, sarà qui, per un prezzo.",
		"La terrazza dei mercanti, dove i banditori annunciano le offerte a voce appena più alta di una conversazione.",
	},
	["dar.subzone_enter.w05.005"] = {
		"entra nel Cenarion Enclave, dove un orso passa pesante sul sentiero e, pochi passi dopo, si rialza in forma di druido e prosegue a piedi.",
		"arriva nel Cenarion Enclave e si fa da parte per un druido in forma d'orso, che ringrazia con un cenno del muso, stranamente aggraziato.",
		"passa accanto a una druida inginocchiata fra le radici che serpeggiano nell'Enclave, il palmo premuto sulla corteccia, gli occhi chiusi, in ascolto.",
	},
	["dar.subzone_enter.w05.006"] = {
		"Fandral Staghelm ha il suo seggio da qualche parte sopra questo Enclave. I druidi di sotto parlano di lui con cautela, come si parla di un fiume dopo il disgelo.",
		"L'Enclave dell'Arcidruido. Qui tutti sembrano in ascolto di qualcosa: l'albero, il vento, o la voce di Fandral Staghelm dall'alto.",
	},
	["dar.subzone_enter.w05.007"] = {
		"Il Temple of the Moon. Le sacerdotesse scivolano accanto alla grande fontana come se i loro piedi non avessero mai imparato ad avere fretta.",
		"Dentro il tempio la luce è d'argento e le voci sono poche. La statua al centro guarda in basso con una pazienza più antica di quest'albero.",
		"Tyrande Whisperwind è da qualche parte in questo tempio. Perfino l'aria sembra stare sull'attenti.",
	},
	["dar.subzone_enter.w05.008"] = {
		"si addentra nei giardini del tempio, dove i sentieri girano su se stessi fra fiori e acqua ferma, come se qui nessuno avesse mai bisogno di arrivare da qualche parte.",
		"rallenta il passo nei giardini del tempio, fra siepi curate e fontane lente, dove perfino gli uccelli sembrano cantare a mezza voce.",
	},
	["dar.subzone_enter.w05.009"] = {
		"Un'altra terrazza, un altro ponte ricurvo, un altro posto dove mi siederei volentieri per un'ora.",
		"Ogni angolo di questa città sembra progettato attorno a un panorama. Questo non fa eccezione.",
	},
	["dar.subzone_enter.w05.010"] = {
		"Qui i quartieri non iniziano e non finiscono: scivolano l'uno nell'altro lungo l'acqua. Mi accorgo di aver cambiato zona solo quando cambiano i suoni.",
		"Nessun muro fra i quartieri di Darnassus: solo un ponte, una curva del sentiero, un odore diverso nell'aria. Cuoio, poi incenso, poi soltanto foglie.",
		"Fra un quartiere e l'altro, il rumore dei martelli lascia il posto all'acqua che scorre. È l'unico confine di cui Darnassus sembri aver bisogno.",
	},
	["dar.subzone_enter.w05.011"] = {
		"attraversa un ponte ricurvo verso un'altra parte della città e si ferma sul colmo, dove tutto il lago si apre di sotto.",
		"segue il sentiero attorno all'acqua fino a un altro quartiere, alzando lo sguardo ai grandi rami che fanno da tetto a questo lato della città.",
	},
	["dar.thanks.w05.001"] = {
		"Grazie. Gentile da parte tua, e in questa città la gentilezza sembra arrivare sempre con le buone maniere.",
		"Grazie. Lo restituirò al prossimo viandante smarrito che incontrerò su questi sentieri.",
		"Ti ringrazio. Mi hai risparmiato almeno un altro giro del lago.",
	},
	["dar.thanks.w05.002"] = {
		"Hai la mia gratitudine, e la farò durare più che posso.",
		"Ti sono {g:grato|grata}. Me ne ricorderò, anche se non per diecimila anni.",
	},
	["dar.toast.w05.001"] = {
		"All'Albero del Mondo, e ai suoi pazientissimi inquilini!",
		"Alzate i calici: all'acqua quieta e alle vite lunghe.",
		"A Darnassus, dove perfino i brindisi si fanno sottovoce. Alla salute, ma senza gridare!",
	},
	["dar.travel.w05.001"] = {
		"Luce verde, salici, acqua ferma, e poi lo strattone della pietra del ritorno dietro le costole. Darnassus si dirada come un sogno al risveglio.",
		"Un'ultima occhiata all'acqua e ai salici, poi la pietra mi porta via. La città non farà nemmeno un'increspatura.",
	},
	["dar.travel.w05.002"] = {
		"lancia un'occhiata al lungo sentiero verso il portale mentre la pietra del ritorno si scalda, come per confrontare le due strade.",
		"lascia che il bagliore della pietra del ritorno si raccolga nella mano sotto le foglie, e sparisce prima che una Sentinella di passaggio abbia finito di voltarsi.",
	},
	["dar.weather_change.w05.001"] = {
		"si tira su il cappuccio quando comincia la pioggia, e guarda le grandi foglie lassù rovesciare l'acqua raccolta in improvvisi fili d'argento.",
		"si ripara sotto un arco mentre arriva la pioggia, e le larghe foglie in alto si riempiono, si piegano e si svuotano come ciotole inclinate.",
		"guarda la pioggia picchiettare il lago, mentre le Sentinelle sui ponti proseguono come se niente fosse.",
	},
	["dar.weather_change.w05.002"] = {
		"Pioggia a Darnassus. Nessuno corre al riparo: i kaldorei continuano a camminare, solo un po' più piano, come se fosse un ospite da accogliere.",
		"È arrivata la pioggia, e la città non sembra farci caso. Una Sentinella mi passa accanto con l'acqua che le cola dall'armatura, senza cambiare passo.",
	},
	["dar.weather_change.w05.003"] = {
		"Il cielo si è aperto sopra la chioma. La luce del sole trova i varchi tra le foglie e posa monete luminose sull'acqua.",
		"Di nuovo il sole, lassù da qualche parte. Chiazze di luce scivolano attraverso la volta di foglie e vagano lente sulle terrazze.",
		"Le nuvole se ne vanno, e il sole torna a pezzi, sparso tra le foglie come qualcosa di rovesciato.",
	},
	["dar.weather_change.w05.004"] = {
		"alza lo sguardo mentre le nuvole si aprono, e attraverso un varco tra le foglie coglie una manciata di stelle sopra la città.",
		"si accorge che il cielo notturno si schiarisce fra i rami alti, e le stelle compaiono una a una, come se le accendessero le Sentinelle.",
	},
	["dar.weather_change.w05.005"] = {
		"La nebbia è risalita lungo l'albero. Le terrazze lontane sono sparite, le lanterne sono solo macchie viola, e le voci arrivano dal nulla.",
		"La foschia scivola sul lago e inghiotte le isole. Darnassus era già silenziosa; ora è silenziosa e mezza invisibile.",
		"Nebbia sulla città. Sento l'acqua ma non la vedo, e ogni ponte sembra portare dentro una nuvola.",
	},
	["dar.weather_change.w05.006"] = {
		"Tuoni lassù nella chioma! Tenetevi a qualcosa: l'albero intero sta ascoltando.",
		"Una tempesta su Teldrassil, e i rami della città scricchiolano come il fasciame di una nave.",
	},
	["dar.muse.w23.ancient.001"] = {
		"Nessuno a Darnassus pronuncia il nome di Azshara come fanno i cantastorie. Lo dicono piatto, come il nome in calce a un debito che non verrà mai saldato.",
		"Quando un kaldorei dice 'Azshara' non c'è nessun brivido, niente del gusto che ci metterebbe un racconto. Solo il tono di chi legge ad alta voce un conto mai pagato.",
	},
	["dar.muse.w23.ancient.002"] = {
		"In questa città cammina qualcuno che ha visto il Pozzo dell'Eternità coi propri occhi. Continuo a guardare le facce chiedendomi quale.",
		"Alcuni degli anziani che incrocio su questi sentieri sono stati sulla riva del Pozzo dell'Eternità. Non in una canzone: di persona, con la sabbia nei calzari.",
		"Ho incrociato una kaldorei che dava briciole ai pesci e ho pensato: forse lei il Pozzo l'ha visto davvero. Ha gettato un'altra briciola, senza dire nulla.",
	},
	["dar.muse.w23.ancient.003"] = {
		"si ferma accanto a un'anziana che descrive i palazzi degli Highborne a due elfi più giovani, e con una mano disegna nell'aria torri che non esistono più da nessuna parte.",
		"indugia ad ascoltare una vecchia kaldorei che spiega quanto in alto costruissero gli Highborne: la sua mano sale, sale, finché chi l'ascolta alza gli occhi anche lui.",
	},
	["dar.muse.w23.ancient.004"] = {
		"Un popolo che un tempo aveva la magia più splendida del mondo ora guarda una scintilla evocata come si guarda un cane che ti ha morso da piccolo.",
		"Mostra a un kaldorei un giochetto arcano e guardagli il viso farsi immobile. Non è paura, proprio. È come riconoscere un vecchio conoscente che ha rovinato tutto.",
	},
	["dar.muse.w23.ancient.005"] = {
		"La Legione Infuocata mise piede in questo mondo, all'inizio, da una porta tenuta aperta dalla regina stessa degli elfi della notte. Qui non lo nascondono. Solo, non ci aggiungono nulla.",
		"Fu la loro stessa corte a chiamare la Legione, molto prima che un orco ne sentisse il nome. I kaldorei lo raccontano senza giri di parole e lasciano la vergogna dov'è caduta.",
	},
	["dar.muse.w23.ancient.006"] = {
		"Pensa avere una regina così pessima che il tuo popolo ne parla ancora cento secoli dopo.",
		"Ogni regno ha un sovrano che preferirebbe dimenticare. Qui non ci riescono: qualcuno se la ricorda in faccia.",
	},
	["dar.muse.w23.ancient.007"] = {
		"La vecchia pietra elfica che ho visto altrove in Kalimdor è tutta guglie aguzze e orgoglio. Quella di qui si curva e s'inchina. Ha l'aria di una lezione imparata.",
		"Le rovine sparse per Kalimdor mostrano cosa costruivano i kaldorei quand'erano superbi: aghi di pietra puntati verso l'alto. Darnassus è più bassa, più morbida, umile apposta.",
	},
	["dar.muse.w23.ancient.008"] = {
		"Le sacerdotesse custodiscono il tempio di una dea che, dicono, vide il suo popolo fare a pezzi il mondo e non lo abbandonò. Ne parlano con una fermezza che invidio.",
		"Nel Temple of the Moon parlano della guerra antica senza rancore. Elune è rimasta, dicono le sacerdotesse, anche quando i suoi figli le davano ogni ragione per andarsene.",
	},
	["dar.muse.w23.ancient.009"] = {
		"osserva un anziano kaldorei fermarsi sul bordo di una vasca e fissarla molto più a lungo di quanto meriti un riflesso, come per controllare che non ne salga qualcosa, come accadde un tempo da un'altra acqua.",
		"nota un vecchio elfo che non si avvicina mai troppo al bordo dell'acqua e la guarda da una distanza prudente, come si guarda un animale addormentato.",
	},
	["dar.muse.w23.ancient.010"] = {
		"Chiedi a un umano di una guerra di tre secoli fa e ti dà le date. Chiedi a un kaldorei di una di cento secoli fa e ti racconta chi fu sgarbato con chi a cena.",
		"La storia degli umani è re e date. Quella dei kaldorei, da quel che origlio, è soprattutto chi ha detto cosa a chi, e come l'altro l'ha presa.",
	},
	["dar.muse.w23.ancient.011"] = {
		"Non tutti gli Highborne seguirono la regina nella rovina, mi ha detto un druido. Alcuni si voltarono all'ultimo. L'ha detto con cautela, come chi difende un parente.",
		"Ci furono Highborne che ruppero con Azshara prima della fine, mi dicono. I kaldorei lo accennano di rado e in fretta, come se temessero che qualcuno porti via loro anche quella parte buona.",
	},
	["dar.muse.w23.ancient.012"] = {
		"Un'artigiana qui ricuce una cinghia con un punto che, dice, era già vecchio quando Azshara era bambina. Il punto è sopravvissuto all'impero. Le cose piccole di solito ce la fanno.",
		"La conciatrice al banco accanto ha imparato il nodo che sta facendo prima che il mondo si spezzasse. Gli imperi crollano; un buon nodo tira dritto.",
	},
	["dar.muse.w23.ancient.013"] = {
		"Ho chiesto a un'elfa com'era la guerra antica. Ha detto 'rumorosa' ed è tornata al suo tè.",
		"Ho domandato a una kaldorei della Guerra degli Antichi. Una parola sola, 'lunga', e un silenzio gentilissimo.",
	},
	["dar.muse.w23.ancient.014"] = {
		"Prima che esistessero alleanze e orde, prima che metà dei popoli avesse un nome, i kaldorei affrontarono da soli la Legione e non si spezzarono. Si vede da come stanno fermi.",
		"Combatterono la Legione Infuocata quando nessun altro in questo mondo avrebbe potuto, e vinsero a un prezzo che nessuno ha finito di pagare. Quel peso lo senti sotto la cortesia.",
	},
	["dar.muse.w23.ancient.015"] = {
		"osserva una studiosa kaldorei srotolare su una sporgenza una mappa fragile: metà della costa disegnata finisce in mare aperto, e lei liscia proprio quella metà con una cura particolare.",
		"dà un'occhiata a una vecchia mappa stesa accanto al sentiero, con coste che corrono dentro acque dove non c'è più terra, e all'elfo che ne ferma gli angoli con dei sassolini.",
	},
	["dar.muse.w23.ancient.016"] = {
		"Gli Highborne bevvero potere dal Pozzo finché non riuscirono più a smettere. Vedendo i kaldorei rifiutare perfino le piccole comodità della magia, penso che ricordino ancora quanto era buono.",
		"Dell'arcano non li spaventa la debolezza. Li spaventa che fosse meraviglioso, e che ricordino con esattezza quanto.",
	},
	["dar.muse.w23.ancient.017"] = {
		"Gli anziani kaldorei a volte si fermano a metà frase e la finiscono in una forma più vecchia della loro lingua, come se il pensiero fosse nato prima che le parole cambiassero.",
		"Un elfo anziano, a metà racconto, è passato a un modo di parlare che i giovani attorno seguivano a fatica. Certe cose, pare, si possono dire solo nella lingua in cui sono accadute.",
	},
	["dar.muse.w23.ancient.018"] = {
		"Alcuni di noi furono Highborne, o figli di Highborne. Per strada non se ne parla, ma impari a riconoscerne le mani: troppo fini, troppo ferme, in attesa di un potere che non c'è più.",
		"Tra noi ci sono vecchi che servivano a corte prima della caduta. Adesso curano giardini. Sono giardini perfetti, e non sorridono mai guardandoli.",
	},
	["dar.muse.w23.ancient.019"] = {
		"Altrove 'storia antica' vuol dire i tempi del nonno. Qui qualcuno potrebbe correggerti i dettagli.",
		"Attento a cosa dici della guerra antica, da queste parti. Potrebbe esserci un testimone ad ascoltare.",
	},
	["dar.muse.w23.ancient.020"] = {
		"I kaldorei a volte dicono 'prima' senza nient'altro, e ognuno di loro sa esattamente di quale prima si parla.",
		"Qui dicono 'prima' in un modo che non ha bisogno di altro. Prima del Pozzo, prima del mare, prima di tutto. Lo capiscono tutti.",
	},
	["dar.muse.w23.ancient.021"] = {
		"sente due anziani discutere con garbo sul colore di uno stendardo che sventolò l'ultima volta prima che il mondo si spezzasse, entrambi certissimi e nessuno dei due disposto ad alzare la voce.",
		"ascolta due vecchi kaldorei litigare, con una cortesia squisita, su quale lato di una via scomparsa stesse una certa fontana.",
	},
	["dar.muse.w23.ancient.022"] = {
		"Tyrande Whisperwind combatté nella Guerra degli Antichi, dicono le sacerdotesse, e da allora guida il suo popolo. Qualunque cosa un kaldorei chiami 'tanto tempo', comincia lì.",
		"L'Alta Sacerdotessa era già sacerdotessa quando regnava ancora Azshara, dicono le Sentinelle. I loro ordini vengono da qualcuno che ha visto tutto cominciare. Dev'essere difficilissimo spaventarle.",
	},
	["dar.muse.w23.ancient.023"] = {
		"Le pietre degli edifici kaldorei più antichi, di là a Darkshore e ad Ashenvale, sono incastrate senza malta. Anche quelle nuove di qui. Certi mestieri sopravvivono alle città che ne avevano bisogno.",
		"I tagliapietre kaldorei squadrano ancora la pietra perché combaci senza malta, alla vecchia maniera, come se le città di un tempo dovessero riconoscere i loro nipoti.",
	},
	["dar.muse.w23.ancient.024"] = {
		"Battere la Legione Infuocata e non nominarla mai. Io me lo farei scolpire sopra la porta.",
		"Se avessi respinto io la Legione Infuocata, lo racconterei a ogni cena. Qui nessuno ne parla.",
	},
	["dar.muse.w23.bench.001"] = {
		"si siede su una bassa sporgenza di pietra, si toglie uno stivale e ne fa uscire un sassolino che viaggiava con lui da tre terrazze.",
		"si ferma a bordo del sentiero, si sfila uno stivale, ne fa cadere una pietruzza e lo rimette guardando il sassolino come un traditore.",
	},
	["dar.muse.w23.bench.002"] = {
		"prende posto su un gradino e divide quel che resta nella borsa in mucchietti ordinati su un ginocchio, poi rifà tutto nel caso i mucchietti fossero sbagliati.",
		"sparge le monete su un ginocchio, separa il rame dall'argento e sospira per quanto poco ci voglia.",
	},
	["dar.muse.w23.bench.003"] = {
		"Stare {g:seduto|seduta} immobile qui pare un'arte. Mi siedo e in un attimo sto già trafficando con una cinghia. Il kaldorei sulla sporgenza accanto non si è mosso da quando ci sono io.",
		"Sto cercando di non fare niente, come fanno qui. Le mani continuano a trovare qualcosa da aggiustare.",
	},
	["dar.muse.w23.bench.004"] = {
		"prende posto su una larga radice che spunta dal sentiero proprio all'altezza di una seduta, e si chiede se qualcuno l'abbia previsto.",
		"si sistema su un ricciolo di legno vivo al bordo del sentiero; è così comodo che quasi si aspetta che si aggiusti da solo.",
	},
	["dar.muse.w23.bench.005"] = {
		"Basta sedersi abbastanza a lungo su un gradino, e la città comincia a scorrerti intorno come l'acqua attorno a un sasso. Nessuno ci fa caso. Nessuno chiede.",
		"Sono qui da così tanto che chi passa ha smesso di notarmi. Credo di far parte ormai della terrazza.",
	},
	["dar.muse.w23.bench.006"] = {
		"Due minuti {g:seduto|seduta}. Poi la banca. Poi l'addestratore. Poi forse altri due minuti.",
		"Riposo solo le gambe. Tra poco tornano in servizio. Sono state avvisate.",
	},
	["dar.muse.w23.bench.007"] = {
		"sta {g:seduto|seduta} col mento sul pugno a guardare un mercante piegare la stessa pezza di stoffa in tre modi diversi prima di tornare al primo.",
		"riposa su una sporgenza e osserva chi tiene una bancarella spostare qualche vaso, fare un passo indietro e spostarli ancora una volta, a lungo e in pace.",
	},
	["dar.muse.w23.bench.008"] = {
		"I kaldorei si siedono come se volessero restare per una stagione. Io mi siedo come chi aspetta da un momento all'altro una chiamata.",
		"Quando un elfo si siede, stare seduti è tutto lo scopo. Quando mi siedo io, è solo una pausa fra due altre faccende.",
	},
	["dar.muse.w23.bench.009"] = {
		"trova posto sull'erba per rammendare una cinghia sfilacciata, ago in mano, e continua ad alzare gli occhi come aspettandosi un rimprovero.",
		"trova un gradino tranquillo per ricucire una cucitura allentata dello zaino, lavorando piano mentre la città sbriga le sue faccende tutt'intorno.",
	},
	["dar.muse.w23.bench.010"] = {
		"si siede un momento, chiude gli occhi un momento di più, e si sveglia di soprassalto scoprendo che non è cambiato niente.",
		"si appisola con la schiena contro un pilastro e si sveglia di colpo, guardandosi intorno con aria colpevole, ma la città non se n'è nemmeno accorta.",
	},
	["dar.muse.w23.bench.011"] = {
		"Mi stanno riparando l'armatura qui dietro, con calma e molto bene. Non mi resta che aspettare e sentirmi senza vestiti addosso.",
		"Aspettare una riparazione è la commissione più strana: consegni quello che ti tiene intero e poi resti lì, cercando di darti un'aria disinvolta.",
	},
	["dar.muse.w23.bench.012"] = {
		"Di tutte le mie commissioni in questa città, sedermi è l'unica che mi riesce bene.",
		"Ho un elenco di cose da fare su ogni terrazza. Sedermi non c'è da nessuna parte, ed è l'unica che ho portato a termine.",
	},
	["dar.muse.w23.bench.013"] = {
		"sul muretto di un'aiuola mangia un panino semplice preso dallo zaino, con grande cura, per non far cadere briciole su qualcosa di così ordinato.",
		"mangia qualcosa dallo zaino su un gradino accanto al sentiero, raccogliendo ogni briciola nel palmo della mano.",
	},
	["dar.muse.w23.bench.014"] = {
		"Aspettare a Darnassus è diverso. Nessuno sospira, nessuno sposta il peso da un piede all'altro, nessuno controlla niente. Faccio io da orologio a tutta la terrazza.",
		"Ho aspettato il mio turno al banco per un po' e ho notato che in fila ero l'unica persona a sapere che il tempo passava.",
	},
	["dar.muse.w23.bench.015"] = {
		"Bel posto. Me lo tengo. Chi lo vuole aspetti. Con pazienza. Alla maniera del posto.",
		"Non fate caso a me. Sto solo aspettando che i piedi tornino a rivolgermi la parola.",
	},
	["dar.muse.w23.bench.016"] = {
		"Appena mi siedo, il dolore alle gambe ha finalmente tutta la mia attenzione. E ha parecchio da dire.",
		"Nel momento in cui mi siedo, ogni terrazza che ho attraversato mi risale su dalle piante dei piedi.",
	},
	["dar.muse.w23.bench.017"] = {
		"si siede in disparte e guarda altri visitatori correre dalla bancarella alla banca e poi di corsa alla bancarella, riconoscendo ogni loro errore.",
		"si appollaia su un gradino e guarda un nano chiedere la stessa strada a tre persone diverse, provando per lui un affetto enorme.",
	},
	["dar.muse.w23.bench.018"] = {
		"Nessuna fretta. Resto qui a invecchiare con eleganza. Be', a invecchiare.",
		"Faccia con calma. Io di tempo ne ho... be', parecchio meno di lei, ma prego.",
	},
	["dar.muse.w23.bench.019"] = {
		"indugia al margine della Tradesmen's Terrace senza più niente da comprare, guardando dimagrire le borse degli altri.",
		"aspetta a lato della terrazza mentre alla bancarella più vicina si svolge una vendita lunga e meticolosa, e perde del tutto interesse per la propria commissione.",
	},
	["dar.muse.w23.bench.020"] = {
		"I Temple Gardens sono l'unico posto della città dove smetto di fingere di avere commissioni. Mi siedo, e la lista in tasca può aspettare.",
		"In questi giardini nessuno sta andando da nessuna parte in particolare, e per una volta nemmeno io.",
	},
	["dar.muse.w23.bench.021"] = {
		"aspetta sotto un ampio arco che la pioggia si calmi, e guarda un kaldorei passeggiarci attraverso come se non ci fosse.",
		"lascia passare la pioggia sotto una sporgenza, zaino sulle ginocchia, contando le gocce che riescono a filtrare tra le foglie.",
	},
	["dar.muse.w23.bench.022"] = {
		"Stare {g:fermo|ferma} in questa città è la parte più difficile. Camminando sembro chiunque abbia una commissione. Da {g:seduto|seduta} sembro quel che sono: qualcuno dell'Orda in una capitale elfica.",
		"Riposerei le gambe, ma riposare vuol dire farsi guardare. Continuo a camminare, piano, come chiunque abbia da fare in banca.",
	},
	["dar.muse.w23.bench.023"] = {
		"Qui sono dell'Alleanza, e mi accolgono bene a ogni banco. Eppure a ognuno chiedo scusa: per gli stivali, per i bagagli, per la voce.",
		"I kaldorei sono stati soltanto cortesi, in banca e alle bancarelle. Io continuo a ringraziare due volte, come se la cortesia potesse finire.",
	},
	["dar.muse.w23.bloom.001"] = {
		"Lungo le ringhiere cresce un fiore pallido che non si apre mai più di metà. Ho chiesto a un'elfa perché. Mi ha risposto che è per pudore, e non ho capito se scherzasse.",
		"Accanto ai sentieri c'è un fiore che resta socchiuso qualunque cosa tu faccia. Un giardiniere mi ha detto che si apre del tutto solo per chi non lo fissa. Ho smesso di fissarlo. Non si è aperto.",
	},
	["dar.muse.w23.bloom.002"] = {
		"indugia accanto a un'aiuola che ronza di api, e nota che le api, a differenza di qualunque altra cosa in città, vanno di gran fretta.",
		"sosta presso un'aiuola piena di api, il rumore più indaffarato per un bel tratto, e le guarda lavorare i fiori come se l'albero intero stesse per chiudere bottega.",
		"segue il ronzio delle api fino a un cespuglio così carico di fiori che i rami non si vedono, e le api non si contano.",
	},
	["dar.muse.w23.bloom.003"] = {
		"Un profumo dolce e pesante si infila in ogni angolo della città, perfino in banca. Ho smesso di accorgermene. Me ne accorgerò sulla strada, quando non ci sarà più.",
		"C'è un fiore, chissà dove, il cui profumo arriva ovunque: la banca, le bancarelle, i ponti. La pianta non l'ho mai trovata. Comincio a pensare che sia l'albero intero.",
	},
	["dar.muse.w23.bloom.004"] = {
		"Quel fiore è più grosso della mia testa e profuma meglio di tutto il mio zaino.",
		"Annuserei quel fiore, ma ha l'aria di uno che potrebbe annusare me.",
	},
	["dar.muse.w23.bloom.005"] = {
		"Sulla Craftsmen's Terrace gli erboristi appendono mazzi di fiori a testa in giù a seccare, e le bancarelle sanno di un prato che qualcuno ricorda piano piano.",
		"Le rastrelliere degli erboristi, là sulla Craftsmen's Terrace, sono cariche di fiori appesi a testa in giù. Ci passi accanto e il profumo ti segue per mezza città.",
	},
	["dar.muse.w23.bloom.006"] = {
		"guarda un unico petalo viola posarsi sul libro aperto di uno scrivano di passaggio, che continua a leggergli attorno invece di scostarlo.",
		"alza gli occhi su una Sentinella di guardia proprio mentre un petalo le si posa sulla spalla; lei lo lascia lì, e il petalo resta.",
	},
	["dar.muse.w23.bloom.007"] = {
		"Dalle commessure della pietra spuntano fiori, là dove in qualunque città umana ci sarebbero erbacce. Forse non c'è differenza. Forse qui parlano solo meglio.",
		"Ogni crepa nella pietra chiara ha il suo fiore. A Stormwind sarebbe lavoro per qualcuno con la zappa. Qui sembra proprio lo scopo.",
		"Un fiore cresce da una crepa sui gradini della banca, e chiunque entri lo aggira, impiegati e clienti allo stesso modo.",
	},
	["dar.muse.w23.bloom.008"] = {
		"Alcuni di questi fiori vengono da Hyjal, dicono i druidi: semi portati via dalla cenere e piantati qui. Non so se sia vero. Mi fermo a guardarli comunque.",
		"Un druido una volta mi ha indicato un'aiuola di piccoli fiori bianchi e mi ha detto che crescevano sulle pendici di Hyjal prima dell'incendio. Ogni tanto vado a trovarli. Loro non sanno a cosa sono sopravvissuti.",
	},
	["dar.muse.w23.bloom.009"] = {
		"Lo senti? No, l'altro. No, quello viola. ...Sono tutti viola, vero?",
		"Da che fiore viene questo profumo? Lascia stare. Ho appena notato che sono viola dal primo all'ultimo.",
	},
	["dar.muse.w23.bloom.010"] = {
		"Lungo l'acqua ci sono alberi da frutto che nessuno sembra raccogliere. Ci pensano gli uccelli, rumorosamente, e i noccioli li lasciano sui ponti perché ci inciampi qualcun altro.",
		"Frutti piccoli pendono sopra i sentieri a grappoli, maturi e mai colti. O i kaldorei non hanno fame, o aspettano il momento perfetto, e potrebbe volerci un po'.",
	},
	["dar.muse.w23.bloom.011"] = {
		"si inginocchia al bordo di un'aiuola dei Temple Gardens dove un fiore piegato è stato sostenuto con un rametto e una striscia di stoffa, curato come un malato.",
		"nota, qui nei giardini, un unico stelo afflosciato legato con delicatezza a una stecca di canna, e gli gira largo intorno, come si fa con il letto di un malato.",
	},
	["dar.muse.w23.bloom.012"] = {
		"Ho sfiorato così tante aiuole che ho gli stivali impolverati d'oro di polline. Lascio una scia leggera ovunque vada, come un ladro molto sbadato.",
		"Ho le maniche gialle fino al gomito a forza di appoggiarmi a ringhiere avvolte di fiori. Chiunque potrebbe seguirmi per tutta la città solo dal polline.",
	},
	["dar.muse.w23.bloom.013"] = {
		"I fiori vicino alle lampade si piegano tutti verso di loro, nessuno escluso, come se le lampade fossero tutto il cielo di cui hanno bisogno.",
		"Pianta un fiore accanto a una lampada di Darnassus e quello volge la faccia al chiarore e ce la tiene. Ho visto gente fare lo stesso davanti a un fuoco dopo una lunga strada.",
		"Una lampada accanto al sentiero ha un anello di fiori ai piedi, tutti con la faccia rivolta in su, come bambini che ascoltano una storia.",
	},
	["dar.muse.w23.bloom.014"] = {
		"Un erborista raccoglieva foglie lungo il sentiero, una da ogni pianta e mai due. Ci ha messo un'eternità. Alle piante basterà un attimo per perdonare.",
		"Ho guardato un erborista kaldorei percorrere una fila di piante prendendo una sola foglia da ciascuna, senza ringraziarne nessuna ad alta voce, anche se aveva tutta l'aria di un ringraziamento.",
	},
	["dar.muse.w23.bloom.015"] = {
		"Qui sulla Craftsmen's Terrace alcuni sarti tengono vasi di petali pestati per le tinture, e ogni mano al lavoro è macchiata di una sfumatura di viola fino al polso.",
		"I vasi di tintura su questa terrazza sanno di un giardino lasciato in infusione. Un sarto ci ha immerso un taglio di stoffa e l'ha tirato fuori del colore delle lampade.",
	},
	["dar.muse.w23.bloom.016"] = {
		"si china ad annusare un fiore grande come due mani a coppa, e si raddrizza col naso spolverato di giallo e un'aria di grande dignità.",
		"si avvicina a un enorme fiore pallido, starnutisce una volta e riprende a camminare come se niente fosse, mentre una Sentinella che passa quasi sorride.",
	},
	["dar.muse.w23.bloom.017"] = {
		"Ogni fiore di questa città è in un certo senso una prima generazione: semi che non hanno mai conosciuto altra terra che un ramo alto sopra il mare. E se la cavano.",
		"I fiori di qui sono cresciuti soltanto su un albero. Nessun campo, nessuna collina, nessuna valle nel loro passato. Non si vede. Fioriscono come se nessuno gliel'avesse detto.",
	},
	["dar.muse.w23.bloom.018"] = {
		"Nelle anse quiete dei ruscelli galleggiano ninfee ben chiuse. Una Sentinella mi ha detto che si aprono solo quando nei paraggi nessuno ha fretta. Forse è per questo che non ne ho mai vista una aperta.",
		"Certi fiori di qui si chiudono quando ti ci chini sopra e si riaprono appena te ne sei andato. Ho deciso di non prenderla sul personale.",
		"Il fiore qui accanto era un bocciolo quando ho preso posto, e adesso è aperto. In questa città potrei credere che aspettasse solo che guardassi altrove.",
	},
	["dar.muse.w23.bloom.019"] = {
		"Starnutisco dall'ultimo ponte. C'è un fiore in questa città che è molto soddisfatto di sé.",
		"Ogni aiuola di Darnassus mi ha fatto starnutire almeno una volta. Sono molto scrupolose.",
	},
	["dar.muse.w23.bough.001"] = {
		"I grandi rami non si limitano a reggere la città: la dividono. Uno sotto, uno sopra, e un'intera terrazza che vive nello spazio fra i due, come su un ripiano di credenza.",
		"Darnassus sta sull'albero come i libri sugli scaffali: un ramo sotto ogni terrazza, un altro sopra, e la città riposta in ordine nel mezzo.",
		"Ogni angolo di questa città ha un soffitto di ramo e un pavimento di ramo. Ho smesso di pensarli come piani: somigliano piuttosto a cassetti.",
	},
	["dar.muse.w23.bough.002"] = {
		"segue con lo sguardo il ventre di un grande ramo, dal punto in cui lascia il tronco a quello in cui si perde, e lungo la strada conta tre muschi diversi.",
		"osserva il lato inferiore di un ramo altissimo, chiaro e solcato come la pancia di una balena, e scopre piccole felci radicate nelle sue pieghe.",
	},
	["dar.muse.w23.bough.003"] = {
		"Su un ramo così ci sono nidi più grandi dell'ultima stanza che ho preso in affitto. Immagino che gli uccelli paghino meno.",
		"Lassù, su quel ramo, ci sono nidi grandi come un carro da fieno. Qualcuno se la passa meglio di me.",
		"Gli uccelli di Teldrassil costruiscono in proporzione. In uno di quei nidi lassù ci starebbe comodo un pony.",
	},
	["dar.muse.w23.bough.004"] = {
		"Una conciatrice mi ha detto che la sua porta quest'anno è più stretta di un dito rispetto all'anno scorso. Non sembrava seccata: il ramo «si sta sistemando», ha detto, come si dice di un ospite.",
		"Un'artigiana giura che la sua porta si è spostata da quando ci abita: il ramo che la regge si piega, un capello a stagione. Ne parla con affetto, come di un gatto che dorme sulla sedia sbagliata.",
		"Qui le porte non sono cose del tutto ferme, ho scoperto. Un'artigiana mi ha mostrato dove ha dovuto limare lo stipite perché il legno attorno era cresciuto. Sembrava fiera del legno.",
	},
	["dar.muse.w23.bough.005"] = {
		"Che nessuno dica al ramo quanto peso gli hanno messo addosso. Sembra contento di non saperlo.",
		"Un'intera città appoggiata a un ramo, e il ramo non si è lamentato una volta. Avrei da imparare.",
		"Banca, locanda, tempio, tutto su un ramo. Qualcuno si è fidato parecchio di questo legno.",
	},
	["dar.muse.w23.bough.006"] = {
		"osserva una Sentinella che avanza su un ramo largo come una strada fin dove si assottiglia, guarda qualcosa in lontananza e torna indietro senza fretta.",
		"nota una figura lontana su un ramo in alto, piccola come un'unghia contro le foglie, e solo dopo un po' capisce che è una Sentinella di ronda.",
		"scorge, alta su un ramo dove nessun sentiero sembra arrivare, una Sentinella seduta con le gambe nel vuoto, tranquilla lassù come sul muretto di un giardino.",
	},
	["dar.muse.w23.bough.007"] = {
		"scosta una tenda di liane che pende da un ramo sopra il sentiero; dietro, un kaldorei fa lo stesso col dorso della mano, senza nemmeno alzare gli occhi.",
		"si china sotto una frangia di liane che pendono dall'alto e, per ringraziamento, si ritrova una foglia giù per il colletto.",
		"scosta un lungo rampicante e scopre che è fiorito per tutta la lunghezza di piccoli fiori chiari, aperti sul lato lontano dal sentiero.",
	},
	["dar.muse.w23.bough.008"] = {
		"Ho cominciato a orientarmi coi rami. Quello grosso porta verso la banca, quello biforcuto indica un posto dove non sono mai {g:stato|stata}. È l'unica mappa che questa città conceda.",
		"Ogni ramo là sopra parte dal tronco come il raggio di una ruota. Seguine uno con gli occhi abbastanza a lungo e sai dov'è il centro del mondo, almeno quassù.",
	},
	["dar.muse.w23.bough.009"] = {
		"Due rami si sono incrociati sopra il sentiero e, semplicemente, sono cresciuti l'uno nell'altro. Nessuno l'ha deciso, oppure qualcuno l'ha deciso con moltissima pazienza.",
		"Lassù c'è un punto dove due rami si sono incontrati e fusi, con la cucitura ancora visibile come su una manica rammendata. Ogni volta che passo alzo gli occhi, come si guardano due vecchi sposi che si tengono ancora per mano.",
		"Qui i rami che si toccano non si sfregano: si uniscono. Ho visto già tre punti in cui due rami ne sono diventati uno, e nessuno dei due sembrava farne un dramma.",
	},
	["dar.muse.w23.bough.010"] = {
		"Non state troppo col naso all'insù, in questa città. Trovate un ramo, poi un altro sopra, e restate qui fino alla prossima stagione.",
		"Guardare in alto una volta va bene. Due volte, e hai perso un'ora a contare rami.",
		"Mai alzare gli occhi a Darnassus, se avete fretta. C'è sempre un ramo in più.",
	},
	["dar.muse.w23.bough.011"] = {
		"Ogni ramo, qui, potrebbe nascondere un arco. Ad Ashenvale lo prenderei per una minaccia. Qui è solo un motivo in più per tenere il cappuccio basso e la bocca chiusa.",
		"Giù ad Ashenvale i Warsong abbattono alberi come questo per farne legname. Sotto un ramo vivo così grande, nel cuore della loro città, quel pensiero lo tengo ben zitto.",
	},
	["dar.muse.w23.bough.012"] = {
		"Sdraiati sulla schiena e fissa abbastanza a lungo: i rami lassù cominciano a girare piano, come un soffitto dopo il terzo bicchiere. Sono io a muovermi, si capisce. Quasi certamente.",
		"Mi sono {g:sdraiato|sdraiata} sull'erba a guardare i rami finché sembravano andare alla deriva. Lassù non si muoveva niente. Niente che potessi dimostrare.",
	},
	["dar.muse.w23.bough.013"] = {
		"Su quel ramo ci sono un gufo, due scoiattoli e una Sentinella, e non è nemmeno uno dei grossi.",
		"Qualunque ramo, qui, reggerebbe una casa. Alcuni lo fanno.",
	},
	["dar.muse.w23.bough.014"] = {
		"Ho scelto un ramo sopra di me e ho deciso che, per il tempo di una sosta, era mio. Nessuno ha obiettato. Credo che qui nessuno obietti mai a cose del genere.",
		"Sotto quel ramo in particolare c'è un pezzo di pavimento che ho cominciato a considerare il mio posto. L'albero non lo sa. Spero che non gli dispiacerebbe.",
		"A Darnassus ognuno ha bisogno di un ramo preferito. Il mio è storto, basso e senza niente di speciale: proprio per questo nessun altro l'ha reclamato.",
	},
	["dar.muse.w23.bough.015"] = {
		"segue un ramo che si abbassa fino a sfiorare il tetto di una sala, e lì è semplicemente cresciuto dentro il tetto, diventandone parte.",
		"si accorge che una delle sale non ha un confine netto fra il punto in cui finisce il tetto e quello in cui comincia il ramo che la sovrasta.",
		"risale con gli occhi la linea di un tetto e la vede trasformarsi, senza una giuntura, nel ramo che lo sostiene.",
	},
	["dar.muse.w23.bough.016"] = {
		"nota un uccello che saltella lungo un ramo altissimo, così minuscolo al confronto da sembrare una briciola che cammina su un tavolo.",
		"guarda uno scoiattolo correre lungo un grande ramo e continuare, e continuare ancora, ben oltre il punto in cui qualunque altro scoiattolo sarebbe arrivato in fondo.",
		"segue uno scoiattolo su un ramo in alto finché quello sparisce alla vista, sempre sullo stesso ramo.",
	},
	["dar.muse.w23.bough.017"] = {
		"Bel ramo, questo. Regge una città e non si piega. Ho visto ponti con meno carattere.",
		"Qualcuno dovrebbe ringraziare questo ramo. Ufficialmente. Con una targa.",
		"Se mai mi farò una casa, voglio che la costruisca chi ha convinto questo ramo a reggere una città.",
	},
	["dar.muse.w23.courtesy.001"] = {
		"ricambia il piccolo inchino di un kaldorei ma lo fa un po' troppo profondo; l'elfo, gentile, si piega appena di più, perché nessuno dei due resti in fallo.",
		"risponde a un cenno con un inchino troppo basso, e vede l'elfa correggersi con un lievissimo chinare del capo, per andare incontro all'ospite a metà strada.",
		"ricambia l'inchino di un elfo di passaggio, poi si chiede se fosse un saluto o un congedo, e si inchina un'altra volta per coprire entrambi i casi.",
	},
	["dar.muse.w23.courtesy.002"] = {
		"A Darnassus nessuno fissa. Guardano, brevemente e per intero, poi distolgono gli occhi: in qualche modo è un esame più accurato.",
		"I kaldorei non restano mai a bocca aperta. Un'occhiata chiara, come si legge un'insegna, e hanno finito. Mi hanno letto, e archiviato.",
	},
	["dar.muse.w23.courtesy.003"] = {
		"Un mercante umano ha teso la mano a una kaldorei. Lei l'ha guardata, poi ha guardato lui, e per un istante gli ha posato due dita sul polso. Una stretta di mano, tradotta.",
		"Ho visto un elfo accogliere la stretta di mano di un nano come si accetta un regalo strano: con garbo, in fretta, e pensando bene a cosa farne dopo.",
	},
	["dar.muse.w23.courtesy.004"] = {
		"Perdonate. Mi dicono che cammino come un intero squadrone di cavalleria. Cercherò di avere il passo più leggero.",
		"Scusate il rumore. I miei stivali non sono fatti per una città così attenta.",
		"Scusate. Ero io? Sì, ero io. Farò più piano.",
	},
	["dar.muse.w23.courtesy.005"] = {
		"Ogni rifiuto kaldorei che ho incontrato arriva incartato come un consiglio. 'Forse la Tradesmen's Terrace fa più al caso vostro.' Ed è così. Lo è sempre.",
		"Qui nessuno dice di no a un visitatore. Dicono 'forse altrove' con un tale calore che li ringrazio prima di capire che era un congedo.",
	},
	["dar.muse.w23.courtesy.006"] = {
		"si vede offrire una coppa d'acqua fresca da un'elfa sulla soglia, senza alcuna spiegazione, e la beve sotto uno sguardo paziente e soddisfatto.",
		"accetta una ciotola d'acqua da un kaldorei che non chiede nulla in cambio, e solo dopo aver bevuto capisce che il senso era proprio quello.",
	},
	["dar.muse.w23.courtesy.007"] = {
		"I kaldorei aspettano un attimo dopo che qualcuno ha finito di parlare, casomai ci fosse dell'altro. I visitatori si affrettano a riempire quella pausa, e gli elfi li lasciano fare con garbo.",
		"Qui dopo ogni frase resta un piccolo silenzio, tenuto aperto come una porta per quello che volevi ancora dire. Quasi tutti gli ospiti ci passano davanti senza vederlo.",
	},
	["dar.muse.w23.courtesy.008"] = {
		"Grazie. E grazie ancora. Smetto, giuro: credo di averti ringraziato fino alla prossima stagione.",
		"Ti ho detto grazie tre volte e tu hai annuito tre volte. Diciamo che siamo pari?",
		"Eccomi a ringraziarti un'altra volta. Si direbbe che le buone maniere le abbia scoperte cinque minuti fa.",
	},
	["dar.muse.w23.courtesy.009"] = {
		"Una Sentinella è uscita dal sentiero per farmi passare. Io ho fatto lo stesso dall'altro lato, per far passare lei. Il sentiero è rimasto vuoto fra noi finché non ha sorriso per prima.",
		"Due persone che si cedono il passo nello stesso momento lasciano il sentiero deserto. Così ho passato un lungo istante sul muschio, davanti a un druido cortesissimo che faceva altrettanto.",
	},
	["dar.muse.w23.courtesy.010"] = {
		"segue il tentativo di uno gnomo di fare il gesto a palmo aperto con cui i kaldorei ringraziano, e produrre, con grande sincerità, qualcosa di più simile a scacciare una vespa.",
		"sorprende un nano a provare il lento ringraziamento con la mano al petto degli elfi intorno a lui, farlo al contrario, ed essere ringraziato per lo sforzo con lo stesso gesto, fatto come si deve.",
	},
	["dar.muse.w23.courtesy.011"] = {
		"Qui nessuno mi ha chiesto come mi chiamo. Non per freddezza: credo che a Darnassus il nome sia una cosa che si offre, e nessuno si sognerebbe di prenderlo.",
		"Nelle altre città gli sconosciuti vogliono il tuo nome, i tuoi affari e la tua strada. Qui non vogliono niente, e aspettano, nel caso tu voglia dare qualcosa.",
	},
	["dar.muse.w23.courtesy.012"] = {
		"In tutto questo tempo nessun kaldorei mi ha invitato da qualche parte, e nessuno mi ha chiuso fuori da niente. È una libertà strana, e un po' solitaria.",
		"Aiutano l'ospite a trovare qualsiasi cosa, gli spiegano qualsiasi cosa, gli portano qualsiasi cosa. Quello che non fanno è chiedergli di sedersi. Le loro tavole restano loro.",
	},
	["dar.muse.w23.courtesy.013"] = {
		"Abbassa la voce. No, di più. Io l'ho detto così e una sacerdotessa si è girata.",
		"Sussurra. Qui sussurrano tutti. Sì, anche sul prezzo del formaggio.",
		"Shh. Persino la fontana fa piano, ed è una fontana.",
	},
	["dar.muse.w23.courtesy.014"] = {
		"si ferma ai piedi di una passerella stretta per lasciar passare per primo un anziano kaldorei, e riceve un cenno così lento da durare quanto la traversata.",
		"aspetta accanto a un ponticello stretto che un vecchio elfo lo attraversi senza alcuna fretta, e dall'altra parte si guadagna uno sguardo lungo e pieno di approvazione.",
		"lascia passare per prima una sacerdotessa su una scala stretta e ne riceve un mormorio in darnassiano che somiglia molto a un'approvazione.",
	},
	["dar.muse.w23.courtesy.015"] = {
		"Quando le sacerdotesse si inginocchiano non so mai se inginocchiarmi con loro o allontanarmi. Mi limito a restare immobile, cosa che non sembra offendere nessuno.",
		"Una sacerdotessa raccolta nel suo rito, e io accanto con le mani che non sanno dove stare. Alla fine le ho intrecciate e ho aspettato, ospite del raccoglimento di un altro.",
	},
	["dar.muse.w23.courtesy.016"] = {
		"Ho provato a dare una moneta all'elfa che mi aveva indicato la strada. L'ha guardata come se le avessi dato un sassolino dallo stivale, e me l'ha resa con enorme gentilezza.",
		"Offri del denaro a un kaldorei per una gentilezza e te lo ritrovi in mano, insieme a uno sguardo che fa sembrare la moneta piccolissima.",
	},
	["dar.muse.w23.courtesy.017"] = {
		"raccoglie un rocchetto di filo rotolato giù da una bancarella e lo restituisce, e riceve un ringraziamento così serio e completo che il piccolo gesto sembra diventare più grande.",
		"riporta a un elfo il cesto che aveva posato e dimenticato, e riceve un inchino che starebbe bene a un favore molto più grande.",
	},
	["dar.muse.w23.courtesy.018"] = {
		"Si fa l'inchino a un druido che al momento è un gatto? Io l'ho fatto. Il gatto ha avuto l'aria di gradire.",
		"Ho salutato con un cenno un cervo vicino al sentiero, caso mai fosse qualcuno. Ha ricambiato, il che non chiarisce niente.",
	},
	["dar.muse.w23.courtesy.019"] = {
		"Permesso, scusi, pardon. Ecco tutto il mio darnassiano, ed è tutto in Comune.",
		"È scortese chiedere la strada due volte? Lo chiedo per un amico. L'amico sono io.",
		"Scusi, mi indica la banca? E magari poi me la indica un'altra volta, più piano?",
	},
	["dar.muse.w23.courtesy.020"] = {
		"Attento ai fiori. E al muschio. E, a dirla tutta, a tutto.",
		"Non sederti lì. Non so perché, ma lì non si siede nessuno.",
		"Fa' come me. Io copio l'elfo qui davanti, quindi è una specie di esempio.",
	},
	["dar.muse.w23.courtesy.021"] = {
		"Grazie di non aver riso. O di aver riso così piano che non l'ho sentito.",
		"Hai avuto molta pazienza con me. Ho il sospetto che tu ci abbia fatto parecchia pratica.",
	},
	["dar.muse.w23.courtesy.022"] = {
		"allunga la mano per abitudine a tenere la porta all'elfo che segue, trova solo un arco aperto, e trasforma il gesto in una specie di ampio invito a passare.",
		"fa per tenere aperta una porta che si rivela un arco aperto di legno vivo, e riceve comunque un ringraziamento per il gesto.",
	},
	["dar.muse.w23.courtesy.023"] = {
		"La cortesia kaldorei non è nata per gli ospiti. È nata per un popolo destinato a vivere accanto agli stessi vicini per migliaia di anni. I visitatori se la prendono solo in prestito.",
		"Quando dividi una strada con qualcuno per qualche migliaio di anni, impari a non dire mai la cosa che non si può ritirare. Credo che tutta questa educazione sia questo.",
	},
	["dar.muse.w23.courtesy.024"] = {
		"si tiene ai margini del pavimento del tempio, fuori dal passaggio delle sacerdotesse, come un ospite resta accanto al muro durante i riti di un altro popolo.",
		"si ferma appena dentro il Temple of the Moon e non va oltre, nel dubbio su quanto possa spingersi chi è in visita, finché un piccolo gesto di una sacerdotessa non fa cenno di proseguire.",
	},
	["dar.muse.w23.courtesy.025"] = {
		"Qui nei Temple Gardens un giardiniere kaldorei ha spostato un vaso di un dito perché uno gnomo passasse senza sfiorare i petali. Nessuno dei due ne ha fatto parola.",
		"Ogni visitatore nei Temple Gardens cammina come se portasse una ciotola piena: gomiti stretti, occhi bassi, attento a ogni stelo.",
	},
	["dar.muse.w23.crown.001"] = {
		"I re portano corone piene di gemme. Quest'albero ne porta una con dentro una banca, una casa d'aste e una locanda. Direi che ci ha guadagnato.",
		"La chiamano la corona di Teldrassil. Se mai l'albero decidesse di togliersela, gradirei un preavviso.",
		"Una corona, chiamano la città. Di solito le corone pesano sulla testa che le porta. Quest'albero non sembra accorgersene.",
	},
	["dar.muse.w23.crown.002"] = {
		"Da un varco ai margini della città ho visto un uccello volare sotto di me, molto più in basso, di schiena. Mi ci è voluto un momento per capire perché mi sembrasse così sbagliato.",
		"Laggiù ci sono falchi che girano in tondo sotto la città. Sono {g:abituato|abituata} a guardarli dal basso. Guardarli dall'alto mette le ginocchia di cattivo umore.",
		"Oltre il bordo della terrazza gli uccelli sbrigano le loro faccende voltandomi la schiena. Li ho guardati a lungo, con la strana sensazione di spiarli.",
	},
	["dar.muse.w23.crown.003"] = {
		"si appoggia a un parapetto sul bordo della chioma e guarda giù, e continua a guardare, oltre foglie e rami e altre foglie, finché l'occhio rinuncia a trovare il fondo.",
		"si sporge dal bordo di una terrazza verso le profondità verdi dell'albero, dove i rami di sotto continuano all'infinito, ognuno più piccolo e più azzurro del precedente.",
	},
	["dar.muse.w23.crown.004"] = {
		"La città sta nella chioma, ma la chioma non finisce con la città. Sopra l'ultima terrazza l'albero continua a salire, e nessuno di quelli a cui ho chiesto è mai stato lassù.",
		"Ho chiesto a una Sentinella cosa c'è sopra il ramo più alto. Ha guardato in su con me per un bel po' e poi ha detto: «Altro albero.» Credo fosse una battuta.",
		"Sopra Darnassus c'è più Teldrassil di quanto se ne parli. La città è ospite della chioma, non tutta la sua famiglia.",
	},
	["dar.muse.w23.crown.005"] = {
		"Apprezzerei se la gente smettesse di ricordarmi quanto è lontano il mare, laggiù.",
		"Una città in cima a un albero, mi dicono, con orgoglio. Come se fosse una consolazione.",
		"Bella vista. Basta non guardarla dritta in giù.",
	},
	["dar.muse.w23.crown.006"] = {
		"Pare che Fandral Staghelm abbia voluto la città nella chioma, ben al di sopra di tutto ciò che cammina. Dopo Hyjal, non mi sento di dargli torto.",
		"Metti una città in cima a un albero, e chiunque voglia bruciarla deve prima arrampicarsi parecchio. A Hyjal i kaldorei hanno imparato qualcosa, e a caro prezzo.",
		"Una capitale fuori dalla portata di ogni esercito in marcia. Scommetto che chi ha scelto la chioma per Darnassus pensava al fuoco.",
	},
	["dar.muse.w23.crown.007"] = {
		"alza gli occhi dalla terrazza e, per una volta, non vede neanche un ramo dell'albero che {g:lo|la} regge: solo foglie, e la città adagiata in mezzo come un uovo nel nido.",
		"si ferma a una curva del sentiero e osserva come le terrazze stiano raccolte nella chioma, ognuna tenuta con la cura che si ha per un uovo.",
	},
	["dar.muse.w23.crown.008"] = {
		"Abbiamo messo la nostra città dove vivono i gufi e le asce non arrivano. Qualcuno la chiama superbia. Io la chiamo memoria.",
		"Quassù le asce dei Warsong sono lontane un mare e una foresta. La nostra chioma è l'unico posto di Kalimdor dove riposo senza tendere l'orecchio.",
	},
	["dar.muse.w23.crown.009"] = {
		"Dal bordo della città si vedono altre parti della chioma, isole verdi di foglie dove non abita nessuno, e mi ritrovo a chiedermi per chi le tengano in serbo.",
		"Darnassus occupa solo una parte della chioma. Il resto è vuoto, verde e paziente, come le stanze di una casa costruita per una famiglia che deve ancora arrivare.",
		"Gran parte della chioma è disabitata. O i kaldorei contano di crescere, o amano tenersi attorno parecchio silenzio. Forse tutte e due le cose.",
	},
	["dar.muse.w23.crown.010"] = {
		"Splendida vista. Me la godrei di più se non ricordassi su cosa poggia.",
		"Se mai dovessi cadere da questa città, dite pure che è stata colpa dell'albero.",
		"Quassù ogni moneta che cade è un lungo addio.",
	},
	["dar.muse.w23.crown.011"] = {
		"Le sacerdotesse dicono che la città fu innalzata così in alto per stare più vicina a Elune. Non so come una dea misuri le distanze, ma loro qui camminano come se lei fosse vicina.",
		"Una sacerdotessa mi ha detto, senza ombra di sorriso, che la chioma di un albero è il posto giusto per un tempio: il più lontano dalla polvere che un popolo riesca a salire.",
	},
	["dar.muse.w23.crown.012"] = {
		"allunga il collo per trovare la cima della chioma e ne trova solo altra, foglia sopra foglia come le scaglie di qualcosa di enorme che dorme.",
		"dopo un po' rinuncia a vedere la cima dell'albero e si massaggia la nuca, {g:sconfitto|sconfitta}.",
		"piega la testa sempre più all'indietro, cercando dove finiscono le foglie, finché un kaldorei di passaggio alza gli occhi anche lui, per cortesia, a vedere quale sia il problema.",
	},
	["dar.muse.w23.crown.013"] = {
		"Vivere in cima a un albero rende tutto ciò che sta sotto una specie di diceria. Darkshore, Ashenvale, l'intera Kalimdor: una macchia verde e qualche racconto.",
		"Quassù nella chioma il resto del mondo diventa sentito dire. Devo ricordarmi che laggiù ci sono strade, e gente che le percorre.",
		"Da quassù i guai di Kalimdor suonano lontanissimi, come una lite in un'altra casa. So che non è così. Ma è piacevole lo stesso.",
	},
	["dar.muse.w23.crown.014"] = {
		"Una chioma è un posto strano per un inizio. Quasi tutte le città nascono presso un fiume o un guado. Questa è nata in cima, e tutto il resto è toccato salirlo.",
		"Tutte le città che conosco sono cresciute dalle fondamenta. Darnassus, a pensarci, è cresciuta dal tetto in giù, e del suolo non si è curato granché nessuno.",
	},
	["dar.muse.w23.crown.015"] = {
		"guarda dal bordo della città il successivo grande ramo della chioma, un'isola di foglie sospesa nell'aria con nient'altro sotto.",
		"segue con lo sguardo un ramo che lascia il margine della città e si allunga sul vuoto, avanti e avanti, come se l'albero tendesse un braccio verso Darkshore.",
		"posa entrambe le mani su un parapetto e osserva un ramo lontano della chioma, così distante che le sue foglie si confondono in un'unica, morbida nuvola verde.",
	},
	["dar.muse.w23.crown.016"] = {
		"In cima all'albero. Da qui tutta Kalimdor è in discesa, il che consola finché non pensi alla strada per risalire.",
		"Occhio al bordo, eh. Fino ai piedi di quest'albero c'è parecchia strada, e nessun modo morbido di farla.",
		"Il posto più alto della casa. Peccato per la salita.",
	},
	["dar.muse.w23.custom.001"] = {
		"Una Sentinella mi ha detto che durante la guardia non pronunciano i nomi delle cadute. Dopo, fuori servizio, li dicono tutti, in ordine, e adesso ci vuole molto.",
		"Fra le Sentinelle c'è un'usanza, mi dicono: i nomi dei morti si tengono per dopo la guardia. Ashenvale ha allungato parecchio quell'elenco.",
	},
	["dar.muse.w23.custom.002"] = {
		"Una druida mi ha raccontato che certi kaldorei anziani versano ancora una goccia d'acqua per l'albero prima di bere. L'ha detto come se fosse un po' imbarazzante, e come se lo facesse anche lei.",
		"Alcuni anziani rovesciano un po' d'acqua a terra prima di bere, ha detto una druida: l'albero beve per primo. Ho notato che lo faceva anche lei, in fretta, quando non avrei dovuto guardare.",
	},
	["dar.muse.w23.custom.003"] = {
		"In Darnassus nessuno accende un fuoco alla leggera. Una Sentinella l'ha detto chiaro: in una città fatta d'albero, una scintilla si tratta come un'arma sguainata.",
		"Qui i fuochi per cucinare sono piccoli, chiusi nella pietra e sorvegliati. Quando ho chiesto, un mercante mi ha ricordato con garbo su che cosa poggia l'intera città.",
		"Lampade, sì. Torce, di rado. Falò, mai. Una Sentinella me l'ha spiegato con un'occhiata al pavimento.",
	},
	["dar.muse.w23.custom.004"] = {
		"Fra i kaldorei, mi ha detto una sacerdotessa, i doni si danno con due mani e si ricevono con due. Una mano sola, ha detto, è per le cose che non contano.",
		"Due mani per dare, due per ricevere. L'ho imparato da un kaldorei che ha aspettato, sorridendo, finché non ho teso anche l'altra mano.",
	},
	["dar.muse.w23.custom.005"] = {
		"I falegnami kaldorei usano solo legno caduto, mi ha detto un druido. Difficile da credere finché non ho guardato i loro archi, ognuno con una curva un po' diversa.",
		"Niente di ciò che hanno in bottega gli artigiani è stato tagliato da un albero vivo, mi assicurano. Solo rami caduti. Pare che i druidi controllino.",
	},
	["dar.muse.w23.custom.006"] = {
		"Un kaldorei che promette qualcosa, mi ha avvertito un mercante, mantiene la parola molto dopo che la richiesta ti è uscita di mente. Meglio badare a cosa si ordina, in questa città.",
		"Le promesse dei kaldorei non scadono, mi ha detto una mercante, e poi ha accennato a un ordine che sta ancora evadendo per qualcuno che non vede da due secoli.",
	},
	["dar.muse.w23.custom.007"] = {
		"Una sacerdotessa mi ha detto che alcuni kaldorei hanno cominciato a contare gli anni che passano, cosa di cui prima di Hyjal non si curavano. Non ha detto che fosse triste. Non ce n'era bisogno.",
		"Contare gli anni è un'abitudine nuova, qui, mi dicono. Per quasi tutta la loro storia i kaldorei non ne avevano motivo. Ora qualcuno ha cominciato, in silenzio, come si comincia a controllare il tetto dopo la prima goccia.",
	},
	["dar.muse.w23.custom.008"] = {
		"vede un kaldorei posare un solo fiore ai piedi di una colonna scolpita, sfiorarlo una volta e andarsene senza voltarsi.",
		"nota piccole offerte infilate in una nicchia lungo il sentiero, una piuma, una foglia pressata, un sasso liscio, e un kaldorei di passaggio aggiungerne una senza rallentare.",
		"sosta davanti a una piccola nicchia dove qualcuno ha lasciato una ghianda lucidata e un rametto verde, e li lascia esattamente com'erano.",
	},
	["dar.muse.w23.custom.009"] = {
		"Mi tolgo gli stivali? Mi inchino? Tutte e due? Qualcuno qui avrà pure un elenco.",
		"In questa città c'è un modo giusto per fare ogni cosa, e io li sto scoprendo uno per uno sbagliandoli.",
		"Se ho infranto un'usanza, ditemi quale. Le altre le infrangerò in ordine.",
	},
	["dar.muse.w23.custom.010"] = {
		"Un ospite kaldorei, mi ha detto un viaggiatore, offre l'acqua prima di ogni altra cosa. A una bancarella mi hanno porto una tazza d'acqua, e solo dopo ho capito che era un benvenuto.",
		"Prima l'acqua: è così che un kaldorei accoglie un ospite, ho sentito dire. Un venditore mi ha passato una tazza senza una parola, e l'ho bevuta senza sapere che quello era un saluto.",
		"La tazza d'acqua è arrivata prima del prezzo. Solo dopo ho capito quale delle due cose contasse di più per il mercante.",
	},
	["dar.muse.w23.errand.001"] = {
		"Nella mia testa l'elenco diceva banca, addestratore, locanda. Darnassus l'ha rimesso in ordine secondo la terrazza in cui mi capitava di finire.",
		"Avevo un ordine preciso per le mie commissioni. I sentieri ne avevano un altro, e hanno vinto loro.",
	},
	["dar.muse.w23.errand.002"] = {
		"conta le commissioni sulle dita camminando, perde il filo alla quarta e ricomincia dal pollice.",
		"spunta un breve elenco sulle dita, resta con un dito in più e non c'è verso di ricordare a cosa servisse.",
	},
	["dar.muse.w23.errand.003"] = {
		"Mi serviva una cosa sola. Ne ho comprate tre, e quella mi serve ancora.",
		"Una commissione. Questo era il piano. Nel frattempo, al piano sono spuntate le foglie.",
		"Avevo bisogno di una cosa. Darnassus me ne ha vendute prima altre tre, con molta delicatezza.",
	},
	["dar.muse.w23.errand.004"] = {
		"Chi mi precede in banca studia ogni oggetto prima di consegnarlo, come per salutarlo. Ormai quei guanti li conosco meglio dei miei.",
		"Davanti a me in banca un kaldorei si separa da un anello, un mantello e una scatolina, piano, con un lungo sguardo per ciascuno. Comincio a sentirmi a un funerale.",
	},
	["dar.muse.w23.errand.005"] = {
		"Nella cassetta della posta solo un biglietto: offerta superata. Qui anche le cattive notizie arrivano con garbo.",
		"Una lettera sola: all'asta qualcuno ha offerto più di me. In silenzio, naturalmente.",
	},
	["dar.muse.w23.errand.006"] = {
		"Ho venduto un sacco di cianfrusaglie. Dall'altra parte del banco hanno esaminato un dente scheggiato come fosse una gemma, e me l'hanno pagato in rame, con vera cortesia.",
		"Hanno girato due volte la mia fibbia rotta, mi hanno offerto tre monete di rame e mi hanno pure ringraziato. Nessuno mi aveva mai detto grazie per della robaccia.",
	},
	["dar.muse.w23.errand.007"] = {
		"Ogni visita da un addestratore va allo stesso modo: borsa più leggera, testa più piena, e una lunga camminata per rimuginarci sopra.",
		"Quello che ho appena imparato mi è costato quasi tutto l'argento. Almeno la strada attraverso la città è gratis, e abbastanza lunga da ripassare tutto a mente.",
	},
	["dar.muse.w23.errand.008"] = {
		"Ho messo all'asta un paio di stivali. Chi teneva il registro li ha annotati come se stesse trascrivendo un trattato.",
		"Tre oggetti messi all'asta, e un ringraziamento a parte per ciascuno. I miei vecchi stivali non sono mai stati trattati così bene.",
	},
	["dar.muse.w23.errand.009"] = {
		"Ho attraversato mezza città fino alla banca e al banco non ricordavo più perché fossi lì. Dall'altra parte hanno aspettato. Ovvio che hanno aspettato.",
		"A metà strada ho dimenticato cosa dovessi fare in banca. Ho proseguito lo stesso: la camminata se lo meritava.",
	},
	["dar.muse.w23.errand.010"] = {
		"sta davanti alla banca con una borsa aperta, una tazza sbeccata in una mano e una chiave arrugginita nell'altra, e non riesce a decidere quale tenere.",
		"divide il contenuto delle borse sul banco in tre mucchi, da tenere, da vendere e perché-ce-l'ho, e il terzo è il più alto.",
	},
	["dar.muse.w23.errand.011"] = {
		"Riparazioni, un pasto, una lezione, e la borsa è vuota. Darnassus è gentile su tutto, tranne che sul conto finale.",
		"Le monete sono finite due commissioni prima della lista. Le ultime due le lascio a una versione di me più ricca.",
	},
	["dar.muse.w23.errand.012"] = {
		"Non serve contare il resto due volte. Ah. Tre volte, allora. Grazie.",
		"Conti pure con calma, non ho fretta. È una bugia, ma educata.",
		"Conti con tutta la calma che vuole. Io resto qui e intanto metto radici.",
	},
	["dar.muse.w23.errand.013"] = {
		"La mappa che ho comprato mostra ogni terrazza con un inchiostro bellissimo e nemmeno uno dei sentieri in mezzo. Temo sia una mappa onesta di Darnassus.",
		"Adesso ho una mappa di questa città. È bellissima, e utile quanto il dipinto di una scala.",
	},
	["dar.muse.w23.errand.014"] = {
		"arriva alla banca, si ricorda che la roba da depositare è rimasta dall'addestratore e torna indietro con un lungo sospiro silenzioso.",
		"raggiunge la casa d'aste, si tasta ogni tasca due volte e capisce che l'oggetto da vendere è ancora in banca.",
	},
	["dar.muse.w23.errand.015"] = {
		"Le commissioni sono il modo migliore di vedere una città. Nessuno guarda due volte chi sta chiaramente andando in banca.",
		"Mi piace avere qualche faccenda da sbrigare qui. Mi dà un motivo per attraversare le terrazze che non sia solo restare a bocca aperta.",
	},
	["dar.muse.w23.errand.016"] = {
		"Se in questa città la locanda affittasse sedie a ore, non mi schioderebbero più.",
		"Vado alla locanda. Non a dormire: solo a sedermi sotto un tetto e a far finta di sapere dov'è ogni cosa.",
	},
	["dar.muse.w23.errand.017"] = {
		"Due rotoli di stoffa, un sacchetto di filo e un paio di guanti nuovi, tutto da portare a mano da una parte all'altra della città. Qualcuno dovrebbe inventare una città più piccola.",
		"Ho le braccia piene di acquisti, e ogni sentiero di Darnassus ha scelto proprio adesso di essere panoramico.",
	},
	["dar.muse.w23.errand.018"] = {
		"compra un po' di tutto a una bancarella, poi si fa da parte per farlo entrare in borse già piene.",
		"si ferma a una bancarella per acqua e provviste da viaggio, e passa un bel po' a farle stare nello zaino.",
	},
	["dar.muse.w23.errand.019"] = {
		"Banca, addestratore, bancarella, e indietro. Tutto fatto. Qualcuno lo annoti: non ricapiterà.",
		"Tutte le commissioni sbrigate in un colpo solo. Gradirei una piccola cerimonia. Basta un cenno.",
		"Commissioni finite, tutte quante. Adesso resto qui un momento a godermela con aria insopportabile.",
	},
	["dar.muse.w23.errand.020"] = {
		"La banca e la casa d'aste stanno sulla stessa terrazza, eppure riesco a fare avanti e indietro tre volte a ogni visita.",
		"Qui sulla Tradesmen's Terrace tutto quello che mi serve è a poche decine di passi. Non mi ha mai impedito di dimenticare qualcosa all'altro capo.",
	},
	["dar.muse.w23.errand.021"] = {
		"L'addestratore è occupato. Va bene. Guardo gli esercizi e fingo di imparare con gli occhi.",
		"Sono qui per imparare, e mi fa già male tutto solo a guardare gli altri allenarsi.",
	},
	["dar.muse.w23.errand.022"] = {
		"Di notte la città è semmai più attiva. Sono io a sbadigliare tra una commissione e l'altra, mentre i kaldorei hanno appena cominciato.",
		"È passata mezzanotte e le bancarelle sono ancora aperte, gli addestratori ancora pazienti. Le mie commissioni ormai seguono gli orari dei kaldorei, non i miei.",
	},
	["dar.muse.w23.errand.023"] = {
		"Mentre la luce cala, i sentieri si riempiono. Pare che i kaldorei sbrighino le loro faccende al tramonto, e io ho scelto la stessa ora di tutti loro.",
		"Crepuscolo, e d'un tratto c'è la fila a ogni bancarella. La gente del posto comincia la sua giornata; io cerco di finire la mia.",
	},
	["dar.muse.w23.errand.024"] = {
		"Uno gnomo risolverebbe questa città in una settimana con qualche binario d'ottone e un paio di montacarichi. Nessuno me l'ha chiesto, e ho deciso di non offrirmi.",
		"Ho abbozzato tre modi per dimezzare la strada dalla banca agli addestratori. Tutti con ingranaggi, quindi restano tutti nel taccuino.",
	},
	["dar.muse.w23.grain.001"] = {
		"si accovaccia ai piedi di una scala e segue la venatura con un dito: scorre dal gradino di sotto a quello di sopra senza una giuntura, come se l'intera rampa fosse cresciuta tutta d'un pezzo.",
		"si ferma su una scala e nota che la venatura si piega a seguire ogni gradino, salendo e scavalcando come l'acqua sui sassi.",
		"fa scorrere la punta di un dito sul bordo di una scala e sente la venatura salire insieme, gradino dopo gradino, senza mai spezzarsi.",
	},
	["dar.muse.w23.grain.002"] = {
		"Sto cercando un chiodo, a Darnassus. Un piolo, un incastro, il segno di una sega, qualsiasi cosa. Niente. Un falegname di Stormwind qui morirebbe di fame, e poi lo seppellirebbero in una cassa bellissima.",
		"Non c'è il segno di una sega in tutta la città. Il legno è stato convinto a prendere forma, non tagliato, e si vede: ogni spigolo è quello che voleva essere.",
		"Da qualche parte a Ironforge c'è una corporazione di falegnami che piangerebbe a vedere questo posto. Neanche un incastro a coda di rondine. Neanche uno.",
	},
	["dar.muse.w23.grain.003"] = {
		"Nel muro lungo il sentiero c'è un nodo a forma di occhio socchiuso. Ormai l'ho superato quattro volte. Ho il sospetto che se ne sia accorto.",
		"Nodi qua e là nel legno vivo, ognuno con la venatura che gli gira attorno come la folla attorno a chi parla. L'albero ha i suoi piccoli punti di riferimento.",
		"Comincio a conoscere i nodi. Uno vicino alla scala, come un'impronta di pollice; uno sopra una porta, come un cipiglio. Non è una mappa, ma meglio di niente.",
	},
	["dar.muse.w23.grain.004"] = {
		"Gli anelli di un albero in cui vivi non li puoi contare. I druidi ne dicono l'età in anni, un numero piccolo, e lo dicono con uno sguardo che ti sfida a stupirti.",
		"Da qualche parte dentro questo legno ci sono gli anelli, pochi, uno per ogni anno da quando fu piantato. Una fattoria di Elwynn potrebbe avere travi più vecchie.",
		"Una druida mi ha detto l'età dell'albero come si dice quella di un bambino: con orgoglio, e in anni che si contano sulle dita.",
	},
	["dar.muse.w23.grain.005"] = {
		"osserva un artigiano kaldorei rigirare tra le dita lunghe un ritaglio di legno chiaro, leggendone la venatura come altri leggono una lettera, prima di posarlo senza averlo toccato con alcun attrezzo.",
		"vede un'artigiana posare il palmo lungo un ramo caduto e farlo scorrere piano, gli occhi socchiusi, cercando nella venatura qualcosa che solo la mano sa trovare.",
	},
	["dar.muse.w23.grain.006"] = {
		"Uno gnomo accanto a me ha bussato a un muro con le nocche, per sentire se fosse vuoto. Il muro non ha risposto. Lo gnomo se l'è presa sul personale.",
		"Ho visto uno gnomo misurare una porta, due volte, e poi fissare i numeri come se gli avessero mentito. Qui niente ha la stessa larghezza dal basso all'alto.",
		"Uno gnomo sulla scala aveva tirato fuori una livella d'ottone e ne fissava la bolla accigliato. Non si è mai fermata. Qui non si fermerà mai, credo.",
	},
	["dar.muse.w23.grain.007"] = {
		"Dove il pavimento un tempo si è spaccato, l'albero ha fatto crescere un rilievo sopra la crepa, come una cicatrice su una nocca. Nessuno l'ha riparata. Si è riparata da sola, e ha tenuto il segno.",
		"Una cucitura attraversa il sentiero dove il legno un tempo si era aperto, ora chiusa da un labbro rialzato di legno nuovo. La scavalco con cura, come si risparmia un punto dolente.",
		"L'albero ripara le sue crepe e non le nasconde. Ho visto abitudini peggiori nelle persone.",
	},
	["dar.muse.w23.grain.008"] = {
		"posa la mano su un muro e scopre, lungo la linea dove la pietra chiara incontra il legno vivo, che da una parte è fresco e dall'altra appena tiepido.",
		"nota il punto in cui la pietra chiara è stata incastonata nel legno vivo: la corteccia ne ha ricoperto l'orlo per un dito, quasi a tenerla ferma.",
		"studia un blocco di pietra bianca affondato in una parete di legno e vede la venatura scorrergli attorno da entrambi i lati, come un torrente intorno a un masso.",
	},
	["dar.muse.w23.grain.009"] = {
		"Questo pavimento ha una venatura. Camminaci contro e i piedi lo sentono, come accarezzare un gatto contropelo.",
		"Toccate i muri, qui. Su, provate. Lisci come una ciotola, e neanche il segno di un attrezzo.",
		"Persino il pavimento ha un verso, in questa città. Mi sorprendo a seguirlo senza volerlo.",
	},
	["dar.muse.w23.grain.010"] = {
		"Una druida mi ha spiegato come si fa crescere un muro: chiedi al legno, aspetti, poi chiedi di nuovo in un altro modo. Detto da lei sembrava un corteggiamento.",
		"Chiedi a un druido quanto ci è voluto per dare forma a una porta e ti risponde una stagione, forse due. Chiedi come, e ottieni solo la parola «ascoltando».",
		"I druidi non costruiscono: suggeriscono. Qui una porta è la risposta del legno a una domanda fatta con molta gentilezza per moltissimo tempo.",
	},
	["dar.muse.w23.grain.011"] = {
		"segue una linea scura nella venatura chiara di uno stipite e scopre che non è una macchia ma una vena di legno più scuro, che sale fino a perdersi come un filo nella stoffa.",
		"nota che da un lato dell'arco la venatura è fitta e sottile, dall'altro larga e allentata, come se il legno fosse cresciuto più in fretta dal lato rivolto all'acqua.",
		"sfiora con un dito un nodo chiaro in un pilastro e vede la venatura avvolgerlo in cerchi, come le increspature attorno a un sasso caduto in acqua.",
	},
	["dar.muse.w23.grain.012"] = {
		"A Stormwind abbattiamo una quercia per fare il tetto di una casa. Qui chiedono all'albero di essere la casa, e lui accetta. Sto ancora decidendo chi dei due popoli sia il più maleducato.",
		"Ogni trave di Stormwind un tempo era un albero, ed è morta per diventarlo. Qui le travi sono ancora alberi. A un muratore di casa mia servirebbe una lunga seduta per riprendersi.",
	},
	["dar.muse.w23.grain.013"] = {
		"Qui sulla Craftsmen's Terrace i banchi da lavoro fanno parte del pavimento, e la venatura scende dal piano del banco dritta nelle assi. Nessuno li sposterà mai, e nessuno ne ha l'intenzione.",
		"I tavoli di questa terrazza spuntano dal pavimento. Ci ho posato lo zaino e ho avuto la sensazione assurda di dover chiedere il permesso.",
		"Su questa terrazza perfino i banchi da lavoro hanno radici. Gli artigiani ci si appoggiano come alla spalla di un vecchio amico.",
	},
	["dar.muse.w23.grain.014"] = {
		"Neanche una scheggia in tutta la città. Ho controllato. Con le mani, per lo più per sbaglio.",
		"Su questi pavimenti si potrebbe correre scalzi. Mi dicono che qualcuno lo fa.",
	},
	["dar.muse.w23.grain.015"] = {
		"si siede su un gradino di legno vivo e, dopo un momento, si sposta un po' più in là: nel primo punto c'era un nodo esattamente dove nessuno vuole un nodo.",
		"si accomoda su una sporgenza di legno chiaro, la trova piuttosto comoda e sospetta che sia stata modellata per qualcuno con gambe molto più lunghe.",
		"si lascia andare su un sedile ricurvo cresciuto dalla parete e scopre che i piedi non arrivano del tutto a terra.",
	},
	["dar.muse.w23.grain.016"] = {
		"lascia cadere una moneta, la sente suonare sorda sul pavimento di legno e la vede rotolare via in una lunga curva, seguendo la venatura più che la pendenza.",
		"guarda un bottone caduto rotolare sul pavimento, piegando dolcemente lungo la venatura come se conoscesse la strada, e fermarsi ai piedi di un kaldorei che lo restituisce senza una parola.",
	},
	["dar.muse.w23.grain.017"] = {
		"Guarda questa venatura. Pare acqua gelata mentre correva.",
		"Questo muro si leggerebbe come una mappa, se uno conoscesse la lingua.",
		"Ogni ricciolo di questo legno un tempo andava da qualche parte. Pagherei per sapere dove.",
	},
	["dar.muse.w23.grief.001"] = {
		"Oltre il mare, Darkshore è piena di città elfiche finite sotto il muschio e di archi spezzati. Quassù costruiscono archi nuovi con le stesse curve, e mi chiedo se sia ricordare o rifiutarsi di farlo.",
		"Le rovine sulla costa di Darkshore e le terrazze di Darnassus hanno le stesse linee, gli stessi tetti arricciati. Le une sono ciò che era. Le altre sono i kaldorei che lo ridisegnano, con cura, a memoria.",
	},
	["dar.muse.w23.grief.002"] = {
		"osserva un'elfa posare una sola foglia sull'acqua di un ruscello e seguirla con gli occhi finché non scompare, poi riprendere il cammino come se nulla fosse.",
		"vede una kaldorei fermarsi su un ponte, lasciar cadere un fiore pallido nella corrente e restare lì immobile finché l'acqua non l'ha portato via.",
	},
	["dar.muse.w23.grief.003"] = {
		"Diecimila anni senza funerali, e poi la Terza Guerra ha costretto i kaldorei a imparare il lutto in fretta. Nel loro lutto c'è una goffaggine che trovo molto commovente.",
		"Per un popolo immortale la morte era soprattutto qualcosa che capitava agli altri. Ora capita a loro, e piangono come chi impara: con serietà, un po' rigidi, senza le vecchie formule a cui si appoggiano gli altri popoli.",
	},
	["dar.muse.w23.grief.004"] = {
		"Quando salta fuori un nome che nessuno diceva da tempo, i kaldorei fanno un'espressione tutta loro. Non abbassano gli occhi. Guardano appena in alto, di lato, come se la persona fosse proprio lì dietro.",
		"Quando qui si pronuncia il nome di chi non c'è più, nessuno china la testa. Guardano di lato, verso un punto vuoto, come per fare educatamente posto a qualcuno.",
	},
	["dar.muse.w23.grief.005"] = {
		"Oltre lo stretto, le città kaldorei di Darkshore si sbriciolano nella risacca. Qui nessuno chiede di tornare a ricostruirle. Forse una tomba non si ricostruisce.",
		"Ho camminato tra le città spezzate e annegate di Darkshore. Gli elfi di questa città le conoscono tutte per nome, e non ne ho mai sentito uno proporre di tornarci a vivere.",
	},
	["dar.muse.w23.grief.006"] = {
		"Un'intera città in lutto, e trovano ancora il tempo di dare indicazioni a uno sconosciuto. Fa sentire piccoli.",
		"Questa gente ha seppellito più di quanto io potrò mai sapere, e ancora mi tengono aperta la porta.",
	},
	["dar.muse.w23.grief.007"] = {
		"I ricordini non sono mai stati un'abitudine kaldorei. Perché tenere una ciocca di capelli di qualcuno che ci sarebbe sempre stato? Ora vedo anziani con sacchetti alla cintura, e non chiedo cosa ci sia dentro.",
		"I sacchetti portati stretti alla cintura sono una novità a Darnassus, mi ha detto un artigiano. Ricordi. Un popolo che non aveva mai avuto bisogno di tenere nulla dei morti ha cominciato a tenere qualcosa.",
	},
	["dar.muse.w23.grief.008"] = {
		"si fa da parte mentre una sacerdotessa intona poche parole sommesse su una piccola lampada al margine del tempio, poi spegne la fiamma tra due dita e s'inchina allo stoppino scuro.",
		"resta a rispettosa distanza mentre una sacerdotessa accende una piccola lampada per qualcuno che non c'è, pronuncia sopra una breve frase e la lascia accesa in una fila di altre tutte uguali.",
	},
	["dar.muse.w23.grief.009"] = {
		"Alcuni degli alberi giovani di questi giardini sono stati piantati per i morti della Terza Guerra, mi hanno detto. Nessuno segna quali. Vanno trattati tutti con dolcezza, per sicurezza.",
		"Una giardiniera qui mi ha detto che per ogni kaldorei perduto sull'Hyjal o ad Ashenvale si mette a dimora un alberello. Non me ne ha indicato nessuno. Non serviva: i giardini ne sono pieni.",
	},
	["dar.muse.w23.grief.010"] = {
		"Qui non si dimentica nulla, e il dolore dei kaldorei lo sa. Qui una perdita non sbiadisce con gli anni; si deposita, come il limo in una vasca ferma, e resta.",
		"Le vite brevi dimenticano, e dimenticare è una grazia. Gli elfi di qui non ce l'hanno. Si portano dietro ogni perdita, nitidissima, per tutta la vita.",
	},
	["dar.muse.w23.grief.011"] = {
		"Qui non piangono. Diventano molto silenziosi, e per molto tempo.",
		"Il dolore dei kaldorei non fa rumore. Quasi vorrei che lo facesse.",
	},
	["dar.muse.w23.grief.012"] = {
		"Dall'Hyjal so che i volti dei miei anziani cambieranno, e se ne andranno. Ora li guardo più a lungo, come si impara a memoria una costa da una nave che salpa.",
		"Ho cominciato a studiare i volti dei vecchi di questa città. Non proprio con tristezza. Con la cura di chi ricopia una pagina prima che l'inchiostro sbiadisca.",
	},
	["dar.muse.w23.grief.013"] = {
		"Le scuse di un kaldorei per una cosa fatta quattromila anni prima: le ho sentite su un ponte. L'altra parte le ha accettate con garbo e ha detto che le stava aspettando.",
		"Due vecchi elfi hanno appena fatto pace dopo una lite cominciata prima della Frattura. Qui i rancori durano un pezzo. Pare anche il tatto.",
	},
	["dar.muse.w23.grief.014"] = {
		"s'imbatte in una Sentinella ferma accanto a un druido in lacrime: non dice nulla, resta lì spalla contro spalla finché lui non è pronto a ripartire.",
		"osserva un kaldorei posare una mano aperta tra le scapole di un altro, senza parole e senza muoversi, mentre l'altro fissa a lungo l'acqua.",
	},
	["dar.muse.w23.grief.015"] = {
		"Ogni grande albero che i kaldorei hanno piantato l'hanno piantato dopo aver perso qualcosa. Nordrassil dopo la Frattura, Teldrassil dopo l'Hyjal. È strano vivere dentro il lutto di un popolo e trovarlo così verde.",
		"Cammino nella chioma di un gesto di lutto. Teldrassil fu piantato dopo che la benedizione dell'Hyjal andò perduta, e la città è spuntata da quel dolore come una foglia da una gemma.",
	},
	["dar.muse.w23.grief.016"] = {
		"Il mio popolo ha sempre saputo di dover morire, e ha avuto tutto il tempo di farci delle battute. I kaldorei sono nuovi a questo. Mi verrebbe da dare lezioni, e so che non devo.",
		"Da dove vengo io, sulla morte ci sono un paio di battute buone. I kaldorei non hanno ancora trovato le loro. Ho imparato a non provare le mie con loro.",
	},
	["dar.muse.w23.grief.017"] = {
		"Pioggia che filtra tra i rami, e una sacerdotessa che cammina piano lungo il sentiero senza cappuccio, lasciandosela cadere sul viso. Non credo stia pregando. Credo lasci piangere la pioggia al posto suo.",
		"Con questa pioggia i kaldorei escono invece di ripararsi. Una vecchia Sentinella sta vicino all'acqua col viso rivolto in su, e capisco che non dovrei guardare.",
	},
	["dar.muse.w23.grief.018"] = {
		"Con tutto ciò che questo popolo ha perso, non ho mai sentito un kaldorei dire che il mondo è rovinato. Ferito, sì. Più piccolo, sì. Ma ancora un mondo dove vale la pena piantare.",
		"Il lutto qui non diventa mai amarezza, per quel che vedo. Hanno perso la loro patria, la loro regina, il loro per sempre, e continuano a mettere semi nella terra.",
	},
	["dar.muse.w23.grief.019"] = {
		"I miei ricordi peggiori hanno dieci anni. I loro diecimila. Smetto di lamentarmi.",
		"Brutta giornata? Parlane con un kaldorei di un brutto millennio.",
	},
	["dar.muse.w23.grief.020"] = {
		"tace accanto a una vecchia kaldorei che si è fermata a metà passo e si è voltata come se qualcuno l'avesse chiamata; resta immobile, ad ascoltare una voce che non parla da tanto tempo.",
		"nota un'anziana alzare di scatto la testa a una risata dall'altra parte dell'acqua, come si fa per una voce conosciuta, poi ricordare piano, e abbassare gli occhi.",
	},
	["dar.muse.w23.grief.021"] = {
		"Non ci sono mai servite molte parole per i morti. Ora le stiamo inventando, un funerale per volta, e ogni parola nuova sembra presa in prestito dal dolore di qualcun altro.",
		"I miei anziani mi hanno insegnato tutti i nomi del cielo e nessuno per il lutto. Quelli ho dovuto prenderli in prestito dagli umani, e calzano male, come gli stivali di un estraneo.",
	},
	["dar.muse.w23.grief.022"] = {
		"Perfino i loro giardini sembrano ricordare qualcuno.",
		"Bella città. Triste città. La seconda parte la nascondono bene.",
	},
	["dar.muse.w23.guest.001"] = {
		"Osserva un kaldorei con un nano in visita: gentile in ogni parola, e nemmeno un passo più vicino di quanto la cortesia richieda. Calore, tenuto a un braccio di distanza.",
		"La gentilezza dei kaldorei verso gli ospiti sa tenere benissimo le distanze. Nessuno è freddo, e nessuno si avvicina più di quanto serva alla conversazione.",
	},
	["dar.muse.w23.guest.002"] = {
		"Mi comporto bene da così tanto che mi fanno male le spalle. Le buone maniere sono più faticose di quanto sembri.",
		"A Darnassus la buona educazione è un mestiere a tempo pieno. Ho il collo rigido a forza di tenere la testa così dritta.",
		"Attento alla voce, ai gomiti, alle aiuole. Qui la cortesia è un allenamento.",
	},
	["dar.muse.w23.guest.003"] = {
		"si accorge che gli stivali hanno lasciato una scia di polvere sulla pietra chiara, e passa un momento a cercare di cancellarla con l'altro stivale.",
		"abbassa gli occhi sui propri abiti segnati dal viaggio, poi su due kaldorei impeccabili che passano, e si spazzola una manica senza farsi notare.",
		"nasconde una cinghia sfilacciata e si sistema il colletto, come se a chiederlo fosse stata la città stessa.",
	},
	["dar.muse.w23.guest.004"] = {
		"L'elfa che mi ha venduto un rocchetto di filo forse ricorda foreste dove adesso c'è acqua aperta. Eppure mi ha contato il resto con tutta la cura possibile.",
		"Fra questa gente c'è chi ha camminato sotto alberi finiti negli abissi prima che un solo regno umano avesse un nome. E si ferma lo stesso a indicare la strada a chi è di passaggio.",
	},
	["dar.muse.w23.guest.005"] = {
		"Darnassus non dice mai vietato entrare, e nessuno qui lo direbbe. La forma di un'accoglienza kaldorei l'ospite la impara da dove si ferma la conversazione.",
		"Nessun cartello, nessun cancello, nessun avviso. Le porte chiuse ai visitatori si chiudono con una pausa e un cambio di argomento.",
	},
	["dar.muse.w23.guest.006"] = {
		"Dalla banca a qui mi hanno fatto l'inchino quattro volte. Sto finendo i modi per ricambiare.",
		"C'è una regola su quanti inchini vuole una passeggiata? Io ho perso il conto, e ho idea che loro no.",
		"Da quando sono qui il mio collo si è inchinato più che in tutto il resto dell'anno.",
	},
	["dar.muse.w23.guest.007"] = {
		"Una bottegaia kaldorei ha definito 'recente' la Seconda Guerra, parlando con un cliente umano. Non scherzava. L'umano ci ha messo un momento a riprendersi.",
		"Per una mercante della terrazza, la fondazione di Stormwind è una notizia non ancora del tutto digerita. L'umano a cui l'ha detto è rimasto in silenzio a lungo.",
		"'Poco tempo fa', ha detto un'elfa a un nano, e ha raccontato una cosa di prima che Ironforge fosse scavata. Il nano ha annuito come se ci fosse stato anche lui.",
	},
	["dar.muse.w23.guest.008"] = {
		"abbassa la voce senza volerlo mentre chiede la strada, e l'elfa che risponde abbassa la sua allo stesso tono, come per un accordo tacito.",
		"chiede indicazioni a un elfo di passaggio e le riceve così lente e complete che andarsene prima della fine sarebbe impensabile.",
	},
	["dar.muse.w23.guest.009"] = {
		"Nelle altre città chi è di passaggio teme i ladri. Qui temo il volume della mia voce, la mia fretta e la polvere che ho addosso.",
		"Le altre capitali mi fanno badare alla borsa. Darnassus mi fa badare ai gomiti, alla voce e al rumore degli stivali.",
	},
	["dar.muse.w23.guest.010"] = {
		"Le loro città antiche sono rovine oltre l'acqua, eppure nella nuova fanno ancora spazio agli ospiti. Non so se, dopo una perdita simile, avrei tanta generosità.",
		"Un popolo che ha perso una patria intera, e apre agli stranieri l'ultimo rifugio in alto che gli resta. Qualcuno, al tempio, ha fatto una scelta difficile per permetterlo.",
	},
	["dar.muse.w23.guest.011"] = {
		"Da quando sono quassù non ho toccato quasi niente. Sembra una casa il cui padrone è uscito un attimo fa, fidandosi che io aspetti.",
		"Darnassus ha l'aria della stanza di qualcun altro: bella, aperta, e piena di cose che preferirei non rovesciare.",
		"Qui tengo le mani a posto, come nel salotto di uno sconosciuto. Nessuno me l'ha chiesto. È la città che fa questo effetto.",
	},
	["dar.muse.w23.guest.012"] = {
		"Gli umani abituati a guardare i nani dall'alto, qui alzano gli occhi, e li vedi aggiustare la propria dignità strada facendo.",
		"Accanto ai kaldorei anche un umano alto sembra l'apprendista di qualcuno. Gli gnomi, saggiamente, hanno smesso da tempo di fare confronti.",
	},
	["dar.muse.w23.guest.013"] = {
		"Per un umano le sale di Ironforge sono antichissime. Per i kaldorei sono un lavoro piuttosto recente. Qui ogni ospite è giovane, qualunque cosa dica la sua barba.",
		"Ciò che altrove è vecchio, qui è di mezza età. Il nano più canuto sul ponte è probabilmente più giovane dell'elfa che gli vende le erbe.",
	},
	["dar.muse.w23.guest.014"] = {
		"Essere ospiti ha qualcosa di riposante. Niente, a Darnassus, tocca a me aggiustarlo, sorvegliarlo o preoccuparmene.",
		"Qui l'ospite ha un solo dovere: non dare fastidio. Dopo tanti posti che volevano qualcosa da me, è un sollievo che mi si chieda così poco.",
	},
	["dar.muse.w23.guest.015"] = {
		"I congedi dai visitatori, qui, sono dolci e brevi. Quando sopravvivi a quasi tutti quelli che incontri, forse impari a tenere ogni ospite con leggerezza.",
		"Di quanti ospiti si sarà affezionato un kaldorei, per poi vederli incanutire e sparire? Forse è per questo che l'accoglienza qui è calda ma mai stretta.",
	},
	["dar.muse.w23.guest.016"] = {
		"I visitatori sono gli unici a Darnassus che continuano a chiedere che ora è. I kaldorei rispondono, ma si vede che devono calcolarla.",
		"Chiedi l'ora a un kaldorei e una risposta arriva, dopo una pausa, come se gli avessi chiesto delle usanze di qualcun altro.",
	},
	["dar.muse.w23.guest.017"] = {
		"Ho detto a una kaldorei che l'avrei rivista presto. Mi ha chiesto, serissima, quale presto intendessi. Non sapevo ce ne fosse più di uno.",
		"'Torno fra poco', ho detto alla bancarella. Mi hanno risposto con un cenno, come se fra poco potesse voler dire un anno, e hanno messo da parte il mantello.",
	},
	["dar.muse.w23.guest.018"] = {
		"Cosa si porta a un padrone di casa che ha già visto ogni regalo possibile? Ho deciso: stivali puliti e voce bassa.",
		"Un ospite dovrebbe portare qualcosa. Ma cosa potrei offrire a un popolo così antico, che non abbia già avuto, perso e fatto ricrescere? Dovranno bastare le mie buone maniere.",
	},
	["dar.muse.w23.guest.019"] = {
		"Qui sulla Tradesmen's Terrace distingui l'ospite dal padrone di casa dalla borsa. I visitatori la stringono. I kaldorei la portano come se nessuno al mondo potesse pensare di prenderla.",
		"I visitatori di questa terrazza contano le monete due volte e si guardano intorno prima di aprire la borsa. I kaldorei pagano e basta, vagamente perplessi da tanta cautela.",
	},
	["dar.muse.w23.heartwood.001"] = {
		"Sotto il muschio e la pietra il tronco continua, giù e ancora giù fino al mare. Ci penso come si pensa alle fondamenta di una casa: quasi mai, e poi tutto in una volta.",
		"Tutta Darnassus è la cima di una colonna di legno vivo piantata nel mare. Ogni tanto non riesco a smettere di saperlo.",
		"Sotto ogni terrazza c'è il tronco, e sotto il tronco il mare. Me ne ricordo solo quando poso qualcosa di pesante.",
	},
	["dar.muse.w23.heartwood.002"] = {
		"Il durame è il legno più vecchio di un albero, il nucleo morto che regge quello vivo. Quello di Teldrassil non può avere più di qualche anno. Un'intera città poggia su qualcosa di più giovane della sua Sentinella più giovane.",
		"Il cuore di una vecchia quercia ha secoli di profondità. Il cuore di quest'albero è più giovane di chi mi ha appena venduto una pagnotta. Continuo a rimuginarci sopra.",
		"Quasi tutti gli alberi tengono al centro il legno più antico. Il legno più antico di questo era un germoglio quando gli anziani della città erano già vecchissimi.",
	},
	["dar.muse.w23.heartwood.003"] = {
		"Alcuni dei druidi più anziani, quando credono di non essere ascoltati, dicono che l'albero fu piantato in fretta, senza chiedere a chi andava chiesto. Poi tornano a curarlo, con grande attenzione.",
		"Una Sentinella mi ha detto che Nordrassil fu piantato con la benedizione di grandi potenze, e Teldrassil con la speranza di un solo Arcidruido. L'ha detto senza inflessione, e poi non ha voluto aggiungere altro.",
	},
	["dar.muse.w23.heartwood.004"] = {
		"nota un'anziana kaldorei fermarsi sul sentiero, posare una mano a terra e restare china così per un momento, come chi controlla la fronte di un bambino che dorme.",
		"vede un druido fermarsi a metà passo, accovacciarsi e posare entrambi i palmi sul pavimento vivo, con un lieve cipiglio, prima di rialzarsi e proseguire come se nulla fosse stato chiesto né risposto.",
		"osserva una Sentinella che, alla fine del giro di ronda, sfiora con le nocche un pilastro del tronco prima di voltarsi, come si tocca uno stipite per buona fortuna.",
	},
	["dar.muse.w23.heartwood.005"] = {
		"Quasi ovunque la terra è più vecchia di chiunque ci cammini sopra. Qui è il contrario: il popolo è antichissimo, e il suolo sotto i suoi piedi conosce appena il proprio nome.",
		"Popolo antico, suolo giovane. A Darnassus gli anziani sono più vecchi del pavimento su cui camminano di qualche migliaio d'anni, come minimo.",
		"Nelle altre città le pietre ricordano più della gente. Qui è la gente a ricordare, e il legno sta ancora imparando.",
	},
	["dar.muse.w23.heartwood.006"] = {
		"Qualcuno l'ha piantato, questo. Pagherei bene per aver visto la buca.",
		"Pensate ad annaffiarlo. Pensate al primo anno, quando arrivava al ginocchio.",
		"Un seme, un bel po' di druidi, e guardatelo adesso. Al confronto un orto sembra poco ambizioso.",
	},
	["dar.muse.w23.heartwood.007"] = {
		"Nordrassil ci aveva dato l'eternità, e l'abbiamo spesa a Hyjal. Teldrassil ci dà una città e una volta di foglie e non chiede nulla in cambio. Cerco di provare gratitudine per un dono più piccolo.",
		"I druidi dicono che quest'albero non sarà mai ciò che fu Nordrassil. Io ne tocco comunque la corteccia, ogni volta che passo, come si stringe la mano a chi ci sta mettendo tutto l'impegno.",
	},
	["dar.muse.w23.heartwood.008"] = {
		"I kaldorei non sembrano preoccuparsi che l'albero possa cadere. L'ho chiesto a una di loro. Mi ha guardato con compassione e ha detto che gli alberi non cadono, si sdraiano, e questo non ha motivo di farlo.",
		"Ho chiesto a un druido cosa tenga in piedi l'albero in mezzo al mare. «Le radici», ha detto, come si risponderebbe «le gambe» a chi chiede come fa una persona a stare dritta.",
		"Una Sentinella mi ha detto, serissima, che il tronco affonda più di quanto il mare sia profondo. Non le ho chiesto come lo sapesse. Non volevo saperlo.",
	},
	["dar.muse.w23.heartwood.009"] = {
		"In un tronco così grande devono esserci delle cavità, laggiù. Una Sentinella mi ha detto che ci sono, e che i druidi le conoscono tutte per nome. Non si è offerta di presentarmele.",
		"Chissà che suono ha l'interno di un albero così grande. Non la corteccia: il centro. Forse come l'interno di una campana, molto dopo che è stata suonata.",
	},
	["dar.muse.w23.heartwood.010"] = {
		"scavalca una lunga gobba del sentiero, dove una parte profonda dell'albero spinge su attraverso il pavimento, e nota che anche tutti i kaldorei davanti l'hanno scavalcata, pur potendo pestarla senza fatica.",
		"nota una cresta di legno vivo che taglia il sentiero e, come i kaldorei attorno, la scavalca invece di calpestarla, senza sapere bene perché.",
	},
	["dar.muse.w23.heartwood.011"] = {
		"Vengo da gente che costruisce con legno morto e pietra squadrata. Vivere dentro qualcosa di vivo richiede abitudine. Continuo a chiedere scusa agli stipiti.",
		"Da dove vengo io, una casa che si muove è una casa che sta per crollare. Qui una porta che si sposta un po' è solo l'albero che si mette comodo, e a sobbalzare ci sono solo io.",
	},
	["dar.muse.w23.heartwood.012"] = {
		"Il pavimento del tempio è legno vivo sotto la pietra chiara, e le sacerdotesse spesso ci camminano scalze. Molto più giù il cuore dell'albero regge ogni cosa senza dire una parola.",
		"Nel Temple of the Moon mi scopro a camminare piano tanto per rispetto dell'albero quanto della dea.",
		"Qui nel tempio la pietra è stesa sul legno come una tovaglia su un tavolo, e il tavolo, sospetto, è l'ospite che conta di più fra i due.",
	},
	["dar.muse.w23.heartwood.013"] = {
		"Qui nell'Enclave i druidi trattano le pareti vive come un collega: ci si appoggiano, ci parlano accanto, le consultano con una mano e tornano al lavoro.",
		"Qualcuno nell'Enclave ha lasciato una tazza su una mensola di legno vivo, e il legno ha cominciato, molto lentamente, a farle crescere un bordo attorno.",
		"Nell'Enclave nessuno bussa sul legno per scaramanzia. Ci posano il palmo, piuttosto, e aspettano, come se potesse avere un'opinione.",
	},
	["dar.muse.w23.heartwood.014"] = {
		"Alcuni druidi dicono che un albero ricorda ogni mano che vi si è posata. Se è vero, Teldrassil ormai conosce un'infinità di forestieri, ed è stato paziente con ciascuno.",
		"Se l'albero ricorda davvero le mani, come dicono i druidi, adesso la mia è lì da qualche parte, fra quella di una Sentinella e quella di uno gnomo.",
	},
	["dar.muse.w23.heartwood.015"] = {
		"Con la nebbia fra i rami più bassi il tronco sparisce sotto la città, e Darnassus semplicemente galleggia. Non mi è mai sembrato così incerto che qualcosa la regga.",
		"Nebbia sotto le terrazze, nebbia fra i rami più bassi. Per una volta l'albero tiene per sé la propria altezza, e la città sembra posata su una nuvola.",
	},
	["dar.muse.w23.heartwood.016"] = {
		"Albero giovane, popolo antichissimo, e a portare tutto il peso è l'albero.",
		"Quest'albero ha poco più anni dei miei stivali più vecchi, e si porta in spalla una capitale.",
		"Strana città. Gente vecchia, pavimento nuovo.",
	},
	["dar.muse.w23.heartwood.017"] = {
		"si ferma a guardare un druido che insegna a due più giovani come posare le mani sul tronco, correggendo un polso, un dito, e annuendo solo quando restano immobili.",
		"scorge un vecchio druido premere più a fondo il palmo di un allievo contro la corteccia e dire una sola parola, piano piano, che lo fa sorridere.",
	},
	["dar.muse.w23.heartwood.018"] = {
		"Fin dove scende il tronco? Fino al mare? Fino al mare. Certo. Bene. Benissimo.",
		"Ho un albero intero sotto gli stivali. Continuo a dimenticarmelo, e poi no.",
		"Tutti a camminare normalmente. Il pavimento è un albero e l'albero è altissimo. Normalmente, ho detto.",
	},
	["dar.muse.w23.heartwood.019"] = {
		"Toccherei ferro per scaramanzia, ma qui di ferro non ce n'è, e toccare legno sembra bussare alla porta di qualcuno.",
		"Bussare sul legno? Qui? Rischierei di svegliare qualcuno.",
	},
	["dar.muse.w23.hush.001"] = {
		"Il mio zaino tintinna a ogni passo: fibbie, una tazza di latta, qualche moneta sciolta. Altrove non è niente; qui sembro il carretto di un calderaio.",
		"Ho avvolto la tazza di latta in una calza perché smettesse di sbattere contro le fibbie. Darnassus mi fa fare cose strane.",
	},
	["dar.muse.w23.hush.002"] = {
		"è in una fila silenziosa quando lo stomaco brontola, forte e a lungo, e due kaldorei si voltano con educato interesse.",
		"si preme una mano sullo stomaco che brontola nel silenzio, e finge con tutto l'impegno di studiare gli intagli.",
	},
	["dar.muse.w23.hush.003"] = {
		"si sorprende a fischiettare un motivo da taverna a metà di un ponte, e smette così di colpo che l'ultima nota resta lì da sola.",
		"comincia a canticchiare senza volerlo, se ne accorge e lascia spegnere il motivetto nel nulla.",
	},
	["dar.muse.w23.hush.004"] = {
		"Non avrei mai pensato di sentire la mancanza del cigolio di una ruota di carro. Quassù pagherei buon argento per sentirne passare una.",
		"Un silenzio così rende nervosa la gente di città. Senza carri e grida a scandire le ore, non capisco più che cosa stia facendo la mia giornata.",
	},
	["dar.muse.w23.hush.005"] = {
		"Nei posti che conosco, una sala diventa così silenziosa un attimo prima che qualcuno tiri una sedia. Qui resta silenziosa e basta, e io resto all'erta.",
		"Ogni istinto che ho dice che un silenzio così profondo annuncia guai. Darnassus continua a smentirli, uno dopo l'altro.",
	},
	["dar.muse.w23.hush.006"] = {
		"È maleducato sussurrare, qui? Perché non farlo sembra peggio.",
		"Continuo a parlare sottovoce e nessuno me l'ha chiesto. Questa città fa questo effetto.",
	},
	["dar.muse.w23.hush.007"] = {
		"Due kaldorei parlano dall'altra parte dell'acqua e io sento ogni parola, anche se non ne capisco nessuna. Il suono va lontano, quando niente gli sbarra la strada.",
		"Con così poco rumore in giro, le voci arrivano da una terrazza all'altra. Ho ascoltato un intero affare senza vedere nessuna delle due parti.",
	},
	["dar.muse.w23.hush.008"] = {
		"cammina con uno stivale che cigola a ogni passo, e dopo poco si ferma a strofinare un po' di grasso sul cuoio.",
		"prova tre modi diversi di appoggiare uno stivale che cigola, e cigolano tutti.",
	},
	["dar.muse.w23.hush.009"] = {
		"lascia ricadere una manciata di monete nella borsa e fa una smorfia quando il tintinnio arriva fino a metà terrazza.",
		"conta qualche moneta d'argento per una bancarella e, sentendo fin dove arriva il rumore, finisce di contare con le monete chiuse nel palmo.",
	},
	["dar.muse.w23.hush.010"] = {
		"Mi sono {g:sorpreso|sorpresa} già due volte a parlare da {g:solo|sola}. In una città più rumorosa nessuno sentirebbe. Qui una Sentinella si è voltata, con molta delicatezza, come se potessi aver bisogno d'aiuto.",
		"Ho borbottato qualcosa sui miei stivali, e una sacerdotessa che passava ha mormorato in risposta qualcosa che sembrava comprensione.",
	},
	["dar.muse.w23.hush.011"] = {
		"si schiarisce la voce prima di parlare a un mercante, e quel piccolo rumore sembra non finire più.",
		"posa una tazza di latta su una sporgenza di pietra, e quel piccolo tocco sembra allontanarsi sull'acqua per un bel pezzo.",
	},
	["dar.muse.w23.hush.012"] = {
		"Stormwind ha le sue campane e Ironforge i suoi martelli. Darnassus ha il suono che resta quando smetti di aspettarti gli uni e le altre.",
		"Le orecchie continuano a cercare un rumore che non arriva: un martello, una campana, un carro. Impareranno, oppure me ne andrò prima io.",
	},
	["dar.muse.w23.hush.013"] = {
		"Il silenzio continua a ingannarmi, a farmi credere di essere {g:solo|sola}. Poi mi giro, e a pochi passi c'è un elfo che era lì da sempre.",
		"Qui il silenzio non vuol dire che non c'è nessuno. L'ho imparato voltandomi, più di una volta, e trovando qualcuno immobile poco distante.",
	},
	["dar.muse.w23.hush.014"] = {
		"Qualcuno potrebbe far cadere una pentola? Una sola. Per i miei nervi.",
		"Cosa darei per un cane che abbaia da qualche parte. Un cane qualsiasi, un abbaio qualsiasi.",
		"Un rumore forte. Qualsiasi. Andrebbe bene anche una capra.",
	},
	["dar.muse.w23.hush.015"] = {
		"racconta una battuta a un mercante kaldorei e ottiene una risata fatta quasi solo di spalle e di occhi.",
		"dice qualcosa che fa ridere un elfo lì vicino, e non sente alcun suono: vede solo le spalle sussultare una volta e ricomporsi.",
	},
	["dar.muse.w23.hush.016"] = {
		"La prima ora il silenzio di qui dà fastidio. La seconda si posa. Alla terza sono io a guardare storto un visitatore rumoroso.",
		"Ci vuole un po' per smettere di combattere il silenzio. Poi mi accorgo che cammino più piano e me la prendo con chi non lo fa.",
	},
	["dar.muse.w23.hush.017"] = {
		"alza il pugno per bussare, per abitudine, trova solo un arco aperto e ricurvo, e abbassa la mano con aria impacciata.",
		"cerca una porta a cui bussare all'ingresso di una sala, trova solo un arco aperto e indugia sulla soglia finché qualcuno non {g:gli|le} fa cenno di entrare.",
	},
	["dar.muse.w23.hush.018"] = {
		"In qualunque altra città chiamerei a gran voce qualcuno dall'altra parte della piazza. Qui faccio un cenno, poi uno più ampio, e alla fine attraverso tutta la terrazza a piedi.",
		"Chiamare qualcuno dall'altra parte di una terrazza sarebbe come suonare un gong a un funerale. Così mi sbraccio, come un naufrago.",
	},
	["dar.muse.w23.hush.019"] = {
		"La locanda qui sulla Craftsmen's Terrace dev'essere la sala più vivace di Darnassus. Eppure ci ho sentito qualcuno girare una pagina dall'altra parte.",
		"Perfino la locanda è silenziosa. Da qualche parte dietro le erbe e le pelli di questa terrazza, i viaggiatori bevono senza far tintinnare un bicchiere.",
	},
	["dar.muse.w23.hush.020"] = {
		"Ero nel tempio per chiedere una cosa a una sacerdotessa, e il silenzio era tale che ho dimenticato quale.",
		"Nel tempio abbasso la voce, poi la abbasso ancora, e alla fine decido che la domanda può aspettare un posto più rumoroso.",
	},
	["dar.muse.w23.hush.021"] = {
		"Da dove vengo io, una strada così silenziosa vuol dire che tutti si nascondono da qualcosa. Qui la strada è semplicemente fatta così.",
		"Qui ogni elfo sentirebbe cadere uno spillo. Io ho appena sentito scricchiolare le mie ginocchia, e temo anche loro.",
	},
	["dar.muse.w23.hyjal.001"] = {
		"Per fermare Archimonde sull'Hyjal, i kaldorei hanno rinunciato al per sempre. Vedendo un'anziana massaggiarsi un polso dolorante, capisco che solo da poco impara cosa vuol dire far male e non guarire.",
		"Alcuni elfi di questa città hanno incontrato da poco il primo capello bianco. Lo capisci da come lo toccano, come se fosse di un estraneo.",
	},
	["dar.muse.w23.hyjal.002"] = {
		"Sull'Hyjal, raccontano, un signore dei demoni scalò la montagna per divorare l'Albero del Mondo, e gli elfi della notte lasciarono andare tutta la forza dell'albero per fermarlo. Qui nessuno la chiama vittoria senza una pausa prima.",
		"Archimonde arrivò ai piedi di Nordrassil e non fece un passo di più. Il prezzo fu la benedizione dell'albero e l'eternità degli elfi stessi. Lo pagarono lì, su due piedi.",
	},
	["dar.muse.w23.hyjal.003"] = {
		"osserva un'anziana kaldorei sedersi su un gradino una giuntura alla volta, e la giovane Sentinella accanto fingere, con molta cura, di non accorgersene.",
		"vede un vecchio elfo fermarsi a metà scala con una mano sul ginocchio, con l'aria un po' perplessa di chi ha un corpo che si è messo a dettare regole nuove.",
	},
	["dar.muse.w23.hyjal.004"] = {
		"Nordrassil fu piantato con la benedizione dei grandi draghi, dicono i druidi. Di Teldrassil dicono altre cose, più lentamente, e solo tra loro.",
		"Quando un druido paragona Teldrassil a Nordrassil, resta un piccolo silenzio dove dovrebbe esserci qualcosa. L'ho sentito tre volte ormai, quel silenzio, e mai riempito.",
	},
	["dar.muse.w23.hyjal.005"] = {
		"C'è un erborista in città che vende unguenti per le giunture rigide a gente che in diecimila anni non ha mai avuto una giuntura rigida. Gli affari, dicono, non sono mai andati meglio.",
		"Prima dell'Hyjal nessuno a Darnassus aveva bisogno di un rimedio per le ginocchia. Ora gli erboristi non riescono a tenerne abbastanza. Anche la mortalità ha il suo mercato.",
	},
	["dar.muse.w23.hyjal.006"] = {
		"Hanno barattato l'eternità per salvare il mondo. Direi grazie, ma non so a chi dirlo.",
		"Un intero popolo ha rinunciato a vivere per sempre, sull'Hyjal. Il minimo che posso fare è pulirmi gli stivali.",
	},
	["dar.muse.w23.hyjal.007"] = {
		"Quando Archimonde cadde, dicono i druidi, furono gli spiriti degli antenati kaldorei a trascinarlo giù, migliaia di piccole luci insieme. I fuochi fatui di questa città sono trattati con grande delicatezza, e ora so perché.",
		"Una Sentinella mi ha detto che i fuochi fatui che abbatterono Archimonde erano i morti del suo popolo, chiamati tutti in una volta. L'ha detto come si dice che un nonno ha aiutato a costruire la casa.",
	},
	["dar.muse.w23.hyjal.008"] = {
		"Appena appena, i kaldorei hanno cominciato ad avere fretta. Qualche passo in più al minuto rispetto agli anziani. È il cambiamento più piccolo del mondo, ed è così che appare da fuori la fine dell'immortalità.",
		"Chi è giovane, tra i kaldorei, cammina un filo più svelto degli anziani, e non credo se ne renda conto. Sull'Hyjal è partito un orologio, e i piedi dei giovani l'hanno sentito per primi.",
	},
	["dar.muse.w23.hyjal.009"] = {
		"passa accanto a due sacerdotesse che fasciano un ginocchio sbucciato a un piccolo kaldorei, lente e serissime, come se l'arte di curare le piccole ferite fosse ancora nuova per loro.",
		"segue con discreto interesse una sacerdotessa che pulisce il palmo sbucciato di un bambino con un'attenzione solenne, e il bambino che lo sopporta con la stessa serietà: imparano qualcosa tutti e due.",
	},
	["dar.muse.w23.hyjal.010"] = {
		"Un popolo che progettava per millenni ora deve progettare per vite. Quando piantano un albero si vede il conto che fanno dietro gli occhi.",
		"Diecimila anni di 'ci sarà tempo' sono finiti sull'Hyjal. Ho visto un artigiano kaldorei posare un lavoro a metà e fissarlo, rifacendo i conti con i numeri nuovi.",
	},
	["dar.muse.w23.hyjal.011"] = {
		"Da quando Nordrassil ha dato la sua forza, conto. Gli anni, soprattutto. Prima non contavo nulla, e l'abitudine non mi piace per niente.",
		"Prima dell'Hyjal, il per sempre era semplicemente la forma delle cose. Ora mi sorprendo a contare gli anni, come fanno i popoli dalla vita breve, e mi vergogno di quanta paura mi faccia.",
	},
	["dar.muse.w23.hyjal.012"] = {
		"Umani, orchi ed elfi della notte tennero insieme una montagna contro Archimonde. Poi tornarono a casa e ripresero a odiarsi. È la storia, immagino.",
		"Per qualche settimana disperata, sull'Hyjal, orchi ed elfi combatterono fianco a fianco. I kaldorei lo ricordano con un'espressione che posso solo chiamare profondamente perplessa.",
	},
	["dar.muse.w23.hyjal.013"] = {
		"Hanno salvato il mondo sull'Hyjal, rinunciato all'eternità, e ancora spazzano i gradini come se niente fosse. Notevole.",
		"Pensa: fermi un signore dei demoni, torni a casa, e scopri che adesso hai le ginocchia.",
	},
	["dar.muse.w23.hyjal.014"] = {
		"I druidi di qui parlano di un corno che Malfurion suonò sull'Hyjal, e della risposta venuta da ogni radice e ogni fuoco fatuo della montagna. Il suono non lo descrivono. Tacciono, nel punto dove starebbe.",
		"Nell'Enclave i druidi ricordano l'Hyjal dal corno: un unico richiamo lungo, dicono, e tutta la foresta che si leva. Ogni volta che qualcuno lo racconta, il racconto si ferma nello stesso punto.",
	},
	["dar.muse.w23.hyjal.015"] = {
		"Una Sentinella mi ha detto che un tempo pensava a ogni amicizia come a una lunga passeggiata senza fine in vista. Dall'Hyjal, ha detto, ha cominciato a salutare come si deve.",
		"Da quando l'immortalità se n'è andata, mi ha detto una sacerdotessa, i kaldorei hanno imparato l'abitudine dell'addio. Ci sono ancora goffi, ha aggiunto, e ha sorriso come se fosse una gentilezza.",
	},
	["dar.muse.w23.hyjal.016"] = {
		"nota che ogni volta che una sacerdotessa pronuncia la parola Hyjal volta appena il capo verso sud, come ci si inchina a una tomba passandole accanto.",
		"sorprende una Sentinella anziana a portarsi due dita alla fronte quando si nomina l'Hyjal, un piccolo gesto che le più giovani lì accanto copiano con un attimo di ritardo.",
	},
	["dar.muse.w23.hyjal.017"] = {
		"Un'anziana qui mi ha chiesto, serissima, quanto ci mette di solito a guarire una caviglia slogata. Tutti quei millenni e non aveva mai avuto bisogno di saperlo.",
		"Una kaldorei mi ha chiesto consiglio per un raffreddore. Mi hanno chiesto indicazioni, monete, aiuto in un combattimento, ma mai di spiegare un naso chiuso a qualcuno più vecchio di Stormwind.",
	},
	["dar.muse.w23.hyjal.018"] = {
		"Sento ancora l'odore dell'Hyjal in fiamme quando nel tempio accendono l'incenso troppo forte. Le mie sorelle dicono di no. Credo lo dicano per gentilezza.",
		"Tra noi c'è un silenzio particolare quando si ricordano i fuochi dell'Hyjal. Nessuno distoglie lo sguardo. Nessuno parla. Aspettiamo insieme che passi.",
	},
	["dar.muse.w23.hyjal.019"] = {
		"Nordrassil sta ancora sull'Hyjal, segnato e silenzioso, dicono i druidi. Ne parlano come di un anziano che ha dato tutte le sue forze alla famiglia e ora siede accanto al fuoco.",
		"Vanno a trovare Nordrassil, i druidi, mi dicono, come si va da un vecchio nonno che non parla quasi più. Tornano mansueti e dicono pochissimo.",
	},
	["dar.muse.w23.hyjal.020"] = {
		"L'Hyjal ha tenuto. Ricordatelo, ogni volta che le cose sembrano senza speranza.",
		"Su quella montagna hanno spezzato un signore dei demoni. Qualunque cosa mi aspetti, è più piccola.",
	},
	["dar.muse.w23.hyjal.021"] = {
		"La prima generazione di kaldorei che invecchia lo sta imparando dai popoli che l'hanno sempre fatto. Ho visto un nano spiegare a un elfo come frizionare una spalla col linimento, con una pazienza enorme da entrambe le parti.",
		"La mortalità ha reso i kaldorei curiosi dei popoli dalla vita breve. Un'anziana mi ha chiesto com'è sapere di dover morire. Ho detto 'si ha da fare', e lei se l'è scritto.",
	},
	["dar.muse.w23.hyjal.022"] = {
		"si vede sfiorare da un fuoco fatuo, e nota la vecchia Sentinella accanto al sentiero voltare il capo a seguirlo con una strana tenerezza, come se potesse essere qualcuno che conosceva.",
		"vede un anziano fermarsi per lasciar passare un fuoco fatuo e mormorargli qualcosa, piano piano, come si saluta un vicino al di là di una staccionata.",
	},
	["dar.muse.w23.isle.001"] = {
		"Attraverso il lago è a un tiro di sasso. Girandoci intorno, mezz'ora di sentieri cortesi. Sto seriamente pensando di nuotare.",
		"L'altra riva è lì davanti. I ponti fanno il giro di ogni isolotto prima di arrivarci. A nuoto comincia a sembrare la strada onesta.",
		"Ogni ponte di questa città è una deviazione con vista. Cederei volentieri la vista per un traghetto.",
	},
	["dar.muse.w23.isle.002"] = {
		"squadra il lago fino alla riva opposta, poi il lungo giro dei ponti, e si vede che soppesa il prezzo degli stivali bagnati contro la camminata.",
		"si ferma sulla riva a misurare con occhio esperto la nuotata fino all'altra sponda, mentre una Sentinella di passaggio, a sua volta, studia la scena.",
	},
	["dar.muse.w23.isle.003"] = {
		"Su uno degli isolotti un albero solitario si sporge sull'acqua come se leggesse il proprio riflesso. Laggiù non va mai nessuno, pare. Vorrei sapere chi l'ha piantato.",
		"Certe isole del lago non sono più grandi di una stanza: una chiazza di muschio, una pietra, un alberello magro. Sembrano curate, ma il custode non l'ho mai visto.",
	},
	["dar.muse.w23.isle.004"] = {
		"conta le isole dalla riva e ottiene ogni volta un numero diverso, perché alcune sono solo uno scoglio orlato di canne e altre si nascondono dietro le vicine.",
		"prova a contare le isole del lago, si perde tra le più piccole, poco più di un sasso e un ciuffo verde, e lascia perdere.",
	},
	["dar.muse.w23.isle.005"] = {
		"Un popolo che ha visto la propria terra affondare nel mare, e nel cuore della nuova città ha voluto un lago con piccole isole al sicuro. Mi chiedo se sia stata una scelta o un'abitudine.",
		"Isolette che nessuno potrà mai sommergere. Forse il lago serve a questo, per chi ricorda il mondo che si spezzava.",
	},
	["dar.muse.w23.isle.006"] = {
		"Ogni isolotto laggiù ha un albero, un sasso e una libellula compiaciuta. Li invidio tutti e tre.",
		"Se mai mi ritirerò, voglio uno di quegli isolotti. Un sasso, un albero, acqua tutto intorno. Nessuno potrebbe chiedermi indicazioni.",
	},
	["dar.muse.w23.isle.007"] = {
		"Le voci sul lago viaggiano in modo strano. Due kaldorei che parlano piano sulla riva opposta sembrano starmi accanto.",
		"L'acqua porta i suoni come un vassoio porta le tazze. Una parola detta sottovoce su un isolotto arriva alla riva intera e chiara.",
		"Sull'acqua una risata, piccolissima e limpida, attraversa tutto il lago senza perdere una nota.",
	},
	["dar.muse.w23.isle.008"] = {
		"passa accanto a un kaldorei che pesca dalla riva del lago, la lenza in acqua, così immobile che una libellula si è posata sulla canna.",
		"si ferma a qualche passo da un elfo che pesca sul bordo dell'acqua e aspetta, quasi senza volerlo, di vedere se qualcosa abbocca. Niente. A nessuno dei due importa.",
		"si attarda mentre un pescatore kaldorei ritira la lenza vuota, studia a lungo l'amo spoglio e lo rimanda in acqua senza traccia di delusione.",
	},
	["dar.muse.w23.isle.009"] = {
		"Quanto sarà profondo quel lago? No, non dirmelo. Mi verrebbe voglia di scoprirlo.",
		"Ho chiesto a una Sentinella quanto è profondo il lago. Ha detto 'abbastanza'. Credo fosse un avvertimento.",
		"Potrei chiedere quanto è profondo il lago. Oppure potrei tenermi un po' di mistero nella vita.",
	},
	["dar.muse.w23.isle.010"] = {
		"si sporge dal parapetto di un ponte, valuta di sputare nel lago senza alcun motivo, lancia un'occhiata alla Sentinella più vicina e ci ripensa.",
		"lascia passare un lungo momento ozioso su un ponte, il mento sul parapetto, poi sorprende il proprio riflesso a fare una smorfia e si raddrizza di colpo.",
	},
	["dar.muse.w23.isle.011"] = {
		"Guarda giù da un ponte abbastanza a lungo e le foglie riflesse cominciano a tirare. Per un attimo sembra di poter cadere all'insù dentro il lago.",
		"Sotto il parapetto il lago mostra i rami capovolti, profondi e verdi. A fissarli la città s'inclina; mi tengo al parapetto e aspetto che smetta.",
		"La chioma riflessa è così profonda e ferma che il ponte sembra sospeso tra due foreste, una delle due capovolta.",
	},
	["dar.muse.w23.isle.012"] = {
		"guarda un druido avanzare nell'acqua bassa fino alle ginocchia vicino a un isolotto, la veste annodata ai fianchi, strappare qualcosa dal fondo con tutte le radici e studiarlo accigliato.",
		"nota una druida ferma nell'acqua bassa del lago, la veste sollevata, che esamina una manciata d'alghe gocciolanti con l'aria di una guaritrice che legge una ferita.",
	},
	["dar.muse.w23.isle.013"] = {
		"Monete che passano di mano così vicino all'acqua corrente. Un attimo di goffaggine e l'argento di qualcuno prende la via lunga verso il mare.",
		"Contare soldi accanto a un ruscello mi rende {g:nervoso|nervosa}. Uno scivolone e i miei risparmi vanno a fare un giro turistico giù per il tronco.",
	},
	["dar.muse.w23.isle.014"] = {
		"Per quanto lontano io vada, il suono di quest'acqua mi mette in pace qualcosa dentro. Non casa come luogo. Casa come suono.",
		"In nessun'altra parte del mondo una fontana suona come queste. Le riconoscerei a occhi chiusi, nel sonno, dopo cent'anni.",
	},
	["dar.muse.w23.isle.015"] = {
		"guarda due Sentinelle attraversare un ponte fianco a fianco, mentre i loro riflessi camminano capovolti sotto di loro, passo per passo, senza un'increspatura.",
		"vede una sacerdotessa attraversare una passerella con un passo così liscio che il suo riflesso, sotto, non trema nemmeno una volta.",
	},
	["dar.muse.w23.isle.016"] = {
		"Il lago quassù è così calmo che è difficile credere che lo stesso mondo contenga il mare attorno alle radici, a rodere la corteccia. Due acque, un albero, e non si guardano mai.",
		"Lago tranquillo sopra, mare inquieto sotto, e tutta l'altezza di Teldrassil in mezzo. L'albero tiene separate le due acque come un padrone di casa paziente che mette due rivali ai capi opposti del tavolo.",
	},
	["dar.muse.w23.isle.017"] = {
		"Quell'isolotto ha un ponte tutto per sé, e sopra solo muschio. Rispetto una città che costruisce un ponte per far visita al muschio.",
		"Un ponte intero, per arrivare a una chiazza di muschio. A Darnassus non è uno spreco, è cortesia.",
	},
	["dar.muse.w23.kaldorei.001"] = {
		"sente un druido in forma di felino fermarsi sul sentiero, tornare elfo giusto il tempo di finire una frase con un amico, e ricadere su quattro zampe per proseguire.",
		"ascolta di sfuggita una conversazione fra due elfi in cui uno dei due, per un po', è un grosso felino, e nessuno dei due ci trova niente di strano.",
		"nota un felino che cammina accanto a una Sentinella, e solo quando si ferma a starnutire in un modo molto da elfo capisce che era un druido fin dall'inizio.",
	},
	["dar.muse.w23.kaldorei.002"] = {
		"Un druido che da elfo si gratta dietro un orecchio fa esattamente lo stesso da orso. Certe abitudini stanno più a fondo della forma.",
		"Ho visto una druida tormentarsi la manica, trasformarsi in orso e continuare a tormentarla con una zampa, una manica che non c'era più.",
	},
	["dar.muse.w23.kaldorei.003"] = {
		"Dove finiscono i vestiti di una druida quando diventa un felino? L'ho chiesto a una. Mi ha risposto che era una domanda molto scortese, e ha sorriso.",
		"Nessuno vuole dirmi dove vadano gli stivali di un druido mentre è un orso. L'ho chiesto tre volte e ho ricevuto tre sorrisi diversi.",
	},
	["dar.muse.w23.kaldorei.004"] = {
		"nota che il druido davanti a {g:lui|lei} cammina scalzo sulla pietra, piegando appena le dita a ogni passo, come se leggesse il sentiero con i piedi.",
		"scorge una druida fermarsi a togliersi i sandali prima di mettere piede sull'erba, e portarli in mano per il resto della strada.",
		"vede un druido fermarsi sul sentiero e premere il palmo sull'erba, come si tocca la fronte di un bambino che dorme, e ripartire soddisfatto.",
	},
	["dar.muse.w23.kaldorei.005"] = {
		"Una Sentinella mi ha detto, molto asciutta, che i druidi hanno dormito per gran parte della storia e fanno ancora un pisolino appena possono. Non sembrava scherzare.",
		"Fra le Sentinelle gira un piccolo scherzo antico sui druidi e il sonno. L'ho sentito due volte, raccontato con le stesse identiche parole, ed entrambe le volte chi lo raccontava non ha sorriso.",
	},
	["dar.muse.w23.kaldorei.006"] = {
		"Qui nell'Enclave i druidi tengono orari tutti loro. Uno è immerso nello studio, un altro disteso sull'erba a occhi chiusi, ed è impossibile dire chi dei due lavori di più.",
		"Nell'Enclave nessuno sembra fare niente, e tutti sono occupati. Di un druido disteso nell'erba a occhi chiusi mi hanno detto che era «in riunione».",
	},
	["dar.muse.w23.kaldorei.007"] = {
		"Un conciatore kaldorei misura, aspetta, misura ancora, e poi aspetta un altro po'. Il taglio, quando arriva, è un colpo solo.",
		"Ho visto qualcuno davanti a un banco studiare una pelle così a lungo che ho finito per allontanarmi. Al mio ritorno il lavoro era fatto, e fatto alla perfezione, come in un solo attimo.",
		"L'artigianato kaldorei è soprattutto attesa. Poi un solo gesto, esatto, e si torna ad aspettare.",
	},
	["dar.muse.w23.kaldorei.008"] = {
		"indugia accanto a un fabbricante di frecce che rifila penne con un coltellino minuscolo, ogni taglio così simile al precedente che le frecce sembrano copie l'una dell'altra.",
		"resta un po' accanto a un banco dove un kaldorei fissa le penne alle aste, tenendo ferma ciascuna ben oltre il momento in cui qualunque colla ne avrebbe bisogno.",
	},
	["dar.muse.w23.kaldorei.009"] = {
		"Ho provato a comprare un mantello dal tavolo di un sarto kaldorei. Non è finito, mi hanno detto. Sembrava finito. A quanto pare continuerà a sembrarlo per un'altra stagione o due.",
		"Certi lavori sui banchi degli artigiani non sono ancora in vendita, e in questa città quell'«ancora» può durare moltissimo.",
	},
	["dar.muse.w23.kaldorei.010"] = {
		"osserva un conciatore qui sulla terrazza che fa penetrare l'olio in una pelle col palmo della mano, a cerchi lenti, sempre lo stesso cerchio, per moltissimo tempo.",
		"rallenta sulla terrazza accanto a un'artigiana che riavvolge il filo sul rocchetto dopo un errore che nessun altro avrebbe notato, disfacendo un lungo tratto di lavoro senza un sospiro.",
	},
	["dar.muse.w23.kaldorei.011"] = {
		"Fra i kaldorei si rammenda tutto. A una cinghia strappata si danno punti nuovi, non una cinghia nuova. Quando le cose devono durare secoli, immagino che si impari ad amare l'ago.",
		"Non ho mai visto un kaldorei buttare via qualcosa. Le ciotole incrinate si legano, le suole consumate si rifanno. Qui ci si aspetta che le cose invecchino insieme a chi le possiede.",
		"Un calzolaio kaldorei mi ha risuolato gli stivali mentre aspettavo. Poi li ha risuolati daccapo, perché il primo lavoro era soltanto «accettabile».",
	},
	["dar.muse.w23.kaldorei.012"] = {
		"Prenditi il tuo tempo. No, davvero, vedo che lo farai.",
		"È finito? Non rispondere. Dalla faccia capisco che è una domanda filosofica.",
		"Lavoro splendido. Quanto ci è voluto? No, non dirmelo. Mi verrebbero solo i sensi di colpa.",
	},
	["dar.muse.w23.kaldorei.013"] = {
		"Da Hyjal in poi, alcuni kaldorei hanno cominciato a camminare un po' più in fretta. Non tanto. Una Sentinella mi ha detto che è perché adesso gli anni contano davvero.",
		"Fra i kaldorei c'è una cosa nuova, mi ha detto una sacerdotessa: l'impazienza. Da quando hanno rinunciato all'immortalità a Hyjal, alcuni dei più giovani l'hanno presa come si prende un'infreddatura.",
	},
	["dar.muse.w23.kaldorei.014"] = {
		"Le facce, i kaldorei le ricordano. Un mercante mi ha salutato per nome dopo una sola visita, a mesi di distanza. Non so se sia una lusinga o un campanello d'allarme.",
		"Incontri un kaldorei una volta e la volta dopo ti riconosce, e anche alla terza. Le loro memorie sembrano avere moltissimo spazio.",
	},
	["dar.muse.w23.kaldorei.015"] = {
		"Stare da soli in compagnia: i kaldorei ci riescono benissimo. Tre di loro possono dividersi un fazzoletto d'erba senza una parola e sembrare i migliori amici del mondo.",
		"Il silenzio fra kaldorei non è imbarazzante. Due di loro sono rimasti accanto a me a lungo senza dire niente, e solo io sentivo il bisogno di riempirlo.",
	},
	["dar.muse.w23.kaldorei.016"] = {
		"A notte fonda i banchi di lavoro sono più affollati che di giorno. I kaldorei lavorano meglio con poca luce, o così mi ha detto un conciatore senza alzare lo sguardo.",
		"Le mani della città sono più indaffarate al buio. Aghi, lesine e mortai, tutti all'opera in silenzio, come se il lavoro aspettasse solo che il sole se ne andasse.",
	},
	["dar.muse.w23.kaldorei.017"] = {
		"nota una Sentinella di guardia con gli occhi socchiusi contro la luce piena del giorno, l'unico segno che quella non è la sua ora.",
		"sorprende una sacerdotessa a tirare un po' avanti il cappuccio contro il riverbero del giorno, come se il sole fosse un ospite che parla troppo forte.",
	},
	["dar.muse.w23.kaldorei.018"] = {
		"I kaldorei non affrettano il passo per la pioggia. La attraversano allo stesso ritmo, cappuccio abbassato, come se bagnarsi facesse semplicemente parte della passeggiata.",
		"Piove, e nessun kaldorei si mette a correre. Una Sentinella è rimasta al suo posto sotto l'acqua che le colava dal mento, con l'aria quasi soddisfatta.",
	},
	["dar.muse.w23.kaldorei.019"] = {
		"I visitatori ci guardano come se fossimo lenti. Non siamo lenti. È solo che prima non eravamo mai in ritardo per niente.",
		"Gli stranieri pensano che ce la prendiamo comoda. Ci hanno cresciuti persone che avevano l'eternità, e non l'abbiamo disimparato. Forse non dovremmo.",
	},
	["dar.muse.w23.kaldorei.020"] = {
		"Ogni Sentinella che incrocio potrebbe essere stata a Hyjal. Alcune c'erano. Le saluto tutte allo stesso modo, perché non so distinguere quali.",
		"Alle Sentinelle mi inchino un po' più a fondo di quanto facciano i forestieri. Hanno custodito le foreste mentre gli altri di noi sognavano o dimenticavano. È il minimo dovuto.",
	},
	["dar.muse.w23.kaldorei.021"] = {
		"Piano. La città non scappa, e noi nemmeno.",
		"Cammina un po' con me. Qui non c'è fretta, non per noi.",
	},
	["dar.muse.w23.kaldorei.022"] = {
		"Ogni Sentinella qui ha un glaive e una lunga memoria. Tengo gli occhi bassi e le maniere impeccabili.",
		"In questa città ho imparato a camminare piano. Niente tradisce uno straniero più della fretta, e non posso permettermi che qualcuno mi guardi due volte.",
	},
	["dar.muse.w23.kaldorei.023"] = {
		"Scusa, sei un druido o un orso molto tranquillo? Vorrei rivolgermi a te nel modo giusto.",
		"Se quel gatto mi risponde, avrò bisogno di sedermi.",
		"Quel gatto mi ha appena fatto un cenno. Ricambio. Ho deciso di non pensarci.",
	},
	["dar.muse.w23.kaldorei.024"] = {
		"guarda un druido in forma d'orso fare la fila con grande pazienza davanti a una bancarella, per poi tornare elfo, arrivato in testa, giusto il tempo di pagare.",
		"vede un druido passare da felino a elfo a metà di un passo, e finirlo su due piedi come se non fosse cambiato proprio niente.",
		"si ritrova in fila dietro un orso davanti a una bancarella, e si sorprende solo un poco quando, arrivato al banco, l'orso si alza in piedi, diventa un druido e chiede del filo.",
	},
	["dar.muse.w23.manner.001"] = {
		"Un kaldorei ha definito una vecchia lite «piuttosto recente». Era cominciata, per quanto ho capito, prima che a Stormwind qualcuno sapesse leggere.",
		"«Non molto tempo fa», dice un kaldorei, e ho imparato a chiedere: non molto tempo per chi? Di solito la risposta è qualche secolo.",
		"«Di recente», detto da un kaldorei, è un'espressione da montagna. Ho smesso di chiedere date.",
	},
	["dar.muse.w23.manner.002"] = {
		"I kaldorei lasciano un vuoto quando smetti di parlare, nel caso tu non avessi finito. Io non ho quasi mai finito. Mi sta facendo dire più di quanto volessi.",
		"Qui nessuno interrompe. Finisci una frase e segue un piccolo silenzio cortese, in attesa di vedere se ne arriva un'altra. Io continuo a riempirlo.",
		"Parla con un kaldorei e potrai dire tutto quello che hai da dire, ogni volta, e poi verrà una piccola pausa, nel caso volessi ritirarne qualcosa.",
	},
	["dar.muse.w23.manner.003"] = {
		"lascia cadere un guanto sul sentiero, e un kaldorei di passaggio glielo restituisce porgendolo su entrambi i palmi, come fosse qualcosa di prezioso.",
		"si lascia sfuggire una moneta che rotola via; un kaldorei la ferma col piede, la raccoglie e la rende con un piccolo inchino, quasi scusandosi con la moneta per il disturbo.",
		"sfiora la manica di un kaldorei passando, chiede scusa, e riceve in risposta delle scuse lunghe il doppio.",
	},
	["dar.muse.w23.manner.004"] = {
		"Chiedi a un kaldorei quanti anni ha e ti risponde con cifre tonde. Molto tonde.",
		"Ho chiesto l'età a un'elfa. Mi ha dato un secolo, più o meno uno. Non ho chiesto quale.",
		"Quanti anni? No, non dirmelo. Perderei il conto.",
	},
	["dar.muse.w23.manner.005"] = {
		"Continuo a vedere kaldorei sfiorare lo stipite entrando, leggermente, con due dita. Nessuno me l'ha spiegato, e non ho avuto il coraggio di chiedere.",
		"Due dita sullo stipite entrando, ogni volta, Sentinelle e mercanti allo stesso modo. Forse una cortesia verso il legno. Forse solo abitudine. Ho cominciato a farlo anch'io.",
	},
	["dar.muse.w23.manner.006"] = {
		"Una mercante kaldorei mi ha detto di tornare «quando arriva la merce nuova». Intendeva fra tre anni circa, e lo intendeva con gentilezza.",
		"Torna più tardi, ha detto il mercante. Con un kaldorei ho imparato a chiedere: più tardi in questa stagione, o in questo secolo?",
	},
	["dar.muse.w23.manner.007"] = {
		"guarda due kaldorei incontrarsi sul sentiero e restare un lungo momento con le fronti quasi a contatto, in silenzio, prima di andarsene ciascuno per la sua strada.",
		"vede due vecchi amici incontrarsi sul sentiero: niente abbracci, niente strette di mano, solo un lungo sguardo e un lento cenno condiviso, come per riprendere un discorso lasciato a metà tanto tempo fa.",
		"osserva due kaldorei stringersi l'avambraccio per il tempo di qualche parola e lasciarsi nello stesso istante, come d'accordo.",
	},
	["dar.muse.w23.manner.008"] = {
		"Qui tutti si muovono come se portassero qualcosa pieno fino all'orlo.",
		"Conosco ghiacciai più veloci. Più eleganti, no.",
		"Scusa, ti sorpasso. Piano. Con rispetto. Nel giro di un po'.",
	},
	["dar.muse.w23.manner.009"] = {
		"Grazie. No, più piano. Grazie.",
		"Grazie, davvero. Ecco, l'ho detto con calma. Sto imparando.",
		"Grazie. Lo penso sul serio, anche se l'ho detto in fretta.",
	},
	["dar.muse.w23.manner.010"] = {
		"Una volta ho ripetuto una cosa a una kaldorei, per sicurezza. Mi ha guardato perplessa e ha detto che mi aveva sentito la prima volta. Non era un rimprovero. Era un fatto.",
		"Ripeti una cosa a un kaldorei e ricevi uno sguardo paziente, come se gli avessi dato due volte la stessa moneta. Ascoltano con attenzione, e si aspettano di essere ascoltati allo stesso modo.",
	},
	["dar.muse.w23.manner.011"] = {
		"chiede la strada a un kaldorei di passaggio e riceve, dopo una pausa abbastanza lunga da farsi delle domande, una risposta completa fino al numero delle svolte.",
		"rivolge una domanda veloce a un kaldorei e aspetta in un silenzio che sembra soppesarla con cura, finché non arriva una risposta piena e meditata.",
		"fa una domanda semplice a un kaldorei e ottiene la risposta, la sua ragione, e un breve e cortese avvertimento sulla seconda svolta.",
	},
	["dar.muse.w23.manner.012"] = {
		"Col dito, i kaldorei non indicano. Voltano tutta la mano, palmo in su, verso dove devi andare, come se ti presentassero il sentiero.",
		"Qui le indicazioni arrivano con la mano aperta, offerte come un dono lungo il quale si può camminare. Non ho ancora visto un kaldorei puntare il dito verso qualcosa.",
		"Ho notato che i kaldorei non indicano mai una persona. Mai. Una Sentinella mi ha guardato di traverso quando l'ho fatto, e ho smesso.",
	},
	["dar.muse.w23.manner.013"] = {
		"Ho sentito il nome di Elune nel mezzo di una contrattazione, di una sgridata e di uno scherzo, pronunciato ogni volta con la facilità del nome di un'amica.",
		"Nei discorsi di tutti i giorni dei kaldorei la dea compare come altrove compare il nome di un vicino: una parola di passaggio, mai una predica.",
	},
	["dar.muse.w23.manner.014"] = {
		"osserva un kaldorei congedarsi da un amico: una parola, un mezzo giro, e nessuno sguardo indietro, il commiato chiuso pulito come un nodo.",
		"nota che gli amici kaldorei si separano senza indugiare, una parola sommessa e due schiene voltate, come se entrambi fossero certi di avere tempo per rivedersi.",
	},
	["dar.muse.w23.manner.015"] = {
		"I commiati dei kaldorei sono brevi, come se un altro incontro fosse certo. Per gran parte della loro storia lo era. Da Hyjal in poi, mi chiedo se l'abitudine abbia cominciato a fare male.",
		"Per chi non ha mai temuto di restare senza tempo, un addio non aveva bisogno di essere lungo. Quella certezza l'hanno persa a Hyjal, ma gli addii brevi sono rimasti.",
	},
	["dar.muse.w23.manner.016"] = {
		"Ho cominciato a fare l'inchino ai bottegai. Aiuto.",
		"Ho appena chiesto scusa a una porta per averla urtata. Questa città mi sta entrando dentro.",
		"Ho detto «permesso» a un albero. A mia discolpa, forse stava ascoltando.",
	},
	["dar.muse.w23.manner.017"] = {
		"I kaldorei parlano il Comune come chi maneggia cristalli presi in prestito: con precisione, un po' rigidi, attentissimi a non far cadere una parola.",
		"Il loro Comune è migliore del mio, e più lento. Ogni parola posata apposta, niente di biascicato, niente di inghiottito. Ascoltandoli, mi sembra di parlare in modo sciatto.",
		"Il Comune dei kaldorei ha spigoli che nella mia bocca non avevo mai notato. Ogni consonante riceve tutto quello che le spetta.",
	},
	["dar.muse.w23.manner.018"] = {
		"Lo sguardo di un kaldorei dura un attimo più di quello di chiunque altro. Non è maleducazione. È scrupolo.",
		"Reggono uno sguardo un po' oltre il punto in cui quasi tutti lo distoglierebbero. Ho imparato a ricambiarlo. In ogni caso sembra di perdere una partita lenta.",
	},
	["dar.muse.w23.manner.019"] = {
		"nota che il kaldorei {g:lo|la} ascolta con le orecchie protese in avanti, come quelle di un gatto verso un rumore, e cerca di dire qualcosa che meriti tanta attenzione.",
		"vede le lunghe orecchie di un mercante kaldorei abbassarsi appena mentre si discute il prezzo, e sospetta che dicano più del mercante stesso.",
		"coglie l'orecchio di un kaldorei che scatta verso una voce lontana nel mezzo della conversazione, e aspetta educatamente che il resto dell'elfo lo raggiunga.",
	},
	["dar.muse.w23.manner.020"] = {
		"Guarda le orecchie, mi ha detto una Sentinella, se vuoi sapere cosa pensa davvero un kaldorei. Lo ha detto con le orecchie perfettamente immobili.",
		"Mi hanno detto che le orecchie tradiscono i kaldorei. Chi me l'ha detto teneva le sue così ferme che doveva essere una lezione anche quella.",
	},
	["dar.muse.w23.manner.021"] = {
		"Un mercante kaldorei mi ha incartato l'acquisto in una foglia e un filo d'erba ritorto, piegato così bene che quasi non volevo aprirlo.",
		"Il mio acquisto è arrivato avvolto in un panno, legato con un nodo che non sapevo sciogliere senza una lezione. Il mercante me l'ha insegnata. Ci è voluto un po'. Nessuno se l'è presa.",
		"In questa città anche una manciata di chiodi si incarta come un regalo. Il mercante ha piegato il panno, ne ha rimboccato gli angoli e me l'ha porto come se contenesse qualcosa di raro.",
	},
	["dar.muse.w23.manner.022"] = {
		"Scusa. Troppo veloce? Ricomincio, più piano.",
		"Era una scortesia? Con voi non lo capisco mai. Siete tutti così educati anche in questo.",
		"L'ho detto troppo forte? Lo capisco dai gufi.",
	},
	["dar.muse.w23.manner.023"] = {
		"Qui fra i mercanti della terrazza un affare si chiude con un piccolo cenno reciproco, mai con una stretta di mano. Una volta ho teso la mia, e l'hanno guardata con interesse cortese, come una conchiglia curiosa.",
		"Su questa terrazza nessuno stringe la mano per un affare. Un cenno da entrambe le parti, un piccolo inchino, ed è concluso come un contratto.",
		"Su questa terrazza i prezzi si dicono una volta, a bassa voce, e non si ripetono. Contrattare è permesso; alzare la voce per farlo no.",
	},
	["dar.muse.w23.manner.024"] = {
		"Altrove lo chiamerei freddezza: un lungo sguardo, un cenno, e nient'altro. Fra i kaldorei, ho imparato, è quasi un abbraccio.",
		"Non abbracciano, non danno pacche sulle spalle, non chiedono come stai. I kaldorei mostrano stima ricordando il tuo nome un anno dopo.",
	},
	["dar.muse.w23.manner.025"] = {
		"Grazie delle indicazioni. Adesso mi perderò più lentamente.",
		"Hai avuto molta pazienza con me. Cercherò di meritarla.",
		"Mi hai risposto due volte alla stessa domanda, ed entrambe le volte come se fosse nuova. Grazie.",
	},
	["dar.muse.w23.manner.026"] = {
		"Potreste parlare un po' più forte? No? No. Certo che no.",
		"Sto bisbigliando da un'ora e nessuno me l'ha chiesto. È contagioso.",
	},
	["dar.muse.w23.moss.001"] = {
		"Qui il muschio cresce su tutto quello che resta fermo abbastanza a lungo. Ho cominciato a spostare il peso ogni tanto, giusto per sicurezza.",
		"Siediti troppo a lungo su un gradino di Darnassus e il muschio comincia a prenderti le misure. Meglio alzarsi prima che finisca.",
	},
	["dar.muse.w23.moss.002"] = {
		"osserva una lumaca avanzare lungo il parapetto di un ponte, e dopo un po' si rende conto che sta guadagnando terreno su una coppia di anziani druidi diretti dalla stessa parte.",
		"segue l'avanzata di una lumaca su un gradino scolpito, e smette di interessarsene solo quando diventa chiaro che la lumaca ha più senso dell'orientamento.",
		"posa una foglia caduta davanti a una lumaca, a fare da ponte sopra una pozzanghera, e la lumaca la aggira con perfetta serenità.",
	},
	["dar.muse.w23.moss.003"] = {
		"I funghi tra le radici brillano, di un azzurro tenue nell'ombra. In qualunque altra città lo prenderei come il segnale di smettere di mangiare quello che ho appena mangiato.",
		"Piccoli funghi azzurri splendono ai piedi dei muri, come lampade per bestiole più piccole dei topi. In questa città qualcuno illumina tutto, pavimento compreso.",
	},
	["dar.muse.w23.moss.004"] = {
		"Non pestare i funghi. Non so perché. Ma ha tutta l'aria di una città che se lo ricorderebbe.",
		"Occhio ai funghi. Nessuno me l'ha detto, ma qui hanno la memoria lunga, e non ci tengo a finirci dentro per questo.",
	},
	["dar.muse.w23.moss.005"] = {
		"Una felce accanto al sentiero sta srotolando un'unica fronda, così piano che giurerei sia ferma, come si apre una lettera che non si è sicuri di voler leggere.",
		"Le felci giovani si arricciano accanto ai gradini come i ricci dei violini. Ripassa dopo qualche giorno e una si è aperta, appena appena, come se cercasse di non farsi notare.",
	},
	["dar.muse.w23.moss.006"] = {
		"preme il palmo nel muschio accanto al sentiero e guarda l'impronta riempirsi di nuovo, adagio, finché non resta alcun segno che qualcuno sia mai passato.",
		"affonda una mano in un cuscino di muschio fino alle nocche, e la ritrae fresca, umida e lievemente profumata, come da un catino.",
		"passa il pollice sul muschio di una ringhiera e scopre che è stato pareggiato, appena appena, a un'altezza uniforme, come la barba di un vecchio nano scrupoloso.",
	},
	["dar.muse.w23.moss.007"] = {
		"Qui c'è un coleottero minuscolo con il guscio dello stesso colore della veste di una sacerdotessa. A Stormwind, mi dicono, i gioiellieri chiedono una fortuna per molto meno.",
		"Un coleottero mi ha attraversato lo stivale con un dorso di vetro viola lucidato. Se gli gnomi imparassero a fare uno smalto così fine, diventerebbero insopportabili.",
	},
	["dar.muse.w23.moss.008"] = {
		"La pietra chiara qui sta già raccogliendo licheni in anelli grigioverdi. Una città giovane, dicono tutti. Ai licheni nessuno l'ha detto.",
		"Sulle ringhiere hanno cominciato i licheni, piccole rosette grigie che si allargano dagli angoli. Lascia passare qualche secolo e Darnassus sembrerà vecchia quanto la sua gente.",
	},
	["dar.muse.w23.moss.009"] = {
		"Qualcuno dovrebbe dire al muschio che questa è una città. Lui crede di essere un bosco con delle ambizioni.",
		"Il muschio sta vincendo. A nessuno qui sembra importare, quindi non importerà nemmeno a me.",
	},
	["dar.muse.w23.moss.010"] = {
		"si accovaccia a guardare una fila di formiche che trasporta briciole lungo il bordo di un gradino, di gran lunga la gente più indaffarata di tutta la terrazza.",
		"aspetta davanti a una fila di formiche che trascina lungo una crepa della pietra una crosta di pane grande il doppio di loro, e riparte solo quando è passata l'ultima.",
	},
	["dar.muse.w23.moss.011"] = {
		"Sotto tutto questo silenzio c'è un ticchettio piccolo e costante nel muschio: grilli, coleotteri, cose a cui non so dare un nome, che tengono il tempo per una città che non se ne cura.",
		"Ascolta bene e i prati sono pieni di rumori minuscoli: uno scatto, un raschio, un ronzio d'ali. Darnassus è quieta solo perché qui tutto parla così in piccolo.",
	},
	["dar.muse.w23.moss.012"] = {
		"Da dove vengo io il muschio significa muri umidi e un padrone di casa che non ripara il tetto. Qui lo curano come un prato, e probabilmente mi multerebbero se lo rovinassi.",
		"Nella maggior parte delle città il muschio è una cosa da raschiare via. A Darnassus è una cosa da aggirare, con cura, chiedendo scusa a mezza voce.",
	},
	["dar.muse.w23.moss.013"] = {
		"aggira un cerchio di piccoli funghi chiari sul prato, e nota che ogni elfo che passa fa la stessa piccola deviazione senza sembrare pensarci.",
		"nota un cerchio perfetto di funghi minuscoli nell'erba, e un druido di passaggio che allunga un passo quanto basta per non metterci piede dentro.",
	},
	["dar.muse.w23.moss.014"] = {
		"Sotto le foglie che gocciolano il muschio beve e si gonfia finché ogni passo ci affonda un poco, e dietro di me l'impronta si riempie di una piccola pozza limpida.",
		"La pioggia arriva finalmente al muschio, una goccia grassa dopo l'altra, e tutta la città comincia a profumare come l'interno di un bosco dopo una lunga attesa.",
	},
	["dar.muse.w23.moss.015"] = {
		"A Ironforge il muschio cresce negli angoli che nessuno spazza. Qui spazzerebbero via me piuttosto che il muschio, e lo farebbero con garbo.",
		"Sotto la montagna, il muschio sulla pietra vuol dire che qualcuno batte la fiacca. Qui vuol dire che qualcuno ha lavorato sodo. Non mi ci abituerò mai.",
	},
	["dar.muse.w23.moss.016"] = {
		"sosta nell'Enclave accanto a un ramo caduto lasciato esattamente dov'era, ora coperto di peluria verde e di funghi, che i druidi scavalcano come si scavalca un ospite addormentato.",
		"passa accanto a un ramo caduto qui nell'Enclave che nessuno ha portato via; il muschio se l'è preso, le felci si sono prese il muschio, e sulla sua estremità un druido siede a leggere.",
	},
	["dar.muse.w23.moss.017"] = {
		"Un bruco si sta mangiando una foglia grande come un mantello, senza la minima fretta. Di questo passo finirà la chioma in qualche migliaio d'anni. Sembra saperlo.",
		"Su una delle grandi foglie c'è un bruco verde che rosicchia una mezzaluna precisa dal bordo. Ha davanti l'albero intero e le maniere di un ospite a una cena lunghissima.",
	},
	["dar.muse.w23.moss.018"] = {
		"La rugiada resta sul muschio a ogni ora, in perline così fini che sembra brina finché non la tocchi. In questa città niente si asciuga mai del tutto.",
		"Inginocchiati accanto a un gradino qualunque di Darnassus e il muschio è tempestato di goccioline. Non l'ho mai visto asciutto. Non so se l'albero lo permetterebbe.",
	},
	["dar.muse.w23.moss.019"] = {
		"Questo muschio è più morbido di qualunque letto abbia mai pagato. Cerco di non farne una questione di principio.",
		"Se mi sdraio sul muschio, qualcuno mi farà la multa o mi rimboccherà le coperte? In questa città può andare in tutti e due i modi.",
	},
	["dar.muse.w23.moss.020"] = {
		"Quella lumaca mi ha superato due volte. Preferisco credere che giri in tondo.",
		"Non fate caso a me. Sto gareggiando con una lumaca, e sto perdendo.",
	},
	["dar.muse.w23.owl.001"] = {
		"Metà degli archi della città portano gufi scolpiti, e i gufi veri ci si appollaiano sopra. Non so dire se sia un omaggio o una protesta.",
		"Sopra una porta c'è un gufo vivo appollaiato su un gufo di pietra, identico in tutto, solo che uno dei due sbatte le palpebre.",
		"Gufi scolpiti sulle ringhiere, gufi scolpiti sotto le gronde, e uno vero seduto sulla scultura, con l'aria di sentirsi un po' superiore.",
	},
	["dar.muse.w23.owl.002"] = {
		"osserva un gufo che si liscia le penne su una sporgenza alta, finché una piumetta morbida si stacca e scende a spirale fino al sentiero, dove un elfo di passaggio la scavalca con cura.",
		"alza gli occhi quando una piuma leggera scende dai rami girando piano, e la segue a ritroso fino a un gufo che si sta pulendo lassù con grande serietà.",
		"vede una piuma lunga un dito posarsi sull'acqua di un ruscello, e un gufo lassù che la guarda allontanarsi con un vago rimpianto.",
	},
	["dar.muse.w23.owl.003"] = {
		"Quel gufo mi segue di tetto in tetto. O sono una persona affascinante, o gli devo dei soldi.",
		"Stesso gufo, terzo tetto. Mi pedina qualcosa che ci vede meglio di qualunque spia di Stormwind.",
	},
	["dar.muse.w23.owl.004"] = {
		"I gufi qui non sono soprammobili. Ne ho visto uno portar via un topo dall'orlo di un sacco di grano, così pulito che l'artigiano lì accanto non ha nemmeno alzato la testa.",
		"Con tutte le loro facce solenni, i gufi della città lavorano. Un topo si è fatto troppo audace vicino alla Craftsmen's Terrace, e un gufo ha chiuso la faccenda con una sola picchiata silenziosa.",
		"Le Sentinelle sostengono che i gufi della città prendano solo i parassiti e mai gli uccelli canori. Non posso garantirlo, ma gli uccelli canori qui sono straordinariamente tranquilli.",
	},
	["dar.muse.w23.owl.005"] = {
		"Una Sentinella mi ha detto che sa capire cosa ha mangiato un gufo da quello che lascia sotto il posatoio. L'ho ringraziata e non le ho chiesto una dimostrazione.",
		"Secondo una Sentinella con cui ho parlato, quelle palline grigie sotto ogni posatoio sono il registro completo dei topi della città. Lei lo trovava affascinante. Io ci ho girato intorno.",
	},
	["dar.muse.w23.owl.006"] = {
		"nota una sagoma alata attraversare uno squarcio della chioma, molto più in alto: un ippogrifo, a giudicare dal profilo, sparito prima che le foglie si richiudano.",
		"intravede un ippogrifo da un varco tra le grandi foglie, le ali aperte e immobili, che scivola sul verde come un pensiero troppo grande per la città.",
		"coglie il breve buio dell'ombra di un ippogrifo che passa sulle foglie in alto, e il lieve affievolirsi della luce verde subito dopo.",
	},
	["dar.muse.w23.owl.007"] = {
		"Sopra la chioma grida un ippogrifo: un verso da falco, ma con opinioni molto più grandi. Sul sentiero nessuno alza nemmeno lo sguardo.",
		"Quello strillo oltre le foglie è un ippogrifo, mi ha assicurato una Sentinella. L'ha detto come si parla della capra chiassosa dei vicini.",
	},
	["dar.muse.w23.owl.008"] = {
		"Un gufo ha attraversato il sentiero all'altezza della mia faccia e non ho sentito niente, nemmeno un fruscio d'ali. Ho conosciuto gatti più rumorosi.",
		"Il volo del gufo è muto. Uno mi è passato abbastanza vicino da toccarlo, e l'ho capito solo perché la lampada alle sue spalle si è spenta per un istante.",
		"Qualcosa mi è sfilato accanto all'orecchio come un mantello lanciato, senza un sussurro. Il tempo di voltare la testa e il gufo si stava già sistemando su una ringhiera.",
	},
	["dar.muse.w23.owl.009"] = {
		"Ho chiesto la strada a un gufo. Mi ha guardato come a dire: e tu chi saresti? Bella domanda, certi giorni.",
		"Scusa, gufo. La banca? No? Allora smettila di guardarmi come se a non sapere la strada fossi io.",
	},
	["dar.muse.w23.owl.010"] = {
		"Un gufo sulle gronde del tempio. Le Sentinelle più anziane li chiamano gli altri occhi della dea, e io mi ritrovo ancora a raddrizzare la schiena quando uno mi guarda.",
		"Alcune Sentinelle anziane dicono che Elune tiene i gufi come un capitano tiene le vedette. Non ho mai chiesto se lo intendano davvero. Ai gufi faccio un cenno lo stesso.",
	},
	["dar.muse.w23.owl.011"] = {
		"si ferma a guardare tre uccellini che fanno il bagno in una vasca di pietra scolpita, sollevando tra tutti più acqua di quanta sembri possibile.",
		"indugia accanto a una vasca di pietra dove alcuni uccellini bruni si danno il turno per il bagno, e ognuno si scrolla con un'importanza smisurata.",
		"vede un uccellino posarsi sull'orlo di una vasca, studiare il proprio riflesso e decidere che il bagno, dopotutto, può aspettare.",
	},
	["dar.muse.w23.owl.012"] = {
		"Qualcuno ha modellato la curva di una gronda attorno a un nido invece di toglierlo. Il tetto lì si piega appena, quanto basta, come una mano chiusa a coppa attorno a una candela.",
		"In una piega del tetto sopra il sentiero c'è un nido, e il legno vivo gli è cresciuto attorno come una manica. Chi cura quel tetto ha deciso che gli uccelli erano arrivati prima.",
		"Un nido sotto la gronda, e la gronda stessa incurvata per reggerlo. In quasi ogni altra città qualcuno sarebbe già andato a prendere scala e scopa.",
	},
	["dar.muse.w23.owl.013"] = {
		"Ogni tanto un ippogrifo passa basso sopra la chioma e le foglie tremano tutte insieme. Sotto, tutti continuano a fare quel che facevano, tranne me, che resto lì a bocca aperta.",
		"Gli ippogrifi sorvolano la chioma così bassi che i colpi d'ala li senti nei denti. I kaldorei non alzano la testa. Io la alzo sempre.",
	},
	["dar.muse.w23.owl.014"] = {
		"I gufi di questa città stanno più dritti di me. E sono pure più educati.",
		"Guarda quel gufo. Neanche una penna fuori posto. Io una compostezza così non l'ho mai avuta.",
	},
	["dar.muse.w23.owl.015"] = {
		"Un gufo dorme su una ringhiera sotto gli occhi di tutti, con un occhio socchiuso appena appena. È la guardia più rilassata di Darnassus, e forse la più attenta.",
		"Quel gufo sulla ringhiera sembra addormentato, ma la fessura di un occhio mi ha tenuto d'occhio per tutta la lunghezza del ponte.",
	},
	["dar.muse.w23.owl.016"] = {
		"guarda un gufo staccarsi dal buio dei rami e sfiorare il lago così basso che le punte delle ali quasi toccano l'acqua, poi risalire con qualcosa di piccolo che scalcia nella stretta.",
		"non sente proprio nulla, poi vede un gufo levarsi dal prato con la sua preda, una sagoma pallida che si richiude nel buio tra i rami.",
	},
	["dar.muse.w23.owl.017"] = {
		"Un uccello lassù tra i rami ha imparato il tintinnio dell'armatura di una Sentinella e lo rifà alla perfezione. Già due volte ho salutato il vuoto.",
		"Sopra il sentiero c'è un uccello che imita piuttosto bene le fibbie di una Sentinella. Le Sentinelle non ci fanno caso. Io gli ho già ceduto il passo due volte.",
	},
	["dar.muse.w23.owl.018"] = {
		"Qui nei Temple Gardens gli uccellini hanno smesso del tutto di temere chiunque. Uno mi è appena passato sopra lo stivale per arrivare a un seme, senza chiedere scusa.",
		"Gli uccellini di questi giardini saltellano fin sul sentiero, sfrontati come mendicanti a un banchetto. Qui nessuno ha mai dato loro un motivo per avere paura.",
		"In questi giardini un passero si è posato sull'orlo della mia tazza come se fosse invitato, e ha bevuto per primo.",
	},
	["dar.muse.w23.owl.019"] = {
		"si ferma sotto un albero dove due gufi siedono spalla a spalla sullo stesso ramo, con la netta impressione di aver interrotto una conversazione.",
		"passa sotto una coppia di gufi appollaiati fianco a fianco, che smettono entrambi di fare quel che facevano per seguirne il passaggio, perfettamente all'unisono.",
	},
	["dar.muse.w23.owl.020"] = {
		"Chi ha insegnato ai gufi di questa città a guardare con quell'aria delusa? Vorrei scambiarci due parole.",
		"Ogni gufo qui mi guarda come un maestro davanti a un compito fatto male.",
	},
	["dar.muse.w23.owl.021"] = {
		"Se un altro ippogrifo mi scrolla le foglie in testa, mando il conto a Rut'theran.",
		"Foglie che mi cadono in testa? Solo un ippogrifo di passaggio. Quassù conta come una notizia.",
	},
	["dar.muse.w23.pool.001"] = {
		"osserva una sacerdotessa chinarsi su una vasca immobile e sfilarne una foglia caduta con due dita, come si toglie un capello dalla manica di qualcuno.",
		"resta a guardare mentre un'elfa ripesca da una vasca una foglia alla deriva, la scuote una volta e la posa sull'erba accanto all'acqua.",
		"sosta accanto a una vasca mentre un kaldorei anziano raccoglie nel palmo a coppa qualche petalo a galla e lo restituisce, con garbo, alle aiuole.",
	},
	["dar.muse.w23.pool.002"] = {
		"Quella vasca sembra alta una spanna. Scommetterei dell'argento buono che non lo è.",
		"L'acqua limpida mente sulla propria profondità. Meglio sondarla con un bastone che con uno stivale.",
		"Regola di Darnassus: se vedi il fondo, il fondo è più giù di quanto pensi.",
	},
	["dar.muse.w23.pool.003"] = {
		"Le sacerdotesse dicono che il pozzo lunare conserva ciò che vede. Sul suo bordo mi raddrizzo un poco, non si sa mai.",
		"Qui nel tempio l'acqua del pozzo non pare muoversi mai. Una sacerdotessa mi ha detto che nessuno ne beve senza chiedere prima; non ha detto a chi.",
		"Le sacerdotesse girano intorno al pozzo lunare, mai a cavallo del bordo, mai a lungo di spalle. Le imito senza sapere perché.",
	},
	["dar.muse.w23.pool.004"] = {
		"s'inginocchia sul bordo di una vasca e trova la pietra chiara ancora netta agli spigoli, non ancora consumata dalle mani che vi si appoggeranno per secoli.",
		"passa il pollice lungo l'orlo di una vasca e sente quanto sia ancora vivo l'intaglio: pietra di una città nuova, che nessuno ha avuto il tempo di levigare.",
		"posa il palmo sull'orlo di una vasca, dove la pietra è ancora fresca e nuova, e pare immaginare la conca che vi scaveranno mille anni di mani.",
	},
	["dar.muse.w23.pool.005"] = {
		"Nessuna patina verde sulle vasche, nemmeno una piuma a galla, nessun odore d'acqua ferma. Qualcuno le cura. Non l'ho mai colto sul fatto.",
		"L'acqua ferma dovrebbe guastarsi. A Darnassus semplicemente non succede, e nessuno a cui chiedo lo trova degno di spiegazione.",
		"Ogni vasca della città è così pulita che ci si potrebbe bere, e non ho mai visto nessuno strofinarne una. O l'acqua si pulisce da sé, o qualcuno si alza molto presto.",
	},
	["dar.muse.w23.pool.006"] = {
		"Neanche una moneta sul fondo delle vasche, in tutta la città. O qui nessuno desidera niente, o sanno che i desideri non si pagano.",
		"Vasche pulite, fondi vuoti. Altrove la gente butta rame nelle fontane. Qui te lo ripescherebbero e te lo restituirebbero.",
		"Nemmeno una moneta in queste fontane. Quasi quasi l'usanza la inauguro io. Probabilmente mi arresterebbero.",
	},
	["dar.muse.w23.pool.007"] = {
		"Metti un polso in una vasca per rinfrescarlo e il freddo sale dritto fino al gomito. Quello che alimenta queste vasche viene da molto in profondità.",
		"L'acqua delle vasche è più fredda di quanto l'aria giustifichi. Ci infili una mano e fa male prima di abituarsi.",
		"Gelide da intorpidire le dita, queste vasche. Belle da guardare; non ci entrerei nemmeno per una borsa d'oro.",
	},
	["dar.muse.w23.pool.008"] = {
		"guarda una Sentinella chinarsi su una vasca quieta per sistemarsi i capelli e una cinghia, usando l'acqua come specchio, e poi riprendere il cammino come nulla fosse.",
		"nota un'artigiana kaldorei controllare il cerchietto nella superficie immobile di una vasca, girando appena la testa a sinistra, poi a destra.",
		"osserva una Sentinella chinarsi su una vasca immobile per controllare una macchia sulla guancia, toglierla col pollice e rialzarsi come se non si fosse mai fermata.",
	},
	["dar.muse.w23.pool.009"] = {
		"Chinati su una vasca ferma e il volto che ti guarda è nitidissimo e piuttosto stanco. L'acqua non adula, ma nemmeno mente.",
		"Il mio riflesso in una vasca, preciso come un ritratto. Ho l'aria di chi ha fatto molta strada, ed è giusto così.",
		"Specchi onesti, queste vasche. Mi ero scordato quella piega precisa tra gli occhi.",
	},
	["dar.muse.w23.pool.010"] = {
		"Le sacerdotesse portano l'acqua delle vasche in ciotole basse, a due mani, gli occhi sulla superficie, senza versarne una goccia. Ho visto soldati andare in battaglia con meno cura.",
		"Passa una sacerdotessa con una ciotola d'acqua tenuta in piano tra i palmi, lenta come una processione di una persona sola. Dall'orlo non sfugge niente.",
		"L'acqua per il tempio non si porta mai di corsa. Ho visto una sacerdotessa fare il giro lungo del lago pur di non rischiare di versarla su quello corto.",
	},
	["dar.muse.w23.pool.011"] = {
		"Alcuni dei più anziani tra noi non si siedono mai in riva al lago. Ricordano un'altra acqua, profondissima e abbagliante, e ciò che ne venne fuori.",
		"Acqua limpida fino al fondo, ovunque in questa città. Credo che a qualcuno di noi serva vedere tutto ciò che l'acqua contiene. Il Pozzo ce l'ha insegnato, tanto tempo fa, e a caro prezzo.",
	},
	["dar.muse.w23.pool.012"] = {
		"Una Sentinella mi ha detto che le vasche sono da guardare e l'acqua corrente da bere. L'ha detto come una cosa che sa anche un bambino.",
		"Si beve dai ruscelli, non dalle vasche: così mi ha detto una Sentinella vedendomi inginocchiare. Non ha spiegato perché, e non ho chiesto una seconda volta.",
		"Bevi da ciò che scorre, guarda in ciò che è fermo. Così mi ha consigliato una Sentinella, di passaggio, come se lo ripetesse ogni giorno.",
	},
	["dar.muse.w23.pool.013"] = {
		"lascia cadere una foglia in una vasca per vedere da che parte va l'acqua, e la guarda compiere un giro lento e restare esattamente dov'è caduta.",
		"posa una foglia su una vasca quieta e aspetta che vada alla deriva da qualche parte; dopo un po' è chiaro che la foglia non ha programmi.",
		"fa cadere con un colpetto un petalo in una vasca ferma e aspetta che vada da qualche parte. Resta sulla superficie, contentissimo, senza muoversi.",
	},
	["dar.muse.w23.pool.014"] = {
		"Qui nei Temple Gardens l'acqua fa parte delle aiuole. I ruscelli passano tra le piante apposta, e ogni fiore sembra sporgersi verso il più vicino.",
		"Qui nessun giardiniere annaffia a mano. Ci pensano i canali, che s'insinuano tra le aiuole a un passo su cui i fiori sembrano essersi messi d'accordo.",
		"Ogni piccola vasca dei Temple Gardens sembra messa lì per un fiore in particolare.",
	},
	["dar.muse.w23.pool.015"] = {
		"Ogni vasca ferma della città ha la sua luna. Ne ho contate sette in una breve passeggiata, e quella in cielo era la più pallida.",
		"La luna è lassù, oltre le foglie, ma il lago l'ha presa intera e la tiene così ferma che pare incastonata nell'argento.",
	},
	["dar.muse.w23.pool.016"] = {
		"Ogni vasca di questa città è uno specchio. Difficile tenere un volto preso in prestito quando l'acqua continua a mostrarti quello vero.",
		"Troppa acqua ferma a Darnassus. Continuo a sorprendere il mio riflesso e a trasalire, come se potesse tradirmi con la prossima Sentinella.",
	},
	["dar.muse.w23.pool.017"] = {
		"I kaldorei costruiscono vasche come altri costruiscono muri: una a ogni angolo, per sicurezza.",
		"Una città di vasche. Dove c'era posto per una panca hanno messo una vasca d'acqua, e poi accanto anche la panca, per non sbagliare.",
		"Ho smesso di contare le vasche di Darnassus. O così, o cominciavo a dar loro un nome.",
	},
	["dar.muse.w23.pool.018"] = {
		"Mi hanno detto di non lavare i calzini nelle vasche. Non avevo nemmeno chiesto.",
		"Una Sentinella mi ha {g:visto|vista} guardare quella vasca con gli stivali in mano. Non ha detto una parola. Gli stivali sono tornati ai piedi.",
	},
	["dar.muse.w23.pool.019"] = {
		"Se ci casco dentro, dite che stavo ammirando il riflesso.",
		"Bella vasca. Se sentite un tonfo, ne stavo studiando la profondità. Scientificamente.",
	},
	["dar.muse.w23.pool.020"] = {
		"Molte soglie di questa città hanno una vasca accanto. I kaldorei ci gettano un'occhiata passando, come altri guardano il cielo prima di mettersi in viaggio.",
		"Una piccola vasca accanto a una soglia, e chiunque entri prima ci guarda dentro. Non so cosa controllino. Ho cominciato a farlo anch'io.",
	},
	["dar.muse.w23.priestess.001"] = {
		"passa accanto a una sacerdotessa di Elune che spazza petali caduti da una scala con colpi lunghi e senza fretta, come se la preghiera fosse lo spazzare e la scala pulita solo una conseguenza.",
		"vede una sacerdotessa togliere le foglie da un gradino con una scopa leggera, senza mai finire davvero, ricominciando dall'alto ogni volta che ne cade qualcuna.",
		"si ferma per una sacerdotessa che rastrella un vialetto di ghiaia in curve lente, e poi la guarda ripassare il rastrello proprio dove sono appena passati i suoi stivali.",
	},
	["dar.muse.w23.priestess.002"] = {
		"Le sacerdotesse portano piccoli argenti ai polsi e alla gola, e camminando non fanno alcun rumore. Sospetto che ci voglia esercizio.",
		"Non ho mai sentito tintinnare i gioielli di una sacerdotessa. Argento a ogni polso, e nemmeno un rintocco. O si muovono alla perfezione, o l'argento è loro complice.",
	},
	["dar.muse.w23.priestess.003"] = {
		"Ho sentito una sacerdotessa ridere sul sentiero, anche forte, per qualcosa detto dalla compagna. La città non è crollata. Anzi, mi è parsa contenta.",
		"Due sacerdotesse sono passate ridacchiando come apprendiste per uno scherzo tutto loro. La devozione, a quanto pare, lascia spazio anche a questo.",
		"Avevo in testa, chissà perché, che le sacerdotesse di Elune non ridessero mai. Una risata sonora sul sentiero me l'ha appena tolto, per quella che sembrava una storia su una capra.",
	},
	["dar.muse.w23.priestess.004"] = {
		"Una sacerdotessa mi ha detto che pregano a mani aperte, mai giunte: ciò che Elune dona, ha detto, non lo si prende col pugno.",
		"Mani aperte, palmi in su, quando le sacerdotesse pregano. Una di loro mi ha spiegato che una mano chiusa può tenere solo quello che ha già.",
	},
	["dar.muse.w23.priestess.005"] = {
		"segue con lo sguardo una sacerdotessa anziana che corregge la postura di una più giovane con due dita sulla scapola, poi sul mento, e poi si fa semplicemente indietro.",
		"si ferma a guardare una sacerdotessa che sistema la postura di una novizia con tocchi leggerissimi, spalla, mento, polso, e poi si scosta per lasciarle trovare il resto da sola.",
		"indugia a vedere una novizia ripetere più e più volte un solo piccolo gesto, mentre la maestra scuote la testa, paziente, ogni volta.",
	},
	["dar.muse.w23.priestess.006"] = {
		"Le sacerdotesse portano archi oltre alle benedizioni. La dea che servono, mi dicono, non ha mai chiesto loro di scegliere.",
		"Sotto quelle vesti ci sono arciere. Chiedi a una sacerdotessa delle antiche guerre e ti parlerà di preghiera, e poi, sottovoce, di mira.",
		"Una sacerdotessa con l'arco a tracolla mi è passata accanto, diretta al tempio. Pensavo che l'arco fosse cerimoniale, finché non ho visto l'impugnatura consumata.",
	},
	["dar.muse.w23.priestess.007"] = {
		"Se sto in un posto sacro, sacerdotessa, basta un cenno. Mi sposto.",
		"Qui si può parlare? Nessuno me l'ha detto, e nessuno me l'ha impedito.",
		"Perdonami, sacerdotessa. Mi hanno detto di abbassare la voce vicino al tempio, ma nessuno mi ha detto quanto.",
	},
	["dar.muse.w23.priestess.008"] = {
		"Il calendario delle sacerdotesse segue il volto mutevole di Elune, mi ha detto una di loro. Chiedi quando accadrà qualcosa e potrebbero risponderti in fasi, non in giorni.",
		"Chiedi una data a una sacerdotessa e forse la conterà a volti della dea anziché a settimane. È un altro modo di tenere il tempo, e più lento.",
	},
	["dar.muse.w23.priestess.009"] = {
		"nota una sacerdotessa di Elune in fila alla banca, vesti immacolate, mani intrecciate davanti a sé, in attesa del suo turno come chiunque altro.",
		"trova un certo conforto nel vedere una sacerdotessa contare monete nel palmo davanti a una bancarella, aggrottando appena la fronte per il totale come una cliente qualunque.",
		"guarda una sacerdotessa contrattare, con molta dolcezza e molta fermezza, sul prezzo del filo, e spuntarla.",
	},
	["dar.muse.w23.priestess.010"] = {
		"Qui nel tempio le sacerdotesse parlano ai visitatori in Comune e tra loro in qualcosa di più antico, e tutt'e due le lingue suonano come preghiere.",
		"Dentro il tempio le sacerdotesse si muovono senza fretta e senza un ordine preciso, eppure nessuna urta l'altra. Una danza imparata così tanto tempo fa che hanno dimenticato che lo sia.",
		"Con un catino colmo fra le mani, una sacerdotessa si ferma per lasciarmi il passo. L'ospite sono io; il catino pieno ce l'ha lei. In questo tempio l'ordine è questo.",
	},
	["dar.muse.w23.priestess.011"] = {
		"Le sacerdotesse curano i malati più di un tempo, ho sentito dire. Da Hyjal in poi il loro popolo può ammalarsi, e stanno ancora imparando cosa farne.",
		"Dopo Hyjal i kaldorei possono prendersi una febbre come chiunque. Una sacerdotessa mi ha raccontato che curare raffreddori, un tempo, non faceva parte del suo addestramento. Adesso sì.",
	},
	["dar.muse.w23.priestess.012"] = {
		"Ho provato a camminare come una sacerdotessa. Ho inciampato nell'orlo di una veste che non porto nemmeno.",
		"Come fanno a scivolare così? Ho controllato: hanno i piedi.",
		"Ho visto sacerdotesse portare catini pieni su per una scala senza versarne una goccia. Io rovescio la zuppa anche stando a tavola.",
	},
	["dar.muse.w23.priestess.013"] = {
		"guarda due sacerdotesse fermarsi dove la luna si mostra fra le foglie, posarsi un palmo sulla fronte e riprendere il cammino.",
		"vede una sacerdotessa fermarsi a metà passo sotto la luna scoperta, alzare il mento verso di lei per il tempo di una parola, e proseguire come se nulla fosse.",
	},
	["dar.muse.w23.priestess.014"] = {
		"Qui nei giardini una sacerdotessa lega a un tutore uno stelo piegato con un filo, poi gli parla brevemente, come si dice a un bambino di stare dritto.",
		"In questi giardini una sacerdotessa passa da un'aiuola all'altra con un coltellino, senza tagliare niente, solo guardando, e alla fine lo rimette via.",
	},
	["dar.muse.w23.priestess.015"] = {
		"passa accanto a una sacerdotessa che legge ad alta voce da un libretto a tre Sentinelle sedute sull'erba, i glaive posati accanto, tutte in ascolto come allieve.",
		"si ferma ai margini di un piccolo gruppo dove un anziano parla lentamente a un cerchio di ascoltatori, e nota che nessuno si volta, anche se tutti, senza dubbio, si sono accorti di {g:lui|lei}.",
	},
	["dar.muse.w23.quip.001"] = {
		"Questa città è perfetta per camminare. Il problema è tutto lì.",
		"Darnassus: fatta per passeggiare, da gente che non è mai arrivata in ritardo in vita sua.",
	},
	["dar.muse.w23.quip.002"] = {
		"«Non lontano», detto da un elfo, è un'unità di misura che sto ancora imparando a convertire.",
		"Quando un kaldorei dice che non è lontano, aggiungi un'ora e un ponte.",
	},
	["dar.muse.w23.quip.003"] = {
		"Qui è tutto incantevole. Scambierei un po' di incanto con un cartello.",
		"Un cartello. Chiedo solo questo. Possono anche intagliarci le foglie, se ci tengono.",
	},
	["dar.muse.w23.quip.004"] = {
		"Se mai arrivo in ritardo, date la colpa ai ponti. Ce ne sono più dei posti dove andare.",
		"In questa città ho attraversato un gran numero di ponti, e a quanto vedo erano quasi tutti lo stesso.",
	},
	["dar.muse.w23.quip.005"] = {
		"Ho provato a essere paziente come la gente del posto. Ho resistito quanto un mozzicone di candela.",
		"Mi sto esercitando nella pazienza dei kaldorei. Per ora arrivo quasi a un minuto.",
	},
	["dar.muse.w23.quip.006"] = {
		"Volevo una commissione veloce. A Darnassus non ne vendono.",
		"Veloce e Darnassus non stanno nella stessa frase. Ci ho provato.",
		"Entro ed esco, ho detto. Darnassus ha sentito solo la prima parte.",
	},
	["dar.muse.w23.quip.007"] = {
		"Dovrei lasciare una mancia a una Sentinella per le indicazioni? Ha l'aria di chi troverebbe l'idea affascinante e vagamente offensiva.",
		"Ringrazierei la Sentinella come si deve, ma credo sia già passata a sorvegliare qualcuno più sospetto di me.",
	},
	["dar.muse.w23.quip.008"] = {
		"Tengo un elenco delle cose vicine, a Darnassus. È un elenco corto: c'è solo questo punto.",
		"In questa città la cosa più vicina a qualunque cosa è il punto in cui ti trovi. Il resto è una camminata.",
	},
	["dar.muse.w23.quip.009"] = {
		"Ho deciso di smettere di chiedere dove sono le cose e di stare semplicemente dove capito. Funziona più o meno come immagini.",
		"Nuovo piano: dovunque finisca, era lì che volevo andare.",
	},
	["dar.muse.w23.quip.010"] = {
		"Mi dicono di prendermela con calma. Volentieri. Dove la tengono, la calma?",
		"Tutti continuano a dirmi che non c'è fretta. La mia borsa e i miei bagagli non sono d'accordo.",
	},
	["dar.muse.w23.quip.011"] = {
		"Qui ogni scala è un dolce pendio, e ogni dolce pendio non finisce mai.",
		"Niente salite ripide a Darnassus. Solo lunghe, gentili, interminabili.",
	},
	["dar.muse.w23.quip.012"] = {
		"La casa d'aste è da questa parte? Non rispondere. Lo scoprirò facendo il giro lungo, come sempre.",
		"Prima o poi la trovo, la casa d'aste. È su un albero. Quanto lontano potrà mai essere?",
	},
	["dar.muse.w23.quip.013"] = {
		"Da qualche parte in questa città c'è l'addestratore che cerco, immobile, in attesa di essere trovato. È come giocare a nascondino con un esperto.",
		"Trovare un addestratore qui è una partita a nascondino, e loro hanno avuto secoli per allenarsi.",
	},
	["dar.muse.w23.quip.014"] = {
		"Dove stavo andando? Era importante. Aveva un tetto.",
		"Dovevo essere da qualche parte. Probabilmente è ancora lì. Sono io che mi sono {g:spostato|spostata}.",
	},
	["dar.muse.w23.quip.015"] = {
		"Quella fontana l'ho superata quattro volte. Se potesse parlare, mi darebbe indicazioni per pietà.",
		"Ciao, fontana. Sì, sono io. No, non lo so neanch'io.",
		"Fontana, vecchia amica mia. Da che parte, stavolta?",
	},
	["dar.muse.w23.quip.016"] = {
		"Non mi sono {g:perso|persa}. Sto visitando la città con grande determinazione.",
		"Io, smarrirmi? No. Prendo la strada lunga apposta. Tutte, le strade lunghe.",
		"So perfettamente dove sono. Più o meno. Con un margine di una terrazza o due.",
	},
	["dar.muse.w23.quip.017"] = {
		"Darnassus ha tutto quello che serve a un viaggiatore. Distribuito con grande generosità.",
		"Banca, locanda, addestratori, bancarelle: c'è tutto, tutto incantevole, e ognuno a una lunga, piacevole passeggiata dagli altri.",
	},
	["dar.muse.w23.quip.018"] = {
		"Potrei vivere quassù, se qualcuno mi portasse in braccio.",
		"Città bellissima. Ne vedrei di più se non fossi sempre per strada verso la banca.",
	},
	["dar.muse.w23.quip.019"] = {
		"Su questo sentiero ho superato tre elfi, e in qualche modo sono arrivati tutti prima di me.",
		"Qui tutti camminano piano e arrivano per primi. Mi piacerebbe sapere come fanno.",
	},
	["dar.muse.w23.quip.020"] = {
		"Un nano attraversa Ironforge da un capo all'altro nel tempo che qui ci vuole a trovare la banca. E per strada c'è pure la birra.",
		"Datemi una città con una bella forgia nel mezzo e tutto il resto in cerchio intorno. Alberi, ma vi pare.",
	},
	["dar.muse.w23.reed.001"] = {
		"passa rasente all'acqua e una rana si lascia cadere dalla riva con un solo plop, lasciando un cerchio e una netta impressione di disapprovazione.",
		"spaventa una rana sul bordo di una vasca; finisce in acqua con un plop indignato e non torna più a galla.",
	},
	["dar.muse.w23.reed.002"] = {
		"Qui le rane gracidano a turno, una dopo l'altra, senza mai parlarsi sopra. Qualcuno deve aver spiegato loro le regole.",
		"Le rane di questa città rispettano i turni. Una parla, le altre aspettano, poi tocca alla successiva. Ho assistito a consigli più chiassosi.",
		"Persino le rane abbassano la voce. Un gracidio, una lunga pausa, una risposta dall'altra riva. Praticamente una conversazione.",
	},
	["dar.muse.w23.reed.003"] = {
		"Le canne lungo la riva si accostano e poi si separano con un fruscio secco, l'unico suono della città che non sia acqua o voci sommesse.",
		"I giunchi sul bordo del lago battono piano l'uno contro l'altro, un rumorino asciutto in mezzo a tanto bagnato.",
		"Quando qualcosa smuove le canne, tutta la riva sibila piano, poi si quieta, come imbarazzata.",
	},
	["dar.muse.w23.reed.004"] = {
		"guarda piccoli cerchi sbocciare sul lago dove i pesci salgono a prendere qualcosa dalla superficie, mai due volte nello stesso punto.",
		"vede un pesce affiorare sotto un ponte, afferrare un puntino a galla e lasciare un cerchio che s'allarga fino ai piloni di pietra.",
	},
	["dar.muse.w23.reed.005"] = {
		"In questo lago ci sono pesci lunghi quanto il mio braccio, e non un kaldorei con una rete. Uno scandalo.",
		"Guarda quanto è grosso quello. In qualsiasi altra città sarebbe già cena.",
		"Si può pescare in questo lago? Chiedo per conto del mio stomaco.",
	},
	["dar.muse.w23.reed.006"] = {
		"I pesci sotto il ponte si avvicinano alla mia ombra sull'acqua, pieni di speranza. Qualcuno li nutre. Qualcuno con molta pazienza e molte briciole.",
		"Sporgiti dal parapetto e i pesci si radunano, muso in su, ad aspettare. Sanno benissimo a cosa serve una persona su un ponte.",
	},
	["dar.muse.w23.reed.007"] = {
		"si accovaccia a guardare alcuni insetti dalle zampe lunghe pattinare su una vasca immobile, ogni passo una minuscola fossetta, l'acqua che cede senza mai rompersi.",
		"si china su una vasca tranquilla dove gli insetti pattinatori stanno sulla superficie come su un pavimento, e schizzano via quando la sua ombra li copre.",
	},
	["dar.muse.w23.reed.008"] = {
		"Nei punti tranquilli del lago galleggiano foglie verdi tonde, ognuna inclinata appena, una libellula su una su tre. Sembra disposto ad arte. Probabilmente lo è.",
		"Qui le ninfee sono distanziate come posti a tavola. Non mi stupirebbe che i kaldorei le avessero contate.",
	},
	["dar.muse.w23.reed.009"] = {
		"resta immobile mentre una libellula del colore delle lampade si ferma a mezz'aria davanti al suo viso, valuta, e schizza di nuovo sull'acqua.",
		"segue per qualche passo una libellula blu lungo la riva, finché non si posa in cima a una canna e rifiuta di farsi seguire oltre.",
	},
	["dar.muse.w23.reed.010"] = {
		"Una lumaca è arrivata a metà dell'orlo di pietra di una vasca, lasciandosi dietro una scia d'argento. Scommetto che è partita prima che io arrivassi in città. Forse sarà ancora in cammino quando ripartirò.",
		"Lumache su ogni pietra bagnata vicino all'acqua, ognuna diretta da qualche parte al passo locale. Si integrano meglio di me.",
	},
	["dar.muse.w23.reed.011"] = {
		"Una sarta della Craftsmen's Terrace mi ha detto che il filo più morbido che conosca si fila da una canna del lago. Da allora guardo le canne in un altro modo.",
		"Qualcuno tra gli artigiani diceva che le canne della riva danno la fibra migliore per tessere, se hai la pazienza di macerarle per una stagione. Alla parte sulla pazienza ci credo.",
	},
	["dar.muse.w23.reed.012"] = {
		"guarda una rana saltare sullo stivale di una Sentinella immobile vicino all'acqua e restare lì seduta; la Sentinella abbassa gli occhi, e la lascia stare.",
		"vede una rana arrampicarsi sulla punta dello stivale di una Sentinella di guardia accanto a una vasca. Lei la guarda una volta, seria, e torna al suo turno.",
	},
	["dar.muse.w23.reed.013"] = {
		"Immagino che qualcuno abbia dovuto portare quassù i pesci. Ogni rana e ogni pesciolino di questo lago verrà da una foresta bruciata o da una costa che non c'è più. Profughi, tutti quanti.",
		"Niente in questo lago è nato per vivere su un albero. Pesci, rane, canne: qualcuno li avrà portati quassù da posti dove la guerra è arrivata. Per questo li guardo con più tenerezza.",
	},
	["dar.muse.w23.reed.014"] = {
		"segue le mani di un druido, qui nell'Enclave, mentre versano un po' d'acqua sulle radici di un germoglio e poi restano a coppa, come in attesa di risposta.",
		"si volta e vede una druida dell'Enclave accucciarsi accanto all'acqua corrente, tirar fuori da un canale uno scarabeo in difficoltà e posarlo sull'erba, con una parola troppo bassa per sentirla.",
	},
	["dar.muse.w23.reed.015"] = {
		"sente le rane lungo la riva attaccare tutte insieme mentre la pioggia s'infittisce, come se non avessero aspettato altro.",
		"nota le rane uscire sotto la pioggia sulle pietre bagnate del lago, contentissime del tempo, le uniche in città.",
	},
	["dar.muse.w23.reed.016"] = {
		"Quella cascata farebbe girare una ruota idraulica magnifica. Macinare grano, azionare un mantice, illuminare mezza terrazza. Non lo proporrò. Ho visto come guardano gli ingranaggi da queste parti.",
		"Tanta acqua che cade e nemmeno una ruota a sfruttarla. A Gnomeregan sarebbe stato uno scandalo. Qui è una filosofia.",
	},
	["dar.muse.w23.reed.017"] = {
		"Vicino al lago l'aria sa di pietra bagnata e di canne, fresca e verde. Più all'interno sa di muschio e fiori. Capirei dove sono anche solo dal naso.",
		"La riva ha un odore tutto suo: pietra fredda, canne schiacciate, un sentore di pesce. È l'odore meno elegante di Darnassus, ed è quello che preferisco.",
	},
	["dar.muse.w23.reed.018"] = {
		"s'accovaccia sul bordo di una pozza bassa piena di girini, che si dimenano tutti nella stessa direzione e poi nell'altra, come una folla che non riesce a mettersi d'accordo.",
		"scorge una nuvola di girini nell'acqua bassa, virgole scure che si disperdono alla sua ombra e si radunano di nuovo un attimo dopo.",
	},
	["dar.muse.w23.reed.019"] = {
		"Quella libellula mi gira intorno alla testa da un pezzo. Credo che mi abbia adottato.",
		"Una libellula mi si è posata sulla manica e non se ne va. Fermi tutti: mi ha scelto lei.",
	},
	["dar.muse.w23.rill.001"] = {
		"scavalca un canaletto scavato nel sentiero, dove un filo d'acqua corre accanto ai passanti come se anche lui avesse commissioni su un'altra terrazza.",
		"segue per una dozzina di passi un rigagnolo incassato nella pietra del camminamento, finché non s'infila sotto una lastra e sparisce.",
		"supera con cura un rivolo d'argento che taglia il sentiero, una di quelle acque piccole che sembrano essersi allontanate da una più grande.",
	},
	["dar.muse.w23.rill.002"] = {
		"Ogni ruscello qui ha la sua nota. Uno è acuto e svelto, un altro basso, quasi un ronzio. Potrei orientarmi a orecchio, se mi fidassi delle orecchie.",
		"Ho cominciato a distinguere i ruscelli dal suono. Un chiacchiericcio vuol dire canali stretti; un brontolio profondo, una cascata vicina.",
		"L'acqua parla in modo diverso su ogni terrazza. Se chiudessi gli occhi, credo che ne riconoscerei metà così.",
	},
	["dar.muse.w23.rill.003"] = {
		"Tra una terrazza e l'altra c'è un punto in cui il rumore dell'acqua cessa di colpo, e il silenzio è tanto improvviso che mi giro a vedere cosa sia andato storto.",
		"C'è un tratto di sentiero dove non si sente scorrere niente. In questa città, quel silenzio sembra una porta lasciata socchiusa.",
	},
	["dar.muse.w23.rill.004"] = {
		"Dove va l'acqua quando trabocca dal bordo della città? Giù per il tronco, mi ha detto un druido, fino al mare, e l'albero se ne beve due sorsi per strada.",
		"Una druida mi ha detto che le cascate qui non finiscono davvero. L'acqua scende lungo la corteccia di Teldrassil fino al mare, e l'albero, diceva, si prende la sua parte al passaggio.",
	},
	["dar.muse.w23.rill.005"] = {
		"si accuccia accanto a un canale e lascia scorrere l'acqua tra le dita finché il freddo non le fa dolere, poi le scuote e riprende a camminare.",
		"immerge entrambe le mani in un ruscelletto svelto e le tiene lì, guardando la corrente dividersi attorno a ogni nocca.",
	},
	["dar.muse.w23.rill.006"] = {
		"Vicino alle cascate potresti gridare quanto vuoi. È l'unico posto della città dove la passeresti liscia.",
		"Se mai dovrò imprecare ad alta voce a Darnassus, lo farò accanto a una cascata.",
		"Le cascate sono le sole qui a cui è permesso far rumore. Le invidio.",
	},
	["dar.muse.w23.rill.007"] = {
		"sosta vicino a una cascata e sente gli spruzzi posarsi sulle maniche in minuscole perle d'argento, troppo piccole per bagnare, troppe per scrollarle via.",
		"si avvicina tanto a una cascata che un velo fresco di spruzzi arriva fin lì, e le goccioline accendono il viola delle lampade in ogni piega della stoffa.",
		"passa rasente a una cascata e ne esce con una rugiada di spruzzi sulle spalle, che luccica finché non si asciuga.",
	},
	["dar.muse.w23.rill.008"] = {
		"C'è una scalinata dove un rigagnolo scende accanto ai gradini, con una cascatella a ogni scalino. Fa le scale più in fretta di me e con molto più chiasso.",
		"L'acqua scende le scale insieme a me, un piccolo salto per gradino. Arriva in fondo prima, ogni volta, e giurerei che se ne vanta.",
	},
	["dar.muse.w23.rill.009"] = {
		"L'acqua che scorre è buona compagnia per pensare. Ripete la stessa cosa all'infinito e non pretende mai risposta.",
		"Accanto a questi ruscelli ho pensato più onestamente che in un mese di strada. L'acqua continua a parlare, così non devo farlo io.",
		"Siediti accanto a un ruscello con un problema aggrovigliato e l'acqua comincia a lavorarci, come un pollice su una cinghia rigida.",
	},
	["dar.muse.w23.rill.010"] = {
		"si fa immobile mentre un kaldorei si ferma a un ruscello sulla via del tempio, si bagna le mani, si sfiora la fronte e prosegue senza una parola.",
		"vede una Sentinella fermarsi all'acqua corrente, sciacquarsi le dita e premerle un istante sulle palpebre prima di proseguire verso il Temple of the Moon.",
	},
	["dar.muse.w23.rill.011"] = {
		"Qui nell'Enclave l'acqua non sta nei canali. Si trova la strada da sé tra le radici, e i druidi la scavalcano invece di dirle dove andare.",
		"Nell'Enclave i ruscelli corrono dove gli pare: sotto le radici, di traverso ai sentieri, in mezzo all'aiuola di qualcuno. Qui nessuno pensa che l'acqua debba chiedere permesso.",
	},
	["dar.muse.w23.rill.012"] = {
		"Acqua dolce, in cima a un albero, in mezzo a un mare salato. L'ho assaggiata per esserne {g:certo|certa}. Nemmeno un granello di sale.",
		"Ogni goccia quassù è fresca e morbida sul palato, e l'acqua più vicina, giù in basso, è il mare. Immagino che la cernita l'abbia fatta l'albero.",
	},
	["dar.muse.w23.rill.013"] = {
		"Fredda, limpida, e la lasciano scivolare giù dal bordo della città. In un deserto qualcuno piangerebbe.",
		"Tutta quest'acqua dolce, e metà se ne va giù dal fianco dell'albero senza servire a nessuno.",
	},
	["dar.muse.w23.rill.014"] = {
		"indugia presso una fontana dei Temple Gardens, dove l'acqua sale, resta sospesa un istante in cima al balzo e ricade nella sua vasca senza un suono.",
		"siede sul bordo di una fontana tra le siepi dei Gardens e guarda l'acqua salire e ricadere, salire e ricadere, come qualcosa che prova e riprova una parte.",
	},
	["dar.muse.w23.rill.015"] = {
		"Persino qui, dove si mettono a bagno le pelli e si sciacquano le ciotole, l'acqua che lascia la terrazza sembra pulita come quella che arriva. Vorrei sapere come fanno.",
		"Gli artigiani qui usano i ruscelli per ammollare il cuoio e sciacquare i mortai, eppure a valle il canale scorre limpido. Qualcuno ci ha pensato a lungo.",
	},
	["dar.muse.w23.rill.016"] = {
		"Con la pioggia i ruscelli cambiano voce. Ogni canale corre più pieno e più svelto, e le cascate scendono di un tono.",
		"Piove sulla chioma, e poco dopo ogni rigagnolo della città parla più in fretta. Il lago si prende tutto e non sale di un dito.",
	},
	["dar.muse.w23.rill.017"] = {
		"Senti le cascate? No, è il tuono. No, aspetta: sono tutti e due.",
		"Tuono lassù e cascate quaggiù, a litigare su chi fa più rumore. Stanno vincendo le cascate.",
	},
	["dar.muse.w23.rill.018"] = {
		"I canali di Stormwind corrono dritti tra muri di pietra, tutti affari. Questi ruscelli vagano come invitati a una festa in giardino, e arrivano lo stesso.",
		"I canali di Stormwind sono acqua che lavora: profonda, murata, diretta da qualche parte. Qui l'acqua sembra essere andata in pensione.",
	},
	["dar.muse.w23.rill.019"] = {
		"Non avrei mai pensato di dirlo, ma riempio la borraccia per pura ingordigia. È così buona.",
		"L'acqua più buona di Kalimdor, e nessuno te la fa pagare. Riempio tutti gli otri che ho.",
	},
	["dar.muse.w23.rill.020"] = {
		"attraversa un ruscello su tre pietre piatte messe esattamente a un passo l'una dall'altra, come se chi le ha posate avesse preso le misure a una gamba kaldorei.",
		"passa un ruscello sulle pietre da guado, le trova un po' troppo distanti per un passo comodo, e affronta l'ultima con un saltello poco dignitoso.",
	},
	["dar.muse.w23.rill.021"] = {
		"Ad Ashenvale, dicono le Sentinelle, i ruscelli sono pieni di segatura sotto gli accampamenti dei Warsong. Quassù l'acqua scorre pulita, e la guardano come qualcosa da difendere.",
		"Le Sentinelle dicono che i fiumi di Ashenvale scorrono torbidi a valle dei campi di taglio dei Warsong. In questi ruscelli si lavano le mani con grande delicatezza, come se l'acqua potesse farsi male.",
	},
	["dar.muse.w23.rill.022"] = {
		"Ho chiesto a un'elfa come si chiama questo ruscello. Mi ha guardato come se avessi chiesto il nome di una nuvola.",
		"Hanno un nome, i ruscelli qui? L'ho chiesto. In risposta, un sorriso e un silenzio lunghissimo.",
	},
	["dar.muse.w23.ripple.001"] = {
		"si ferma sotto la curva di un ponte e osserva l'acqua gettare una rete di luce mobile sulla pietra chiara di sopra.",
		"alza lo sguardo al ventre di un arco vicino all'acqua, dove la luce riflessa scorre sulla pietra in fili lucenti e tremanti.",
		"indugia sotto un ponte dove il riflesso dell'acqua striscia sulla pietra senza mai fermarsi, come qualcosa di vivo sotto l'arco.",
	},
	["dar.muse.w23.ripple.002"] = {
		"Ogni sassolino di un ruscello sembra un gioiello sotto un dito d'acqua. Tiralo fuori ed è di nuovo un sasso grigio che si asciuga nel palmo.",
		"I ciottoli sul fondo brillano come oggetti lucidati. Prendine uno e si spegne prima che tu chiuda le dita.",
		"Sott'acqua la ghiaia qui è tutta ambra, verde e viola. Fuori, è ghiaia. Il lavoro lo fa tutto l'acqua.",
	},
	["dar.muse.w23.ripple.003"] = {
		"Il muschio sul bordo di pietra del lago si ferma a una linea esatta, alla stessa altezza tutto intorno. Qui l'acqua non cresce e non cala. Non so cosa pensare di un lago senza umori.",
		"Sulla pietra, all'altezza dell'acqua, c'è una fascia scura dritta come un righello. Niente piene, niente secche. Il lago tiene un solo livello come una Sentinella tiene una sola postura.",
		"Il lago non pare mai più alto o più basso dell'ultima volta che l'ho guardato. L'acqua indecisa è normale; quella che non deve mai decidere mette a disagio.",
	},
	["dar.muse.w23.ripple.004"] = {
		"osserva le torri riflesse nel lago spezzarsi quando qualcosa nuota sotto, poi ricomporsi pezzo per pezzo.",
		"vede un cerchio allargarsi sul lago e i muri bianchi specchiati tremare, ripiegarsi e tornare al loro posto come se nulla li avesse sfiorati.",
	},
	["dar.muse.w23.ripple.005"] = {
		"Qui un ponte sull'acqua ferma non è mai mezzo ponte. L'arco e il suo riflesso si chiudono in un anello, e passarci sopra sembra attraversare qualcosa.",
		"Ogni ponte ricurvo incontra il proprio riflesso e chiude un cerchio. Mi viene sempre voglia di passare in mezzo.",
		"Arco sopra, arco sotto, e in mezzo un anello di pietra e acqua. Qui i ponti sono costruiti per essere visti due volte.",
	},
	["dar.muse.w23.ripple.006"] = {
		"Mi è caduto un rame da un ponte. Ci ha messo tanto ad affondare che ho fatto in tempo a pentirmene due volte.",
		"Crudele, l'acqua limpida. Vedi la tua moneta posarsi sul fondo, lì davanti, del tutto irraggiungibile.",
		"È l'acqua più limpida in cui abbia mai perso dei soldi.",
	},
	["dar.muse.w23.ripple.007"] = {
		"Vicino all'acqua la luce cambia. Sale dal basso oltre che scendere dalle foglie, e i volti sulla riva sembrano illuminati da dentro.",
		"Resta abbastanza sul lago e te ne accorgi: qui la luce arriva da due parti, dalle foglie sopra e dall'acqua sotto, e niente ha un contorno duro.",
		"In riva al lago i volti sembrano più gentili. L'acqua li rischiara dal basso e addolcisce ogni tratto severo.",
	},
	["dar.muse.w23.ripple.008"] = {
		"Una goccia da una foglia, un cerchio sulla vasca, il cerchio che tocca l'orlo di pietra e torna indietro più piccolo. Ne ho guardati quattro e ho perso il conto di tutto il resto.",
		"Basta una goccia da una foglia e tutta la vasca risponde: un cerchio verso fuori, uno più debole verso dentro. È la conversazione più lenta della città.",
		"Una goccia sola cade in una vasca immobile e i cerchi si allargano così piano che potrei contarli. Li ho contati. Sette.",
	},
	["dar.muse.w23.ripple.009"] = {
		"La pietra su cui scorre l'acqua si sta già arrotondando. La città è giovane, ma i ruscelli hanno cominciato il loro lento scavo, e hanno tutto il tempo che i kaldorei avevano un tempo.",
		"L'acqua consuma la pietra, dati abbastanza anni. Qui ha appena cominciato. Un giorno questi canali nuovi e taglienti sembreranno antichissimi, e chi resterà penserà che siano sempre stati così.",
	},
	["dar.muse.w23.ripple.010"] = {
		"Ogni superficie di questa città è uno specchio. In un'ora qui ho visto i miei capelli più che in un mese di strada.",
		"Vasche ovunque, tutte immobili. A Darnassus è difficile sfuggire alla propria faccia. La mia avrebbe bisogno di una lavata.",
	},
	["dar.muse.w23.ripple.011"] = {
		"Nel tempio persino l'acqua è attenta. La fontana ricade nella vasca senza uno schizzo, come se qualcuno le avesse insegnato le buone maniere.",
		"Nel Temple of the Moon la fontana scende così liscia da sembrare una colonna di vetro. Le sacerdotesse le passano accanto senza guardarla; io non riesco a smettere.",
	},
	["dar.muse.w23.ripple.012"] = {
		"nota un piccolo arcobaleno sbiadito sospeso negli spruzzi di una cascata, dove un raggio di sole scende tra le foglie, e fa un passo di lato per non perderlo.",
		"scorge un filo di colori negli spruzzi di una cascata, là dove il sole passa attraverso le chiome, e lo guarda svanire appena le foglie si muovono.",
	},
	["dar.muse.w23.ripple.013"] = {
		"Al crepuscolo il lago si scurisce prima dei sentieri, una pozza d'inchiostro con le lampade che ci galleggiano sopra.",
		"Quando la luce cala, l'acqua è la prima a farsi scura. Per un po' il lago è la cosa più profonda della città, più cupo del buio sotto i rami.",
	},
	["dar.muse.w23.ripple.014"] = {
		"A Ironforge l'acqua sa stare al suo posto: in un tubo, in un abbeveratoio, in un boccale. Qui la lasciano vagare all'aperto, fredda, a raccogliere foglie.",
		"Sotto la montagna avremmo già messo tutto nei tubi, con una valvola per ogni canale. I kaldorei preferiscono lasciarla andare dove vuole. Elfi.",
	},
	["dar.muse.w23.ripple.015"] = {
		"Si capisce fin dove arrivano gli spruzzi di una cascata guardando il muschio: un ventaglio verde perfetto sulla pietra, che finisce esattamente dove finiscono le gocce.",
		"Ogni cascata della città ha disegnato la propria mappa di muschio sulla pietra intorno: fitto dove cadono gli spruzzi, sempre più rado fino alla roccia nuda.",
	},
	["dar.muse.w23.ripple.016"] = {
		"Siediti abbastanza a lungo davanti all'acqua ferma e le vecchie strade risalgono a galla una per una, come foglie dopo che hai mescolato. Le lascio andare alla deriva.",
		"Una vasca tranquilla è un pessimo posto per dimenticare. Tutto ciò che avevo messo da parte risale e gira piano sulla superficie.",
		"Se li lascio fare, i volti incontrati per strada affiorano da una vasca immobile. Non li chiamo. Vengono lo stesso, e se ne vanno.",
	},
	["dar.muse.w23.ripple.017"] = {
		"Guarda com'è ferma. Non credo di essere mai {g:stato|stata} così {g:fermo|ferma} in vita mia.",
		"Neanche un'increspatura. Vorrei conoscere il trucco.",
	},
	["dar.muse.w23.ripple.018"] = {
		"Da dove sono conto quattro acque: un filo ai miei piedi, un ruscello oltre il sentiero, una cascata dietro gli alberi, e sotto tutto il lago, lento e quasi muto.",
		"Vicino, uno sgocciolio. Più in là, un ruscello. Più in là ancora, una cascata. L'acqua di questa città arriva a strati, come voci in una lunga sala.",
	},
	["dar.muse.w23.saber.001"] = {
		"nota la coda di un nightsaber a riposo che penzola da una sporgenza, la punta che si agita appena: l'unica parte del grande felino ancora sveglia.",
		"passa sotto una sporgenza dove un nightsaber è disteso fuori vista, tutto tranne la coda, che pende giù e schiocca pigra contro il nulla.",
	},
	["dar.muse.w23.saber.002"] = {
		"Le orecchie di un nightsaber si sono girate verso un gruppo d'alberi un attimo buono prima che lì frusciasse qualcosa. Qualunque cosa dica la città, i felini la sentono per primi.",
		"Guarda le orecchie di un nightsaber a riposo e sai chi scende per il sentiero prima di vederlo. Si sono girate due volte mentre ero lì: tutte e due le volte, una Sentinella.",
		"I nightsaber dormono con le orecchie sveglie. Uno ha sonnecchiato mentre passava un intero gruppo di visitatori chiacchieroni, e ha aperto gli occhi solo quando una Sentinella ha smesso di parlare.",
	},
	["dar.muse.w23.saber.003"] = {
		"È passata una Sentinella in sella a un felino bianco a strisce grigio chiaro. Un frostsaber, mi hanno detto, da Winterspring, nel lontano nord. Attraversava il verde come un ospite troppo educato per lamentarsi del caldo.",
		"Fra tutti i felini scuri della città, un unico frostsaber bianco, e ogni testa sul sentiero si è girata a seguirlo. Anche qui, una rarità resta una rarità.",
		"Il mantello del frostsaber sembrava fatto per un clima che Darnassus non conosce. Restava all'ombra dei rami, passo dopo passo, come se lo sapesse.",
	},
	["dar.muse.w23.saber.004"] = {
		"Quel felino mi ha appena sbadigliato in faccia. Ho visto porte più strette di quella bocca.",
		"Gattone. Gattone tranquillo. Cammino pianissimo, gattone, e tu mi lasci passare.",
		"Quel nightsaber mi ha appena sospirato addosso? Mi sa che mi ha giudicato noioso.",
	},
	["dar.muse.w23.saber.005"] = {
		"osserva una Sentinella controllare una per una le zampe del suo nightsaber, e il grande felino che gliele porge a turno come un cavallo paziente dal maniscalco.",
		"si ferma a guardare una Sentinella passare il pollice tra i cuscinetti della zampa anteriore del suo felino, in cerca di una spina, mentre il nightsaber guarda lontano e sopporta.",
		"guarda una Sentinella appoggiare tutto il suo peso al fianco del nightsaber per sistemarsi la cinghia di uno stivale, e il felino puntellarsi senza che nessuno glielo chieda.",
	},
	["dar.muse.w23.saber.006"] = {
		"Quando un nightsaber fa le fusa, lo senti nelle assi del ponte prima ancora che nelle orecchie. Un brontolio basso e lento, come un carro che passa in un'altra via.",
		"Ho preso posto vicino a un nightsaber assopito e ha cominciato a fare le fusa. Non per me, credo. Per il mondo in generale, che a quanto pare gli andava a genio.",
	},
	["dar.muse.w23.saber.007"] = {
		"C'era un cervo che brucava accanto al sentiero, a dieci passi da una Sentinella e dal suo felino, e nessuno dei tre sembrava trovarlo strano. Io sì.",
		"I cervi brucano i prati come se i nightsaber fossero mobili. Forse, per un felino ben nutrito in una città, lo sono davvero.",
		"Un cervo è rimasto su un ponte abbastanza da bloccare il carretto di un mercante, e il mercante ha aspettato, paziente come un paracarro, che finisse di guardare l'acqua.",
	},
	["dar.muse.w23.saber.008"] = {
		"rallenta mentre una cerva e il suo piccolo attraversano il sentiero davanti, senza fretta, il cerbiatto che si ferma a fissare finché la madre non lo spinge avanti col muso.",
		"si fa da parte per una cerva che guida un cerbiatto maculato attraverso il prato; il piccolo si pianta in mezzo al sentiero a studiare il viandante, poi rimbalza via dietro la madre.",
	},
	["dar.muse.w23.saber.009"] = {
		"Qui sulla Warrior's Terrace gli animali dei cacciatori stanno sdraiati come una seconda guarnigione, più sonnolenta: felini, orsi, un lupo con un orecchio strappato, tutti a guardare i loro compagni che si esercitano.",
		"Su questa terrazza gli istruttori tengono gli allievi, gli allievi tengono le loro bestiole e le bestiole tengono d'occhio tutti. Un orso ha appena sbadigliato a una coppia di duellanti, come per dar loro un voto.",
	},
	["dar.muse.w23.saber.010"] = {
		"Passi accanto a un nightsaber a riposo e gli occhi li noti per ultimi: due monete di luce color lampada che ti seguono senza che la testa si muova affatto.",
		"Nell'ombra verde sotto un ramo, un nightsaber era invisibile tranne gli occhi, due piccoli riflessi viola che si giravano per non perdermi di vista.",
	},
	["dar.muse.w23.saber.011"] = {
		"I felini delle Sentinelle mi riconoscono come kaldorei, credo: quando passo non alzano nemmeno la testa. Un ospite si becca una lunga occhiata gialla. Io uno sbadiglio, e lo prendo come un benvenuto.",
		"Un nightsaber sulla terrazza mi ha annusato la manica, ha deciso che sapevo di casa e si è riaddormentato sul mio piede. Per non svegliarlo non ho mosso un passo per un bel pezzo.",
	},
	["dar.muse.w23.saber.012"] = {
		"Ogni nightsaber che incrocio mi lancia una lunga occhiata di misura, la stessa che mi aveva dato la sua Sentinella poco prima. Sospetto che dopo si confrontino.",
		"I felini di qui guardano i forestieri come fanno le Sentinelle: piano, partendo dagli stivali. Mi piace pensare di superare l'esame. Il verdetto, i felini se lo tengono per sé.",
	},
	["dar.muse.w23.saber.013"] = {
		"Ognuno di questi felini potrebbe fiutare l'Orda addosso a me sotto qualunque travestimento, ci giurerei. Mi lasciano passare solo perché nessuno gliel'ha ancora chiesto.",
		"Un nightsaber ha alzato la testa al mio passaggio e l'ha tenuta alzata. La sua Sentinella non se n'è accorta. Il felino sì, e lui non ha nessun motivo per mantenere il mio segreto.",
	},
	["dar.muse.w23.saber.014"] = {
		"nota un coniglio che rosicchia trifoglio a pochi passi da un nightsaber assopito, e il felino che lo guarda con un occhio pigro, chiaramente fuori servizio.",
		"osserva un coniglio che bruca sempre più vicino a un nightsaber addormentato, finché il felino muove un orecchio e il coniglio ripensa tutta la sua esistenza.",
		"scorge un coniglio addormentato nella curva della coda di un nightsaber che dorme, e decide che certe sistemazioni di Darnassus è meglio non metterle in discussione.",
	},
	["dar.muse.w23.saber.015"] = {
		"Qui nell'Enclave un cervo è passato tra i druidi come se avesse affari da sbrigare con loro. Forse li aveva. Nessuno gli ha chiesto i documenti.",
		"Un cervo se ne sta tra le radici dell'Enclave a ruminare pensoso, mentre due druidi parlano lì accanto. Sembra seguire la discussione meglio di me.",
	},
	["dar.muse.w23.saber.016"] = {
		"Giurerei che quel cervo mi abbia fatto un inchino. O mi guardava gli stivali. In ogni caso, l'inchino gliel'ho ricambiato.",
		"Un cervo mi ha fatto un cenno. Io ho fatto un cenno al cervo. Direi che ormai ci conosciamo.",
	},
	["dar.muse.w23.saber.017"] = {
		"si scosta dal sentiero per un nightsaber che zoppica su una zampa fasciata, con la sua Sentinella che gli cammina accanto adagio, accordando il passo al suo.",
		"guarda un nightsaber pieno di cicatrici adagiarsi sull'erba con grande cautela, e la sua Sentinella inginocchiarsi accanto, senza dire niente, una mano posata sul suo collo.",
	},
	["dar.muse.w23.saber.018"] = {
		"Due nightsaber si sono incontrati su un ponte e nessuno dei due voleva cedere il passo. Alla fine si sono seduti tutti e due nel mezzo, e l'intero ponte ha dovuto aspettare.",
		"Due felini hanno bloccato un ponte per un bel pezzo, fissandosi con grande dignità. Nessuno ha provato a spostarli. Nemmeno io ci avrei provato.",
	},
	["dar.muse.w23.saber.019"] = {
		"osserva un nightsaber che beve da un ruscello, lappando con tale delicatezza che l'acqua quasi non si muove, poi scuote la testa e spruzza gocce su un passante preso alla sprovvista.",
		"resta a guardare mentre un nightsaber scende fino al bordo dell'acqua, la saggia con una zampa come un bagnante prudente, e solo dopo china la testa per bere.",
	},
	["dar.muse.w23.saber.020"] = {
		"Se quel nightsaber vuole la panca, la panca è sua. Non discuto con niente che abbia più denti di quante monete ho io.",
		"Quel felino si è steso proprio sull'unico angolo d'ombra della terrazza. Ho deciso che preferisco stare in piedi.",
	},
	["dar.muse.w23.saber.021"] = {
		"Un cerbiatto mi ha annusato la mano ed è scappato. A dire il vero, è così che vanno quasi tutte le mie presentazioni.",
		"Quel cerbiatto mi ha guardato come se fossi la cosa più strana di Darnassus. A essere onesti, potrebbe avere ragione.",
	},
	["dar.muse.w23.sap.001"] = {
		"appoggia la mano a un parapetto, la stacca con un lieve schiocco appiccicoso e si guarda il palmo, dove è rimasta una perla di linfa ambrata.",
		"trova una goccia di linfa sulla manica, ci gratta sopra e riesce soltanto a spanderla.",
		"si sfrega il pollice contro l'indice, ancora appiccicosi della linfa di chissà quale ringhiera, e rinuncia a pulirli.",
	},
	["dar.muse.w23.sap.002"] = {
		"In una piega della corteccia, accanto al sentiero, una goccia di linfa ha catturato una moschina verde e si sta chiudendo su di lei, piano. Fra qualche migliaio d'anni qualcuno la alzerà controluce.",
		"Una perla di linfa sulla corteccia, con dentro un minuscolo scarabeo sigillato, le zampe ancora aperte come se volesse finire la sua passeggiata. Quest'albero conserva tutto, a quanto pare, persino gli errori.",
		"Nell'ambra di quel palo c'è un moscerino, perfetto fino alle ali. Teldrassil è giovane, ma ha già cominciato a custodire le cose.",
	},
	["dar.muse.w23.sap.003"] = {
		"Vicino all'Enclave ho visto un ramo potato, il taglio fasciato di argilla e muschio come una ferita. Due druidi gli sono rimasti accanto a lungo senza dire nulla, come si fa con qualcuno che si è fatto male.",
		"Dove un ramo era stato tagliato, la linfa era colata e si era seccata in lunghe lacrime d'ambra. Una druida la puliva con un panno morbido, senza fretta, come si lava un viso.",
		"Ho visto una druida stendere argilla fresca sul taglio di una potatura e mormorargli qualcosa sottovoce. Qualunque cosa dicesse, la diceva come una scusa.",
	},
	["dar.muse.w23.sap.004"] = {
		"Una vecchia druida ha detto, più a se stessa che ad altri, che la linfa di Teldrassil corre più svelta di quanto dovrebbe in qualunque albero. Poi si è accorta che ascoltavo e ha cambiato discorso.",
		"Ho sentito due druidi discutere, piano piano, della linfa. Uno la chiamava vigore. L'altro ha usato una parola che non ho afferrato, e il suono non mi è piaciuto.",
		"«Troppo zelante», ha detto una druida dell'albero, come una maestra di un allievo brillante, e poi ha avuto l'aria di chi vorrebbe non averlo detto ad alta voce.",
	},
	["dar.muse.w23.sap.005"] = {
		"Attenti alle ringhiere: metà stanno ancora colando linfa, e l'altra metà ci sta pensando.",
		"Chi l'avrebbe detto che una città può essere appiccicosa? Un'ora qui e mi resta già attaccata addosso.",
		"Se non mi muovo per un po', ho idea che l'albero mi terrà con sé.",
	},
	["dar.muse.w23.sap.006"] = {
		"La linfa qui non sa di pino. È più dolce, ricorda le pere dimenticate in cantina, con sotto qualcosa di verde che non so nominare.",
		"Avvicina il naso alla corteccia e senti un odore di miele un po' inselvatichito. Poi continuo a ritrovarlo sulle mie mani per un pezzo.",
		"Resina, pera, steli schiacciati: è l'odore della corteccia quando ti ci chini sopra. Niente a che vedere con la pece di uno scafo, e sto cercando di capire perché.",
	},
	["dar.muse.w23.sap.007"] = {
		"osserva una fila sottile di formiche che risale la corteccia verso un nodo che trasuda linfa; ognuna ridiscende più lenta di come è salita.",
		"si accovaccia per seguire una fila di formiche su per un tronco chiaro fino a una venatura lucida di linfa, dove si accalcano come invitati attorno a una fontana.",
		"resta un po' a guardare le formiche al lavoro su una goccia di linfa, indaffarate come facchini al mercato, mentre i kaldorei passano senza degnarle di uno sguardo.",
	},
	["dar.muse.w23.sap.008"] = {
		"Appoggia l'orecchio al tronco dove è più spesso e senti un ticchettio leggero, come una casa che si raffredda. Un druido mi ha detto che è la linfa che sale. Io avrei pensato a qualcosa di più piccolo e indaffarato.",
		"Ho poggiato la testa a un pilastro di legno vivo e ho sentito, appena appena, un fruscio come di grano che scorre dentro un muro. «La linfa», ha detto un druido passando, senza fermarsi.",
	},
	["dar.muse.w23.sap.009"] = {
		"La linfa di Teldrassil ha l'odore delle antiche foreste di Hyjal. L'albero è nuovo, l'odore no. Ci resto dentro più del necessario.",
		"Linfa sulle dita, e per un attimo sono in un luogo molto più antico di questa città. Non la pulisco subito.",
		"Il nostro albero nuovo, il nostro odore antico. Qualunque cosa i druidi abbiano sbagliato o azzeccato, la linfa l'hanno azzeccata.",
	},
	["dar.muse.w23.sap.010"] = {
		"osserva un forestiero che cerca di staccare col coltello un grumo di linfa ambrata da una ringhiera, finché accanto a lui compare un druido, così in silenzio che il coltello torna nel fodero quasi da solo.",
		"vede un nano che raschia linfa in una scatoletta di latta, tutto soddisfatto, finché l'ombra di una Sentinella non cade sulla scatoletta e lui si ricorda di un impegno urgente altrove.",
	},
	["dar.muse.w23.sap.011"] = {
		"La pioggia tira fuori la linfa dalla corteccia. Bastano pochi minuti e tutta la città sa di resina, dolce e greve, come una dispensa piena di marmellate.",
		"Con la pioggia ogni tronco comincia a luccicare e a mandare un odore più dolce. Pare che l'albero apra i pori all'acqua.",
	},
	["dar.muse.w23.sap.012"] = {
		"Lo sentite? Resina. In qualche punto di quest'albero c'è sempre qualcosa che si sta rimarginando.",
		"Niente chiodi, niente colla. Lasciano fare alla linfa.",
		"Quell'odore dolce è l'albero. Non un forno. Ho controllato.",
	},
	["dar.muse.w23.sap.013"] = {
		"Linfa sugli stivali, linfa sui polsini, linfa sulla moneta che ho appena dato a una bancarella. Ho chiesto scusa. Nessuno sembrava pensare che ce ne fosse bisogno.",
		"Ogni moneta che spendo qui mi torna indietro un po' appiccicosa. A quanto pare Darnassus segna il suo denaro.",
	},
	["dar.muse.w23.sap.014"] = {
		"Qui la linfa diventa ambra in poche stagioni, mi ha detto un'artigiana. Le ho chiesto se qualcuno la vende. Mi ha chiesto se io venderei le lacrime di un amico. L'ho presa per un no.",
		"Ho chiesto a una bancarella se avessero ambra da vendere. Lo sguardo che ho ricevuto avrebbe potuto sigillare una mosca all'istante.",
		"L'ambra di Teldrassil varrebbe una fortuna in qualunque altro posto. Qui nessuno vuole nemmeno parlarne, e ho smesso di chiedere.",
	},
	["dar.muse.w23.sap.015"] = {
		"nota una sacerdotessa fermarsi a pulire con l'angolo della manica una venatura di linfa che cola da uno stipite, delicata come una madre che asciuga un mento.",
		"vede un kaldorei fermarsi accanto a uno stipite lucido di linfa fresca, sfiorarne la goccia con la punta di un dito e proseguire, come chi saluta qualcuno di passaggio.",
		"osserva un anziano attendere che una lenta goccia di linfa cada da un architrave, raccoglierla sulla punta di un dito e premerla di nuovo nella corteccia.",
	},
	["dar.muse.w23.sap.016"] = {
		"Non appoggiarti lì. Sta piangendo. No, non in quel senso: linfa. Comunque non appoggiarti.",
		"Attenzione, quel palo è fresco. Di linfa, intendo, non di vernice. Qui non dipingono niente.",
	},
	["dar.muse.w23.sentinel.001"] = {
		"Sono le mani di uno sconosciuto che le Sentinelle guardano per prime, poi la faccia. Ho cominciato a farlo anch'io, e la cosa dice parecchio delle strade che ho percorso.",
		"Prima le mani, poi il viso: è l'ordine in cui una Sentinella ti legge. L'ho notato solo perché era così rapida.",
		"Lo sguardo di una Sentinella parte dalle mani. Niente di personale: è da lì che di solito cominciano i guai.",
	},
	["dar.muse.w23.sentinel.002"] = {
		"passa accanto a una Sentinella appoggiata a una balaustra, che fa scorrere ogni freccia tra due dita per saggiarne le penne, una dopo l'altra, senza mai abbassare lo sguardo.",
		"nota una Sentinella che tasta l'impennaggio di ogni asta della faretra, piano e alla cieca, come chi conta monete in fondo a una tasca buia.",
		"segue le mani di una Sentinella al suo posto che fa rotolare una sola freccia fra pollice e indice, la traguarda per tutta la lunghezza e la rimette nella faretra con qualcosa di simile all'approvazione.",
	},
	["dar.muse.w23.sentinel.003"] = {
		"Ho chiesto la strada a una Sentinella e ho avuto quattro parole e un cenno del mento. Tutte e quattro necessarie. Ho controllato.",
		"Le Sentinelle danno indicazioni come tirano con l'arco: un colpo solo, niente parole di troppo, e in qualche modo vanno a segno.",
		"Ho domandato a una Sentinella dove fosse la locanda. Ha sollevato il mento di un dito in una direzione. L'ho trovata.",
	},
	["dar.muse.w23.sentinel.004"] = {
		"osserva un'ufficiale delle Sentinelle percorrere una breve fila di guerriere, dando uno strattone a ogni cinghia e fibbia, e passare oltre in silenzio quando niente cede.",
		"scorge una Sentinella più anziana scorrere una fila di compagne d'armi, saggiando una fibbia qui, una cinghia là, senza dire nulla finché tutto tiene.",
		"assiste a un'ispezione: una fila di Sentinelle immobili, senza un mormorio. L'ufficiale trova una cinghia appena troppo lenta, e l'intera fila sembra stringersi con lei.",
	},
	["dar.muse.w23.sentinel.005"] = {
		"Quella Sentinella mi ha guardato tre volte. Credo che mi stia imparando a memoria.",
		"Lei non ha battuto ciglio. Io l'ho battuto abbastanza per due.",
		"Sì, sono io. No, non sto combinando niente. Puoi smettere di impararmi a memoria.",
	},
	["dar.muse.w23.sentinel.006"] = {
		"L'armatura delle Sentinelle non è nuova. Ogni piastra è stata ammaccata, raddrizzata a martellate e oliata daccapo, e loro portano i rammendi in vista quanto il metallo.",
		"Guarda da vicino l'equipaggiamento di una Sentinella: cuoio rattoppato, una fibbia sostituita, una piastra ribattuta dopo chissà quale colpo. Non si butta niente che possa ancora reggere una guardia.",
		"Niente di ciò che indossa una Sentinella è nuovo, e niente è trasandato. Riparato, oliato, riparato ancora una volta: perfino la sua roba ha l'aria paziente.",
	},
	["dar.muse.w23.sentinel.007"] = {
		"sente una Sentinella rimproverare il suo grande felino a voce bassa e paziente, e il felino ascoltare con l'aria precisa di chi lo rifarà.",
		"coglie una Sentinella che mormora qualcosa al suo felino mentre ne stringe i finimenti, in un tono a metà tra l'ordine e un vecchio scherzo fra loro due.",
		"guarda una Sentinella accovacciarsi a controllare le zampe del suo felino una per una, come un fabbro controlla i ferri, mentre la grossa bestia sopporta a occhi chiusi.",
	},
	["dar.muse.w23.sentinel.008"] = {
		"Anche a riposo, una Sentinella tiene il peso un poco indietro, pronta a scartare da una parte o dall'altra. Secoli così, ed è diventato semplicemente il suo modo di stare in piedi.",
		"Guarda i piedi di una Sentinella, non la faccia: mai piantati dritti, sempre a mezzo passo dal muoversi. Per loro il riposo sembra solo una prontezza più leggera.",
		"Nessuna Sentinella si adagia mai del tutto. Anche appoggiata a una balaustra, una di loro tiene un piede libero, come se la balaustra potesse aver bisogno di difesa.",
	},
	["dar.muse.w23.sentinel.009"] = {
		"Che non succeda niente di interessante durante la tua guardia, Sentinella. Lo dico con affetto.",
		"Guardia lunga? Non chiedo quanto. Sospetto che la risposta abbia dentro qualche secolo.",
		"Non badare a me, Sentinella. Sto solo ammirando quanto sai stare ferma.",
	},
	["dar.muse.w23.sentinel.010"] = {
		"nota come una Sentinella sul sentiero si raddrizzi al passaggio di una sacerdotessa, e come la sacerdotessa risponda con un cenno del capo non più profondo del suo.",
		"vede una Sentinella e una sacerdotessa incrociarsi sul sentiero e scambiarsi lo stesso breve cenno, profondo uguale da entrambe le parti, come un debito saldato da tempo.",
	},
	["dar.muse.w23.sentinel.011"] = {
		"Una Sentinella di guardia mangiava un frutto senza mai staccare gli occhi dal sentiero. Ho visto soldati fare peggio con tutte e due le mani libere.",
		"Anche il pasto di una Sentinella si consuma sull'attenti: piccoli morsi, sguardo alto, il torsolo riposto in una borsa invece che gettato.",
		"Mangiano in piedi, le Sentinelle, a piccoli morsi, con gli occhi sul sentiero. Non ne ho mai vista una finire un pasto; sospetto che non lo comincino mai davvero.",
	},
	["dar.muse.w23.sentinel.012"] = {
		"Le Sentinelle portano i capelli stretti e raccolti, niente di sciolto che un ramo o un nemico possa afferrare. Perfino la vanità, da loro, è stata addestrata.",
		"Ogni Sentinella ha i capelli intrecciati all'indietro nello stesso modo accurato. Per praticità, mi dicono; eppure ogni treccia finisce in modo un po' diverso, come se l'ultimo pollice fosse tutto suo.",
	},
	["dar.muse.w23.sentinel.013"] = {
		"Qui sulla terrazza le Sentinelle si esercitano con i glaive a coppie, prima piano, poi più veloci, finché l'acciaio è una macchia e nessuna delle due ha spostato i piedi.",
		"Due Sentinelle ripetono lo stesso esercizio con il glaive, abbastanza piano da far vedere ogni torsione del polso. Su questa terrazza la velocità è l'ultima cosa che ti guadagni.",
		"Le Sentinelle, qui, ripetono lo stesso lancio cento volte, e il centesimo viene osservato con la stessa attenzione del primo.",
	},
	["dar.muse.w23.sentinel.014"] = {
		"Ho sistemato il colletto senza che nessuno me lo chiedesse. Le Sentinelle fanno quest'effetto.",
		"Uno sguardo di una Sentinella e raddrizzo la schiena. E non sono nemmeno ai suoi ordini.",
		"C'è qualcosa nelle Sentinelle che mi fa controllare le fibbie. Tutte. Due volte.",
	},
	["dar.muse.w23.sentinel.015"] = {
		"sente il raschio lento di una cote e scopre una Sentinella che la passa lungo il filo di un glaive, fermandosi ogni tanto ad ascoltare l'acciaio come se potesse rispondere.",
		"tende l'orecchio a un raschio morbido e regolare e trova una Sentinella che affila il suo glaive, ogni passata della stessa lunghezza, la pietra inumidita fra un colpo e l'altro con la punta di un dito.",
	},
	["dar.muse.w23.stranger.001"] = {
		"guarda un nano che su un ponte attacca una risata fragorosa, nota tutte le teste che si voltano e la finisce in un sussurro che gli scuote la barba intera.",
		"sente un nano fermare a metà la propria risata tonante e piegarne il resto in un colpo di tosse, mentre due Sentinelle fingono di non aver sentito.",
	},
	["dar.muse.w23.stranger.002"] = {
		"Uno gnomo al bancone della banca, in punta di piedi, che tratta affari col mento di chi sta dietro al banco. Nessuno dei due sembrava trovarlo strano, così ho fatto del mio meglio per imitarli.",
		"Qui i banconi sono tagliati su misura per i kaldorei. Ho visto uno gnomo porgere le monete verso l'alto come una supplica rivolta a un balcone, con una dignità impeccabile.",
	},
	["dar.muse.w23.stranger.003"] = {
		"Gli gnomi a Darnassus sono ospiti due volte: di Ironforge da quando Gnomeregan è caduta, e di questo albero. Sembrano esserci diventati bravissimi.",
		"Sulla terrazza una gnoma raccontava a un druido, allegramente, che da anni non ha più una città sua. Il druido è rimasto zitto a lungo, poi le si è seduto accanto.",
	},
	["dar.muse.w23.stranger.004"] = {
		"È passato di corsa un corriere umano, con le lettere sotto il braccio, e l'intera terrazza l'ha seguito con gli occhi come si segue una falena entrata dalla finestra.",
		"La gente di Stormwind la riconosci al volo: cammina come se la città chiudesse a una certa ora. Darnassus, a quanto pare, non chiude mai.",
	},
	["dar.muse.w23.stranger.005"] = {
		"nota un umano che mormora un breve ringraziamento alla Luce sul suo pasto in riva all'acqua, e poco lontano una sacerdotessa di Elune che ascolta con interesse cortese e senza fretta.",
		"vede un umano in visita chinare il capo verso la Luce prima di mangiare, e una sacerdotessa di passaggio rallentare per riguardo finché lui non ha finito.",
	},
	["dar.muse.w23.stranger.006"] = {
		"Ogni cenno cortese in questa città è rivolto a qualcuno che credono io sia. Tengo la testa bassa e le mani in vista.",
		"Se una Sentinella mi guarda un istante di troppo, è finita. Non ho mai avuto tanta paura in un posto così educato.",
		"Ogni cortesia che ricambio è una bugia ben educata. I kaldorei meritano di meglio, e io merito di uscire di qui senza farmi notare.",
	},
	["dar.muse.w23.stranger.007"] = {
		"Chi passa mi mormora Ishnu-alah, e io rispondo con un cenno come se fossi di qui. Meno parlo meglio è: una parola col mio accento svuoterebbe la terrazza.",
		"Una città nemica, mite come un giardino. La cosa peggiore è quanta voglia ho di sedermi in riva all'acqua e smettere di fingere.",
	},
	["dar.muse.w23.stranger.008"] = {
		"Un nano vestito di rosso e oro ha attraversato la terrazza, e per un momento Darnassus è sembrata un quadro firmato con l'inchiostro sbagliato.",
		"I forestieri, qui, si notano dal colore. Fra tutto quel viola e argento, uno gnomo vestito d'arancione è praticamente un fuoco di segnalazione.",
	},
	["dar.muse.w23.stranger.009"] = {
		"esita davanti a un sedile scolpito lungo il sentiero, senza sapere se sia per chiunque, e alla fine resta in piedi lì accanto.",
		"si ferma davanti a un muretto che potrebbe servire per sedersi oppure essere sacro, e dopo averci pensato decide di non appoggiarsi a niente.",
		"resta a lungo sul bordo di un prato dove i kaldorei siedono tranquilli, senza sapere se l'erba sia anche per gli ospiti, e decide di ammirarla dal sentiero.",
	},
	["dar.muse.w23.stranger.010"] = {
		"Qualcun altro ha la sensazione di portare fango dentro un tempio? Solo io, a quanto pare.",
		"Continuo a voler pulire gli stivali prima di mettere piede da qualche parte. Su cosa, non saprei.",
		"C'è un posto dove un ospite ha il diritto di essere maldestro? Vorrei andarci per un po'.",
	},
	["dar.muse.w23.stranger.011"] = {
		"Due nani si sono incontrati su un ponte e si sono salutati come parenti ritrovati, anche se scommetto che non si erano mai visti. Una città così sommessa fa rimpiangere ai forestieri chiunque faccia rumore.",
		"Qui i forestieri dello stesso posto lontano si trovano in fretta. Ho visto due umani di Westfall diventare vecchi amici nel tempo di fare il giro del lago.",
	},
	["dar.muse.w23.stranger.012"] = {
		"nota un umano solitario seduto sul bordo del lago, lontano da tutti: l'unico forestiero che sembra aver smesso di cercare di adattarsi, e l'unico che pare a suo agio.",
		"passa accanto a un nano segnato dagli anni che dorme sul muschio, scalzo, russando pianissimo; i kaldorei gli girano intorno con qualcosa di simile all'affetto.",
	},
	["dar.muse.w23.stranger.013"] = {
		"I nani si portano dietro l'odore della forgia, e quassù, fra muschio e fiori, gli resta addosso come un mantello che si sono dimenticati di togliere.",
		"Da dove viene un forestiero lo capisci dall'odore: fumo di forgia su un nano, olio e ottone su uno gnomo, cavallo e strada su un umano. I kaldorei sanno solo d'albero.",
	},
	["dar.muse.w23.stranger.014"] = {
		"A Darnassus la creatura strana sono io. I gufi, i grandi felini, l'acqua che brilla: tutto normalissimo. Io, con i miei anni corti e gli stivali rumorosi, sono la curiosità.",
		"Un giovane kaldorei, chissà dove, si ricorderà di me come di quel forestiero dalla vita breve che fissava tutto. Mi sembra giusto. Anch'io mi ricorderò di loro.",
	},
	["dar.muse.w23.stranger.015"] = {
		"Hai l'aria persa quanto me. Scegli un sentiero: io ti seguo e chiedo scusa a chiunque ci trovi sopra.",
		"Anche tu di passaggio? Dimmi la verità: anche a te la tua voce sembra troppo forte, qui?",
		"Ospite anche tu? Allora capirai perché sto su questo ponte a fingere di ammirare il panorama.",
	},
	["dar.muse.w23.stranger.016"] = {
		"Ho chiesto scusa a un druido, a una Sentinella e a una fontana. La fontana è stata la più indulgente.",
		"Ho detto 'permesso' più volte in questa città che in tutto il resto della mia vita messo insieme.",
		"Scusi, pardon, prego, dopo di lei. La mia bocca sembra aver scordato come si formano altre parole.",
	},
	["dar.muse.w23.stranger.017"] = {
		"divide un tratto di sentiero con uno gnomo in visita, e si indicano le cose a vicenda sottovoce, come scolari in visita a un tempio.",
		"cammina per un po' accanto a un visitatore umano, e i due si fermano insieme a ogni ringhiera scolpita, ospiti che si scambiano impressioni a bassa voce.",
	},
	["dar.muse.w23.stranger.018"] = {
		"spiega una mappa sgualcita su un muretto, e in un attimo un elfo si ferma, la gira dal verso giusto senza dire una parola e prosegue.",
		"studia una mappa disegnata a mano delle terrazze finché un kaldorei di passaggio non si sporge, tocca appena un punto e se ne va prima di qualsiasi ringraziamento.",
		"resta a un bivio a girare e rigirare una mappa finché un elfo, senza dire niente, indica la via a sinistra e aspetta di vederla imboccare.",
	},
	["dar.muse.w23.stranger.019"] = {
		"Ho chiesto da quanto c'è la banca. 'Da poco', mi hanno risposto. Ho imparato a non chiedere cosa voglia dire.",
		"Tutti così alti e così calmi. Mi sento un sasso rotolato per sbaglio in una sala di statue.",
		"Se resto immobile, mi scambieranno per gente del posto? No? Sono gli stivali, vero?",
	},
	["dar.muse.w23.stranger.020"] = {
		"Qualcuno dica a quello gnomo che la fontana non è una macchina. È un pezzo che cerca la manovella.",
		"Ecco un umano che passa di corsa. Qualcuno dovrebbe dirglielo: qui non scappa via niente.",
		"Quell'umano fa l'inchino a una statua da un bel pezzo. Chi glielo dice?",
	},
	["dar.muse.w23.stranger.021"] = {
		"prova a sedersi a gambe incrociate sull'erba come i kaldorei lì vicino, resiste un po' con grande dignità, poi si districa in silenzio.",
		"si abbassa sul muschio per imitare gli elfi seduti lì, e scopre che la loro naturalezza non arriva insieme alla posizione.",
	},
	["dar.muse.w23.stranger.022"] = {
		"si sente fissare, apertamente e a lungo, da un kaldorei molto piccolo, l'unico in città che fissi qualcuno, finché un adulto non mormora una parola e lo sguardo diventa un piccolo inchino accurato.",
		"sorprende un bambino kaldorei a studiare i suoi stivali con aperta curiosità; basta una parola sommessa di qualcuno più grande, e il bambino alza gli occhi e fa un inchino.",
	},
	["dar.muse.w23.stranger.023"] = {
		"Le Sentinelle sono cortesi con ogni visitatore, ma lo sguardo si fa un po' più duro quando passa uno straniero che non sanno inquadrare. Gliel'ha insegnato la guerra in Ashenvale.",
		"Cortesia verso gli ospiti, certo, ma le Sentinelle non smettono mai di valutarli. Un popolo in guerra in Ashenvale ha imparato che non tutti i visitatori arrivano da amici.",
	},
	["dar.muse.w23.stranger.024"] = {
		"I druidi qui nell'Enclave guardano i visitatori come guarderebbero un germoglio sconosciuto: con interesse, con pazienza, e senza sapere ancora cosa ne verrà fuori.",
		"Un druido dell'Enclave ha chiesto a un nano, con molto garbo, di smettere di bussare sulla parete per sentire se era cava. Il nano si è scusato col druido e poi, dopo un attimo, con la parete.",
	},
	["dar.muse.w23.stranger.025"] = {
		"guarda un nano in visita esercitarsi ai bersagli accanto alle Sentinelle, rumoroso, allegro e abbastanza preciso, mentre gli elfi intorno a lui tacciono in un modo che suona come un gran complimento.",
		"osserva per un po' un soldato umano incrociare le armi con un istruttore kaldorei, tutto cortesia presa in prestito e lividi autentici.",
	},
	["dar.muse.w23.sundering.001"] = {
		"Dove ora c'è il mare c'era una città, e un popolo intero addormentato dentro. I kaldorei scampati alla Frattura parlano dell'oceano come di una tomba che non si può visitare.",
		"L'acqua che circonda Teldrassil copre quella che un tempo gli elfi chiamavano la loro capitale. Certuni non riescono a guardare un mare calmo senza vederci sotto dei tetti.",
	},
	["dar.muse.w23.sundering.002"] = {
		"Kalimdor era una terra sola prima che il Pozzo sprofondasse, dicono i druidi, e ogni costa del mondo è l'orlo di quella ferita. Non guarderò più una scogliera allo stesso modo.",
		"Un druido mi ha detto che le coste del mondo sono tutte cicatrici di una sola rovina. Ogni spiaggia che ho mai calpestato, allora, un tempo era entroterra.",
	},
	["dar.muse.w23.sundering.003"] = {
		"segue lo sguardo di una vecchia kaldorei verso l'orlo lontano della chioma, dove c'è il mare, e capisce che lei non guarda l'acqua, ma il punto dov'era una costa.",
		"si ferma accanto a un anziano che guarda tra i rami verso il mare aperto e mormora un nome, troppo piano per afferrarlo, che nessuna mappa porta più da tantissimo tempo.",
	},
	["dar.muse.w23.sundering.004"] = {
		"Con tutti i posti dove piantare un albero dopo che la tua patria è affondata, loro hanno scelto il mare. O è lutto, o è lo scherzo più testardo di Azeroth.",
		"Hanno perso il loro mondo nell'acqua, e poi hanno costruito la nuova capitale circondata dall'acqua. Non so se sia sfida o il senso dell'umorismo di un popolo molto vecchio.",
	},
	["dar.muse.w23.sundering.005"] = {
		"Gli Highborne che non vollero rinunciare alla magia furono mandati oltre il mare, verso est, e non furono mai riaccolti. È un esilio antico, e ancora nessuno in città ama sentirsi chiedere chi avesse ragione.",
		"L'esilio fu la risposta dei kaldorei a chi si aggrappava all'arcano dopo la Frattura: una nave, un orizzonte, nessuna strada per tornare. Un druido me l'ha raccontato e poi ha cambiato discorso due volte.",
	},
	["dar.muse.w23.sundering.006"] = {
		"Gli alti elfi dell'est discendono da esuli kaldorei, ha detto una Sentinella, e non ha aggiunto altro. Raramente ho sentito dire così tanto con così poco.",
		"Chiedi degli elfi oltre il mare d'oriente e i kaldorei tacciono in un modo tutto loro: né ostili né affettuosi. Come quando arriva notizia di un cugino andato via sbattendo la porta.",
	},
	["dar.muse.w23.sundering.007"] = {
		"vede un bambino lasciar cadere un sassolino in una vasca e un vecchio elfo chiudergli piano la mano prima del secondo, senza una parola di spiegazione.",
		"nota un anziano inginocchiarsi accanto a un piccolo che schizza sul bordo di una vasca e insegnargli, con grande pazienza, a toccare l'acqua senza turbarla.",
	},
	["dar.muse.w23.sundering.008"] = {
		"L'acqua del pozzo nel tempio è l'unica di Darnassus in cui le sacerdotesse ti lasciano guardare a lungo. Tutta l'altra, noto, la tengono in movimento.",
		"Nel tempio l'acqua resta ferma e benedetta. Nel resto della città scorre, schizza, cade. Mi viene in mente che i kaldorei forse non si fidano dell'acqua che si ferma.",
	},
	["dar.muse.w23.sundering.009"] = {
		"La loro vecchia capitale sta in fondo al mare. Ridimensiona parecchio le mie lamentele sulla locanda.",
		"Hanno perso un continente e hanno fatto un albero. Io la settimana scorsa ho perso un guanto e ho tenuto il muso per giorni.",
	},
	["dar.muse.w23.sundering.010"] = {
		"Ogni kaldorei oltre una certa età porta in testa un luogo che non esiste più da nessun'altra parte. Non una rovina: niente, nemmeno macerie, solo acqua.",
		"Gli umani piangono le città distrutte perché le rovine restano. Gli elfi sopravvissuti alla Frattura piangono luoghi che non hanno lasciato una pietra su cui posare la mano.",
	},
	["dar.muse.w23.sundering.011"] = {
		"Una druida mi ha giurato che in certe ore immobili, oltre le radici di Teldrassil, si sentono campane sott'acqua. Le ho chiesto se le avesse sentite. Ha detto che preferiva di no.",
		"I barcaioli alle radici raccontano una storia, mi ha detto una Sentinella: campane sotto le onde, dove affondò la vecchia capitale. L'ha detto con leggerezza, e alla fine non ha riso.",
	},
	["dar.muse.w23.sundering.012"] = {
		"Dopo che il mondo si spezzò, si dice, i sopravvissuti si ritrovarono su una costa nuova senza niente, e la prima cosa che fecero fu piantare qualcosa. Quell'istinto è ancora ovunque, in città.",
		"La risposta dei kaldorei alla catastrofe sembra essere il giardinaggio. L'hanno fatto dopo la Frattura, l'hanno fatto dopo Hyjal, e ogni aiuola qui dice che lo rifarebbero.",
	},
	["dar.muse.w23.sundering.013"] = {
		"nota una costa incisa in una balaustra, con la linea che si interrompe a metà, e la chiazza liscia dove innumerevoli dita si sono fermate sulla rottura.",
		"passa il pollice lungo un litorale intagliato in un vecchio pannello e lo sente finire di colpo, il legno lucidato e chiaro in quel punto da molte mani prima della sua.",
	},
	["dar.muse.w23.sundering.014"] = {
		"Laggiù, chissà dove, c'è una spiaggia dove un anziano kaldorei andava a piedi da bambino, e adesso è a tre giorni di nave nella direzione sbagliata. Perdersi assume tutto un altro senso.",
		"Per me la strada di casa è una strada. Per alcuni degli elfi più vecchi di qui, la strada di casa va dritta in giù, sotto parecchia acqua.",
	},
	["dar.muse.w23.sundering.015"] = {
		"Sotto le onde, a est, giacciono le sale dell'antica capitale. Non c'ero ancora quando sprofondarono, eppure la parola per quel mare mi si ferma in gola.",
		"Gli anziani hanno una parola per il mare che vuol dire tomba e culla insieme. Un tempo credevo fosse poesia. Ora la sento come una descrizione esatta.",
	},
	["dar.muse.w23.sundering.016"] = {
		"Perdere un'intera terra e restare educati. Non credo che ci riuscirei.",
		"Il mare gli ha preso tutto e ancora dicono per favore. C'è gente migliore di me, al mondo.",
	},
	["dar.muse.w23.sundering.017"] = {
		"Quando le cascate della città si fanno rumorose, i kaldorei più vecchi alzano gli occhi un istante, poi tornano a quel che facevano. Un riflesso più vecchio di quasi ogni regno.",
		"Ho visto un anziano sussultare al fragore di un ruscello in caduta, e poi sorridere di sé. Qualunque cosa ricordino le sue orecchie, era più forte di così.",
	},
	["dar.muse.w23.sundering.018"] = {
		"I druidi dell'Enclave accennano, molto piano, a un secondo pozzo trovato dopo la morte del primo. Lo dicono come si confessa un debito, e non dicono dove.",
		"Qui tra i druidi ho sentito dire che non tutte le acque del Pozzo andarono perdute. Chi me l'ha detto poi ha fissato l'erba a lungo, come se potesse fare la spia.",
	},
	["dar.muse.w23.sundering.019"] = {
		"Il grande gorgo dove sprofondò il Pozzo gira ancora, laggiù in mezzo all'oceano, dicono i marinai. I kaldorei non lo nominano mai. Girano al largo dell'argomento.",
		"C'è un punto al centro del mare dove l'acqua non ha mai smesso di vorticare da quando il Pozzo crollò. Chiedine a un elfo, qui, e ti offrirà un tè al posto della risposta.",
	},
	["dar.muse.w23.sundering.020"] = {
		"Qui non lasciano cadere niente in acqua. Visto com'è andata l'ultima volta che qualcosa è affondato, li capisco.",
		"Mai dire a un kaldorei che il mare sembra tranquillo. Fidati.",
	},
	["dar.muse.w23.sundering.021"] = {
		"Sotto il cielo aperto, di notte, gli anziani a volte restano a guardare a lungo verso est. Verso il mare, verso gli esuli, verso ciò che resta di quella notte. Nessuno li disturba.",
		"A quest'ora ho visto degli anziani fermarsi sui sentieri e voltarsi a est, dove andarono gli Highborne. Non fanno mai un cenno. Restano lì e ricordano chi partì.",
	},
	["dar.muse.w23.sundering.022"] = {
		"indugia accanto a un'artigiana kaldorei che macina una conchiglia pallida per farne tintura; la conchiglia, osserva lei senza rivolgersi a nessuno, viene da una spiaggia che un tempo era la cima di una collina.",
		"sosta a un banco dove una tintora frantuma conchiglie in una polvere viola sottilissima, e la sente mormorare che la nonna di sua nonna coglieva fiori dove ora si trovano quei gusci.",
	},
	["dar.muse.w23.tongue.001"] = {
		"Ishnu-alah. L'ho detto bene? Non rispondere: lasciami la speranza.",
		"A te, Ishnu-alah. Ho fatto pratica con i gufi, e loro non mi correggono mai.",
	},
	["dar.muse.w23.tongue.002"] = {
		"Le sacerdotesse si congedano con Elune-adore. Ne ho sentita una spiegare a un umano che significa: Elune sia con te. Detto piano, somiglia meno a un addio che a una porta accostata con dolcezza.",
		"Elune-adore, a ogni commiato. Chiede alla dea di farti compagnia, ha spiegato una Sentinella a uno gnomo sul ponte. Un saluto più gentile di quasi tutti gli altri.",
	},
	["dar.muse.w23.tongue.003"] = {
		"I visitatori imparano a rispondere Andu-falah-dor senza mai scoprire cosa voglia dire. Ho visto un nano ripeterlo con sicurezza assoluta e un mezzo inchino.",
		"L'elfo dice Andu-falah-dor; l'umano risponde Andu-falah-dor, con cautela, come chi firma un foglio che non ha letto.",
	},
	["dar.muse.w23.tongue.004"] = {
		"passa accanto a due kaldorei che parlano nella loro lingua, e li sente passare al Comune per una frase mentre passa, poi tornare indietro, come chi si scosta sul sentiero e riprende il suo posto.",
		"coglie lo scorrere morbido del darnassiano fra due elfi su un ponte; a metà frase passano al Comune per riguardo verso chi passa, e ritornano alla loro lingua appena la via è libera.",
		"sente una Sentinella finire una frase in darnassiano, accorgersi di avere qualcuno accanto, e ripeterne l'ultima parte in Comune, nel caso possa servire.",
	},
	["dar.muse.w23.tongue.005"] = {
		"Il darnassiano non ha spigoli. Persino una lite, in quella lingua, sembra qualcuno che legge ad alta voce una lunga lettera.",
		"Gli ospiti che non sanno il darnassiano ne imparano comunque gli umori: vocali lunghe per la cortesia, brevi e secche quando una Sentinella ha notato qualcosa.",
		"Un litigio in darnassiano sembra una recita. So che era un litigio solo perché i due elfi se ne sono andati in direzioni opposte.",
	},
	["dar.muse.w23.tongue.006"] = {
		"Il Comune dei kaldorei è accurato e un po' antiquato: parole che ho incontrato solo in libri molto polverosi, usate bene e senza ombra di vanità.",
		"Una druida si è scusata per il suo Comune, poi l'ha parlato meglio di qualsiasi araldo di Stormwind. Dopo, nessuno intorno a lei ha più osato aprire bocca.",
	},
	["dar.muse.w23.tongue.007"] = {
		"sente uno gnomo provare Ishnu-alah con una Sentinella in tre modi diversi, e la Sentinella, seria, approvare il terzo.",
		"guarda un umano ripassare a fior di labbra un saluto darnassiano per tutto il ponte, poi perdersi d'animo dall'altra parte e dire soltanto salve.",
	},
	["dar.muse.w23.tongue.008"] = {
		"Tre parole di darnassiano, ecco tutto il mio patrimonio: Ishnu-alah, Elune-adore, Andu-falah-dor. Le spendo come monete prese in prestito, nel caso valgano più di quanto credo.",
		"Conosco un saluto, un congedo e una frase che non so tradurre. Con quelle, qui, mi capiscono meglio che con tutto il mio Comune.",
	},
	["dar.muse.w23.tongue.009"] = {
		"Ho sentito una Sentinella spiegare a un nano che Ishnu-alah vuol dire buona fortuna a te. Da allora lui lo dice a tutti, come uno che distribuisce monete a una fiera.",
		"Una sacerdotessa ha detto Ishnu-alah a uno gnomo, poi l'ha tradotto: buona fortuna a te. E l'ha ripetuto più lentamente, perché gli restasse.",
	},
	["dar.muse.w23.tongue.010"] = {
		"Grazie della pazienza che hai avuto con me. Elune-adore.",
		"Andu-falah-dor. La tua gentilezza non è passata inosservata, anche se le mie maniere non le hanno tenuto dietro.",
		"Vi lascio in pace. Elune-adore, e buona fortuna.",
	},
	["dar.muse.w23.tongue.011"] = {
		"ascolta un elfo ripetere le indicazioni sempre più lentamente, scegliendo ogni volta parole più semplici, finché il senso arriva e viene accolto da un cenno sollevato.",
		"fa una domanda e guarda il kaldorei che risponde cercare la parola più semplice del Comune, come chi sceglie il sasso più liscio da porgere oltre un ruscello.",
	},
	["dar.muse.w23.tongue.012"] = {
		"Alcune parole che sento su queste terrazze si dicevano già prima che il mondo andasse in pezzi, se le sacerdotesse hanno ragione. Adesso sono parole comuni, di pane e di stivali.",
		"I druidi dicono che la loro lingua è cambiata pochissimo in tutte queste lunghe epoche. Pensa: chiedere il pane con le stesse parole di chi ha visto il mondo spezzarsi.",
	},
	["dar.muse.w23.tongue.013"] = {
		"Un kaldorei ha riso di una battuta detta di passaggio. Una risata breve, sorpresa, subito ripiegata. Chi se l'è guadagnata ci vivrà sopra per un pezzo.",
		"Ci vuole tempo per far ridere un kaldorei, e i visitatori raramente hanno il loro genere di tempo. Un sorriso però si può ottenere, e vale la pena di tenerselo.",
	},
	["dar.muse.w23.vigil.001"] = {
		"Per secoli i druidi dormirono nel Sogno di Smeraldo e le Sentinelle custodirono da sole le foreste. I druidi le ringraziano spesso. Le Sentinelle non sembrano mai sapere cosa rispondere.",
		"Druidi che sognano, Sentinelle che vegliano, generazione dopo generazione. Quando adesso un druido ringrazia una Sentinella, ho notato, lei annuisce soltanto, come chi si vede restituire un mantello prestato.",
	},
	["dar.muse.w23.vigil.002"] = {
		"osserva due Sentinelle passarsi il turno con una frase così consumata dall'uso che esce come un'unica parola sommessa, e un tocco al polso che chiaramente vuol dire di più.",
		"nota che quando le Sentinelle si danno il cambio si sfiorano un istante il polso, un gesto così abituale e così piccolo che dev'essere più vecchio della città attorno a loro.",
	},
	["dar.muse.w23.vigil.003"] = {
		"Gli orchi Warsong tagliano la vecchia foresta di Ashenvale per farne legname, e le Sentinelle scendono dall'albero a fermarli, una volta e un'altra. Quassù ne parlano come i contadini parlano di una piena che torna ogni anno.",
		"Ashenvale sanguina un po' di più a ogni stagione, e Darnassus manda Sentinelle a piantarsi davanti alle asce. Nessuno in questa città nomina i Warsong senza che il viso gli si indurisca.",
	},
	["dar.muse.w23.vigil.004"] = {
		"Le Sentinelle che si esercitano su questa terrazza tengono la posizione molto più a lungo di quanto serva. Un'istruttrice mi ha detto che non si allenano al colpo: si allenano a secoli di guardia.",
		"Qui le giovani Sentinelle imparano l'immobilità prima di qualunque altra cosa. Un'istruttrice ha detto, senza sorridere, che l'attesa è la prima arma del suo ordine.",
	},
	["dar.muse.w23.vigil.005"] = {
		"I loro druidi hanno dormito per secoli e loro sono rimaste di guardia tutto il tempo. Io vorrei delle scuse per iscritto.",
		"Un pisolino di qualche secolo, quello dei druidi, e le Sentinelle a coprirli. Qui nessuno ci trova niente da ridere, tranne me.",
	},
	["dar.muse.w23.vigil.006"] = {
		"Lo stesso Cenarius cadde ad Ashenvale, abbattuto da Grom Hellscream. I kaldorei pronunciano piano il nome del semidio, e quello dell'orco per niente.",
		"Il semidio della foresta fu ucciso ad Ashenvale da un signore della guerra orco. Le Sentinelle ne parlano senza alzare la voce. Quella calma fa molta più paura delle urla.",
	},
	["dar.muse.w23.vigil.007"] = {
		"vede una Sentinella con una cicatrice fresca lungo l'avambraccio allacciarsi l'equipaggiamento accanto al sentiero, senza fretta e in silenzio: è chiaro che torna giù, ad Ashenvale.",
		"scorge una Sentinella che saggia in lenti cerchi una spalla rigida, da poco rimessa in sesto, prima di caricarsi lo zaino e avviarsi verso il bordo della città senza voltarsi.",
	},
	["dar.muse.w23.vigil.008"] = {
		"Una Sentinella mi ha detto che la parte più dura della lunga veglia non erano i nemici. Erano i secoli senza nessuno a cui raccontare niente, perché chi avrebbe ascoltato stava sognando.",
		"Di cosa parlavano le Sentinelle, in tutti quegli anni coi druidi addormentati? Tra di loro, mi ha detto una. E poi, per molto tempo, di niente del tutto.",
	},
	["dar.muse.w23.vigil.009"] = {
		"Adesso i druidi sono svegli, e le Sentinelle danno loro indicazioni come se potessero riaddormentarsi per strada.",
		"Coi druidi, le Sentinelle usano un tono tutto loro. Affettuoso, sbrigativo, appena sospettoso: il tono di chi ti ha visto dormire attraverso qualche secolo di guai.",
	},
	["dar.muse.w23.vigil.010"] = {
		"Da Darnassus Ashenvale non si vede, ma si vedono le Sentinelle appena tornate. La mappa sono le loro facce.",
		"Qui nessuno ha bisogno di messaggeri dal sud. Quando le Sentinelle risalgono l'albero più silenziose di quando sono scese, l'intera città legge le notizie.",
	},
	["dar.muse.w23.vigil.011"] = {
		"osserva una Sentinella più anziana correggere la postura di un'allieva con due dita al gomito e una sola parola, e la giovane tenere la nuova posizione come scolpita.",
		"vede una Sentinella veterana percorrere la fila delle allieve, fermandosi a ciascuna giusto il tempo di raddrizzare un polso o un mento, senza dire quasi nulla.",
	},
	["dar.muse.w23.vigil.012"] = {
		"Ho visto una Sentinella e un druido incrociarsi su un ponte, scambiarsi uno sguardo e tirare dritto. Secoli di storia lì dentro: debito, affetto, un po' di rimprovero. Tutto in un'occhiata.",
		"C'è un modo in cui le Sentinelle guardano i druidi, per un attimo solo, prima che arrivi la cortesia. È lo sguardo di un vecchio soldato verso un amico che la guerra se l'è persa.",
	},
	["dar.muse.w23.vigil.013"] = {
		"Le Sentinelle restarono fedeli a Elune per tutta la lunga veglia, mi ha detto una sacerdotessa, senza nessuno che sentisse le loro preghiere tranne loro stesse. Spiega perché pregano ancora così in breve: impararono a farlo di guardia.",
		"Una sacerdotessa mi ha detto che le Sentinelle pregano con poche parole perché un tempo pregarono di guardia per secoli, a occhi aperti. Ancora adesso, ha detto, non li chiudono.",
	},
	["dar.muse.w23.vigil.014"] = {
		"Alcune di quelle Sentinelle fanno la guardia da prima che quasi ogni regno avesse un nome. Occhio a dove metti i piedi.",
		"Qualunque cosa tu pensi della pazienza, quelle guardie hanno secoli di vantaggio su di te. Un po' di rispetto.",
	},
	["dar.muse.w23.vigil.015"] = {
		"Ogni Sentinella che scende ad Ashenvale è una di noi che va incontro alle asce. Quando gli elenchi dei caduti risalgono l'albero li leggo due volte, sperando che la seconda sia diversa.",
		"Un tempo non seppellivamo nessuno. Ora Ashenvale ci insegna come, pochi nomi per volta. Ho imparato i riti meglio di quanto avrei mai voluto.",
	},
	["dar.muse.w23.vigil.016"] = {
		"La lunga veglia, mi ha raccontato una Sentinella, non finì con una battaglia, ma con un druido che si svegliava, sbadigliava e chiedeva cosa si fosse perso. Credo stesse ancora decidendo cosa ne pensava.",
		"Come la racconta una Sentinella, i druidi tornarono dal Sogno stiracchiandosi e chiedendo le novità. 'Secoli di novità,' ha detto. 'Tu da dove avresti cominciato?'",
	},
	["dar.muse.w23.vigil.017"] = {
		"nota una Sentinella a riposo con la schiena contro un tronco, gli occhi aperti, perfettamente tranquilla, e capisce che sta dormendo, o facendo quel che la lunga veglia le ha insegnato a fare al posto del sonno.",
		"passa accanto a una Sentinella seduta su una radice, gli occhi socchiusi e immobili, sprofondata in un vecchio riposo vigile al punto che una falena le si posa sul ginocchio indisturbata.",
	},
	["dar.muse.w23.vigil.018"] = {
		"Ogni Sentinella di questa città ha una sorella morta ad Ashenvale e un'idea precisa di chi abbia vibrato l'ascia. Tengo il cappuccio basso e le mie opinioni sul legname per me.",
		"Qui parlano dei Warsong come la mia parte parla del Flagello. In mezzo a loro capisco l'una e l'altra cosa un po' troppo bene per sentirmi a mio agio.",
	},
	["dar.muse.w23.vigil.019"] = {
		"A quest'ora le Sentinelle sembrano più se stesse, gli occhi che catturano il debole bagliore delle lampade. Hanno vegliato attraverso innumerevoli ore come questa, e si capisce che non hanno mai smesso di amarle.",
		"Il buio si addice alle Sentinelle. Ci si muovono con la naturalezza di chi vi ha fatto la guardia per secoli, mentre chiunque amassero stava sognando.",
	},
	["dar.muse.w23.vigil.020"] = {
		"Ho provato a stare di guardia come una Sentinella. Ho resistito giusto il tempo di avere fame.",
		"Dieci secoli di guardia. Io non reggo dieci minuti senza agitarmi.",
	},
	["dar.muse.w23.vigil.021"] = {
		"Le Sentinelle parlano degli alberi di Ashenvale come di compagni feriti. 'Ne hanno presi altri tre vicino al fiume,' ha detto una, e mi ci è voluto un attimo per capire che intendeva tronchi.",
		"Quando una Sentinella conta le perdite di Ashenvale, conta gli alberi insieme alle sorelle, nello stesso elenco. Ho smesso di trovarlo strano.",
	},
	["dar.muse.w23.vigil.022"] = {
		"nota lo sguardo di una Sentinella passare in rassegna il sentiero per pura abitudine, non trovare niente e posarsi di nuovo, come una mano che tasta una tasca per sicurezza.",
		"nota come una Sentinella guardi un sentiero dopo l'altro, senza fretta e con cura, un controllo così automatico che continua a parlare con la compagna per tutto il tempo.",
	},
	["dar.muse.w23.vigil.023"] = {
		"Le loro sorelle muoiono ad Ashenvale e quassù si inchinano ancora agli sconosciuti. Gente gentile. Gente dura.",
		"Tornano da Ashenvale e ripartono subito, le Sentinelle. Io almeno mi siederei un attimo.",
	},
	["dar.muse.w23.wander.001"] = {
		"La mia regola per orientarmi qui era seguire l'acqua. L'acqua, a quanto pare, porta soprattutto ad altra acqua.",
		"Segui il ruscello, pensavo, qualcosa di utile troverai. Ho trovato qualcosa di incantevole, che non è la stessa cosa.",
	},
	["dar.muse.w23.wander.002"] = {
		"imbocca la curva a sinistra con grande sicurezza e, qualche minuto dopo, ne esce esattamente da dove era {g:entrato|entrata}.",
		"sceglie un sentiero, lo segue con pazienza fino in fondo e si ritrova al bivio da cui era {g:partito|partita}.",
	},
	["dar.muse.w23.wander.003"] = {
		"Ho chiesto la strada a una Sentinella. Ha indicato, e in qualche modo pure il suo braccio è riuscito a fare una curva.",
		"Indicazioni da una Sentinella: un lungo sguardo, un gesto, e io troppo {g:orgoglioso|orgogliosa} per chiederle di ripeterlo.",
	},
	["dar.muse.w23.wander.004"] = {
		"Dalla banca alla Warrior's Terrace ci vogliono più o meno due motivetti canticchiati per intero, se non mi fermo a guardare. Mi fermo sempre a guardare.",
		"A Darnassus le distanze non si misurano in passi. Si misurano in quante volte ti dici che dev'essere qui dietro, di sicuro.",
	},
	["dar.muse.w23.wander.005"] = {
		"esita a un bivio, poi si accoda a qualche passo da un druido che cammina come se la strada fosse ovvia, e spera per il meglio.",
		"si ferma dove tre sentieri si dividono, aspetta qualcuno dall'aria sicura e segue una sacerdotessa a rispettosa distanza.",
	},
	["dar.muse.w23.wander.006"] = {
		"Ho seguito un nano che camminava con una determinazione formidabile. Tre ponti dopo si è fermato, si è guardato intorno e ha chiesto a me la strada.",
		"Da un pezzo ho davanti una gnoma che cammina con aria decisissima. Comincio a sospettare che sia persa quanto me.",
	},
	["dar.muse.w23.wander.007"] = {
		"I sentieri sono morbidi, larghi, gentili coi piedi, e così non ti accorgi di quanta strada hai fatto finché le ginocchia non presentano il conto.",
		"Puoi girare tutta Darnassus senza mai una salita di cui lamentarti. Poi ti siedi, e scopri che cosa hai combinato.",
	},
	["dar.muse.w23.wander.008"] = {
		"passa per la terza volta davanti alla stessa bancarella, e chi sta dietro il banco ogni volta accenna un inchino un po' più profondo.",
		"passa un'altra volta accanto alla stessa aiuola, finché la giardiniera inginocchiata lì non alza gli occhi e {g:lo|la} saluta come una vecchia conoscenza.",
	},
	["dar.muse.w23.wander.009"] = {
		"In altre città ti perdi tra i muri e li maledici. Qui ti perdi tra salici e muschio, e non c'è niente da maledire.",
		"È difficile tenere il broncio per essersi persi, quando ogni svolta sbagliata finisce davanti a qualcosa che vale la pena guardare.",
	},
	["dar.muse.w23.wander.010"] = {
		"taglia per un prato per risparmiarsi una lunga curva del sentiero, sente su di sé lo sguardo di un anziano kaldorei seduto lì vicino e finisce la scorciatoia in punta di piedi.",
		"accenna una scorciatoia sull'erba, incontra lo sguardo tranquillo di una Sentinella e torna sul sentiero senza dire niente.",
	},
	["dar.muse.w23.wander.011"] = {
		"Due terrazze di distanza, in linea d'aria. Peccato che io non voli.",
		"È vicino, mi hanno detto. In linea d'aria, forse.",
		"Una breve passeggiata, ha detto la Sentinella. Le Sentinelle vanno a piedi fino ad Ashenvale.",
	},
	["dar.muse.w23.wander.012"] = {
		"Sto imparando la città dagli odori. Cuoio e tinture vuol dire che ho sbagliato verso gli artigiani; incenso, che ho sbagliato verso il tempio.",
		"Vasche da concia da una parte, fiori e incenso dall'altra, acciaio e paglia più in là. Il naso conosce Darnassus meglio dei piedi.",
	},
	["dar.muse.w23.wander.013"] = {
		"abbozza la strada per la banca su un pezzetto di carta, la studia, la gira di un quarto, poi di un altro quarto, con crescente sospetto.",
		"traccia una mappa veloce sul margine di un taccuino e la guarda diventare, linea dopo linea, una spirale.",
	},
	["dar.muse.w23.wander.014"] = {
		"A volte non chiedo affatto la strada. Scelgo un sentiero e lascio decidere a lui, e non mi ha mai portato in un posto di cui pentirmi.",
		"Perdermi a Darnassus è diventato un piccolo piacere. C'è sempre qualcuno a cui chiedere, e quasi mai chiedo.",
	},
	["dar.muse.w23.wander.015"] = {
		"Oltre l'acqua, intorno all'albero, di là dal ponte. In questa città ogni direzione sembra la stessa direzione.",
		"Fammi indovinare: oltre il ponte, lungo l'acqua, e poi ancora un po'. È quello che dicono tutti di qualunque posto.",
	},
	["dar.muse.w23.wander.016"] = {
		"Ho provato a contare i passi dalla locanda alla banca. Ho perso il conto vicino a una fontana, a una cifra che non mi è piaciuta.",
		"Oltre i quattrocento passi ho smesso di contare la strada per la banca. Saperlo avrebbe solo peggiorato le cose.",
	},
	["dar.muse.w23.wander.017"] = {
		"fa un giro completo sul posto dove si incontrano diversi sentieri, poi prende quello scelto da un gatto di passaggio, convinto che il gatto lo sappia.",
		"resta a un incrocio di sentieri girando piano sul posto, come una banderuola in attesa di un parere.",
	},
	["dar.muse.w23.wander.018"] = {
		"Ho chiesto dove fosse l'addestratore e mi hanno raccontato la storia della terrazza. Storia bellissima. Dov'è l'addestratore, ancora non lo so.",
		"Ogni volta che chiedo la strada qui imparo qualcosa. Mai la strada.",
	},
	["dar.muse.w23.wander.019"] = {
		"Da una terrazza si vede la successiva, abbastanza vicina da chiamare qualcuno. Arrivarci è un'altra faccenda: giù, intorno, oltre, su, e un bel po' di tempo andato.",
		"In questa città ogni cosa è in vista di tutte le altre, e nessuna è a portata di nessuna.",
	},
	["dar.muse.w23.wander.020"] = {
		"Con questa nebbia non riesco nemmeno a perdermi come si deve. Non vedo abbastanza lontano da capire qual è la direzione sbagliata.",
		"Nebbia sulla città. Prima non sapevo dove fossi; adesso almeno ho una scusa.",
	},
	["dar.muse.w23.wander.021"] = {
		"cerca un addestratore tra le sale invase dal verde dell'Enclave, e tre druidi diversi, con garbo, {g:gli|le} indicano tre direzioni diverse.",
		"sale una rampa dell'Enclave, poi un'altra, e sbuca su un pianerottolo tranquillo senza sapere più quale rampa abbia preso.",
	},
	["dar.muse.w23.wander.022"] = {
		"I visitatori mi fermano su ogni sentiero per chiedere la strada. Do indicazioni piano, con cura, e vedo comunque metà di loro svoltare dalla parte sbagliata al ponte.",
		"Essendo kaldorei, tutti danno per scontato che conosca ogni sentiero di Darnassus. Ne conosco quasi tutti. Per gli altri bluffo con grande dignità.",
	},
	["dar.muse.w23.welcome.001"] = {
		"L'accoglienza kaldorei non è un banchetto né un discorso. È spazio: spazio sul sentiero, spazio nella conversazione, spazio per restare quanto vuoi.",
		"Nessuno, da queste parti, getta un braccio intorno alle spalle dell'ospite. Il benvenuto è più quieto: un posto lasciato libero per te, e nessuno che ti metta fretta per andartene.",
	},
	["dar.muse.w23.welcome.002"] = {
		"Fino a poco fa, per come lo contano i kaldorei, chi si spingeva nelle loro foreste trovava Sentinelle, non saluti. Adesso i nani vendono mappe sulla terrazza. Per loro, un cambiamento rapido.",
		"Per intere epoche i kaldorei hanno tenuto il mondo fuori. Lasciare che gli estranei passeggino sulle loro terrazze dev'essere costato più coraggio di una battaglia.",
	},
	["dar.muse.w23.welcome.003"] = {
		"riceve da una Sentinella di passaggio una sola parola in darnassiano e un palmo aperto, e il resto deve capirlo da sé.",
		"riceve un sommesso benvenuto da un elfo che innaffia i fiori, e che non smette di innaffiarli.",
		"si sente augurare il benvenuto in Comune da un druido che ha chiaramente dovuto cercare le parole, e trova la ricerca più toccante delle parole stesse.",
	},
	["dar.muse.w23.welcome.004"] = {
		"Grazie di avermi accolto nella vostra città. La lascerò come l'ho trovata.",
		"La vostra città è generosa con gli stranieri. Non lo dimenticherò.",
		"Camminerò piano e non toccherò niente. È il minimo, per un ospite.",
	},
	["dar.muse.w23.welcome.005"] = {
		"Alla locanda qualcuno ha messo un paio di sgabelli più bassi, chiaramente per nani e gnomi. Nessuno ne parla. Ecco l'accoglienza, in un solo mobile.",
		"Piccole premure per gli ospiti bassi: una panca più bassa vicino al fuoco della locanda. Qualcuno qui ha pensato a nani e gnomi, e non l'ha detto a nessuno.",
	},
	["dar.muse.w23.welcome.006"] = {
		"Gli ospiti possono entrare nel Temple of the Moon, mi dicono, purché entrino in silenzio. Che un popolo così riservato lasci aperto il suo luogo più sacro dice più di qualsiasi saluto.",
		"Nessuno mi ha fermato sui gradini del tempio. Le sacerdotesse hanno alzato gli occhi, visto qualcuno di passaggio, e sono tornate al loro lavoro. L'ho presa come la cortesia più profonda della città.",
	},
	["dar.muse.w23.welcome.007"] = {
		"assiste mentre una Sentinella spiega qualcosa a un gruppetto di nani in visita, con grande pazienza e molti gesti verso le aiuole. I nani annuiscono gravi e scendono dal prato.",
		"vede un gruppo di nani accompagnati con garbo fuori da un prato da una Sentinella che non alza mai la voce; scendendo, chiedono scusa all'erba.",
	},
	["dar.muse.w23.welcome.008"] = {
		"I nostri ospiti attraversano Darnassus in punta di piedi, come se l'albero potesse svegliarsi e protestare. Vorrei dire loro che è solo un albero, ma non sarebbe del tutto vero.",
		"Nani sui nostri ponti, gnomi alla nostra banca, umani che chiedono la strada alle nostre Sentinelle. Fino a poco fa non ci avrei creduto. Sto imparando ad apprezzare il rumore.",
	},
	["dar.muse.w23.welcome.009"] = {
		"Ho detto Elune-adore a un nano che se ne andava, e lui me l'ha ridetto, male e con enorme cura. Era tanto che non lo sentivo dire così bene.",
		"Una gnoma mi ha ringraziato con un Ishnu-alah che aveva chiaramente provato salendo. Le ho risposto prima nella nostra lingua, poi nella sua.",
	},
	["dar.muse.w23.welcome.010"] = {
		"Se fossi una Sentinella, dopo il terzo secolo di 'dov'è la banca?' avrei perso la pazienza. Loro rispondono ogni volta come se fosse una bella domanda.",
		"Le Sentinelle sentiranno 'da che parte è la casa d'aste?' cento volte per turno di guardia. La risposta arriva sempre con la stessa calma, come se nessuno l'avesse mai chiesto.",
	},
	["dar.muse.w23.welcome.011"] = {
		"Alleati, ci chiamano adesso. La parola sta ancora un po' rigida addosso a entrambi, come un mantello nuovo. Diamole tempo: i kaldorei ne hanno in abbondanza.",
		"L'Alleanza ha i kaldorei, e i kaldorei hanno l'Alleanza. Nessuno dei due sembra ancora sicuro di chi abbia fatto il favore all'altro.",
	},
	["dar.muse.w23.welcome.012"] = {
		"riceve senza spiegazioni un rametto di qualcosa di profumato da un giovane druido, che prosegue prima che si possa ringraziarlo.",
		"si ritrova in mano un rametto di una pianta chiara e dolce, lasciato da un elfo di passaggio che sparisce prima di qualsiasi domanda.",
		"riceve da un giardiniere un unico fiore chiaro, porto oltre una siepe come una moneta di benvenuto, e resta lì a tenerlo senza sapere cosa ci si aspetti adesso.",
	},
	["dar.muse.w23.welcome.013"] = {
		"Com'è andato il viaggio? Qui non lo chiede nessuno. Credo che sembrerebbe una domanda strana: la strada è alle spalle, e tu sei qui.",
		"A Ironforge vogliono ogni dettaglio del tuo viaggio. A Darnassus nessuno chiede niente: esserci basta come risposta.",
	},
	["dar.muse.w23.welcome.014"] = {
		"Uscire da una conversazione kaldorei richiede quanto entrarci. C'è un modo giusto per scenderne, come da una scala, e non si salta.",
		"Qui il congedo è una piccola cerimonia. Ho imparato a cominciare ad andarmene un bel po' prima di quando voglio davvero partire.",
	},
	["dar.muse.w23.welcome.015"] = {
		"Pace alle vostre terrazze, e pazienza con i vostri ospiti.",
		"Buona fortuna a questa città, e a chi la custodisce.",
		"State bene. Cercherò di meritarmi la cortesia che ho ricevuto qui.",
	},
	["dar.muse.w23.welcome.016"] = {
		"osserva un kaldorei accompagnare un umano smarrito fino alla banca invece di indicargliela, inchinarsi sulla porta e rifare tutta la strada all'indietro.",
		"nota un elfo lasciare incustodita la bancarella per guidare uno gnomo disorientato oltre due ponti, e tornare più tardi come se non fosse mancato niente.",
	},
	["dar.muse.w23.welcome.017"] = {
		"si accorge che la mercante, dopo uno sguardo all'equipaggiamento consumato dal viaggio, arrotonda il prezzo in basso senza dir nulla, e decide che protestare sarebbe scortese.",
		"paga quanto chiesto e si vede restituire una moneta, per ragioni spiegate soltanto da un piccolo sorriso chiuso.",
	},
	["dar.muse.w23.welcome.018"] = {
		"La locanda di questa terrazza è dove finiscono gli ospiti, e si sente: il Comune parlato un po' troppo forte, risate subito smorzate, un nano che chiede qualcosa di più forte.",
		"Qui un sarto umano in visita è chino su un banco di lavoro kaldorei, a studiare punti troppo piccoli per vederli, con la faccia di chi è appena stato messo al suo posto e non se la prende.",
	},
	["dar.muse.w23.wisp.001"] = {
		"Qui nell'Enclave un fuoco fatuo resta sospeso tra le radici, pulsando lento come chi dorme. I druidi ci girano intorno come si scavalca un gatto assopito.",
		"In questa parte dell'Enclave un fuoco fatuo vaga all'altezza del ginocchio, e i druidi gli fanno spazio senza guardarlo, come si fa con un vecchio amico perso nei suoi pensieri.",
	},
	["dar.muse.w23.wisp.002"] = {
		"Una sacerdotessa mi ha detto che i fuochi fatui sono ciò che resta dei kaldorei che se ne sono andati. Da allora, quando ne ho uno vicino, abbasso la voce, nel caso stia ascoltando.",
		"C'è chi dice che un fuoco fatuo sia un'anima kaldorei con una faccenda ancora in sospeso. Guardandone uno fermo accanto a una porta, mi domando quale, e se gli dia fastidio essere fissato così.",
	},
	["dar.muse.w23.wisp.003"] = {
		"si arresta mentre un fuoco fatuo attraversa il sentiero all'altezza del ginocchio, e attende che passi, come si aspetta che un anziano finisca di attraversare una stanza.",
		"si blocca a metà passo per lasciar passare un fuoco fatuo, e riprende a camminare solo quando la piccola luce pallida è sparita dietro una siepe.",
		"si scosta per un fuoco fatuo che fluttua all'altezza degli occhi, e sente, assurdamente, che forse sarebbe il caso di un inchino.",
	},
	["dar.muse.w23.wisp.004"] = {
		"Quello è un fuoco fatuo o una lampada che si è persa?",
		"Qualcosa mi ha appena brillato in faccia ed è volato via. In un'altra città mi preoccuperei. Qui lo prendo per un saluto.",
	},
	["dar.muse.w23.wisp.005"] = {
		"Mentre la luce cala, le lucciole si alzano dai prati a una a una, a due a due, come se l'erba si ricordasse delle scintille.",
		"Adesso le lucciole salgono dall'erba, lente e sparse, e per un po' i prati sembrano un cielo caduto a terra che non se n'è nemmeno offeso.",
	},
	["dar.muse.w23.wisp.006"] = {
		"scorge un bambino kaldorei portare una lucciola chiusa tra le mani fino al bordo dell'acqua e liberarla con grande solennità, come se rilasciasse un prigioniero di guerra.",
		"nota un piccolo elfo accovacciato nell'ombra fitta sotto un ramo, le mani chiuse a coppa attorno a una lucciola, che sbircia tra le dita con una cura immensa.",
	},
	["dar.muse.w23.wisp.007"] = {
		"Le falene qui hanno preso i colori della città: viola sulle ali, un filo d'azzurro ai bordi. O hanno scelto di intonarsi, o Darnassus le ha dipinte mentre dormivano.",
		"Persino le falene si vestono per Darnassus. Me ne è finita una sulla manica, ali dello stesso viola della veste di una sacerdotessa, e pareva sapere benissimo quanto le stesse bene.",
		"Una falena si è posata su una lampada e per un istante erano dello stesso colore. Poi la falena si è mossa, e non c'è stato verso di ritrovarla.",
	},
	["dar.muse.w23.wisp.008"] = {
		"segue con lo sguardo una grossa falena chiara entrare svolazzando oltre il banco della banca, fare un giro lento della sala come per controllare il proprio saldo, e riuscire insoddisfatta.",
		"nota una falena posarsi sul bordo di un registro aperto, e lo scrivano scriverle attorno con cura, lettera per lettera, pur di non disturbarla.",
	},
	["dar.muse.w23.wisp.009"] = {
		"Le lampade non sono tutte dello stesso colore. Se cammini piano le vedi passare dal viola all'azzurro e viceversa, come un pensiero su cui qualcuno continua a cambiare idea.",
		"Non ci sono due lampade della città accese della stessa sfumatura. Una è quasi lilla, la successiva azzurra come l'acqua profonda, e il sentiero in mezzo prende un po' da entrambe.",
		"Quasi ogni lampada della città sta in una piccola gabbia di legno intagliato, ciascuna di forma diversa: un baccello, una foglia arricciata, un bocciolo sul punto di aprirsi. Ho smesso di cercarne due uguali.",
	},
	["dar.muse.w23.wisp.010"] = {
		"La luce sotto le grandi foglie è verde, il verde di una bottiglia tenuta controluce. Ho smesso di provare a indovinarci l'ora.",
		"Qui sotto tutto è illuminato attraverso le foglie: le facce, la pietra, l'acqua, le mie stesse mani. Dopo un po' il verde smette di essere un colore e diventa l'aria stessa.",
		"Sotto queste foglie anche la pietra bianca prende una sfumatura verde. Ho sciacquato le mani in una fontana e sembravano quelle di un altro.",
	},
	["dar.muse.w23.wisp.011"] = {
		"guarda una chiazza di luce pallida scivolare sul muschio mentre lassù le foglie si spostano, e resta a vedere dove andrà a posarsi.",
		"segue con lo sguardo una macchia di chiarore che vaga sul prato, mentre i rami in alto si muovono e la lasciano passare da una pietra all'altra.",
	},
	["dar.muse.w23.wisp.012"] = {
		"In questa città brillano persino gli insetti. Io, al confronto, sono una candela spenta.",
		"Brillano i coleotteri, brillano le falene, brilla l'acqua. L'unica cosa arrivata qui senza luce propria sono io.",
	},
	["dar.muse.w23.wisp.013"] = {
		"I druidi dicono che a Hyjal i fuochi fatui si levarono a migliaia contro la Legione. Guardandone uno che passa piccolo e lento accanto a un'aiuola, faccio fatica a immaginarlo, e ancora più fatica a dimenticarlo.",
		"Ho sentito dire che a Hyjal i fuochi fatui uscirono dalla foresta come una marea di lampade. Questo qui si sta dando da fare intorno a una siepe. Anche i soldati, immagino, coltivano un orto.",
	},
	["dar.muse.w23.wisp.014"] = {
		"Tra due lampade un ragno ha teso la sua tela, e il chiarore ne accende ogni filo. È il lavoro più fine di tutta la terrazza, e l'artefice è grande quanto la mia unghia.",
		"Una ragnatela tesa davanti al chiarore di una lampada, ogni filo acceso d'azzurro da dietro. Ogni artigiano della città invidierebbe quelle cuciture, se solo si fermasse a guardare.",
	},
	["dar.muse.w23.wisp.015"] = {
		"I fuochi fatui non mi fanno paura. Alcuni di loro, dicono le sacerdotesse, erano persone che hanno percorso questi sentieri prima di me. Passando faccio loro un cenno, come a chiunque altro.",
		"Quando un fuoco fatuo si avvicina resto immobile e lo lascio guardare. Se le sacerdotesse hanno ragione, potrebbe essere uno dei nostri, venuto a vedere che ne abbiamo fatto dell'albero.",
	},
	["dar.muse.w23.wisp.016"] = {
		"allunga la mano verso un puntino di luce che fluttua, senza pensarci, e quello scivola tra le dita come un seme portato dall'aria.",
		"alza una mano verso un piccolo bagliore sospeso all'altezza della spalla; il bagliore valuta la mano, poi sale appena fuori portata e resta lì.",
		"tenta una presa lenta su un luccichio di passaggio, lo manca di un palmo, e fa finta di aver voluto sistemarsi una cinghia fin dall'inizio.",
	},
	["dar.muse.w23.wisp.017"] = {
		"Qui niente proietta un'ombra netta. La luce arriva dalle lampade, dall'acqua, dalle foglie stesse, così morbida che la mia ombra non sembra sapere dove cadere.",
		"La mia ombra, a Darnassus, è una cosa tenue e indecisa, tirata in tre direzioni da tre luci morbide. Continuo ad abbassare gli occhi per controllare che mi segua ancora.",
	},
	["dar.muse.w23.wisp.018"] = {
		"Da quando ho preso posto qui, una falena non ha fatto che cercare di entrare in una lampada. Ammiro la tenacia. La ammirerei di più se avesse un piano.",
		"C'è una falena che gira e rigira attorno alla stessa lampada, senza posarsi e senza andarsene. Conosco la tecnica. È così che cerco la banca.",
	},
	["dar.muse.w23.wisp.019"] = {
		"Piccola luce, se sei l'antenato di qualcuno, scusa se per poco non ti passavo attraverso.",
		"Perdono. Non ti avevo visto. Be', ti avevo visto. Brilli.",
	},
	["dar.muse.w23.wisp.020"] = {
		"Qui è tutto verde. Le mie mani sono verdi. Sono verdi, le mie mani? Non rispondere.",
		"Con questa luce sembrano tutti reduci da un pasto sospetto. Anch'io, si capisce.",
	},
	["dar.npc_meet.w23.asker.001"] = {
		"La richiesta comincia con una storia. Poi un po' di contesto. Poi una pausa per assicurarsi che io abbia seguito. Sospetto che il compito vero sarà la parte più breve.",
		"Prima di dirmi cosa serve, mi spiega perché, e prima del perché, un po' di come le cose sono arrivate a questo punto. Mi preparo ad ascoltare.",
		"Una richiesta kaldorei ha una forma: una lunga radice, un tronco lento, e in cima, piccola piccola, la cosa che vogliono davvero.",
	},
	["dar.npc_meet.w23.asker.002"] = {
		"vede {other} studiarne a lungo il viso prima di dire una sola parola della richiesta, come se il chiedere dipendesse da una domanda mai detta.",
		"aspetta mentre chi ha di fronte decide, apertamente e senza fretta, se chiedere o no.",
	},
	["dar.npc_meet.w23.asker.003"] = {
		"Hai l'aria di chi aspetta di chiedere qualcosa a qualcuno. Posso andare bene io?",
		"Ti ascolto. Prenditi tutto il tempo che ti serve; mi pare che sia parecchio.",
		"{other}? Hai l'aria di chi ha un favore da chiedere. Dimmi pure.",
	},
	["dar.npc_meet.w23.asker.004"] = {
		"Chiedere aiuto, qui, costa qualcosa. Si vede dalla cortesia un po' rigida, dagli occhi che si posano sulla mia spalla invece che sul viso.",
		"C'è orgoglio nel modo in cui la richiesta viene posta, con cura, come se dispiacesse un poco aver bisogno di qualcuno. Conosco la sensazione.",
	},
	["dar.npc_meet.w23.asker.005"] = {
		"ascolta la richiesta con le mani intrecciate, come le tiene chi sta chiedendo, e le lascia ricadere solo all'ultima parola.",
		"imita senza volerlo l'immobilità di chi sta chiedendo, e scopre che così ascoltare è più facile.",
	},
	["dar.npc_meet.w23.asker.006"] = {
		"Tre cortesie, un'osservazione sull'albero e un lungo sguardo. Ancora non so cosa vogliono, ma so già che dirò di sì.",
		"Il solo preambolo basterebbe a riempire un pasto. Ho fame, ma sono anche {g:curioso|curiosa}, che è peggio.",
		"In questo discorso accurato, nascosta, c'è una richiesta. La troverò se continuo ad ascoltare, come una moneta in fondo a una vasca profonda.",
	},
	["dar.npc_meet.w23.asker.007"] = {
		"si sente chiamare più vicino e poi, stranamente, invitare a sedersi prima di ogni altra parola, come se la richiesta fosse troppo pesante da ascoltare in piedi.",
		"accetta l'invito a sedersi, una coppa d'acqua, un momento di silenzio, e solo allora le prime parole di ciò che serve.",
	},
	["dar.npc_meet.w23.asker.008"] = {
		"Non so bene perché i kaldorei chiedano aiuto a chi viene da fuori con tanta facilità. Forse ne hanno troppo pochi da risparmiare, con Ashenvale che se ne prende così tanti.",
		"Un elfo che chiede aiuto a qualcuno come me. Dice molto di quanto siano tirate le loro forze, e sanno che me ne sono {g:accorto|accorta}.",
	},
	["dar.npc_meet.w23.asker.009"] = {
		"Prima che cominci: sarà una storia lunga? Lo chiedo solo per trovare qualcosa a cui appoggiarmi.",
		"Non dirmelo ancora. Indovino: conta molto, è delicata, e nessun altro ha tempo.",
	},
	["dar.npc_meet.w23.asker.010"] = {
		"Chi chiede parla con voce piana, ma nel preambolo c'è un nome, detto una volta sola e mai più ripetuto. Credo sia quello il vero motivo della richiesta.",
		"Sotto la cortesia c'è qualcosa che ha la forma di un lutto. Non chiedo. Se è giusto che lo sappia, verrà fuori raccontando.",
	},
	["dar.npc_meet.w23.asker.011"] = {
		"coglie il momento in cui {other} decide di fidarsi: le spalle che si allentano appena, la voce che si abbassa un poco.",
		"nota che chi chiede lancia un'occhiata verso il Temple of the Moon prima di cominciare, come per averne licenza.",
		"vede la richiesta cominciare con un lungo sguardo alle sue mani, come se fossero quelle le vere referenze da controllare.",
	},
	["dar.npc_meet.w23.asker.012"] = {
		"Qualunque cosa sia, chiedi senza giri di parole. Risponderò allo stesso modo.",
		"Non serve tutta questa cautela con me. Ti ascolterò comunque.",
	},
	["dar.npc_meet.w23.asker.013"] = {
		"Certe richieste, in questa città, aspettano da anni chi le ascolti. Questa ha addosso la polvere della pazienza.",
		"Il modo di chiedere è accurato, come se la faccenda fosse stata rigirata per una lunga stagione prima di affidarla a qualcuno.",
	},
	["dar.npc_meet.w23.hearth.001"] = {
		"Lo sguardo di chi tiene la locanda mi percorre una volta, dagli stivali alle spalle, e giurerei che la durata del mio sonno sia appena stata decisa per me.",
		"Un'occhiata senza fretta, e chi gestisce la locanda ha già capito se mi serve cibo, un letto o solo un posto dove smettere di muovermi. Sospetto tutte e tre le cose.",
	},
	["dar.npc_meet.w23.hearth.002"] = {
		"si vede porgere una ciotola bassa d'acqua per sciacquarsi le mani prima che si dica una sola parola su stanze o prezzi.",
		"riceve, prima di ogni altra cosa, una piccola bacinella d'acqua fresca e un panno, e capisce che si comincerà a parlare quando avrà le mani pulite.",
	},
	["dar.npc_meet.w23.hearth.003"] = {
		"{other}, giusto? Una stanza, per favore, la più silenziosa. Cioè, immagino, una qualsiasi.",
		"Va bene qualunque letto. Dormirò prima di aver finito di ammirarlo.",
		"Hai una stanza che scricchiola? Ho smesso di fidarmi dei posti dove non scricchiola niente.",
	},
	["dar.npc_meet.w23.hearth.004"] = {
		"Nessuna domanda su dove sono {g:stato|stata} o dove vado. Una sola: se ho il sonno leggero o pesante. Non conoscevo la risposta finché non me l'hanno chiesto.",
		"Neanche una parola sui miei affari. Chi tiene la locanda vuole sapere solo quanto è leggero il mio sonno, ed è la domanda più premurosa che mi facciano da un bel pezzo.",
	},
	["dar.npc_meet.w23.hearth.005"] = {
		"posa lo zaino accanto al banco e un gesto garbato {g:gli|le} chiede di spostarlo di un palmo a sinistra, fuori dai piedi di chi arriverà dopo.",
		"lascia le sue cose in un mucchio e le vede risistemare in silenzio, senza un commento, in una pila più composta.",
	},
	["dar.npc_meet.w23.hearth.006"] = {
		"Quanti viaggiatori avrà messo a letto chi tiene questa locanda? I kaldorei contano queste cose a secoli. Io sono una voce minuscola in un libro lunghissimo.",
		"Nella memoria di chi gestisce questa locanda forse ci sono ospiti di prima che Stormwind avesse le mura. Cercherò di non passare alla storia per il russare.",
	},
	["dar.npc_meet.w23.hearth.007"] = {
		"Un letto, se ne hai uno, e niente per cui svegliarmi.",
		"Solo un posto dove sedermi per un po', e nessuna notizia. Si può fare?",
	},
	["dar.npc_meet.w23.hearth.008"] = {
		"Mi ha dato un'occhiata e ha posato davanti a me un piatto di frutta e pane basso senza che chiedessi nulla. Devo avere l'aria più affamata di quanto credessi.",
		"Pane prima ancora che chiedessi qualcosa. O ho la fame scritta in faccia, o chi tiene una locanda kaldorei la sente a naso.",
	},
	["dar.npc_meet.w23.hearth.009"] = {
		"vede {other} posare due dita leggere sul banco, un gesto quieto che sembra voler dire: il riposo è qui, basta chiederlo.",
		"osserva chi tiene la locanda battere piano due volte sul banco e lanciare un'occhiata verso le stanze: a quanto pare è tutto il benvenuto, ed è più che abbastanza.",
	},
	["dar.npc_meet.w23.hearth.010"] = {
		"Ho cominciato a contrattare sulla stanza per abitudine e ho ricevuto uno sguardo così perplesso e gentile che ho pagato il prezzo chiesto, scusandomi pure.",
		"A Darnassus, pare, nessuno contratta con chi tiene la locanda. Io ci ho provato, e mi hanno fatto capire con garbo che era come chiedere il prezzo dell'albero.",
	},
	["dar.npc_meet.w23.hearth.011"] = {
		"accenna di sfuggita ai piedi doloranti e si vede rispondere con un vasetto di qualcosa di verde e una sola parola di istruzioni.",
		"si lascia sfuggire una lamentela sui sentieri lunghi e riceve in cambio uno sguardo comprensivo e un cuscino per la seduta.",
	},
	["dar.npc_meet.w23.hearth.012"] = {
		"Una stanza qualsiasi. In qualunque letto della nostra città si dorme meglio che sulla strada.",
		"La stanza più vicina all'acqua, se è libera. Certe abitudini di casa le conservo.",
	},
	["dar.npc_meet.w23.hearth.013"] = {
		"Ovunque chi tiene una locanda si abitua agli addii. Chi può restare a questo posto per secoli dev'essersene fatto un mestiere, leggero, pratico e mai del tutto distratto.",
		"Ogni ospite se ne va. Chi potrebbe sopravvivere a tutti ha dovuto farci pace, e quella pace si vede dalla delicatezza con cui ti affida una stanza.",
	},
	["dar.npc_meet.w23.hearth.014"] = {
		"conta le monete sul banco per una stanza e se ne vede restituire una, spinta con garbo: troppo, esattamente di quella.",
		"paga la stanza un rame in più e guarda il rame rifare il viaggio sul banco, spinto da un solo dito paziente.",
	},
	["dar.npc_meet.w23.hearth.015"] = {
		"C'è qualche regola sugli stivali nelle stanze? Non vorrei offendere il pavimento.",
		"Farò silenzio, promesso. Più silenzio di quanto ne abbia mai fatto altrove, il che non è dire molto.",
		"Svegliami se l'albero cade. Altrimenti, no.",
	},
	["dar.npc_meet.w23.hearth.016"] = {
		"Chi tiene la locanda canticchia mentre pulisce il banco, un motivo troppo lento da seguire e troppo antico per avere un nome. Mi sporgo per coglierlo.",
		"Dietro il banco c'è un mormorio cantato, basso e senza fretta. Qualunque motivo sia, era già vecchio prima che nascesse chiunque io conosca.",
	},
	["dar.npc_meet.w23.hearth.017"] = {
		"si sente squadrare da chi tiene la locanda con occhio esperto, l'occhio di chi distingue una strada lunga da una corta dal modo in cui un viaggiatore si siede.",
		"si siede, e basta un'occhiata: chi tiene la locanda guarda la piega delle sue spalle e serve acqua, non vino.",
	},
	["dar.npc_meet.w23.tutor.001"] = {
		"Prima di insegnarmi qualcosa, mi ha chiesto di mostrare quello che già so, poi mi ha guardato in silenzio abbastanza a lungo da farmi dubitare di tutto.",
		"Mostrami, ha detto, e nient'altro. Ho mostrato. Il silenzio dopo mi ha insegnato più della lezione.",
		"La vera prova non è la lezione: è come la aspetto. Mi agito. Chi mi addestra se ne accorge e non dice nulla, il che è peggio.",
	},
	["dar.npc_meet.w23.tutor.002"] = {
		"si vede girare il polso di un niente dalla punta delle dita di chi insegna, una correzione così piccola che non può contare nulla, e invece conta.",
		"sente un colpetto leggero al gomito, poi un altro alla spalla, e solo dopo capisce che tutta la sua postura è stata riscritta.",
		"riceve una correzione senza parole: una mano alzata, un palmo inclinato, e chi insegna che aspetta di vederglielo capire.",
	},
	["dar.npc_meet.w23.tutor.003"] = {
		"Quanto ci vuole di solito per impararlo? No, aspetta. Non dirmelo in anni kaldorei.",
		"Imparo in fretta. Per i tuoi criteri, sono una macchia che passa.",
		"Quello è un cenno di approvazione, o hai solo pazienza con me?",
	},
	["dar.npc_meet.w23.tutor.004"] = {
		"Chi mi insegna nomina di sfuggita il proprio maestro, con un tono che fa capire che se n'è andato da moltissimo tempo e che gli si obbedisce ancora.",
		"Dietro ogni lezione, qui, c'è una lezione più antica, e un maestro più antico. Li sento nelle pause.",
	},
	["dar.npc_meet.w23.tutor.005"] = {
		"saluta {other} con un inchino prima della lezione, e ne riceve uno della stessa identica profondità: sembra la prima cosa insegnata.",
		"china il capo verso chi l'addestra e riceve in cambio un cenno preciso, né più profondo né più lieve: già una lezione.",
	},
	["dar.npc_meet.w23.tutor.006"] = {
		"Ho ricevuto una sola parola di lode. In questa città, da chi mi addestra, sospetto valga un corteo in festa.",
		"Bene, ha detto. Solo questo. Ci vivrò sopra per una settimana.",
		"Qui la lode arriva in monete piccolissime. Me ne hanno appena data una, e la tengo con cura.",
	},
	["dar.npc_meet.w23.tutor.007"] = {
		"ripete lo stesso piccolo gesto per cinque volte davanti a chi insegna, poi una sesta, e alla sesta vede un cenno appena.",
		"deve rifarlo un'altra volta, e un'altra, e solo alla fine capisce che non si contavano i tentativi, ma le differenze tra l'uno e l'altro.",
	},
	["dar.npc_meet.w23.tutor.008"] = {
		"Chi mi addestra mi insegna come un kaldorei insegna a un kaldorei: niente pazienza in più, niente riguardi. È bello che ci si aspetti che io stia al passo.",
		"Nessuna indulgenza per me, nessuna lentezza di facciata. Tra noi, una lezione è una lezione.",
	},
	["dar.npc_meet.w23.tutor.009"] = {
		"Insegnami quello che insegneresti a chiunque. Preferisco essere {g:corretto|corretta} che {g:risparmiato|risparmiata}.",
		"Ti ascolto. E guardo. E cerco di non agitarmi, che è la parte difficile.",
	},
	["dar.npc_meet.w23.tutor.010"] = {
		"Mi ha detto di esercitarmi e di farmi rivedere quando mi sembrerà facile. Non quando ne sarò {g:stanco|stanca}. Non quando crederò di averlo capito. Quando mi sembrerà facile.",
		"Esercitati finché non ti annoia, mi ha detto, e poi ancora un po', perché è lì che comincia a essere tuo.",
		"Il consiglio è sempre lo stesso, dato con gentilezza: più piano. Non meglio, non più forte. Più piano. Comincio a pensare che sia tutto il segreto.",
	},
	["dar.npc_meet.w23.tutor.011"] = {
		"prova ad affrettare la lezione con una domanda impaziente e riceve in risposta, con gentilezza, un silenzio più lungo di prima.",
		"chiede se è tutto, e vede un sopracciglio alzarsi di un pelo, che a quanto pare significa: tutt'altro.",
		"annuisce come chi ha capito, e si sente chiedere, con molta dolcezza, di spiegarlo con parole sue.",
	},
	["dar.npc_meet.w23.tutor.012"] = {
		"Strano: chi mi addestra guarda appena le mie mani. È il mio viso che osserva, come se gli errori cominciassero lì e le mani si limitassero a finirli.",
		"Quasi tutti i maestri guardano quello che fai. Qui si guarda dove guardo io. Due volte mi hanno corretto prima ancora che mi muovessi.",
	},
	["dar.npc_meet.w23.tutor.013"] = {
		"Grazie. Mi eserciterò come mi hai mostrato, non come preferirei io.",
		"Mi ricorderò di quella correzione. Probabilmente nel momento peggiore, ma me ne ricorderò.",
	},
	["dar.npc_meet.w23.tutor.014"] = {
		"aspetta che chi insegna finisca con un allievo kaldorei, che se ne va con la stessa aria vagamente stordita che di lì a poco, con ogni probabilità, avrà anche il suo viso.",
		"si fa da parte mentre un altro allievo viene congedato con un cenno, e riconosce quell'espressione: è di chi ha appena scoperto quanto gli resta da imparare.",
	},
	["dar.npc_meet.w23.tutor.015"] = {
		"Non mi è stato chiesto dove mi sia {g:allenato|allenata} prima, né con chi. Mi hanno solo guardato muovermi, e pare ci abbiano letto tutto l'elenco.",
		"Chi mi ha insegnato prima, a quanto pare, è scritto in come sto in piedi. Qui l'hanno letto in un'occhiata e hanno cominciato subito a disfarlo.",
	},
	["dar.npc_meet.w23.vault.001"] = {
		"Chi tiene i conti cerca il mio nome con la gravità di chi consulta una carta molto antica, e a quanto pare mi trova su un affluente secondario.",
		"Il mio conto è qualche riga in un libro enorme. Chi sta al banco ci arriva con il rispetto che si deve a un capitolo.",
		"Sono {g:sicuro|sicura} che il mio conto sia la cosa meno interessante di tutto il caveau. Nessuno dietro il banco me lo farebbe mai capire.",
	},
	["dar.npc_meet.w23.vault.002"] = {
		"consegna un fagotto da custodire e lo vede avvolgere, etichettare con una grafia sottile e portare via come se contenesse qualcosa di prezioso.",
		"deposita qualche cianfrusaglia e vede ogni pezzo annotato a parte, fino a un bottone scheggiato.",
		"chiede un oggetto dal deposito e aspetta che venga recuperato, svolto e presentato con una vaga aria di cerimonia.",
	},
	["dar.npc_meet.w23.vault.003"] = {
		"Piano con quella borsa. È quasi tutto valore affettivo e pelucchi.",
		"{other}, lascio più roba del solito. Non fare quella faccia contenta: sono quasi tutte carabattole.",
		"Mettilo da qualche parte al sicuro, per favore. Dove possa dimenticarmelo per bene.",
	},
	["dar.npc_meet.w23.vault.004"] = {
		"C'è uno strano conforto nel consegnare le mie cose a chi molto probabilmente sarà ancora a questo banco quando io non ci sarò più. Le mie poche cose potrebbero sopravvivermi in buona compagnia.",
		"Quello che lascio qui sarà custodito da chi ha secoli a disposizione. È la cosa più vicina alla permanenza che possieda.",
	},
	["dar.npc_meet.w23.vault.005"] = {
		"vede chi sta al banco togliere un granello di sporco da una moneta prima di annotarla nel registro, e d'un tratto le proprie monete {g:gli|le} sembrano piuttosto sudice.",
		"osserva un rame annerito girato due volte, esaminato e accettato con un'espressione di grande generosità.",
	},
	["dar.npc_meet.w23.vault.006"] = {
		"Chi tiene i conti si ricordava, senza che chiedessi, cosa avevo lasciato l'ultima volta, perfino l'ordine in cui l'avevo consegnato. Non so se mi piace essere così leggibile.",
		"Prima che dicessi una parola, il cassetto giusto era già aperto. O in questa banca sono bravissimi, o io sono molto prevedibile.",
	},
	["dar.npc_meet.w23.vault.007"] = {
		"Metti dentro tutto, per favore, tranne le monete. Io e le monete non abbiamo ancora finito.",
		"Solo una borsa, grazie. Le altre possono farsi compagnia.",
	},
	["dar.npc_meet.w23.vault.008"] = {
		"Chissà cosa lasciano in questa banca i kaldorei stessi. Non monete, immagino. Cose salvate da città che ora stanno sotto le onde, forse.",
		"Le mie cose stanno qui dentro, accanto a oggetti molto più antichi e cari di quanto possa immaginare. I cimeli di un popolo che ha perso quasi tutti i suoi.",
	},
	["dar.npc_meet.w23.vault.009"] = {
		"firma il registro dove un dito lungo indica, e nota che il proprio nome sembra goffo accanto alle colonne fluide più in alto.",
		"aggiunge il proprio segno al libro della banca e lascia una piccola macchia d'inchiostro, che chi sta al banco osserva un istante e poi, con grazia, ignora.",
	},
	["dar.npc_meet.w23.vault.010"] = {
		"Non mi hanno mai ringraziato con tanta sincerità per aver depositato una manciata d'argento. Potrei cominciare a farlo solo per la cortesia.",
		"I miei piccoli risparmi vengono trattati con la stessa identica cura delle fortune altrui. È molto gentile o molto discreto, e non so se ci sia differenza.",
		"In altre città la banca mi ricorda quanto poco possiedo. Questa mi tratta con fiducia, che per la borsa è anche peggio.",
	},
	["dar.npc_meet.w23.vault.011"] = {
		"aspetta al banco dietro un nano che deposita una quantità allarmante di minerale, e ammira la totale assenza di stupore di chi lo serve.",
		"fa la fila dietro uno gnomo il cui deposito richiede un bel po' per essere elencato, e nota che la penna dall'altra parte del banco non accelera mai.",
	},
	["dar.npc_meet.w23.wares.001"] = {
		"Qualunque cosa compri viene avvolta in una foglia larga e legata con un filo d'erba. Sembra tutto il regalo di qualcuno molto paziente.",
		"L'incarto dura più della vendita. Foglia, piega, nodo, una lisciata leggera col palmo. Non ho mai visto tanta cerimonia per qualche moneta di rame.",
		"Ho provato a dire che non serviva incartarlo. Lo sguardo che ho ricevuto mi ha fatto capire che non era proprio una scelta.",
	},
	["dar.npc_meet.w23.wares.002"] = {
		"propone un prezzo un po' troppo in fretta e vede chi sta al banco valutarlo, poi valutare chi l'ha detto, e rifiutare entrambi con un sorriso.",
		"avanza una controfferta e riceve un lungo sguardo incuriosito, come se dall'altra parte del banco ci si chiedesse da dove venga un'usanza simile.",
	},
	["dar.npc_meet.w23.wares.003"] = {
		"Quanto? No, è giusto. Mi piace solo chiederlo.",
		"Non dirmi ancora il prezzo. Lasciamelo ammirare un attimo: mi pare che qui si faccia così.",
		"{other}, lo prendo. Prima di pensarci quanto ci penseresti tu.",
	},
	["dar.npc_meet.w23.wares.004"] = {
		"Chi vende sa dire chi ha fatto ogni pezzo esposto, e l'anno in cui l'ha fatto. Per alcuni quell'anno è molto, molto lontano.",
		"Ogni cosa in vendita arriva con una breve storia: chi l'ha fatta, a cosa serviva, chi l'ha avuta per ultimo. Io volevo solo una cinghia.",
		"Ho chiesto di un oggetto e ho saputo del suo artigiano, del maestro dell'artigiano e del boschetto da cui veniva il legno. L'ho comprato per rispetto.",
	},
	["dar.npc_meet.w23.wares.005"] = {
		"paga e osserva le monete divise in tre ciotoline di legno secondo il metallo, ognuna posata senza un suono.",
		"consegna le monete e le vede finire non in una borsa ma in un piatto intagliato, allineate fianco a fianco come semi in un solco.",
	},
	["dar.npc_meet.w23.wares.006"] = {
		"In due conversazioni intere chi sta al banco non ha mai definito niente un affare. È inquietante. Come faccio a sapere di cosa diffidare?",
		"Nessun mercante di questa città mi ha detto che sto facendo un affare. Continuo ad aspettarlo, come si aspetta che cada l'altro stivale.",
	},
	["dar.npc_meet.w23.wares.007"] = {
		"Fammi vedere quello che dura di più. Le cose, con me, soffrono.",
		"Cos'hai per chi consuma gli stivali più in fretta di quanto un elfo consumi gli anni?",
	},
	["dar.npc_meet.w23.wares.008"] = {
		"Tra la merce, mezzo nascosta, una coppa d'argento antico lavorata con motivi che ho visto solo sulle pietre spezzate di Darkshore. Non è in vendita, mi dicono con dolcezza, e la ricoprono.",
		"In fondo al telo c'è una cosa che non viene mai offerta: una ciotola piccola e consunta, di uno stile più antico. Non ho chiesto. La cura con cui l'hanno spostata diceva abbastanza.",
	},
	["dar.npc_meet.w23.wares.009"] = {
		"allunga la mano verso un ninnolo nello stesso istante di un cliente kaldorei, ed entrambi la ritirano con tanta cortesia che alla fine chi vende non lo porge a nessuno dei due.",
		"esita così a lungo tra due borse quasi identiche che chi sta al banco, con grande gentilezza, ne mette via una.",
		"chiede a cosa serva un oggetto, riceve una risposta lenta e accurata, e continua a non averne idea, ma annuisce lo stesso.",
	},
	["dar.npc_meet.w23.wares.010"] = {
		"I prezzi sono onesti, fissi, e scritti con una grafia più bella di qualunque io avrò mai. Contrattare sarebbe come scarabocchiarci sopra.",
		"Qui ogni cosa ha il suo prezzo segnato, in una scrittura piccola e accurata, e niente nell'aria di chi vende fa pensare che sia un punto di partenza.",
	},
	["dar.npc_meet.w23.wares.011"] = {
		"È fatto con l'albero? Dovrei chiedergli scusa?",
		"Lo compro. Ti prego, non incartarlo in niente di più bello di me.",
		"Li hai sistemati così bene che mi dispiace prenderne uno.",
	},
	["dar.npc_meet.w23.wares.012"] = {
		"guarda una piccola bilancia d'ottone assestarsi, e assestarsi ancora, mentre chi vende aspetta che sia del tutto immobile prima di dire la cifra.",
		"resta ad aspettare mentre si pesa una manciata di qualcosa, si aggiunge un granello, lo si toglie, e lo si rimette.",
		"attende che la bilancia venga letta due volte, una per lato, e che il prezzo sia pronunciato come una sentenza che non dispiace a nessuno.",
	},
	["dar.npc_meet.w23.wares.013"] = {
		"Chi sta al banco è cortese in tutto, e con me appena più lento che con l'elfo di prima, come per assicurarsi che ogni parola arrivi. Non so se commuovermi o offendermi.",
		"Stessa merce, stesso prezzo del kaldorei davanti a me, solo spiegata con il doppio della cura. La prenderò per gentilezza.",
	},
	["dar.npc_meet.w23.wares.014"] = {
		"Questa bancarella non avrà più di qualche anno; tutta la città è appena più vecchia. Ma chi ci sta dietro vende come chi ha avuto un banco in una dozzina di città che non esistono più.",
		"Città nuova, mestiere antico. Le parole di chi vende sono gentili e levigate, consumate da molti più anni di quanti ne abbia avuti Teldrassil.",
	},
	["dar.npc_meet.w23.wares.015"] = {
		"conclude l'acquisto e se lo vede porgere con entrambe le mani, come se l'oggetto venisse affidato più che venduto.",
		"prende la merce tesa oltre il banco su due palmi aperti, e quasi s'inchina senza volerlo.",
	},
	["dar.npc_meet.w23.wares.016"] = {
		"Mi serve qualcosa di robusto, non di bello. Anche se vedo che qui è difficile trovarlo.",
		"Solo quello semplice, per favore. Non so se sono all'altezza di quello intagliato.",
	},
	["dar.npc_meet.w23.wares.017"] = {
		"Per riflesso ho contato il resto. Giusto fino all'ultimo rame, naturalmente, e chi stava al banco mi ha guardato con la vaga pietà dovuta a chi viene da città più rumorose.",
		"Ho contato le monete due volte. Erano giuste tutte e due le volte, e un po' mi è dispiaciuto, con una punta di nostalgia per i mercati dove non lo sarebbero state.",
	},
	["dar.npc_meet.w23.watch.001"] = {
		"La sua armatura è stata rammendata in tre punti, ognuno da una mano diversa. In quelle cuciture leggo qualche campagna, senza che nessuno me ne racconti una parola.",
		"Cuoio rattoppato sulla spalla, una piastra più nuova sul fianco, un'ammaccatura vecchia che nessuno ha voluto raddrizzare. Questa Sentinella ne ha viste parecchie.",
		"I rammendi sull'armatura sono ordinati e recenti. Qualunque cosa l'abbia strappata, lei ha deciso che non vale la pena parlarne.",
	},
	["dar.npc_meet.w23.watch.002"] = {
		"chiede la strada a una Sentinella e la ottiene in sei parole e un dito alzato, che si rivelano proprio sufficienti.",
		"domanda indicazioni e una Sentinella gliele dà senza sprecare una sillaba: un'occhiata al sentiero, un giro di polso, fatto.",
	},
	["dar.npc_meet.w23.watch.003"] = {
		"Lo sguardo è andato prima alle mie mani, poi alla cintura, poi alla faccia. Un'ispezione completa nel tempo di un saluto, e pare che l'abbia superata.",
		"Mani, cintura, viso: è l'ordine in cui ti guarda una Sentinella. L'ho notato solo perché ho cominciato a guardarla anch'io così.",
	},
	["dar.npc_meet.w23.watch.004"] = {
		"Tengo le mani in vista, Sentinella. Per abitudine, non per colpa.",
		"Non serve tenermi d'occhio così. La cosa più pericolosa che farò qui è lasciar cadere una moneta nel lago.",
		"Tranquilla, Sentinella. Qualunque cosa tu stia aspettando, non sono io.",
	},
	["dar.npc_meet.w23.watch.005"] = {
		"rivolge un saluto cortese a una Sentinella e se lo sente restituire parola per parola, pesato e reso al giusto valore.",
		"saluta una Sentinella e riceve indietro le stesse identiche parole, nello stesso ordine, come se qui la cortesia fosse una moneta da non lesinare.",
	},
	["dar.npc_meet.w23.watch.006"] = {
		"Dietro la sua compostezza c'è una stanchezza che lei non lascia arrivare alle spalle. Non chiedo. Dubito che mi direbbe accanto a chi ha combattuto l'ultima volta.",
		"Il viso non lascia trapelare nulla, ma gli occhi sono più vecchi del viso, e stanchi in un modo che il portamento si rifiuta di mostrare.",
	},
	["dar.npc_meet.w23.watch.007"] = {
		"si accorge che il glaive della Sentinella sta un pollice più a sinistra di prima, e per nulla al mondo saprebbe dire quando lei l'abbia spostato.",
		"distoglie gli occhi da una Sentinella per un attimo e, guardandola di nuovo, trova il glaive appoggiato con un'inclinazione appena diversa, senza aver visto alcun movimento.",
	},
	["dar.npc_meet.w23.watch.008"] = {
		"Non ho mai visto una Sentinella fare il saluto. Abbassa il mento, una volta, e lo rialza. Mi sono {g:sorpreso|sorpresa} a fare lo stesso, e non saprei dire da quando.",
		"Un cenno del mento, niente di più. È così che una Sentinella ti riconosce, e senza volerlo ho preso anch'io l'abitudine.",
		"Mentre passavo ha abbassato il mento appena appena. Io ho abbassato il mio. Nessuna delle due parti ne ha parlato, e pare che si usi così.",
	},
	["dar.npc_meet.w23.watch.009"] = {
		"Posso chiederti il nome, Sentinella? No? Allora il posto di guardia. Va bene lo stesso.",
		"Ti ho chiesto il nome e mi hai detto il tuo posto di guardia. D'accordo. Mi ricorderò di quello.",
	},
	["dar.npc_meet.w23.watch.010"] = {
		"si toglie dal cammino di una Sentinella prima che lei lo chieda, poi si domanda che cosa, nel suo portamento, abbia dato l'ordine.",
		"si sposta per lasciar passare una Sentinella senza che nessuno glielo dica, e solo dopo si accorge che non è stata detta una parola.",
		"cede il passo a una Sentinella per puro istinto, come l'acqua si scosta davanti a un sasso.",
	},
	["dar.npc_meet.w23.watch.011"] = {
		"Saluta i kaldorei che passano con una parola nella loro lingua, e me con un cenno. Giusto così: il cenno è la parte che capisco.",
		"Due elfi ricevono una frase sommessa in darnassiano; io un cenno del capo. Non me la prendo. Avrei solo storpiato la risposta.",
	},
	["dar.npc_meet.w23.watch.012"] = {
		"La Sentinella risponde al mio saluto nella nostra lingua, in breve, come si parla a un vicino. Sotto questi rami basta questo per sentirsi riconosciuti.",
		"Ishnu-alah, dice lei, e io lo ripeto. Uno scambio minimo, e la guardia della nostra città mi sembra meno un muro.",
	},
	["dar.npc_meet.w23.watch.013"] = {
		"Il suo sguardo mi passa sopra e va oltre. Tengo il passo identico a prima e non lascio che le spalle tradiscano nulla.",
		"Lo sguardo di una Sentinella, calmo e completo. Il mio resta sul sentiero. In questa città il travestimento migliore è non avere niente da dire.",
	},
	["dar.npc_meet.w23.watch.014"] = {
		"Quell'armatura ha fatto parecchia strada dura, Sentinella. Ashenvale, immagino. Mi fa piacere che tu sia quassù per un po'.",
		"Ashenvale ha lasciato i suoi segni su quell'armatura, credo. Riposa gli occhi quando puoi, Sentinella.",
	},
	["dar.npc_meet.w23.watch.015"] = {
		"si raddrizza senza volerlo sotto lo sguardo di una Sentinella, spalle indietro e mento dritto, come chi viene colto a ciondolare.",
		"allunga un poco la schiena quando arriva lo sguardo della Sentinella, e la lascia ricadere, con un certo imbarazzo, appena quello passa oltre.",
	},
	["dar.npc_meet.w23.watch.016"] = {
		"Quando mi guarda ho la strana sensazione di essere {g:misurato|misurata} con tutti quelli che ha mai lasciato passare. Una lunga fila, e io sto verso la coda.",
		"Questa Sentinella forse monta la guardia da prima che venisse fondata la città più antica che conosco. Cerco di sembrare qualcosa che valga un attimo di tutto quel tempo.",
		"Difficile indovinare quanti anni abbia. Più facile indovinare quanti viaggiatori siano passati davanti al suo posto: tutti, più o meno, da quando l'albero è stato piantato.",
	},
	["dar.npc_meet.w23.watch.017"] = {
		"incrocia lo sguardo di un grande felino accucciato accanto al posto di una Sentinella; il felino decide per primo, e posa la testa sulle zampe.",
		"si guadagna una lunga occhiata gialla dal felino sdraiato ai piedi di una Sentinella, e un breve colpo di coda sprezzante.",
	},
	["dar.npc_meet.w23.watch.018"] = {
		"Elune-adore, Sentinella. Spero di averlo detto bene.",
		"Ho appena provato il saluto in darnassiano. Se ho sbagliato, ti prego, fa' finta di niente.",
	},
	["dar.npc_meet.w23.watch.019"] = {
		"Ho provato a farle una battuta. Ha aspettato che avessi proprio finito, poi ha annuito come se le avessi riferito qualcosa di minore, e vero.",
		"Con una Sentinella le battute non rimbalzano. Entrano, vengono valutate, e finiscono archiviate in un posto che non vedrò mai.",
		"La mia battuta migliore ha ottenuto un lento sbattere di ciglia. Credo fosse una gentilezza.",
	},
	["dar.npc_meet.w23.watch.020"] = {
		"nota una falena chiara posata sullo spallaccio di una Sentinella e non dice nulla; un attimo dopo lei la scaccia senza guardare, come se lo avesse saputo da sempre.",
		"vede una falena posarsi sulla spalla di una Sentinella; la mano di lei si alza, la allontana con garbo e ricade, mentre gli occhi non lasciano il sentiero.",
	},
	["dar.npc_meet.w23.watch.021"] = {
		"Scommetterei una moneta d'oro che la prossima volta riconoscerà la mia faccia, e quella dopo ancora, e molto dopo che io avrò dimenticato la sua.",
		"Le Sentinelle ricordano i volti, mi ha detto un nano in banca. A giudicare da come mi guarda questa, il mio l'ha già messo da parte al sicuro.",
	},
	["dar.npc_meet.w23.watch.022"] = {
		"C'è qualcosa che non hai mai visto, Sentinella? No, non dirmelo. Preferisco non sapere in che posizione sono.",
		"Chissà quante domande ti fanno i forestieri. Eccone una facile: è scortese fissare l'albero?",
	},
	["dar.quest_complete.w23.afterward.001"] = {
		"mette via la ricompensa e resta lì un attimo più del necessario, come se il posto avesse ancora qualcosa da aggiungere.",
		"nasconde il compenso nella bisaccia, poi indugia, quasi in attesa di un'ultima parola che non arriva.",
	},
	["dar.quest_complete.w23.afterward.002"] = {
		"La parte peggiore del finire è il minuto dopo, quando le mani non hanno più niente da portare e lo cercano lo stesso.",
		"Mani vuote, e le dita continuano a stringersi su una cinghia che non c'è più.",
		"Che strana, questa leggerezza. Continuo a tastarmi il fianco in cerca di qualcosa che ho consegnato.",
	},
	["dar.quest_complete.w23.afterward.003"] = {
		"si allontana a passo lento, adeguandosi senza volerlo all'andatura dei kaldorei sul sentiero.",
		"lascia l'affare alle spalle camminando senza fretta, e solo a metà strada si accorge che è la città a dettare il passo.",
	},
	["dar.quest_complete.w23.afterward.004"] = {
		"I ringraziamenti sono finiti e io sono ancora lì ad annuire. Qualcuno dovrebbe insegnarmi come si chiude un discorso con un elfo.",
		"Grazie ricevute, compenso in tasca, e sono io a non sapere come chiudere. I kaldorei smettono di parlare e basta. È un dono.",
		"Ho salutato due volte. Dall'altra parte, nemmeno una parola, e la partita l'ha vinta il silenzio.",
	},
	["dar.quest_complete.w23.afterward.005"] = {
		"si fa da parte per due sacerdotesse vestite di bianco, e quando sono passate l'incarico sembra già una cosa di prima.",
		"lascia libero il sentiero a una coppia di sacerdotesse, e quando sono sparite il lavoro concluso ha preso le sue giuste dimensioni.",
	},
	["dar.quest_complete.w23.afterward.006"] = {
		"Strano quanto sia silenziosa una cosa finita. Tanto daffare per chiuderla, e adesso non fa più rumore.",
		"Un lavoro, appena consegnato, tace di colpo. Non mi dava pace, e ora nemmeno un sussurro.",
	},
	["dar.quest_complete.w23.afterward.007"] = {
		"sistema le cinghie dello zaino, alleggerito di un incarico, e il peso si assesta in un altro modo sulle spalle.",
		"solleva un po' lo zaino: non porta meno di prima, eppure pesa meglio.",
	},
	["dar.quest_complete.w23.afterward.008"] = {
		"Mi viene sempre da voltarmi una volta verso chi mi ha dato il lavoro. Qui, quando lo faccio, guarda già altrove: una foglia, l'acqua, il nulla. Non è scortesia.",
		"Ho guardato indietro. Chi mi aveva pagato era già immobile, gli occhi sull'acqua, la faccenda riposta in un luogo che non vedrò mai.",
	},
	["dar.quest_complete.w23.afterward.009"] = {
		"rallenta alla prima curva e resta a guardare la città per un po', senza debiti con nessuno, almeno per ora.",
		"si ferma alla curva successiva, senza incarichi che tirino da qualche parte, e per un poco lascia che la città sia soltanto una città.",
		"lascia oziare i piedi a una curva del sentiero, senza nessuno che aspetti e niente di dovuto, e si gode la città come un forestiero in libera uscita.",
	},
	["dar.quest_complete.w23.afterward.010"] = {
		"approfitta della calma per sistemare una fibbia allentata che dava fastidio, ora che non c'è più motivo di rimandare.",
		"si china a riallacciare uno stivale, una piccola faccenda tenuta da parte per quando quella grossa fosse finita.",
	},
	["dar.quest_complete.w23.afterward.011"] = {
		"Il dolore che ho ignorato per tutto il lavoro ha deciso che adesso è il momento buono. Grazie, ginocchia.",
		"Le spalle hanno resistito fino ai ringraziamenti. Ora vogliono dire la loro.",
		"Il corpo aspetta con educazione la ricompensa, poi presenta tutti i reclami in una volta.",
	},
	["dar.quest_complete.w23.afterward.012"] = {
		"infila una moneta della ricompensa in una tasca diversa, vecchia abitudine di strada, poi si allontana lungo la terrazza.",
		"divide il compenso fra due borselli per prudenza, anche qui, e riprende a camminare.",
	},
	["dar.quest_complete.w23.afterward.013"] = {
		"Avrei potuto non chiedere nulla. Fra la nostra gente l'aiuto non si vende. Ma la moneta è data con garbo, e troverò chi ne ha più bisogno.",
		"Pagata da uno dei miei per aver aiutato i miei. Pesa strana, nella borsa.",
	},
	["dar.quest_complete.w23.afterward.014"] = {
		"si massaggia un polso indolenzito ora che il lavoro è consegnato: il piccolo dolore arriva in ritardo, come un ospite che ha perso il banchetto.",
		"apre e chiude le dita intorpidite a consegna fatta: la rigidità si fa sentire solo adesso.",
	},
	["dar.quest_complete.w23.afterward.015"] = {
		"C'è un momento, dopo ogni lavoro, in cui non so chi sono fino al prossimo. Quassù quel momento si allunga, e non è spiacevole.",
		"Fra un incarico e l'altro non sono nessuno in particolare. Darnassus sembra preferirmi così.",
	},
	["dar.quest_complete.w23.afterward.016"] = {
		"Non disturbatevi a farmi strada. Me ne vado per conto mio, più o meno dritto.",
		"La strada la trovo da me. Prima o poi.",
		"No, no, restate pure lì. A perdermi ci penso da solo.",
	},
	["dar.quest_complete.w23.afterward.017"] = {
		"La mia voce ha ancora la forma del grazie che ho ricambiato. Sommessa. Passerà un po' prima che io possa urlare contro un mulo.",
		"Ho preso il loro modo di parlare: basso, senza fretta. Mi passerà prima di arrivare ai piedi dell'albero.",
	},
	["dar.quest_complete.w23.afterward.018"] = {
		"Permesso, passo io. Molto lentamente, come vuole l'usanza.",
		"Scusate. Me ne vado. A passo rispettoso.",
		"Posso passare? Prometto di non avere fretta.",
	},
	["dar.quest_complete.w23.afterward.019"] = {
		"Resto qui un momento con l'aria di chi ha concluso qualcosa.",
		"Datemi un attimo. Ammiro il mio lavoro, in silenzio, all'usanza del posto.",
		"Non fateci caso. Mi sto crogiolando. Con discrezione.",
	},
	["dar.quest_complete.w23.afterward.020"] = {
		"guarda chi ha dato la ricompensa tornare a un lavoro lento e minuzioso, e capisce che la commissione è già stata cucita dentro una storia molto più lunga.",
		"vede chi ha affidato l'incarico già chino su altro, senza fretta, e la commissione prende posto fra tante altre simili.",
	},
	["dar.quest_complete.w23.afterward.021"] = {
		"se ne va nel crepuscolo col lavoro alle spalle, mentre il sentiero davanti sfuma d'azzurro ai bordi.",
		"si volta per andarsene mentre la luce cala, e il lavoro della giornata trova posto proprio nella sua fine.",
	},
	["dar.quest_complete.w23.afterward.022"] = {
		"si allontana nella nebbia, e dopo una dozzina di passi il posto alle spalle è già sfumato nel grigio, come se la faccenda fosse già storia.",
		"lascia che la foschia si richiuda alle spalle dopo i ringraziamenti, e tutta la faccenda svanisce con le voci nel bianco.",
	},
	["dar.quest_complete.w23.afterward.023"] = {
		"Questo lo tolgo dalla lista. È ancora lunga, ma una riga in meno è una riga in meno.",
		"Una voce cancellata. Restano solo tutte le altre.",
	},
	["dar.quest_complete.w23.afterward.024"] = {
		"Dunque. Cosa si fa in questa città a lavoro finito? A giudicare dagli altri, ci si siede.",
		"E adesso? Qui tutti sembrano saper fare niente benissimo. Guardo e imparo.",
	},
	["dar.quest_complete.w23.boon.001"] = {
		"La borsa aveva i lacci chiusi con un nodo che non conoscevo, ordinato come un seme. Quasi mi dispiaceva scioglierlo.",
		"Perfino il sacchetto era legato con cura, con un nodo così pulito che ho passato più tempo ad ammirarlo che a guardarci dentro.",
	},
	["dar.quest_complete.w23.boon.002"] = {
		"si vede offrire la ricompensa su un palmo aperto e piatto, e la lascia prendere a sé, senza che nulla venga spinto in mano.",
		"trova la ricompensa semplicemente tesa e lasciata lì, in attesa di essere presa quando sarà il momento.",
	},
	["dar.quest_complete.w23.boon.003"] = {
		"Mi hanno {g:pagato|pagata} con l'aria di chi salda un debito tra pari, non di chi dà la mancia a un servo. L'argento è lo stesso. Eppure si spende meglio.",
		"Un compenso dato come tra pari, non come una mancia allungata a un facchino. Non sapevo che anche un pagamento potesse avere le sue buone maniere.",
	},
	["dar.quest_complete.w23.boon.004"] = {
		"È generoso. Oppure è la cifra solita, data con generosità. Qui è difficile capirlo.",
		"Grazie. Non capisco se è tanto, o se è solo dato molto bene.",
	},
	["dar.quest_complete.w23.boon.005"] = {
		"La ricompensa non è arrivata come un ripensamento dopo il grazie. Al contrario: prima il ringraziamento, pieno, e poi la borsa, quasi a scusarsi.",
		"Prima il grazie, intero. Poi il compenso, porto quasi con timidezza, come se il denaro fosse la parte scortese della faccenda.",
	},
	["dar.quest_complete.w23.boon.006"] = {
		"ripone la ricompensa mentre chi l'ha consegnata guarda educatamente altrove, finché non è al sicuro.",
		"mette via il compenso mentre chi sta di fronte studia con tatto gli intagli più vicini, finché la borsa non è chiusa.",
		"intasca il compenso, e l'attenzione di chi l'ha dato si sposta cortese su un gufo di passaggio finché la tasca non è abbottonata.",
	},
	["dar.quest_complete.w23.boon.007"] = {
		"Per chi misura in secoli, cos'è una borsa? Eppure è stata pagata al centesimo, senza arrotondare una moneta. Anche la precisione è una forma di rispetto.",
		"Esattamente quanto promesso, fino all'ultimo rame. Un popolo con tanto tempo potrebbe permettersi di essere vago. Sceglie di non esserlo.",
	},
	["dar.quest_complete.w23.boon.008"] = {
		"Lo accetto, e volentieri. Ma l'avrei fatto anche per meno.",
		"Grazie. È più di quanto avrei chiesto.",
		"È un pensiero gentile. Il lavoro l'avrei fatto comunque.",
	},
	["dar.quest_complete.w23.boon.009"] = {
		"soppesa la ricompensa in una mano, la trova più pesante del previsto, e si affretta a fingere che fosse proprio il peso atteso.",
		"solleva la borsa, inarca le sopracciglia e le riabbassa subito, come se fosse una borsa del tutto normale.",
	},
	["dar.quest_complete.w23.boon.010"] = {
		"A essere sinceri: il ringraziamento è stato bellissimo, ma è delle monete che mi ricorderò la prossima volta che avrò fame.",
		"Ringraziamenti garbati, belle maniere e argento. Li apprezzo tutti e tre, più o meno in ordine inverso.",
		"Ricorderò l'inchino con affetto. L'argento lo ricorderò alla locanda, dove la gratitudine diventa utile.",
	},
	["dar.quest_complete.w23.boon.011"] = {
		"{g:Pagato|Pagata} dalla mia gente per un lavoro fatto per la mia gente. Le monete pesano più del loro peso, nel modo buono.",
		"Prendere una ricompensa dai propri simili fa sempre uno strano effetto. L'avrei fatto anche solo per l'albero. Le monete, però, me le tengo.",
	},
	["dar.quest_complete.w23.boon.012"] = {
		"Lo spenderò in un posto molto rumoroso, giusto per compensare.",
		"Dato con garbo. Cercherò di spenderlo con la stessa discrezione.",
		"Prometto di spenderlo con la dovuta dignità. Più o meno.",
	},
	["dar.quest_complete.w23.boon.013"] = {
		"La ricompensa è rimasta un attimo sospesa tra noi due, nessuna mano che mollava, prima di diventare mia. Una piccolezza. Sembrava una stretta di mano fatta d'argento.",
		"Per un momento l'abbiamo tenuta in due. Poi l'altra mano si è aperta, ed era mia. Di compensi ne ho ricevuti tanti; mai proprio così.",
	},
	["dar.quest_complete.w23.boon.014"] = {
		"infila la ricompensa in tasca senza guardarla, come si fa in una città dove a nessuno verrebbe in mente di sbirciare.",
		"mette via la ricompensa senza esaminarla, come se controllarla sul posto fosse una piccola scortesia.",
		"chiude la borsa sulla ricompensa senza un'occhiata, come si fa dopo aver imparato che qui nessuno dà il resto sbagliato.",
	},
	["dar.quest_complete.w23.boon.015"] = {
		"In tutta questa città ci sarà pure un kaldorei che mercanteggia. A me non è ancora capitato.",
		"Nessuno qui ha mai provato a limare una moneta da quanto promesso. Continuo ad aspettarmelo, come uno spiffero da una porta che non si apre mai.",
		"Una città intera, e nemmeno un kaldorei disposto a discutere per una moneta. È riposante. Ed è un ottimo modo per perdere l'abitudine.",
	},
	["dar.quest_complete.w23.boon.016"] = {
		"accetta la ricompensa con il ringraziamento un po' formale che un alleato rivolge a un altro, e riceve la stessa formalità, appena intiepidita ai bordi.",
		"prende il compenso come una mano dell'Alleanza da un'altra, e il cenno che segue è un poco più caldo del primo.",
	},
	["dar.quest_complete.w23.boon.017"] = {
		"Grazie. Andrà più lontano di quanto pensiate.",
		"Giusto, anzi più che giusto. Non dimenticherò chi l'ha pagato.",
		"Ne farò buon uso. È una promessa, non una cortesia.",
	},
	["dar.quest_complete.w23.boon.018"] = {
		"Qualunque cosa valga questa ricompensa alla banca della Tradesmen's Terrace, è stata consegnata come se contasse. È questa la parte che mi tengo stretta davvero.",
		"Un banchiere ci metterebbe sopra un numero. Il modo in cui è stata data non entra in nessun registro, ed è quello che tengo.",
	},
	["dar.quest_complete.w23.boon.019"] = {
		"apre la mano per la ricompensa un attimo prima che venga offerta, la richiude, e aspetta: la mossa giusta, a quanto pare.",
		"allunga la mano verso il compenso troppo presto, la ritira, e lo lascia arrivare con i suoi tempi. Arriva.",
	},
	["dar.quest_complete.w23.boon.020"] = {
		"Ringraziamenti, compenso, e un inchino sotto la pioggia, lento come se fosse asciutto. Io ho risposto più in fretta. Uno dei due si sta bagnando.",
		"Qui nessuno accorcia una consegna per la pioggia. Il grazie ha preso il suo tempo solito; io ci ho gocciolato sopra con educazione.",
	},
	["dar.quest_complete.w23.boon.021"] = {
		"Il vostro grazie vale più delle monete. Non ditelo alle monete.",
		"Parole gentili. Le terrò con me, e l'argento pure, se non vi dispiace.",
		"Parole da tenere, monete da spendere. Una divisione equa.",
	},
	["dar.quest_complete.w23.boon.022"] = {
		"Generoso. Cercherò di non spenderlo tutto su una terrazza sola.",
		"Grazie. Lo tratterò con cura: la casa d'aste di questa città ha l'aria affamata.",
	},
	["dar.quest_complete.w23.gratitude.001"] = {
		"Tre parole di ringraziamento. A Ironforge sarebbero state trenta e un giro di birra. Queste tre dureranno di più.",
		"Tutto il ringraziamento stava in una frase breve. Eppure non c'era niente da aggiungere.",
	},
	["dar.quest_complete.w23.gratitude.002"] = {
		"sente pronunciare piano 'Ishnu-alah' alla fine della faccenda, e risponde con un cenno attento.",
		"si sente congedare con un 'Ishnu-alah' sommesso, l'antico augurio dei kaldorei, e china il capo per accoglierlo.",
	},
	["dar.quest_complete.w23.gratitude.003"] = {
		"Il ringraziamento è stato così breve che ho pensato di essermi {g:perso|persa} il resto. Poi ho capito che il resto non c'era. Era tutto lì, ed era abbastanza.",
		"Ho aspettato la seconda metà del grazie. Non c'era. Una frase sola, detta sul serio, e la faccenda chiusa.",
	},
	["dar.quest_complete.w23.gratitude.004"] = {
		"No, sono io a ringraziare. Elune-adore.",
		"Elune-adore. L'onore è mio.",
		"Il vostro grazie è ben accolto. Andate in pace.",
	},
	["dar.quest_complete.w23.gratitude.005"] = {
		"Credo di essere {g:stato ringraziato|stata ringraziata}. C'è stato uno sguardo, gli occhi abbassati appena, e una parola che non ho capito. Ho deciso di prenderla per una lode sperticata.",
		"Era gratitudine? Era abbastanza sommessa da poter essere qualunque cosa. Scelgo la gratitudine.",
		"Uno sguardo, gli occhi bassi, una parola sommessa. O era un grazie o era un perdono. Vanno bene entrambi.",
	},
	["dar.quest_complete.w23.gratitude.006"] = {
		"viene {g:ringraziato|ringraziata} con una mano aperta posata per un attimo sul petto, dall'altra parte, un gesto che non chiede risposta.",
		"riceve il ringraziamento come una mano premuta un istante su un cuore kaldorei, e risponde con un piccolo inchino, in mancanza di meglio.",
	},
	["dar.quest_complete.w23.gratitude.007"] = {
		"Quando un kaldorei dice grazie, ci senti dentro tutto ciò che ha dovuto attraversare. In quella bocca non è una parola leggera.",
		"La gratitudine di chi ha seppellito tanto ha un suo peso. L'ho sentita posarsi, piccola e solida, e intendo portarla con cura.",
	},
	["dar.quest_complete.w23.gratitude.008"] = {
		"Basta questo. Vi ho sentito bene.",
		"Basta così come ringraziamento. Davvero.",
		"Non c'è bisogno di aggiungere niente. Ho capito.",
	},
	["dar.quest_complete.w23.gratitude.009"] = {
		"Uno sguardo lungo e fermo dopo il grazie, come per fissarmi al mio posto tra moltissimi volti. Ho lasciato fare, senza muovermi. Mi pareva educato.",
		"Dopo il grazie è seguito un lungo sguardo. Non ostile. Come chi rimette un libro sullo scaffale giusto.",
	},
	["dar.quest_complete.w23.gratitude.010"] = {
		"tiene pronto un mezzo sorriso educato per il resto dei ringraziamenti, e lo mantiene un bel po' prima che diventi chiaro che sono finiti.",
		"indugia, sorridendo, in attesa di un secondo giro di gratitudine che non arriva, e alla fine coglie l'antifona.",
		"attende con buona grazia il resto dei ringraziamenti, finché una quiete gentile non rende chiaro che non ce n'è.",
	},
	["dar.quest_complete.w23.gratitude.011"] = {
		"A Stormwind mi avrebbero stretto la mano fino a farmela dolere e l'avrebbero raccontato a tutta la taverna. Qui: un cenno, una parola sommessa. La taverna mi manca un po'. Solo un po'.",
		"Un funzionario di Stormwind avrebbe timbrato qualcosa e chiamato il prossimo della fila. Qui è stato più gentile. Più lento, ma più gentile.",
	},
	["dar.quest_complete.w23.gratitude.012"] = {
		"{g:Ringraziato|Ringraziata} senza che mi offrissero neanche un goccio. Dovrò ricordarmi che qui si usa così, e non è un'offesa.",
		"Nemmeno un boccale per il grazie. Brava gente, i kaldorei, ma qualcuno dovrebbe spiegar loro come si chiude a dovere un lavoro.",
	},
	["dar.quest_complete.w23.gratitude.013"] = {
		"E grazie a voi, per avermelo affidato.",
		"Avete avuto fiducia in me. Già questo mi basta come ringraziamento.",
	},
	["dar.quest_complete.w23.gratitude.014"] = {
		"Il grazie è arrivato in darnassiano, e non ho chiesto la traduzione. Certe parole sono più chiare intere.",
		"Una parola di ringraziamento che non conoscevo, detta una volta e mai ripetuta. Ho deciso che volesse dire esattamente quel che serviva.",
	},
	["dar.quest_complete.w23.gratitude.015"] = {
		"accoglie i ringraziamenti senza aggiungere parola, che in questa città sembra proprio la risposta giusta.",
		"risponde al grazie con il silenzio e un breve inchino, e il silenzio viene capito al volo.",
	},
	["dar.quest_complete.w23.gratitude.016"] = {
		"Sto imparando a ricevere i ringraziamenti come li danno loro: senza agitarmi, senza minimizzare. È più difficile di quanto sembri.",
		"D'istinto direi 'figuratevi, non è niente'. Qui sarebbe scortese: non era niente, e me l'hanno detto. Mi sto esercitando ad annuire e basta.",
		"Saper ricevere un grazie è un'arte. Anche saperlo dare. In questa città sono {g:allievo|allieva} in tutte e due.",
	},
	["dar.quest_complete.w23.gratitude.017"] = {
		"È il grazie più caloroso che abbia mai ricevuto a quel volume.",
		"Lo prendo come uno scroscio di applausi, tarato sulle usanze locali.",
		"Attenzione. Ancora un po' di entusiasmo e qualcuno potrebbe sentirvi.",
	},
	["dar.quest_complete.w23.gratitude.018"] = {
		"Le sacerdotesse infilano il nome di Elune nei loro ringraziamenti, ho notato, come altri ci mettono il nome di chi ringraziano. Persino una piccola commissione suona come qualcosa che qualcuno ha visto.",
		"I ringraziamenti che si sentono dalle parti del Temple of the Moon portano quasi sempre Elune da qualche parte. Ho smesso di sentirmi fuori posto a esserci {g:incluso|inclusa}.",
	},
	["dar.quest_complete.w23.gratitude.019"] = {
		"Sotto la gratitudine c'era una certa stanchezza. Non verso di me. Verso il dover chiedere aiuto, forse. Non l'ho presa sul personale.",
		"Riconoscenza, e un velo di rammarico per averne avuto bisogno. Conosco quello sguardo: lo hanno le persone fiere quando devono chiedere aiuto.",
	},
	["dar.quest_complete.w23.gratitude.020"] = {
		"È stato un piacere. Non lo dico a cuor leggero, in una città che pesa le parole.",
		"Felice di servire. Fatemi sapere se c'è altro.",
	},
	["dar.quest_complete.w23.gratitude.021"] = {
		"coglie, proprio alla fine dei ringraziamenti, il più lieve dei sorrisi, che compare e sparisce come un pesce che si gira nell'acqua profonda.",
		"vede il grazie chiudersi su un sorriso così piccolo che poteva essere un gioco delle lanterne, e ne restituisce uno parecchio più largo.",
	},
	["dar.quest_complete.w23.gratitude.022"] = {
		"Non serve inchinarsi così tanto per me. Davvero.",
		"Vi prego, non c'è bisogno di tanto. Basta un cenno.",
		"Quell'inchino era più profondo di quanto meritasse il lavoro. La prossima volta cercherò di meritarlo.",
	},
	["dar.quest_complete.w23.handover.001"] = {
		"È passato dalle mie mani a mani sottili che l'hanno girato due volte, adagio, come un gioielliere fa con una pietra.",
		"Esaminato da ogni lato senza una parola, come una gemma sotto la lente. Poi un cenno appena: va bene così.",
		"Girato due volte, piano, da dita che sembravano leggerlo. Poi un cenno, e non era più affar mio.",
	},
	["dar.quest_complete.w23.handover.002"] = {
		"porge ciò che era stato chiesto e resta in attesa, finché dita lunghe non lo sollevano senza mai sfiorare le sue.",
		"offre il lavoro compiuto sul palmo aperto, e se lo vede togliere con tanta leggerezza che la mano quasi non avverte il peso che se ne va.",
		"tende il lavoro e resta del tutto immobile mentre viene sollevato via, come si sta fermi quando un uccello si posa sul polso.",
	},
	["dar.quest_complete.w23.handover.003"] = {
		"Altrove una consegna è uno scambio e basta. Qui ha una forma: la mano tesa, una pausa, la mano che torna, gli sguardi che si incontrano alla fine. Io la pausa la dimentico sempre.",
		"Anche restituire qualcosa, in questa città, ha un suo ordine. Si porge, si aspetta che lo prendano, e non si parla per primi. Io ho parlato per {g:primo|prima}.",
	},
	["dar.quest_complete.w23.handover.004"] = {
		"Ecco qua. L'ho controllato due volte, ma prego, una terza occhiata non ha mai fatto male a nessuno.",
		"È tutto vostro. Guardatelo quanto volete, non ho nessuna fretta. Credo.",
	},
	["dar.quest_complete.w23.handover.005"] = {
		"I druidi prendono le cose come per controllare che siano ancora vive. Le sacerdotesse, come se le aspettassero da sempre. Le Sentinelle, come se ne contassero il prezzo. Ormai riconosco chi è chi dalle sole mani.",
		"Chi affida un compito si riconosce da come lo riceve indietro. Un druido lo soppesa, una sacerdotessa lo accarezza con lo sguardo, una Sentinella lo conta. Stavolta, un po' di tutte e tre le cose.",
	},
	["dar.quest_complete.w23.handover.006"] = {
		"L'inchino che l'ha accompagnato era quello piccolo che si scambiano tra loro, non quello più profondo per gli ospiti. Me ne sono {g:accorto|accorta}. Non so se dovevo.",
		"Un inchino lieve, come quelli che ho visto passare tra kaldorei della stessa terrazza. Non quello di rito. Vale più della borsa.",
	},
	["dar.quest_complete.w23.handover.007"] = {
		"lo posa nelle mani che attendono e non molla subito la presa, finché una parola sommessa non ne dà il permesso.",
		"trattiene la presa un istante di troppo, per un'abitudine presa in città più rudi, e lascia andare quando una mano sottile si chiude piano sopra la sua.",
		"lascia il lavoro solo quando l'altra mano ci è del tutto sotto, e la cura di quel piccolo momento viene ricambiata con un cenno.",
	},
	["dar.quest_complete.w23.handover.008"] = {
		"È fatto, ed eccolo qui. Intero, come promesso.",
		"Come avevate chiesto. Non manca nulla, e non ho lesinato su niente.",
		"Tutto ciò che mi avevate affidato. Ora sta nelle vostre mani.",
	},
	["dar.quest_complete.w23.handover.009"] = {
		"L'ho porto come un'offerta, perché qui tutto sembra chiederlo. L'hanno preso come un pacco. Bene: posso smettere di recitare.",
		"Tutta la cerimonia che avevo provato in testa, e me l'hanno preso con la semplicità di un fornaio che ritira una teglia. Per poco non mi rubavano l'inchino.",
	},
	["dar.quest_complete.w23.handover.010"] = {
		"abbassa gli occhi mentre il lavoro viene accolto, come in questa città si impara a fare, e li rialza solo quando i ringraziamenti sono finiti.",
		"tiene lo sguardo rispettoso sulla pietra sotto i piedi mentre la cosa viene esaminata, e lo solleva alla prima parola di approvazione.",
		"studia le venature del pavimento mentre il lavoro viene valutato, una prova di pazienza che in questa città è semplice buona educazione.",
	},
	["dar.quest_complete.w23.handover.011"] = {
		"Il mio nome mi è stato ripetuto come una parola che valesse la pena di conservare. Da tempo nessuno lo pronunciava con tanta cura.",
		"Il mio nome, ripetuto una volta, piano, ogni suono al suo posto. Poca cosa. Ma è stato come mettere una firma sulla consegna.",
	},
	["dar.quest_complete.w23.handover.012"] = {
		"aspetta mentre il lavoro viene esaminato, poi aspetta ancora un po', poi comincia, con molta discrezione, a studiare gli intagli dell'arco più vicino.",
		"resiste a un esame così senza fretta da avere il tempo di contare due volte le foglie del rampicante più vicino.",
		"assiste, durante l'esame, alla visita di una falena alla lanterna più vicina, e tra le due la falena pare la più paziente.",
	},
	["dar.quest_complete.w23.handover.013"] = {
		"Le mani che l'hanno preso sono forse più vecchie della maggior parte dei regni. L'hanno tenuto come si tiene qualcosa di nuovo: con interesse, e nessuna fretta.",
		"Quelle dita forse hanno stretto oggetti di prima che il mondo si spezzasse. Il mio lavoro l'hanno tenuto con la stessa cura, e io scelgo di sentirmene {g:lusingato|lusingata}.",
	},
	["dar.quest_complete.w23.handover.014"] = {
		"Ecco a voi. Attenzione, è... no, certo che fate attenzione.",
		"Eccolo. Occhio al... ah. Lo avete già fatto mille volte.",
		"Prendete. Piano, avrei detto, ma vedo che non serve.",
	},
	["dar.quest_complete.w23.handover.015"] = {
		"Altrove si afferra. Qui si riceve. È solo una questione di velocità, eppure mi pare di aver portato qualcosa di meglio di quanto fosse.",
		"Nessuno l'ha strappato via. Nessuno ha nemmeno allungato la mano. È stato accolto e basta, e io sono {g:rimasto|rimasta} lì con la sensazione di aver consegnato chissà quale tesoro.",
		"È stato ricevuto, non preso. Non sapevo che ci fosse differenza fino a un attimo fa.",
	},
	["dar.quest_complete.w23.handover.016"] = {
		"accenna un inchino alla consegna, un po' rigido nelle ginocchia, e riceve in cambio un inchino che finge con garbo di non accorgersene.",
		"si inchina mentre il lavoro passa di mano, un filo più a fondo del necessario, e riceve in risposta un inchino che gentilmente lo eguaglia.",
		"tenta l'inchino, ne sbaglia la profondità, e vede la risposta adeguarsi della stessa misura, per gentilezza.",
	},
	["dar.quest_complete.w23.handover.017"] = {
		"L'hanno ricevuto come lo riceve chi ha perso molto: con cura, come se anche un piccolo guadagno potesse essere ripreso.",
		"C'è una tenerezza nel modo in cui prendono anche la cosa più semplice. Un popolo che ha perso tanto non maneggia nulla con leggerezza.",
	},
	["dar.quest_complete.w23.handover.018"] = {
		"Prima che diciate qualcosa: sì, lo so, poteva essere più ordinato. Ma è fatto.",
		"Non è elegante, ma è finito. L'eleganza si paga a parte.",
		"Ammetto che ai bordi è un po' grezzo. Il centro, però, è ottimo.",
	},
	["dar.quest_complete.w23.handover.019"] = {
		"si sfiora la fronte con due dita alla consegna, e lo stesso gesto torna subito indietro, tra due kaldorei, senza bisogno di parole.",
		"scambia un cenno quieto con chi ha affidato il compito, il cenno di due kaldorei che non hanno niente da spiegarsi.",
	},
	["dar.quest_complete.w23.handover.020"] = {
		"Le mie mani, a questo punto, sono sempre un po' goffe. Le loro mai. In due, ce la facciamo.",
		"Alla consegna ho armeggiato. Ovvio. È stato preso al volo senza nemmeno guardare, da qualcuno che ha avuto secoli per esercitarsi.",
	},
	["dar.quest_complete.w23.handover.021"] = {
		"comincia a spiegare ogni dettaglio del lavoro, incrocia lo sguardo paziente che ne riceve, e si ferma dopo la prima frase.",
		"attacca un resoconto completo della faccenda, nota la quiete garbata con cui viene accolto, e riduce tutto a una parola: fatto.",
		"arriva a tre parole di spiegazione, vede che non ne serve nessuna, e lascia il resto non detto.",
	},
	["dar.quest_complete.w23.handover.022"] = {
		"Ecco. E prima che lo chiediate: no, nessun disturbo. Be'. Qualche disturbo.",
		"Ecco qui. Nessuna preoccupazione, è stato un piacere. Per lo più.",
	},
	["dar.quest_complete.w23.handover.023"] = {
		"Fatto meglio che ho potuto. Spero che basti.",
		"È finito. Spero sia ciò che vi aspettavate.",
	},
	["dar.quest_complete.w23.handover.024"] = {
		"sente il ringraziamento arrivare dalla nebbia prima ancora del volto, e risponde in direzione della voce.",
		"si inchina a una figura sfumata dalla nebbia, e l'inchino che torna sembra quasi un riflesso.",
	},
	["dar.quest_complete.w23.jest.001"] = {
		"Lo so, sono {g:entrato|entrata} troppo in fretta. Uscirò più piano, così pareggiamo.",
		"Troppo spedito? Me ne vado a mezza velocità. La terrazza può riprendersi la sua calma.",
	},
	["dar.quest_complete.w23.jest.002"] = {
		"Mi dai una ricevuta? No? Un lungo sguardo carico di significato, allora. Va bene lo stesso.",
		"Niente per iscritto? D'accordo. Prendo quello sguardo come prova.",
	},
	["dar.quest_complete.w23.jest.003"] = {
		"Sono {g:entrato|entrata} così in fretta da far sobbalzare una Sentinella. Me ne andrò così piano da annoiarne una.",
		"All'andata ho fatto battere le palpebre a una Sentinella. Al ritorno punto a farne sbadigliare una.",
	},
	["dar.quest_complete.w23.jest.004"] = {
		"Troppo svelto? Posso uscire e consegnartelo di nuovo, più adagio, se si usa così.",
		"Rifaccio tutto al passo giusto? Esco e rientro come una persona assennata.",
	},
	["dar.quest_complete.w23.jest.005"] = {
		"Ti prego, non ringraziarmi tutto in una volta. Diluiscilo. Il tempo non ti manca.",
		"Ringraziami a rate, se vuoi. Io resto in giro per un po', e tu ancora più a lungo.",
	},
	["dar.quest_complete.w23.jest.006"] = {
		"'Finito': l'ho detto così in fretta che la parola è arrivata prima di me.",
		"Finito! L'ho gridato sulla porta, e solo adesso l'ho {g:raggiunto|raggiunta}.",
	},
	["dar.quest_complete.w23.jest.007"] = {
		"Ah, la pausa. Qui la fanno tutti, la pausa. Prenditela. Sto imparando a starci dentro.",
		"Eccola, la pausa dei kaldorei prima di una risposta. Io resto qui e invecchio con dignità.",
	},
	["dar.quest_complete.w23.jest.008"] = {
		"Qualcuno in questa città avrà pure fretta. Indicamelo. Andremmo d'accordo.",
		"C'è almeno una persona a Darnassus che si sbriga? Vorrei stringerle la mano. O farle un cenno.",
	},
	["dar.quest_complete.w23.jest.009"] = {
		"Forse sono la cosa più veloce successa su questa terrazza da un mese. Non badarmi.",
		"Scusa il trambusto. Lo so, quassù il trambusto è raro. Me lo porto via.",
	},
	["dar.quest_complete.w23.jest.010"] = {
		"Un bel lavoro, modestia a parte. Anzi, la modestia la lascio da parte, che arriva troppo tardi.",
		"Me la sono {g:cavato|cavata} piuttosto bene. Lascerei dirlo a un altro, ma qui nessuno parla abbastanza in fretta.",
	},
	["dar.quest_complete.w23.jest.011"] = {
		"Paghi con tanta grazia che quasi ti restituirei tutto. Quasi.",
		"Che bel modo di essere {g:pagato|pagata}. Rifallo, così lo guardo meglio. No? Valeva la pena chiedere.",
	},
	["dar.quest_complete.w23.jest.012"] = {
		"Nessuno applaude. Giusto. Mi applaudo da {g:solo|sola}, piano piano, laggiù.",
		"Niente folla, niente trombe. Festeggio per conto mio, in sordina, dietro un albero. Ce ne sono tanti.",
	},
	["dar.quest_complete.w23.jest.013"] = {
		"Mi hanno detto di non mettere mai fretta a un kaldorei. Nessuno ha detto niente sul sorpassarne uno.",
		"Prima regola quassù, mi hanno detto: non mettere fretta a un elfo. Allora ti giro attorno di corsa.",
	},
	["dar.quest_complete.w23.jest.014"] = {
		"Non badare a me. Sto solo ammirando la calma con cui tutti accolgono il mio trionfo.",
		"Un trionfo, e l'intera terrazza va avanti come prima. Lo rispetto. Un po' mi brucia, ma lo rispetto.",
	},
	["dar.quest_complete.w23.jest.015"] = {
		"Se avessi saputo quanta gioia ti avrebbe dato, avrei fatto con più calma, per farti godere l'attesa.",
		"A saperlo, me la sarei presa comoda. Credo che la suspense ti sarebbe piaciuta.",
	},
	["dar.quest_complete.w23.jest.016"] = {
		"Pagato per intero, e la borsa fa un rumore allegro. L'unico rumore allegro nel giro di un miglio.",
		"Senti questa borsa. È la cosa più rumorosa di Darnassus, e non me ne pento neanche.",
	},
	["dar.quest_complete.w23.jest.017"] = {
		"Aspetto mentre decidi se sorridere? Non ho impegni. Cioè, li ho, ma fai pure.",
		"Prenditi un momento. Anche due. Io resto qui, a essere {g:soddisfatto|soddisfatta}.",
	},
	["dar.quest_complete.w23.jest.018"] = {
		"Altrove un impiegato timbra carte al doppio della velocità di chiunque qui. Un po' mi manca.",
		"In un'altra città mi avrebbero dato un modulo da firmare. Qui un cenno e un silenzio. Preferisco il silenzio.",
	},
	["dar.quest_complete.w23.jest.019"] = {
		"Mi hai ringraziato così piano che dovrò fidarmi. Decido che è stato un grazie caloroso.",
		"Era un grazie, o è caduta una foglia? Lo conto come grazie in ogni caso.",
	},
	["dar.quest_complete.w23.jest.020"] = {
		"Puntuale, per i miei conti. Per i tuoi sarò forse un po' in anticipo, di una decina d'anni.",
		"In anticipo? A misura di kaldorei, immagino che tutto ciò che sta sotto il secolo sia in anticipo.",
	},
	["dar.quest_complete.w23.jest.021"] = {
		"Nella quiete, la mia voce sembrava quella di un banditore al mercato. La prossima volta più gentile, o almeno più breve.",
		"Ogni parola che ho detto sembrava rimbalzare due volte sui muri chiari. Alla prossima visita porto una voce più piccola.",
	},
	["dar.quest_complete.w23.jest.022"] = {
		"Avevo voglia di urlare di gioia. Non ho urlato. Nessuno a Darnassus saprà mai quanto ci sono {g:andato|andata} vicino.",
		"Avevo un evviva proprio dietro i denti. L'ho tenuto lì. La cosa più eroica che ho fatto in tutta la settimana.",
	},
	["dar.quest_complete.w23.jest.023"] = {
		"Tutto quello che ho detto è uscito al doppio della velocità di quello che dicevano loro. Sembravo uno scoiattolo che fa rapporto.",
		"Accanto a quella lenta voce kaldorei sembravo un passero che fa rapporto a una quercia.",
	},
	["dar.quest_complete.w23.jest.024"] = {
		"Se vuoi aggiungere qualcosa, aspetto. Mi sono {g:portato|portata} uno spuntino.",
		"Prenditi tutto il tempo che serve per rispondere. Ho del pane nella sacca e nessuna fretta.",
	},
	["dar.quest_complete.w23.jest.025"] = {
		"Parlo troppo in fretta? Non me ne accorgo più. Quassù ogni cosa che dico sembra uno starnuto.",
		"Troppo veloce? In questa città ogni mia frase sembra detta scappando da un incendio.",
		"Frenami se farfuglio. Mi dicono che farfuglio.",
	},
	["dar.quest_complete.w23.jest.026"] = {
		"Farei un discorso, ma ho il sospetto che lo ascolteresti tutto.",
		"Niente discorsi da parte mia. In questa città qualcuno potrebbe ascoltarli davvero, e allora come ne esco?",
	},
	["dar.quest_complete.w23.jest.027"] = {
		"Devo bussare, un'altra volta? Qui tutti arrivano senza un suono, e io sono {g:entrato|entrata} come un secchio giù per un pozzo.",
		"In futuro entro in punta di piedi. Quell'ingresso ha fatto più fracasso di quanto questa terrazza ne senta in un anno.",
	},
	["dar.quest_complete.w23.jest.028"] = {
		"Mi dicono che il grazie dei kaldorei può metterci un po' ad arrivare. Aspetto qui col sorriso pronto.",
		"La gratitudine è per strada? Nessuna fretta. Tengo il sorriso in caldo.",
		"Grazie in arrivo, mi pare di capire. Intanto resto qui con l'aria riconoscente in anticipo.",
	},
	["dar.quest_complete.w23.jest.029"] = {
		"Un altro favore fra alleati. Qualcuno se lo segni: l'Alleanza tiene i conti malissimo.",
		"Mettilo sul conto dell'Alleanza. È un conto lungo. Nessuno lo legge mai.",
	},
	["dar.quest_complete.w23.jest.030"] = {
		"Grazie! Scusa. Grazie, più piano. Noi gnomi abbiamo la molla un po' tirata.",
		"Ecco tutto! Troppo in fretta? Lo ridico a velocità kaldorei. Graaaziee.",
	},
	["dar.quest_complete.w23.jest.031"] = {
		"Fatto, e {g:fradicio|fradicia}. Pagami in fretta, prima che la pioggia si prenda la sua parte.",
		"Ecco, la faccenda è chiusa. Occhio alle gocce: quassù la pioggia fa il giro panoramico.",
	},
	["dar.quest_complete.w23.nod.001"] = {
		"porta due dita alla fronte, un gesto venuto da altrove, e spera che qui risulti cortese.",
		"accenna un piccolo saluto alla fronte, preso dalle usanze di un'altra città, e osserva se va a segno.",
	},
	["dar.quest_complete.w23.nod.002"] = {
		"si inchina, riceve in risposta un inchino appena più profondo, e si inchina ancora per pareggiare.",
		"risponde a un inchino con un inchino, poi a uno un po' più profondo con uno un po' più profondo, finché la cosa minaccia di non finire mai.",
	},
	["dar.quest_complete.w23.nod.003"] = {
		"comincia a dire qualcosa di arguto, ci ripensa, e si accontenta di un semplice grazie.",
		"apre la bocca per una battuta, la richiude, e offre invece un grazie semplice.",
	},
	["dar.quest_complete.w23.nod.004"] = {
		"ride della propria battuta, da {g:solo|sola}, e la trasforma in un sorriso educato prima che qualcuno se ne accorga.",
		"fa una piccola battuta sulla ricompensa e la guarda attraversare lentamente, molto lentamente, il volto del kaldorei, fino ad arrivare a segno.",
	},
	["dar.quest_complete.w23.nod.005"] = {
		"dondola sui talloni mentre dall'altra parte ci si prende un lungo momento per rispondere, e smette appena viene {g:notato|notata}.",
		"sposta il peso da un piede all'altro nel lungo silenzio che precede la risposta, poi si ferma, {g:colto|colta} sul fatto.",
	},
	["dar.quest_complete.w23.nod.006"] = {
		"consegna il lavoro con un piccolo svolazzo che stona fra gente così misurata, e ci ride sopra con un'alzata di spalle.",
		"conclude con un ampio gesto del braccio che starebbe bene in un mercato affollato, e lo lascia cadere, un po' {g:imbarazzato|imbarazzata}, nella quiete.",
	},
	["dar.quest_complete.w23.nod.007"] = {
		"dice che è fatto e poi, siccome nessuno si muove, lo ripete, più piano.",
		"annuncia che il lavoro è finito, aspetta, e lo ripete a metà volume, che sembra quello giusto.",
	},
	["dar.quest_complete.w23.nod.008"] = {
		"abbassa la voce a metà di una parola, come se la città {g:gli|le} avesse battuto sulla spalla.",
		"sente la propria voce salire e la riporta giù a metà frase, come si raddrizza una tazza.",
	},
	["dar.quest_complete.w23.nod.009"] = {
		"parte a passo di carica, si ricorda dove si trova, e finisce il passo a metà velocità.",
		"si avvia a passo svelto, poi si adegua all'andatura più lenta di tutti gli altri sul sentiero.",
	},
	["dar.quest_complete.w23.nod.010"] = {
		"risponde con tre cenni rapidi al singolo cenno lento di chi l'ha {g:ringraziato|ringraziata}, e sorride del conto.",
		"ricambia un cenno kaldorei senza fretta con parecchi cenni svelti, poi decide che il punteggio è pari.",
	},
	["dar.quest_complete.w23.nod.011"] = {
		"dà due colpetti alla borsa, come per rassicurarla, e lancia un ultimo grazie da sopra la spalla.",
		"dà alla borsa un colpetto affettuoso e aggiunge un altro grazie uscendo, quasi rivolto allo stipite.",
	},
	["dar.quest_complete.w23.nod.012"] = {
		"porge la mano da stringere, la vede esaminata con educato interesse, e trasforma il gesto in un vago saluto.",
		"tende la mano, la trova osservata come una foglia curiosa, e la ritira piano per grattarsi un orecchio.",
	},
	["dar.quest_complete.w23.nod.013"] = {
		"ripete con cura la parola di ringraziamento kaldorei appena sentita, e si guadagna un piccolo cenno di approvazione.",
		"restituisce il grazie elfico a chi gliel'ha appena detto, sillaba per sillaba, e riceve in risposta l'ombra di un sorriso.",
	},
	["dar.quest_complete.w23.nod.014"] = {
		"fischietta due note voltandosi, poi smette, {g:imbarazzato|imbarazzata} da quanto lontano arrivano.",
		"canticchia una battuta di qualcosa di allegro, la sente rimbalzare sui muri chiari, e la lascia morire a metà.",
	},
	["dar.quest_complete.w23.nod.015"] = {
		"posa una mano aperta sul petto e china il capo, un gesto che sembra venire compreso.",
		"si porta il palmo al petto con un breve inchino, e riceve in cambio lo stesso gesto, più lento.",
	},
	["dar.quest_complete.w23.nod.016"] = {
		"sorride, largo e senza difese, e in risposta riceve la più piccola curva di labbra kaldorei.",
		"sfodera un sorriso a trentadue denti e riceve in cambio un sorriso kaldorei appena accennato, che in qualche modo pesa uguale.",
	},
	["dar.quest_complete.w23.nod.017"] = {
		"ringrazia una seconda volta uscendo, nel caso la prima fosse passata inosservata, e riceve uno sguardo che dice che era stata sentita benissimo.",
		"si volta a ringraziare ancora e trova un'espressione che chiarisce bene come il primo grazie fosse più che sufficiente.",
	},
	["dar.quest_complete.w23.nod.018"] = {
		"imita, con un attimo di ritardo, il modo in cui i kaldorei congiungono le mani a cose fatte, e ci riesce quasi.",
		"rifà il piccolo gesto di congedo del kaldorei, le mani che si incontrano alla vita, e si compiace di aver tenuto il passo.",
	},
	["dar.quest_complete.w23.nod.019"] = {
		"attacca un lungo resoconto del lavoro, vede chi ascolta mettersi comodo come per una stagione intera, e chiude in una frase.",
		"si lancia nel racconto completo, nota che chi ascolta si sistema per la lunga durata, e si perde d'animo all'istante.",
	},
	["dar.quest_complete.w23.nod.020"] = {
		"soppesa la ricompensa nel palmo senza guardarla, e la mette via con un cenno che fa da ricevuta.",
		"prende quanto viene offerto, ci chiude sopra la mano e annuisce una volta: la cosa più simile a una firma che questa città sembri chiedere.",
	},
	["dar.quest_complete.w23.nod.021"] = {
		"cerca di mostrarsi {g:composto|composta} come chi ha davanti, e ci riesce giusto il tempo di voltarsi.",
		"mantiene un volto perfettamente sereno per tutto il ringraziamento, poi sorride come un gatto appena girate le spalle.",
	},
	["dar.quest_complete.w23.nod.022"] = {
		"abbandona a metà la frase solenne, ci ride sopra, e finisce con parole semplici che vengono accolte con la stessa gentilezza.",
		"lascia cadere un discorsetto impettito a metà e dice, semplicemente, grazie: funziona meglio.",
	},
	["dar.quest_complete.w23.nod.023"] = {
		"resta un attimo più del necessario, senza sapere se la faccenda sia chiusa, finché una lieve inclinazione del capo non lo conferma.",
		"indugia, nel dubbio che ci si aspetti altro, e un solo lento abbassarsi di ciglia, cortese, scioglie il dubbio.",
		"aspetta un segno che sia finita, ne riceve uno così piccolo da rischiare di perderlo, e se ne va.",
	},
	["dar.quest_complete.w23.nod.024"] = {
		"mormora 'ottimo, ottimo' a nessuno in particolare, come si fa quando una cosa è andata per il verso giusto.",
		"dice piano 'ecco, allora', la piccola formula che si tiene per un lavoro chiuso.",
	},
	["dar.quest_complete.w23.nod.025"] = {
		"risponde a una domanda sul lavoro con un'alzata di spalle e un sorriso, che sembrano dire più di quanto la domanda chiedesse.",
		"alla domanda su com'è andata risponde col pollice alzato, che viene esaminato con autentico interesse.",
		"risponde alla cortese domanda con un allegro 'bene, bene', e lo vede soppesare come fosse un resoconto completo.",
	},
	["dar.quest_complete.w23.nod.026"] = {
		"alza lo sguardo verso la luna, oltre un varco tra le foglie, imitando un gesto appena visto, prima di rispondere; e trova che calza a pennello.",
		"segue gli occhi del kaldorei fino alla luna sopra la volta di foglie, poi li riabbassa, e dice grazie con la stessa voce bassa.",
	},
	["dar.quest_complete.w23.onward.001"] = {
		"Piedi, decidete voi. La banca, la locanda sulla Craftsmen's Terrace, o quella panchina che continuo a promettermi.",
		"Tre direzioni, tutte in curva. Prendo quella che sa di pane.",
		"A sinistra la banca, a destra la locanda. Lo stomaco vota a destra.",
	},
	["dar.quest_complete.w23.onward.002"] = {
		"si ferma a un bivio, soppesa una curva contro l'altra, e prende quella a sinistra senza motivo.",
		"sosta dove due sentieri si separano, e lascia che la direzione di una Sentinella di passaggio scelga al posto suo.",
	},
	["dar.quest_complete.w23.onward.003"] = {
		"Ora, l'addestratore. Da qualche parte. Su un albero, presumo.",
		"Ora l'addestratore. Se qualcuno mi vede passare di qui due volte, faccia finta di niente.",
	},
	["dar.quest_complete.w23.onward.004"] = {
		"Dove adesso? All'asta, per vedere se la ricompensa vale più di quanto valga per me. Probabilmente no. Probabilmente la tengo.",
		"Potrei venderla all'asta. O tenerla, e ricordare il volto di chi me l'ha data. Quassù divento sentimentale.",
	},
	["dar.quest_complete.w23.onward.005"] = {
		"parte con uno scopo preciso, sbaglia tre svolte fra le terrazze, e arriva in un bel posto che non era nei piani.",
		"si avvia di buon passo verso la prossima commissione, e dopo venti passi la città ha già frenato la sua andatura.",
	},
	["dar.quest_complete.w23.onward.006"] = {
		"Nessuno che aspetti qualcosa da me. Potrei andare ovunque in città. Credo che andrò sull'acqua a fare l'airone.",
		"Niente di dovuto, nessuno che mi aspetti. Cosa rara. La spenderò piano, come si usa qui.",
		"Per una volta nessuno ha bisogno di me da nessuna parte. Intendo sprecarla come si deve.",
	},
	["dar.quest_complete.w23.onward.007"] = {
		"Da mangiare. È lì che mi portano i piedi, e non discuto.",
		"Un posto dove mangiare: ecco la prossima commissione. La più onesta che mi sia capitata.",
		"Prima la cena. Tutto il resto, in questa città, può aspettare, e lo farà volentieri.",
	},
	["dar.quest_complete.w23.onward.008"] = {
		"Il mondo aspetta ai piedi dell'albero. Può aspettare ancora un po': voglio fare un'altra passeggiata quassù.",
		"Laggiù, la prossima strada. Quassù, un po' di tempo senza niente da fare. Scelta facile.",
	},
	["dar.quest_complete.w23.onward.009"] = {
		"si lascia attirare dal suono del mazzuolo di un artigiano, senza affari da sbrigare, solo per curiosità.",
		"segue l'odore di erbe tagliate lungo il sentiero, lasciando al naso la scelta della prossima tappa.",
		"va dietro a due apprendisti che chiacchierano, per nessuna ragione migliore del fatto che sembrano sapere dove vanno.",
	},
	["dar.quest_complete.w23.onward.010"] = {
		"I kaldorei ci metteranno una settimana a decidere se gli serve altro da me. Ripasserò. Fra una settimana.",
		"Se c'è altro lavoro, nessuno qui me lo dirà di fretta. C'è tutto il tempo per girovagare prima.",
	},
	["dar.quest_complete.w23.onward.011"] = {
		"Qualcuno va verso la banca? Vengo con voi, se conoscete la strada.",
		"Da che parte per gli addestratori, per favore? Ed è lontano quanto sembra?",
		"Locanda, poi banca, poi letto. Se i sentieri collaborano.",
	},
	["dar.quest_complete.w23.onward.012"] = {
		"dà un'ultima occhiata alla borsa, annuisce a nessuno in particolare e va a cercare cos'altro offre la città.",
		"dà un colpetto allo zaino, sistemando la ricompensa fra il resto, e si volta verso le terrazze più animate.",
	},
	["dar.quest_complete.w23.onward.013"] = {
		"Presto giù dall'albero, verso città del mio genere: rumore, fumo, strade dritte. Mi mancherà più di quanto ammetterò.",
		"Da qualche parte oltre il mare c'è una città che grida. Ci sarò presto, a rimpiangere questa quiete.",
	},
	["dar.quest_complete.w23.onward.014"] = {
		"alza gli occhi ai rami per orientarsi, non trova nessun riferimento, e sceglie comunque una direzione.",
		"cerca un punto di riferimento fra i grandi rami, trova solo foglie, e parte a intuito.",
	},
	["dar.quest_complete.w23.onward.015"] = {
		"prende apposta la strada lunga, lungo l'acqua, come piccolo premio sopra il premio.",
		"sceglie il sentiero più lento, fra le canne, un piacere in più aggiunto al compenso.",
	},
	["dar.quest_complete.w23.onward.016"] = {
		"Ho voglia di raccontarlo a qualcuno. Ma i kaldorei non fanno pettegolezzi, quindi dovrò tenerlo per qualche taverna rumorosa.",
		"Questa merita di essere raccontata bene, e questa città è il pubblico sbagliato. La porterò giù a qualcuno che interrompe.",
	},
	["dar.quest_complete.w23.onward.017"] = {
		"L'addestratore vorrà monete, il mercante vorrà monete, e la borsa sarà magra prima che io abbia finito. Però per un po' è stata grassa.",
		"La ricompensa ha già tre pretendenti, e nessuno è la mia tasca.",
	},
	["dar.quest_complete.w23.onward.018"] = {
		"Qualcun altro ha bisogno di un paio di gambe volenterose? Queste sono già sciolte.",
		"Qualcun altro? Sono in vena, e in questa città potrebbe non ricapitare.",
		"Chi è il prossimo? Ho lo slancio giusto, e quassù è merce rara.",
	},
	["dar.quest_complete.w23.onward.019"] = {
		"Allora, dove ho messo il resto delle mie commissioni?",
		"Il prossimo. C'è sempre un prossimo. Dove si nasconde?",
		"Piede destro, piede sinistro, verso qualcosa di utile. Tutto il piano è questo.",
	},
	["dar.quest_complete.w23.onward.020"] = {
		"Alla locanda, credo. A meno che qualcuno non abbia un'idea migliore e un sentiero più corto.",
		"Vado a vendere quel che non mi serve. L'asta non aspetta. Ah no, aspetta eccome. Qui aspetta tutto.",
	},
	["dar.quest_complete.w23.onward.021"] = {
		"Per un po' non devo decidere niente. Camminerò finché il sentiero finisce, il che a Darnassus potrebbe non succedere mai.",
		"Nessun piano, e per una volta mi sembra un lusso, non un problema.",
	},
	["dar.quest_complete.w23.onward.022"] = {
		"Pieno giorno, monete in mano, e i kaldorei mezzi addormentati attorno a me. Sembro la sola persona sveglia a una festa che non è ancora cominciata.",
		"Sole fra le foglie e niente da fare. Perfino le Sentinelle sembrano assonnate. Potrei unirmi a loro.",
	},
	["dar.quest_complete.w23.reckon.001"] = {
		"Ho fatto quello che avevo detto. Tutto qui, e basta per raddrizzarmi un po' la schiena.",
		"Promesso, e mantenuto. È una sensazione piccola e squadrata, l'unica cosa dritta in questa città tutta curve.",
	},
	["dar.quest_complete.w23.reckon.002"] = {
		"Ogni incarico finito è un motivo in meno per restare qui. Quel conto non mi piace.",
		"Fatto, e ora la città non mi deve niente. Strano come questo la faccia sentire un po' più lontana.",
		"Ogni commissione che chiudo qui allenta un motivo per restare. Curioso quanto poco io voglia che si allenti.",
	},
	["dar.quest_complete.w23.reckon.003"] = {
		"sorride tra sé, per un attimo, a qualcosa che nessun altro vede, e prosegue.",
		"si concede un piccolo cenno privato, quello che si riserva a un lavoro ben chiuso, e riparte col passo più leggero.",
	},
	["dar.quest_complete.w23.reckon.004"] = {
		"Continuo ad aspettare il tranello. In altre città la ricompensa arriva con una seconda richiesta. Qui: un cenno, e silenzio. Sospetto.",
		"Niente 'già che ci sei'. Nessun favore in coda. Non mi fido, e mi piace da morire.",
	},
	["dar.quest_complete.w23.reckon.005"] = {
		"Cosa ho imparato? Che la pazienza paga, quasi sempre, e che io ne ho meno di chi mi ha pagato.",
		"Lezione del lavoro: i kaldorei non ti mettono mai fretta, e così te la metti da te.",
	},
	["dar.quest_complete.w23.reckon.006"] = {
		"non conta niente, non controlla niente: si concede solo un attimo, il lavoro alle spalle e la città davanti.",
		"lascia che la piccola soddisfazione si posi, come si lascia raffreddare il tè prima di berlo.",
	},
	["dar.quest_complete.w23.reckon.007"] = {
		"Nessuno mi ha visto farlo, e nessuno qui se ne vanterà per me. L'unico testimone sono io, e la cosa mi soddisfa.",
		"Niente folla, niente araldi. Solo il saperlo, privato come una moneta nello stivale.",
	},
	["dar.quest_complete.w23.reckon.008"] = {
		"Bene. Una cosa buona al mondo che prima non c'era.",
		"Ecco. Il mondo è un pochino migliore. Proprio un pochino.",
	},
	["dar.quest_complete.w23.reckon.009"] = {
		"Darkshore giace in rovina oltre l'acqua, e io qui mi compiaccio di un piccolo lavoro. Forse è giusto. Forse è coi piccoli lavori che le rovine smettono di allargarsi.",
		"Tanto di rotto oltre il mare, e quassù ho aggiustato una cosa sola. Non è un pareggio. È un inizio.",
	},
	["dar.quest_complete.w23.reckon.010"] = {
		"canticchia qualche nota, poi sente quanto lontano arrivano in questa città silenziosa e lascia morire il motivo.",
		"comincia a fischiettare, ci ripensa, e si accontenta di un piccolo cenno soddisfatto rivolto al sentiero.",
	},
	["dar.quest_complete.w23.reckon.011"] = {
		"Una cosa in più rimessa a posto nella nostra città. La guerra prende tanto; è bello, per una volta, dare qualcosa all'albero.",
		"Un piccolo lavoro per la mia gente. Le Sentinelle in Ashenvale danno molto di più, ma anche questo conta.",
	},
	["dar.quest_complete.w23.reckon.012"] = {
		"Credo che ci ripenserò più avanti, su qualche strada rumorosa lontano da qui. È lì che i momenti quieti mi raggiungono.",
		"Certi lavori li dimentico al villaggio dopo. Questo credo di tenerlo, per una ragione che non so dire.",
	},
	["dar.quest_complete.w23.reckon.013"] = {
		"Penso alle Sentinelle che tengono la linea in Ashenvale mentre io sbrigo commissioni quassù. Poi penso: qualcuno deve pur mandare avanti la città alle loro spalle.",
		"Un lavoro piccolo, accanto alla guerra in Ashenvale. Ma alla fine la guerra si fa per questo: perché alle spalle resti una città in piedi.",
	},
	["dar.quest_complete.w23.reckon.014"] = {
		"Lo chiamerei un lavoretto ben fatto. Qualcuno qui lo chiamerebbe un discreto inizio.",
		"Fatto con garbo, modestia a parte. E quassù nessun altro lo dirà ad alta voce.",
	},
	["dar.quest_complete.w23.reckon.015"] = {
		"C'è un tipo di stanchezza che arriva solo a lavoro finito. È una stanchezza buona. Sotto queste foglie sta bene.",
		"Stanchezza da lavoro concluso, non da strada. È tutta lì la differenza.",
		"Stanchezza, sì, ma di quella pulita, di quella con un motivo attaccato.",
	},
	["dar.quest_complete.w23.reckon.016"] = {
		"siede un momento su un gradino basso dopo i ringraziamenti, i gomiti sulle ginocchia, a godersi la cosa rara e semplice di essere contenti.",
		"si siede sul bordo di un'aiuola di muschio, riposta la borsa, e lascia che il momento sia completo.",
	},
	["dar.quest_complete.w23.reckon.017"] = {
		"Il buon lavoro merita un momento di quiete. Che fortuna: questa città ne è fatta.",
		"Questa me la sono guadagnata. Me la godo un minuto.",
	},
	["dar.quest_complete.w23.reckon.018"] = {
		"Grazie della fiducia. So che qui nessuno la concede alla leggera.",
		"Per voi contava. A me basta questo.",
		"Mi fa piacere che sia toccato a me.",
	},
	["dar.quest_complete.w23.reckon.019"] = {
		"Toh. È andata bene.",
		"Gestita bene, se nessuno si offende a sentirmelo dire.",
		"Nessun reclamo, nessun incidente. Lo segno fra le cose andate bene.",
	},
	["dar.quest_complete.w23.reckon.020"] = {
		"Finito al buio, coi kaldorei attorno a me nel pieno da fare. Io ho voglia di dormire; la città ha voglia di cominciare.",
		"La luna è alta fra le foglie e non ho nessun posto dove andare. Il modo migliore di finire.",
	},
	["dar.quest_complete.w23.reckon.021"] = {
		"Compenso in tasca, e la pioggia mi ha trovato. Bene: lava via il lavoro, e non ho fretta di asciugarmi.",
		"Lavoro finito, monete in tasca, pioggia sul colletto. Lascio che penetri un po': me le sono guadagnate tutte e due.",
	},
	["dar.quest_complete.w23.reckon.022"] = {
		"Gli elfi non si fidano degli aggeggi, ma di me si sono fidati. La prendo come un passo avanti per tutti gli gnomi.",
		"Nessuno mi ha chiesto cosa inventerò con la ricompensa. Discrezione, o paura. Lusinghiere entrambe.",
	},
	["dar.quest_complete.w23.reckon.023"] = {
		"Una piccola soddisfazione, pulita e intera. Nessuno ci canterà sopra, ed è proprio della misura giusta.",
		"Una cosa piccola fatta bene. Sta in una mano. Meglio una dozzina così che una grande impresa che non riesco a portare.",
	},
	["dar.quest_complete.w23.reckon.024"] = {
		"Ecco. Ora può riposare, è in buone mani.",
		"Tolto dalle mie mani, e finito in mani migliori.",
	},
	["dar.quest_complete.w23.reckon.025"] = {
		"È stato bello. Strano quanto di rado lo dica ad alta voce.",
		"Che soddisfazione. Ecco, l'ho detto, e nessuno ha fatto shh.",
	},
	["dar.quest_complete.w23.spoken.001"] = {
		"Grazie. Lo dico una volta sola, e piano, visto che qui pare si usi così.",
		"Ti ringrazio. Ho scelto le parole con cura prima di entrare; spero che reggano.",
		"Grazie, allora. Una parola sola, e lascio che faccia il suo lavoro.",
	},
	["dar.quest_complete.w23.spoken.002"] = {
		"È scortese contarle davanti a te? Mi sembra scortese. Le conto dietro quella colonna.",
		"Non le conto qui. Le conto più in là, dove nessun kaldorei mi veda muovere le labbra.",
	},
	["dar.quest_complete.w23.spoken.003"] = {
		"Ishnu-alah. L'ho detto bene? La tua faccia dice quasi.",
		"A te, Ishnu-alah. Finora l'avevo provato solo con una fontana, e la fontana non mi ha mai corretto.",
	},
	["dar.quest_complete.w23.spoken.004"] = {
		"Come si dice 'non c'è di che' nella tua lingua? Vorrei averlo pronto per la prossima volta.",
		"Insegnami la parola per 'è stato un piacere'. Rispondo sempre al tuo grazie nella lingua comune, e suona così spoglia.",
	},
	["dar.quest_complete.w23.spoken.005"] = {
		"Era troppo profondo, quell'inchino? Con i kaldorei non lo capisco mai. Troppo poco, allora? Una via di mezzo.",
		"Devo inchinarmi, o basta un cenno? Faccio tutti e due, e tu tieni quello che va bene.",
	},
	["dar.quest_complete.w23.spoken.006"] = {
		"Scusa, mi è uscito più forte del previsto. Dicevo: è fatto.",
		"È FATTO. Scusa. È fatto. La seconda era la versione adatta a questa città.",
	},
	["dar.quest_complete.w23.spoken.007"] = {
		"Ti prego, non alzarti. Trovo da me la strada. Con calma, lo prometto.",
		"Non c'è bisogno di alzarsi. La via d'uscita la conosco, più o meno, e non la farò di corsa.",
	},
	["dar.quest_complete.w23.spoken.008"] = {
		"È stato un onore. Non è una parola che spendo spesso.",
		"Un onore, davvero. Quella parola la tengo per le occasioni rare, e questa lo era.",
		"Che sia contato come fatto, e fatto bene.",
	},
	["dar.quest_complete.w23.spoken.009"] = {
		"Vedo del sollievo. Sollievo kaldorei, s'intende: un sopracciglio, appena appena.",
		"Era un sorriso, quello? È comparso e sparito così in fretta che dovrò fidarmi sulla parola.",
	},
	["dar.quest_complete.w23.spoken.010"] = {
		"Ti stringerei la mano, ma ho notato che qui non lo fa nessuno. Un cenno, allora. Bello deciso.",
		"Mani a posto, sì, questo l'ho imparato. Ecco invece il mio cenno migliore.",
	},
	["dar.quest_complete.w23.spoken.011"] = {
		"È stato un piacere. Un piacere e una discreta seccatura, a dire il vero. Più piacere.",
		"Felice di aiutare. Davvero. I miei piedi un po' meno, ma non hanno diritto di voto.",
	},
	["dar.quest_complete.w23.spoken.012"] = {
		"C'è qualcun altro a cui dovrei dirlo? Mi sembra una notizia che qualcuno dovrebbe sentire.",
		"Devo dirlo anche a qualcun altro? A una sacerdotessa, a una Sentinella, a un gufo di passaggio?",
	},
	["dar.quest_complete.w23.spoken.013"] = {
		"Potrei raccontarti com'è andata. No? Scelta saggia: per lo più si è trattato di camminare.",
		"Vuoi il resoconto completo? Il tuo silenzio dice di no, ed è un silenzio molto eloquente.",
	},
	["dar.quest_complete.w23.spoken.014"] = {
		"Tienilo al sicuro, va bene? Mi dispiacerebbe doverlo rifare.",
		"Mettilo via con cura. Una volta è bastata, e lo dico con tutto il rispetto.",
	},
	["dar.quest_complete.w23.spoken.015"] = {
		"Pace a te, e al tuo lavoro.",
		"Che il tuo lavoro scorra quieto, d'ora in poi.",
		"Pace su qualunque cosa farai con le tue mani.",
	},
	["dar.quest_complete.w23.spoken.016"] = {
		"Elune-adore. L'ho sentito dire nei congedi; spero vada bene anche per questo.",
		"Se posso prendere in prestito le parole: Elune-adore. Me le ha dette qualcuno in banca, e mi è piaciuto il suono.",
	},
	["dar.quest_complete.w23.spoken.017"] = {
		"In questa città è facilissimo essere cortesi. Fa metà del lavoro al posto mio.",
		"Qui le buone maniere vengono gratis. Quasi non ho dovuto sforzarmi. Grazie.",
	},
	["dar.quest_complete.w23.spoken.018"] = {
		"Non serve ringraziare. Insomma. Un pochino sì. Ecco, la dose giusta. Grazie a te.",
		"Oh, non c'era bisogno. Va bene, l'hai fatto, ed è stato bello. Basta così.",
	},
	["dar.quest_complete.w23.spoken.019"] = {
		"C'era un momento in cui dovevo inginocchiarmi? Nessuno mi ha parlato di ginocchia.",
		"Adesso devo inginocchiarmi? Mi inginocchio. Dimmelo prima che decidano le mie ginocchia.",
	},
	["dar.quest_complete.w23.spoken.020"] = {
		"Sistemato, allora. Se dovesse mai disfarsi, conosci la mia faccia.",
		"Questo è quanto. Se dovesse sfilacciarsi, vieni a cercarmi: saprò di chi è la colpa.",
	},
	["dar.quest_complete.w23.spoken.021"] = {
		"Posso chiedere cosa significa quell'intaglio sopra la porta? No? Magari alla prossima visita.",
		"Una domanda prima di andare: chi ha intagliato tutte quelle foglie? Ah. Risposta lunga. La prossima volta.",
	},
	["dar.quest_complete.w23.spoken.022"] = {
		"Ho detto grazie in tre modi diversi di fila. Almeno uno sarà stato quello giusto.",
		"Grazie, ti ringrazio, obbligatissimo: li ho usati tutti. Uno sarà pure andato a segno.",
	},
	["dar.quest_complete.w23.spoken.023"] = {
		"Ho parlato troppo. Dall'altra parte hanno ascoltato ogni parola, ed è stato peggio.",
		"Mi sono {g:dilungato|dilungata}. Altrove qualcuno mi avrebbe interrotto. Qui mi hanno lasciato finire, fino all'ultima parola, e quella è stata la punizione.",
	},
	["dar.quest_complete.w23.spoken.024"] = {
		"La prossima volta lascerò che la pausa faccia il suo corso. Quello che un kaldorei dice dopo un silenzio così lungo merita di essere ascoltato.",
		"Ho riempito il silenzio troppo presto. Se avessi aspettato, credo che si sarebbe detto di più. Una lezione per la prossima consegna.",
	},
	["dar.quest_complete.w23.spoken.025"] = {
		"C'è altro? Chiedi adesso, finché resto qui: capita di rado.",
		"Ti serve altro? Dillo ora, approfitta della sosta.",
	},
	["dar.quest_complete.w23.spoken.026"] = {
		"Ho fatto ciò che era stato chiesto. Né più né meno, e volentieri.",
		"Quello che hai chiesto, l'ho fatto. Il resto lo lascio al tuo giudizio.",
		"È finito come lo volevi. Se manca qualcosa, preferisco sentirlo da te.",
	},
	["dar.quest_complete.w23.spoken.027"] = {
		"Grazie della pazienza. Lo so, non sono il genere di visita che riposa.",
		"Gentile a sopportarmi. Mi agito, lo so.",
	},
	["dar.quest_complete.w23.spoken.028"] = {
		"Stavo per dire 'a presto'. Per un kaldorei non so cosa voglia dire 'presto'. Ho detto 'addio', invece.",
		"'Alla prossima', ho detto, chiedendomi quanto lontana suoni 'la prossima' alle orecchie di un kaldorei.",
	},
	["dar.quest_complete.w23.spoken.029"] = {
		"Va' piano, e che il lavoro resista. Elune-adore.",
		"Andu-falah-dor. È fatto, ed è fatto per i nostri.",
	},
	["dar.quest_complete.w23.spoken.030"] = {
		"Non dirò mai grazie come lo dice un kaldorei, ma continuerò a provarci finché qualcuno non sorride.",
		"Grazie, alla mia maniera semplice. Voi lo fate sembrare una canzone; dalle mie parti lo si dice e basta.",
	},
	["dar.quest_complete.w23.token.001"] = {
		"Oltre alla ricompensa, una foglia sola, offerta senza spiegazioni. Chiederò a un druido cosa significa. Oppure no, e me la terrò lo stesso.",
		"Insieme al compenso, qualcuno ha infilato una foglia. Nessun biglietto. L'ho messa tra le pagine del mio diario, e immagino che sia una risposta.",
	},
	["dar.quest_complete.w23.token.002"] = {
		"sente una mano leggera posarsi un istante sulla sua spalla dopo i ringraziamenti, e poi sollevarsi.",
		"viene {g:sfiorato|sfiorata} una volta sulla spalla mentre la faccenda si chiude, un peso breve, sparito prima che si possa rispondere.",
		"riceve un breve tocco sul braccio mentre la faccenda si chiude, leggero come una foglia che cade e sparito altrettanto in fretta.",
	},
	["dar.quest_complete.w23.token.003"] = {
		"Dopo la consegna mi hanno offerto una tazza d'acqua. Solo acqua, fresca e pulita. L'ospitalità, alla maniera kaldorei, sta tutta in una tazza.",
		"Una coppa d'acqua, porta quando la faccenda era chiusa. Nient'altro. In questa città è sembrato un invito a restare per cena.",
	},
	["dar.quest_complete.w23.token.004"] = {
		"L'inchino fa parte del compenso? Perché ne accetterei volentieri altri.",
		"Accetto l'inchino al posto della ricevuta.",
		"Quell'inchino lo conto come un premio extra.",
	},
	["dar.quest_complete.w23.token.005"] = {
		"Quell'ultimo sguardo non era per il lavoro. Era per me, a misurarmi, come devono aver misurato ogni visitatore in ogni età del mondo. Spero di aver fatto bella figura.",
		"Lo sguardo finale è durato abbastanza da sembrare una decisione. Qualunque cosa abbia deciso, mi ha lasciato andare con un cenno.",
	},
	["dar.quest_complete.w23.token.006"] = {
		"fa qualche passo verso il sentiero accanto a chi ha affidato il compito, una cortesia che finisce senza parole alla prima svolta.",
		"si ritrova qualcuno al fianco per un breve tratto dopo i ringraziamenti, poi i passi si separano, senza una parola.",
	},
	["dar.quest_complete.w23.token.007"] = {
		"Alla fine c'è stato un gesto, due dita alla fronte, credo. L'ho rifatto anch'io. Forse ho appena acconsentito a qualcosa.",
		"Ho imitato il gesto che mi hanno fatto, perché non farlo sembrava scortese. A giudicare dalla pausa, l'ho azzeccato quasi del tutto.",
	},
	["dar.quest_complete.w23.token.008"] = {
		"Custodite il vostro grazie. Io custodirò il mio.",
		"Mi ricorderò di questa cortesia. E di chi me l'ha mostrata.",
	},
	["dar.quest_complete.w23.token.009"] = {
		"In questa città la ricompensa non è mai tutto. C'è sempre un piccolo extra: una parola, un cenno che dura un attimo in più, qualche passo fatto insieme. Ho cominciato a cercarlo.",
		"Ho imparato a fare caso alla piccola cosa che arriva dopo il pagamento. C'è quasi sempre. Stavolta mi hanno semplicemente chiesto il nome.",
	},
	["dar.quest_complete.w23.token.010"] = {
		"giunge brevemente i palmi in risposta ai ringraziamenti, un gesto imparato guardando gli altri, e viene accolto con gentilezza.",
		"risponde a mani giunte e con un breve inchino, ricordati a metà dai gradini del tempio, e la cortesia presa in prestito viene accettata senza commenti.",
	},
	["dar.quest_complete.w23.token.011"] = {
		"Un tempo avevamo tutto il tempo del mondo per le cortesie. Ora ne abbiamo meno, e lo troviamo comunque. Mi sembra più coraggioso di quanto appaia.",
		"Da Hyjal i nostri anni sono contati, eppure una consegna riceve ancora il suo inchino intero. Spendere tempo in cortesia ora è una scelta. Continuiamo a farla.",
	},
	["dar.quest_complete.w23.token.012"] = {
		"Un inchino per un inchino. Alla prossima.",
		"Altrettanto a voi, e anche di più.",
	},
	["dar.quest_complete.w23.token.013"] = {
		"In questa città il grazie arriva con un gesto, il gesto con uno sguardo, e lo sguardo con un silenzio che dovrei capire. Ne ho capito metà.",
		"Grazie, gesto, sguardo, silenzio. Mi dicono che sia una frase completa. Io ho afferrato la prima parola.",
	},
	["dar.quest_complete.w23.token.014"] = {
		"riceve, insieme alla ricompensa, un fiore pressato di un viola così cupo da sembrare quasi blu, e lo rigira un po' tra le dita prima di metterlo via.",
		"si vede consegnare un piccolo fiore pressato insieme al compenso, il genere di pensiero che a nessun mercante verrebbe in mente, e lo ripone con cura.",
	},
	["dar.quest_complete.w23.token.015"] = {
		"La gratitudine kaldorei non ti insegue fuori dalla porta. Viene data intera, sul momento, e poi tocca a te portarla. Nessuno ne parlerà più, e nessuno la dimenticherà.",
		"Qui non ringraziano due volte. Una, per intero, e poi la cosa riposa. Scopro che mi piace sapere dove finisce una cosa.",
	},
	["dar.quest_complete.w23.token.016"] = {
		"alla fine di tutto incrocia lo sguardo di chi ha affidato il compito e lo regge con fermezza, perché distogliere gli occhi per primi, in questa città, pare la cortesia minore.",
		"ricambia lo sguardo quieto con cui la faccenda si chiude, e non guarda altrove finché non lo fa chi sta di fronte.",
	},
	["dar.quest_complete.w23.token.017"] = {
		"Alla fine un cenno che voleva dire, se non sbaglio, torna se c'è bisogno. Mi piacerebbe che qui ci fosse bisogno di me.",
		"Il congedo ha lasciato una porta aperta. Non a voce, si capisce. In questa città niente di importante si dice a voce.",
	},
	["dar.quest_complete.w23.token.018"] = {
		"riceve i ringraziamenti con la luce della luna sulla pietra tra loro, e l'inchino che segue si illumina d'argento per tutta la sua lenta durata.",
		"accetta la ricompensa sotto una luna così chiara da mostrare ogni linea del viso kaldorei che si abbassa nel ringraziare.",
	},
	["dar.quest_complete.w23.token.019"] = {
		"Era un inchino o un congedo? Tutti e due? Tutti e due. Bene.",
		"Ah, il cenno. Questo ormai lo conosco. Grazie anche a voi.",
	},
	["dar.quest_complete.w23.token.020"] = {
		"E grazie per la cortesia. Non tutte le città ne hanno così tanta da regalare.",
		"Le vostre buone maniere hanno costretto le mie a migliorare. Grazie anche per questo.",
	},
	["dar.quest_complete.w23.token.021"] = {
		"Noterete che sto parlando piano. Sto imparando come si fa, qui.",
		"Vi ringrazierei come si deve, ma farei più rumore di mezza terrazza.",
	},
	["dar.quest_complete.w23.vow.001"] = {
		"Hai la mia parola: se mai ci fosse da rifarlo, chiedi a me.",
		"La prossima volta chiedi di me. Per nome, se te lo ricordi. Te lo ricorderai, immagino.",
	},
	["dar.quest_complete.w23.vow.002"] = {
		"Chiamami ancora. Verrò, e mi sforzerò tanto di non correre.",
		"Mandami a chiamare quando vuoi. Arriverò passeggiando con dignità, per rispetto della casa.",
	},
	["dar.quest_complete.w23.vow.003"] = {
		"Ovunque andrò, parlerò bene di Darnassus. Questo da me se l'è guadagnato.",
		"Devo a questa città qualche buona parola. La spenderò su ogni strada che prenderò.",
	},
	["dar.quest_complete.w23.vow.004"] = {
		"La prossima volta che ti serve qualcuno, chiedi prima a me. Mi piace essere {g:il primo|la prima}.",
		"Tienimi a mente, va bene? Verso la cima della lista. Dicono che sono affidabile.",
	},
	["dar.quest_complete.w23.vow.005"] = {
		"Non faccio molte promesse, quindi ascolta questa: se chiami, verrò.",
		"Una promessa, allora, e le poche che faccio le mantengo. Chiama, e risponderò.",
	},
	["dar.quest_complete.w23.vow.006"] = {
		"Mi ricorderò del volto che mi ha {g:ringraziato|ringraziata} qui. Mi sembra giusto: quel volto ricorderà il mio molto più a lungo.",
		"Chi mi ha appena detto grazie si porterà dietro la mia faccia per secoli. Il minimo è che io tenga la sua per un po'.",
	},
	["dar.quest_complete.w23.vow.007"] = {
		"Ho detto che tornerò se avranno bisogno. Lo pensavo davvero, e la cosa mi ha un po' {g:sorpreso|sorpresa}.",
		"Alla fine mi è scappata una promessa. Mi sono {g:sentito|sentita} farla e non ho trovato nessuna voglia di ritirarla.",
	},
	["dar.quest_complete.w23.vow.008"] = {
		"Se mai avrà bisogno di aggiustamenti, chiama me prima che altri ci mettano le mani.",
		"Se poi andrà curato, tocca a me curarlo. Ricordatelo.",
	},
	["dar.quest_complete.w23.vow.009"] = {
		"Sarò nei paraggi, ho detto, se servirà. In questa città 'nei paraggi' può voler dire molto a lungo. Spero lo prendano bene.",
		"'Chiamami quando vuoi', ho detto. A chi conta in secoli è una promessa grossa. La manterrò.",
	},
	["dar.quest_complete.w23.vow.010"] = {
		"Un favore alla mia gente, sotto i miei rami. Il grazie suonava diverso. Più vicino.",
		"Lavorare per sconosciuti è una cosa. Farlo per i miei, qui, mi ha lasciato meno da dire, e ogni parola più sentita.",
	},
	["dar.quest_complete.w23.vow.011"] = {
		"L'Alleanza è unita, o almeno così dicono gli stendardi. Eccone una piccola prova.",
		"Gli alleati si aiutano. Detto in un trattato suona semplice. Fatto con le proprie mani è meglio.",
	},
	["dar.quest_complete.w23.vow.012"] = {
		"{g:Pagato|Pagata} dai kaldorei, e nessuno mi ha guardato due volte. Cappuccio giù, poche parole, e via.",
		"Ho ringraziato un elfo nella mia migliore lingua comune, con la voce piccola. Se sapessero in quale borsa sono finite quelle monete, le conterebbero diversamente.",
	},
	["dar.quest_complete.w23.worth.001"] = {
		"Fra un secolo qualcuno qui potrebbe ancora usare quel che ho portato, senza sapere chi l'ha portato. Scopro che non mi dispiace.",
		"Molto dopo di me, una mano kaldorei prenderà questa cosa senza chiedersi chi l'abbia portata. Va bene così. Il lavoro serve a questo.",
		"Quel che ho consegnato sopravvivrà a lungo al mio nome, in questa città. Meglio. I nomi sono la parte meno utile.",
	},
	["dar.quest_complete.w23.worth.002"] = {
		"Ho corso. Ho corso per un popolo che considera dieci anni una breve pausa. Potevo fermarmi a pranzo.",
		"Tutta quella fretta, consegnata a qualcuno che avrebbe aspettato cent'anni senza aggrottare la fronte.",
		"Fretta da vendere, per chi misura i ritardi in decenni.",
	},
	["dar.quest_complete.w23.worth.003"] = {
		"Cosa vale il mio lavoro contro le loro ere? Un sassolino contro una montagna. Eppure l'hanno soppesato con cura, come fosse oro.",
		"Accanto alle loro vite, la mia fatica è un granello di sabbia. Eppure quel granello l'hanno girato e guardato per bene.",
		"Messa accanto a dieci secoli, la mia fatica conta appena. Nessuno qui l'ha trattata così, e me ne sono accorto.",
	},
	["dar.quest_complete.w23.worth.004"] = {
		"riceve in congedo un lieve inchino, e lo porta via come una cosa di valore, cosa che in questa città forse è davvero.",
		"riprende il cammino pensando più all'inchino di commiato che alle monete, intuendo quale dei due fosse più raro.",
	},
	["dar.quest_complete.w23.worth.005"] = {
		"Un tempo un kaldorei poteva aspettare qualunque cosa. Da Hyjal anche i loro anni finiscono, come quelli di tutti. Spero di non avergliene sprecati.",
		"Ora anche i loro anni hanno una fine, come i miei. Spero che il lavoro abbia ripagato il tempo speso ad aspettarmi.",
	},
	["dar.quest_complete.w23.worth.006"] = {
		"Ne è valsa la pena? Chiedetemelo fra qualche secolo. Anzi, chiedetelo a loro: ci saranno ancora.",
		"Valeva la fatica? Qualcuno qui lo saprà. Fra trecento anni circa.",
		"Il tempo dirà se è servito. Qui il tempo parla molto, molto adagio.",
	},
	["dar.quest_complete.w23.worth.007"] = {
		"Moneta onesta e ringraziamenti sinceri. Certe volte non si può chiedere altro.",
		"Paga giusta e una parola sentita. Mi hanno pagato peggio in città più belle. Be', forse non più belle.",
	},
	["dar.quest_complete.w23.worth.008"] = {
		"Chissà se un giorno, fra un secolo, ne parleranno, e io sarò una comparsa: uno straniero che aiutò una volta. Ci sono modi peggiori di essere ricordati.",
		"In qualche racconto kaldorei, fra cent'anni, sarò 'un viandante che diede una mano'. Senza nome. Mi piace più di quanto pensassi.",
	},
	["dar.quest_complete.w23.worth.009"] = {
		"soppesa la borsa nel palmo, guarda i volti pazienti della città e la ripone quasi con imbarazzo per quanto è piccola.",
		"passa lo sguardo dal pugno di monete agli elfi senza fretta sul sentiero, e per un attimo sembra chiedersi che cosa valga il denaro per chi ha tanto tempo.",
	},
	["dar.quest_complete.w23.worth.010"] = {
		"Sono entrati nell'Alleanza tardi, e con cautela. Ogni lavoro onesto che uno straniero fa per loro è un piccolo argomento a favore di quella scelta.",
		"Un alleato che mantiene il patto: non ero altro, poco fa. Non è poco, per un popolo che ancora decide cosa pensare di noi.",
	},
	["dar.quest_complete.w23.worth.011"] = {
		"Che duri quanto coloro che serve.",
		"Che mi sopravviva. Qui è un augurio facile.",
	},
	["dar.quest_complete.w23.worth.012"] = {
		"Tutta la mia carriera, per questa gente, starà comoda fra due dei loro sonnellini.",
		"Per loro sono una visita breve e utile, come un uccello che si posa sulla ringhiera. Arriva, serve, riparte.",
	},
	["dar.quest_complete.w23.worth.013"] = {
		"Una borsa per me, un favore per voi. Credo che la metà più duratura sia toccata a voi.",
		"Paga giusta. Anche se sospetto che voi ne trarrete più anni di me.",
		"Tenetelo bene. Lo avrete molto più a lungo di quanto io avrò queste monete.",
	},
	["dar.quest_complete.w23.worth.014"] = {
		"Un piacere aiutare. Raccontatelo ai nipoti. O ai nonni, che probabilmente sono ancora in giro.",
		"Ricordatemi con affetto. Il tempo non vi manca.",
		"Se fra cent'anni qualcuno chiede, il nome è il mio. Tanto per chiarezza.",
	},
	["dar.quest_complete.w23.worth.015"] = {
		"Chiedi a un kaldorei quanto vale un favore e riceverai uno sguardo lungo, poi la storia di una foresta che non c'è più. La mia domanda la tengo piccola.",
		"Qui un favore si misura contro foreste bruciate e un pozzo che ha annegato il mondo. La mia commissione non ci si avvicina, e nessuno me ne fa una colpa.",
	},
	["dar.quest_complete.w23.worth.016"] = {
		"si ferma a bordo del sentiero a guardare una sacerdotessa che accudisce una lampada con lenta cura, e sembra misurare il lavoro finito con lo stesso metro paziente.",
		"osserva un elfo spazzare un solo gradino con gesti lunghi e attenti, e mette il lavoro appena finito al suo posto, accanto a quello.",
	},
	["dar.quest_complete.w23.worth.017"] = {
		"Certi lavori si fanno per la moneta. Questo sembrava fatto per il luogo stesso, e il luogo non paga, quindi la moneta farà le sue veci.",
		"La borsa dice che c'è stato un compenso. La città, chissà come, dice che c'è stato un grazie. Non sono la stessa cosa, e preferisco la seconda.",
	},
	["dar.quest_complete.w23.worth.018"] = {
		"A Stormwind mi avrebbero stretto la mano e dato una pacca sulla spalla. Qui, uno sguardo e un inchino, e in qualche modo il grazie arriva più a fondo.",
		"Un lavoro svelto da umano per una città lenta da elfi. Spero non sia sembrato scortese.",
	},
	["dar.quest_complete.w23.worth.019"] = {
		"Una paga riscossa in cima a un albero, da gente a cui non è mai piaciuta una forgia. Ci brinderò lo stesso, appena trovo qualcosa di più forte del tè.",
		"Lavoro onesto, anche in cima a un albero. La parola di un nano vale ovunque, e ora questi elfi lo sanno.",
	},
	["dar.quest_complete.w23.worth.020"] = {
		"Non saprò mai che fine farà. È il patto: io faccio il lavoro, e il finale è loro.",
		"La fine della storia resta a loro. A me toccano la parte di mezzo e una borsa di monete.",
	},
	["dar.rest_enter.w23.abide.001"] = {
		"C'è la locanda sulla Craftsmen's Terrace, con un letto, se lo voglio. E c'è anche questo pezzo di muschio, che non mi ha chiesto una moneta.",
		"Una stanza alla locanda sarebbe la scelta saggia. L'erba vicino all'acqua è più a portata, e la saggezza può aspettare.",
	},
	["dar.rest_enter.w23.abide.002"] = {
		"mette sulla bilancia la locanda e l'erba, l'erba e un arco tranquillo, e alla fine si sistema proprio dove si trova.",
		"valuta diversi bei posti per riposare, tutti a pochi passi, e sceglie l'unico che non richiede nemmeno un passo.",
		"si avvia verso la locanda, incontra lungo la strada un tratto d'erba morbida e non va oltre.",
	},
	["dar.rest_enter.w23.abide.003"] = {
		"I kaldorei hanno tempo da vendere. Stando in mezzo a loro, un po' di quel tempo sembra attaccarsi anche a me.",
		"Per un popolo che conta in secoli, un'ora sull'erba non è niente. Ho deciso di contare come loro, almeno per adesso.",
	},
	["dar.rest_enter.w23.abide.004"] = {
		"prende posto su una seduta bassa nella sala curva della locanda, e le voci sommesse intorno continuano senza perdere una parola.",
		"trova un angolo della locanda dove le lampade sono più fioche e ci sprofonda come in acqua profonda.",
	},
	["dar.rest_enter.w23.abide.005"] = {
		"Una locanda dove nessuno canta, nessuno litiga sui dadi e nessuno ha rovesciato niente. Il chiasso quasi mi manca. Quasi.",
		"Mi è comparsa accanto al gomito una tazza di qualcosa alle erbe, senza che la chiedessi. Non so cosa sia, e non intendo domandarlo.",
	},
	["dar.rest_enter.w23.abide.006"] = {
		"Un angolo tranquillo e qualcosa di caldo da bere, se non è un disturbo. Grazie.",
		"È libero questo posto? Sì? Allora adesso è occupato, per un'ora o tre.",
	},
	["dar.rest_enter.w23.abide.007"] = {
		"Da qui, a occhi chiusi, sento le foglie lassù sfregarsi l'una contro l'altra: un suono secco e lento, come pagine voltate da qualcuno che non ha fretta.",
		"La chioma fa un rumore come un lungo sospiro che non finisce mai. In tutto Kalimdor non ho trovato niente di meglio per addormentarmi.",
	},
	["dar.rest_enter.w23.abide.008"] = {
		"scivola verso il sonno sotto la grande chioma, si desta ogni tanto per una goccia che cade o una falena che passa, e si riassopisce.",
		"sonnecchia nell'ombra verde, una mano sullo zaino, e non si muove nemmeno quando un cervo passa lì accanto a passi cauti.",
	},
	["dar.rest_enter.w23.abide.009"] = {
		"Ripassando la giornata trovo una cosa fatta bene e tre che farei diversamente. Per i miei conti è una buona giornata.",
		"Che cosa ho imparato? Poco. Dove mettere i piedi, a chi affidare il resto. Piccole cose, che però si accumulano.",
	},
	["dar.rest_enter.w23.abide.010"] = {
		"Le lampade lungo i sentieri sono le sole sveglie, oltre a me e alle Sentinelle. Sto per uscire da questa compagnia.",
		"È tardi, e la città si è fatta ancora più sommessa del solito. Mi adeguo: fra un'ora dormirò.",
	},
	["dar.rest_enter.w23.abide.011"] = {
		"si sistema sotto una foglia larga che lascia scivolare la pioggia in due tende sottili ai lati, all'asciutto lì in mezzo e senza alcuna fretta di andarsene.",
		"trova un posto sotto una sporgenza di legno vivo e ascolta la pioggia gocciolare dal bordo, felice di restare dov'è.",
	},
	["dar.rest_enter.w23.abide.012"] = {
		"La luce del giorno scende tra le foglie a pezzi. Uno è atterrato sulle mie ginocchia, e me lo tengo.",
		"Una chiazza di sole ha trovato la strada tra le fronde fino al mio angolo d'erba. Ci sto {g:steso|stesa} come un gatto, senza vergogna.",
	},
	["dar.rest_enter.w23.abide.013"] = {
		"La nebbia ha avvolto le terrazze nella lana. Un buon momento per restare dove sono e lasciare che il mondo si sfochi.",
		"La nebbia è salita dal lago e si è inghiottita la riva opposta. Qualunque cosa ci fosse là, può aspettare che la restituisca.",
	},
	["dar.rest_enter.w23.abide.014"] = {
		"riposa a portata d'orecchio dal tempio, dove una voce bassa canta da qualche parte all'interno, e la lascia andare senza cercare di afferrarne le parole.",
		"si siede dove passano le sacerdotesse di Elune dirette al tempio, e risponde a ogni loro piccolo cenno senza alzarsi.",
	},
	["dar.rest_enter.w23.abide.015"] = {
		"Sul sentiero qualcuno mi ha porto un frutto chiaro senza dire una parola. Lo mangio piano, perché qui tutto sembra chiederlo.",
		"Una tazza di qualcosa che sa di fiori e di steli verdi. A Stormwind non lo ordinerei due volte, ma qui è proprio quello che ci vuole.",
	},
	["dar.rest_enter.w23.abide.016"] = {
		"resta così a lungo nello stesso posto che le lampade lì vicino vengono accudite e regolate, senza che se ne accorga.",
		"non si sposta per tutto il tempo che i passanti impiegano a cambiare del tutto, un gruppo di volti quieti dopo l'altro.",
	},
	["dar.rest_enter.w23.abide.017"] = {
		"Il riposino di un kaldorei, mi dicono, può durare una stagione. Io mi accontento di un'ora e la chiamo ambizione.",
		"Una Sentinella mi ha raccontato di essersi riposata quassù per un mese, e di averlo chiamato un pisolino. Io punto più in basso.",
	},
	["dar.rest_enter.w23.abide.018"] = {
		"Non fateci caso. Mi esercito nell'usanza locale di non muovermi.",
		"Andate piano. Io resto qui, per un bel pezzo.",
	},
	["dar.rest_enter.w23.abide.019"] = {
		"Più tardi farò un piano. Per ora il piano è questo pezzo d'erba, e quel che verrà dopo.",
		"Ci sarà tempo per decidere dove andare. I kaldorei direbbero che il tempo c'è sempre. Per una volta sono d'accordo.",
	},
	["dar.rest_enter.w23.abide.020"] = {
		"conta due volte le monete della giornata, si perde al secondo giro e decide che il primo conto bastava.",
		"spiega una mappa sgualcita sulle ginocchia, la guarda per un po' senza leggerla davvero e la ripiega così com'è.",
	},
	["dar.rest_enter.w23.abide.021"] = {
		"Pace a questo luogo, e a chi lo custodisce.",
		"Che la vostra quiete duri, e la mia insieme a lei.",
	},
	["dar.rest_enter.w23.haven.001"] = {
		"Ashenvale brucia oltre l'acqua, e le Sentinelle scendono a difenderla. Quassù, per un po', mi è concesso di smettere di tendere l'orecchio.",
		"Qualunque cosa gli orchi stiano facendo alle vecchie foreste laggiù, fin quassù non arriva. Non finché riposo, almeno.",
	},
	["dar.rest_enter.w23.haven.002"] = {
		"In quasi ogni angolo di questa città c'è una Sentinella in vista. Per una volta vuol dire che non tocca a me fare la guardia.",
		"La guardia la fa qualcun altro, e con secoli di pratica. Posso chiudere tutti e due gli occhi.",
	},
	["dar.rest_enter.w23.haven.003"] = {
		"al primo fruscio tra le foglie allunga la mano verso l'arma, trova solo un gufo che si sistema su un ramo e la lascia ricadere, con un po' d'imbarazzo.",
		"si siede di fronte al sentiero aperto per vecchia abitudine; poi, dopo un po', gli volta le spalle apposta.",
	},
	["dar.rest_enter.w23.haven.004"] = {
		"C'è una sicurezza che viene dalle mura, e un'altra che viene dall'avere intorno gente molto antica e molto calma. Questa è la seconda.",
		"Nessun cancello, nessuna saracinesca, niente di sbarrato. La sicurezza di questa città sta nella sua gente, e la sua gente non ne dubita.",
	},
	["dar.rest_enter.w23.haven.005"] = {
		"Al sicuro come in pochi posti di Kalimdor, direi.",
		"Quassù non mi darà fastidio nessuno. Lo sento nelle spalle.",
		"Neanche un borsaiolo in vista. Potrei farci l'abitudine.",
	},
	["dar.rest_enter.w23.haven.006"] = {
		"Questa città intera è un riparo costruito da chi aveva perso il proprio. Riposarci è come accettare una sedia da qualcuno che un tempo è rimasto in piedi.",
		"I kaldorei sanno cosa vuol dire aver bisogno di un posto dove fermarsi. Dopo la guerra ne hanno costruito uno su un albero, e ci lasciano sedere anche gli estranei.",
	},
	["dar.rest_enter.w23.haven.007"] = {
		"lascia la borsa sull'erba, incustodita, e continua a guardarla, quasi non credesse alla propria audacia.",
		"infila la borsa delle monete sotto un ginocchio per abitudine; poi, in un posto simile, la cosa pare sciocca, e la tira fuori. Poi la rimette sotto.",
	},
	["dar.rest_enter.w23.haven.008"] = {
		"Sotto questi rami non dormo con un orecchio aperto. È tutta qui la differenza tra un bivacco e casa.",
		"Là fuori riposo come una Sentinella. Qui posso riposare come chiunque altro del mio popolo, ed è più raro di quanto sembri.",
	},
	["dar.rest_enter.w23.haven.009"] = {
		"Se qualcosa viene a cercarmi qui, dovrà prima passare sopra qualche migliaio d'anni di Sentinelle.",
		"Il pisolino più sicuro di tutta la stagione. Forse anche il più sorvegliato.",
	},
	["dar.rest_enter.w23.haven.010"] = {
		"si sistema vicino a una Sentinella a riposo, che si sta pettinando i lunghi capelli e rivolge un cenno che non chiede niente.",
		"divide un tratto d'erba con una Sentinella fuori servizio che si scioglie le trecce: tra loro non passa parola, né serve.",
		"riposa accanto a una Sentinella fuori servizio che unge le cinghie dell'armatura con passate lente e regolari, e trova quel ritmo rassicurante.",
	},
	["dar.rest_enter.w23.haven.011"] = {
		"Un nano qui vicino russa con gli stivali ancora ai piedi, e nessuno in questa raffinatissima città ha osato svegliarlo. Li rispetto tutti.",
		"Una gnoma dorme su un gradino con un libro aperto sul petto. Se ci riesce lei, ci riesco anch'io.",
	},
	["dar.rest_enter.w23.haven.012"] = {
		"Riposare nella città dei kaldorei è come appisolarsi nel salotto di un amico molto anziano: benvenuti, sì, ma i piedi giù dai cuscini.",
		"Mi lasciano riposare qui come se ne facessi parte. Non è proprio così, e allora cerco di riposare con educazione.",
	},
	["dar.rest_enter.w23.haven.013"] = {
		"Prima di Hyjal non ci stancavamo così. Adesso so ciò che sanno le razze più giovani: un posto sotto un ramo conosciuto è un dono.",
		"Da Nordrassil in poi il mio popolo impara la stanchezza come una lingua nuova. Sotto le nostre foglie, almeno, non mi serve un interprete.",
	},
	["dar.rest_enter.w23.haven.014"] = {
		"La guardia non mi cade tutta insieme. Scende come un'armatura, pezzo per pezzo, ognuno più pesante di quanto sembrasse.",
		"La vigilanza è un muscolo, e l'ho tenuto contratto troppo a lungo. Qui, finalmente, lo lascio andare.",
	},
	["dar.rest_enter.w23.haven.015"] = {
		"china il capo verso la Sentinella più vicina, come si chiede licenza a chi ospita, e solo allora si siede.",
		"incrocia lo sguardo di una Sentinella prima di sistemarsi, e riceve un cenno appena percettibile che somiglia molto a un permesso.",
	},
	["dar.rest_enter.w23.repose.001"] = {
		"Le mani hanno smesso di stringersi a pugno. Non sapevo nemmeno che lo stessero facendo.",
		"Negli ultimi passi la mascella si è sciolta. Doveva essere serrata da ore.",
		"Le dita si aprono una dopo l'altra, come se ognuna andasse convinta per conto suo.",
	},
	["dar.rest_enter.w23.repose.002"] = {
		"si siede sul primo muretto basso che capita e ci resta parecchio più del previsto.",
		"trova un posto, poi uno un po' migliore, e alla fine non sceglie nessuno dei due: si mette sull'erba lì in mezzo.",
	},
	["dar.rest_enter.w23.repose.003"] = {
		"In questa città nessuno mi chiederà di sbrigarmi. Saperlo fa alla mia schiena più bene di qualsiasi letto.",
		"Qui nessuno mi metterà fretta. Basta questo a sciogliere un nodo a metà della schiena.",
	},
	["dar.rest_enter.w23.repose.004"] = {
		"Da questo momento sono ufficialmente fuori servizio. Al servizio di chi, non saprei dirlo.",
		"Per almeno un'ora, niente discorsi importanti. Grazie.",
		"Bottega chiusa, gente. Riprovate più tardi. Molto più tardi.",
	},
	["dar.rest_enter.w23.repose.005"] = {
		"La giornata continua a ripassarmi dietro gli occhi, nell'ordine sbagliato, e i pezzi più noiosi durano più di tutti.",
		"La testa non si siede solo perché si sono sedute le gambe. Continua a ripercorrere la giornata, tratto per tratto.",
	},
	["dar.rest_enter.w23.repose.006"] = {
		"si stende nell'erba alta al bordo di una terrazza e lascia che uno stelo solletichi un orecchio, senza muovere un dito.",
		"si allunga su un pendio morbido, mani intrecciate sul petto, a guardare i grandi rami che ondeggiano lassù.",
	},
	["dar.rest_enter.w23.repose.007"] = {
		"I miei piedi hanno idee precise sulle distanze di questa città, e per una volta lascio a loro l'ultima parola.",
		"Ogni terrazza è a una piacevole passeggiata da tutte le altre. Le piacevoli passeggiate si sommano. Io mi siedo.",
	},
	["dar.rest_enter.w23.repose.008"] = {
		"È nella quiete che mi raggiunge tutto ciò da cui scappavo. Va bene. Si siedano anche loro: c'è posto.",
		"Quando il corpo si riposa, i vecchi dolori della mente escono allo scoperto, come gatti da sotto un portico.",
	},
	["dar.rest_enter.w23.repose.009"] = {
		"si cala su un gradino basso, prima un ginocchio rigido e poi l'altro, con un lungo verso sommesso di sollievo.",
		"si lascia scendere su una sporgenza di pietra chiara con la cura di chi porta un carico pesante. E in un certo senso lo porta davvero.",
	},
	["dar.rest_enter.w23.repose.010"] = {
		"Continuo a risentire una cosa detta prima, e una migliore che avrei potuto dire. Può aspettare.",
		"La risposta brillante mi è venuta in mente con un ritardo enorme. Me la godo lo stesso, adesso che posso sedermi.",
		"I discorsi della giornata mi riaffiorano a pezzi. Quasi tutti andavano bene. Una frase la cancellerei volentieri.",
	},
	["dar.rest_enter.w23.repose.011"] = {
		"Ah. Così va meglio. Molto, molto meglio.",
		"Mi siedo. Guai a chi mi ferma.",
		"Ecco. Oh, ecco. È proprio il punto giusto.",
	},
	["dar.rest_enter.w23.repose.012"] = {
		"Una foglia per soffitto, una radice per cuscino. Ho pagato buon argento per stanze peggiori.",
		"Dormire sotto le foglie, qui, non sa di bivacco: sa di qualcuno molto alto che ti rimbocca le coperte.",
	},
	["dar.rest_enter.w23.repose.013"] = {
		"s'inginocchia presso un ruscello, si lava via la giornata da mani e viso e si rimette sui talloni, gocciolante e senza fretta.",
		"si sciacqua le mani in una bassa vasca di pietra e guarda la polvere della strada intorbidire l'acqua, poi depositarsi.",
	},
	["dar.rest_enter.w23.repose.014"] = {
		"Quando mi fermo arrivano i volti: gente incrociata, gente aiutata, uno o due che non ho potuto aiutare. Non si trattengono a lungo. Vogliono solo essere contati.",
		"Il riposo è il momento in cui faccio l'appello della giornata. Quasi tutto risponde. Qualche nome no.",
	},
	["dar.rest_enter.w23.repose.015"] = {
		"Grazie. A chiunque spetti la cura di questa quiete, grazie.",
		"Bel posto. Proprio un bel posto.",
	},
	["dar.rest_enter.w23.repose.016"] = {
		"si addormenta a metà mentre slaccia uno stivale, e si risveglia un bel po' dopo col laccio ancora in mano.",
		"si appisola senza nemmeno sdraiarsi, si riscuote di colpo, si guarda intorno per vedere se qualcuno se n'è accorto, e trova un kaldorei che, con molto garbo, se n'è accorto eccome.",
	},
	["dar.rest_enter.w23.repose.017"] = {
		"Restando immobile sento un ondeggiare lievissimo, tutta la terrazza che dondola come un'amaca. O l'albero si muove, o sono {g:più stanco|più stanca} di quanto credessi.",
		"Qui il terreno cede appena, come un pavimento posato su qualcosa di vivo. Ne viene fuori una culla strana, e buona.",
	},
	["dar.rest_enter.w23.repose.018"] = {
		"Un muschio così spesso dovrebbe essere vietato. Ci affondo come un sasso in uno stagno, e non ho intenzione di risalire.",
		"Qui l'erba è così fitta che ci si perde una mano. Io ci ho perso tutto il resto, e volentieri.",
	},
	["dar.rest_enter.w23.repose.019"] = {
		"C'è così silenzio che sento lamentarsi le mie ginocchia. Hanno parecchio da dire.",
		"Abbastanza silenzio da sentire lo stomaco. Vuole da mangiare, e poi un sonnellino.",
	},
	["dar.rest_enter.w23.repose.020"] = {
		"scarta un po' di pane e formaggio, lo mangia piano sull'erba e scuote via le briciole per gli uccellini che le vorranno.",
		"consuma un pasto semplice tirata fuori dallo zaino, a gambe incrociate, e impiega un tempo lunghissimo per l'ultimo boccone.",
	},
	["dar.rest_enter.w23.slack.001"] = {
		"L'elfo sulla seduta accanto non si è mosso da quando ho preso posto. Ho deciso che è una gara, e intendo perdere con dignità.",
		"Provo a riposare come i kaldorei. A quanto pare si comincia dimenticando di aver mai avuto fretta, e io non ho superato il primo gradino.",
	},
	["dar.rest_enter.w23.slack.002"] = {
		"prova a non fare assolutamente nulla, ma continua a distrarsi con piccole faccende utili, finché non si siede sulle proprie mani.",
		"comincia a riordinare lo zaino, ci ripensa e si sdraia lì accanto.",
	},
	["dar.rest_enter.w23.slack.003"] = {
		"Ho una lista di cose da fare. Può riposare anche lei.",
		"Commissioni? Se ne occuperà chi sarò fra qualche ora.",
		"La banca non scappa. E per un po' nemmeno io.",
	},
	["dar.rest_enter.w23.slack.004"] = {
		"I pensieri se ne sono andati per conto loro, come bambini a una fiera. Li vado a riprendere dopo.",
		"Non pensare a niente di preciso è più difficile di quanto sembri, e molto più bello quando riesce.",
	},
	["dar.rest_enter.w23.slack.005"] = {
		"sbadiglia così forte che un kaldorei di passaggio si volta, ci riflette un attimo e sembra approvare.",
		"sbadiglia, cerca di nasconderlo, non ci riesce e lascia perdere.",
		"fa uno sbadiglio enorme, e un gufo lassù tra i rami sembra rispondergli per le rime.",
	},
	["dar.rest_enter.w23.slack.006"] = {
		"C'è un incarico che mi aspetta, chissà dove, e si sente trascurato. Bene. Che impari la pazienza dalla gente del posto.",
		"Una vocina mi dice che dovrei fare qualcosa. L'ho mandata a fare il giro del lago. Ne avrà per ore.",
	},
	["dar.rest_enter.w23.slack.007"] = {
		"segue una foglia sola che gira piano sulla corrente di un ruscello finché non scompare, e non ne cerca un'altra.",
		"resta col mento appoggiato al pugno a osservare con grande attenzione niente di preciso.",
	},
	["dar.rest_enter.w23.slack.008"] = {
		"Se mi addormento, lasciatemi qui. Se russo, dite che non mi conoscete.",
		"Svegliatemi solo se è importante. Niente è importante.",
	},
	["dar.rest_enter.w23.slack.009"] = {
		"Le ginocchia hanno votato per restare giù. E le ginocchia sono la maggioranza.",
		"Ho promesso alle gambe una sosta breve. Le gambe hanno riso.",
	},
	["dar.rest_enter.w23.slack.010"] = {
		"Nessuno mi premierà per questa sosta. Bene. Certe cose vanno fatte per il gusto di farle.",
		"Non esiste un premio per chi riposa bene. Se esistesse, avrei buone possibilità.",
	},
	["dar.rest_enter.w23.slack.011"] = {
		"nota il grande felino di una Sentinella spaparanzato all'ombra, ne studia la tecnica e fa del suo meglio per imitarla.",
		"si sdraia non lontano da un grosso felino striato assopito, che apre un occhio, giudica accettabile la compagnia e lo richiude.",
	},
	["dar.rest_enter.w23.slack.012"] = {
		"È scortese addormentarsi in una città così bella? Lo chiedo per me, e a brevissimo.",
		"Potrei guardarmi intorno ancora un po', o chiudere gli occhi. Farò entrambe le cose, in quest'ordine.",
	},
	["dar.rest_enter.w23.slack.013"] = {
		"canticchia un frammento stonato di qualcosa, si accorge del silenzio intorno e lo finisce in un sussurro.",
		"comincia a fischiettare, incrocia uno sguardo di passaggio e lo trasforma in un lungo silenzio imbarazzato.",
	},
	["dar.rest_enter.w23.slack.014"] = {
		"Per un po' può rendersi utile qualcun altro. La mia parte l'ho fatta.",
		"Il mondo può girare senza di me per un'ora. Ho controllato.",
	},
	["dar.rest_enter.w23.unbuckle.001"] = {
		"lavora una fibbia testarda con le dita stanche e, quando finalmente cede, la guarda come dopo aver chiuso una vecchia lite.",
		"allenta una cinghia dopo l'altra finché tutto l'equipaggiamento non si affloscia come una pelle mutata.",
		"si sfila un guanto coi denti, poi l'altro con la mano libera, e piega piano le dita.",
	},
	["dar.rest_enter.w23.unbuckle.002"] = {
		"Giù lo zaino, e le spalle mi lievitano come pane. Giurerei di aver guadagnato un dito d'altezza.",
		"Via lo zaino. La schiena fa un rumore su cui preferisco non indagare.",
	},
	["dar.rest_enter.w23.unbuckle.003"] = {
		"si toglie gli stivali, li allinea uno accanto all'altro con estrema precisione e poi resta a fissarsi i piedi.",
		"slaccia gli stivali e appoggia le piante nude sul verde fresco, piegando piano le dita.",
	},
	["dar.rest_enter.w23.unbuckle.004"] = {
		"Ogni cinghia che allento mi restituisce un pezzetto di me che avevo prestato alla strada.",
		"La cintura, poi i bracciali, poi la spilla del mantello che mi morde la clavicola da ore. Un pezzo dopo l'altro, mi riprendo.",
	},
	["dar.rest_enter.w23.unbuckle.005"] = {
		"Se qualcuno vede una fibbia rotolare nel lago, era mia, e ho deciso che non mi serve.",
		"Via, via, via. Tutto quello che stringe, via.",
	},
	["dar.rest_enter.w23.unbuckle.006"] = {
		"dispone l'equipaggiamento sull'erba in fila ordinata, controlla ogni pezzo al tatto, poi smette di controllare e resta lì.",
		"rovescia lo zaino a terra, ne scuote via la polvere della strada e lascia che tutto quel disordine stia lì per un po'.",
	},
	["dar.rest_enter.w23.unbuckle.007"] = {
		"Ho ancora le orecchie piene del rumore della giornata. Qui si svuotano piano, come acqua da uno stivale.",
		"Ci vuole un po' perché il chiasso della strada mi esca dalla testa. La città aspetta che abbia finito.",
	},
	["dar.rest_enter.w23.unbuckle.008"] = {
		"Allento una cinghia. Una sola. Una schiena dell'Orda in una città kaldorei non può permettersi di sciogliersi del tutto.",
		"Lo chiamano riposo. Me ne sto immobile tra gente che mi vorrebbe {g:morto|morta}, se sapesse. È quasi riposo.",
	},
	["dar.rest_enter.w23.unbuckle.009"] = {
		"Le mie spalle presentano reclamo formale. Preso nota. Accolto, persino.",
		"Fuori gli stivali. Chi li ha inventati mi deve delle scuse.",
	},
	["dar.rest_enter.w23.unbuckle.010"] = {
		"Inventario: un tallone dolorante, una spalla che scricchiola, un ginocchio con le sue idee. Niente che la calma di questa città non sappia sopportare.",
		"Faccio il conto degli acciacchi. Vince l'anca sinistra, di misura, sul fondo della schiena.",
	},
	["dar.rest_enter.w23.unbuckle.011"] = {
		"preme entrambi i pollici sul fondo della schiena, s'inarca e tiene la posizione a occhi chiusi.",
		"scioglie i nodi di un polpaccio con mani lente e pazienti, come chi impasta il pane.",
	},
	["dar.rest_enter.w23.unbuckle.012"] = {
		"appende il mantello a un piolo che pare cresciuto dalla parete apposta, e si ferma a lungo sul bordo del letto basso.",
		"posa lo zaino in un angolo della stanza della locanda, si siede sul letto e per un bel po' non si rialza.",
	},
	["dar.rest_enter.w23.unbuckle.013"] = {
		"Le mani non sanno cosa fare senza niente da reggere. Le ho posate in grembo come ospiti arrivati in anticipo.",
		"Mani vuote, per una volta. Continuano a cercare una cinghia o una fibbia, e trovano solo l'erba.",
	},
	["dar.subzone_enter.w23.crafts.001"] = {
		"si ferma accanto a un conciatore che taglia una cinghia a mano libera, in un solo lungo tratto, senza mai abbassare gli occhi sul coltello.",
		"rallenta per guardare due mani kaldorei ricavare una striscia da una pelle con un unico gesto, dritto come tracciato col righello.",
		"indugia davanti a un banco da taglio quanto basta per veder uscire un'intera cintura da una sola pelle, senza avanzare un ritaglio.",
	},
	["dar.subzone_enter.w23.crafts.002"] = {
		"I tintori di questa terrazza si riconoscono subito: viola fino al polso, tutti quanti, come se li avessero sorpresi con le mani nello stesso barattolo di marmellata.",
		"I tintori, qui, li riconosci dalle mani. Viola fin oltre le nocche, e a nessuno sembra importare.",
		"Dita viola ovunque, sulla Craftsmen's Terrace. O i tintori lavorano sodo, o tutto il quartiere ha saccheggiato lo stesso cespuglio di bacche.",
	},
	["dar.subzone_enter.w23.crafts.003"] = {
		"Ceste di erbe divise da qualcuno che pare conoscere ogni stelo per nome. Gli erboristi, qui, non raccolgono: mietono.",
		"Le ceste dell'erborista sono ordinate meglio di qualunque altra abbia mai visto: non solo per pianta, ma per quanto tempo fa è stato tagliato ogni mazzo.",
		"Qualcuno, su questa terrazza, divide le erbe soltanto all'odore, a occhi socchiusi. Io ne tirerei fuori un pugno di erbacce.",
	},
	["dar.subzone_enter.w23.crafts.004"] = {
		"Craftsmen's Terrace. Qui c'è un paio di stivali che ci metterà una stagione a nascere e durerà parecchio più di me.",
		"Meglio non chiedere a un artigiano di qui quanto ci vuole per un mantello. Il sorriso cortese è già una risposta.",
		"Il buon lavoro richiede tempo. Qui, a quanto pare, richiede generazioni.",
	},
	["dar.subzone_enter.w23.crafts.005"] = {
		"passa davanti alla porta della locanda proprio mentre qualcuno esce sbadigliando, ancora alle prese con uno stivale, e guarda la terrazza strizzando gli occhi come se nel frattempo si fosse spostata.",
		"si scosta sulla soglia della locanda per lasciar uscire un nano col colletto storto e il passo lento e accorto di chi ha dormito bene.",
	},
	["dar.subzone_enter.w23.crafts.006"] = {
		"La locanda sta in mezzo alle botteghe, e mi sembra giusto. Un letto a portata d'orecchio di un lavoro onesto è un buon letto.",
		"Ovvio che la locanda sia sulla Craftsmen's Terrace. Qui tutti fabbricano qualcosa; chi gestisce la locanda fabbrica il sonno.",
		"Mi piace una locanda che divide la terrazza con conciatori e sarti. Il riposo sembra quasi guadagnato.",
	},
	["dar.subzone_enter.w23.crafts.007"] = {
		"nota che ogni bisaccia, ogni guanto, ogni cintura lavorata sulle rastrelliere porta la stessa piccola foglia, impressa in un punto dove è facile non vederla.",
		"scorre con lo sguardo una fila di cuoio finito e trova una foglia lavorata in ciascun pezzo, nascosta dentro un polsino o sotto una fibbia, come una firma.",
	},
	["dar.subzone_enter.w23.crafts.008"] = {
		"Una volta un conciatore mi ha detto che usano solo la corteccia che l'albero ha già lasciato cadere. Vero o racconto per forestieri, le vasche ne hanno l'odore: aspro, bruno, appena dolce.",
		"Le vasche di concia, qui, sanno di corteccia e non del solito marcio. Qualcuno sostiene che i kaldorei prendano solo ciò che l'albero lascia andare. Non sono in condizione di verificarlo.",
		"Tannino e acqua di corteccia, invece del fetore che mi aspettavo. Pare che l'albero ceda la corteccia ai conciatori quando è pronto, non prima. Così raccontano, almeno.",
	},
	["dar.subzone_enter.w23.crafts.009"] = {
		"sente la terrazza prima ancora di vederla davvero: lo schiocco secco delle cesoie, un pestello che macina in una ciotola di pietra, un ago tirato attraverso il cuoio rigido.",
		"si ferma ad ascoltare: il raschietto che gratta il cuoio, un pestello che gira e rigira, e sotto tutto qualcuno che canticchia mentre cuce.",
	},
	["dar.subzone_enter.w23.crafts.010"] = {
		"Il banco dell'alchimista è un piccolo bosco di vetro. In una fiasca qualcosa sta diventando verde da un'ora e nessuno sembra preoccuparsene, quindi non me ne preoccupo nemmeno io.",
		"Vetro che gorgoglia, una fiammella azzurra, un odore di menta pestata e monete vecchie. Qui l'alchimia sembra meno un mestiere e più un giardino tenuto in bottiglia.",
		"Il banco di un alchimista, ogni fiasca etichettata in una grafia accurata che non so leggere. Mi fido dei colori e resto a distanza.",
	},
	["dar.subzone_enter.w23.crafts.011"] = {
		"Su questa terrazza è tutto splendido, fatto a mano e prezzato di conseguenza.",
		"Potrei comprarmi un mantello, qui. Oppure continuare a mangiare. Scelte difficili.",
	},
	["dar.subzone_enter.w23.crafts.012"] = {
		"osserva un artigiano anziano correggere il punto di uno più giovane senza dire nulla: due dita posate sul dorso della mano, finché il gesto non rallenta.",
		"passa accanto a un banco dove un kaldorei più anziano guida due mani più giovani attraverso un nodo, più e più volte, senza traccia d'impazienza su nessuno dei due volti.",
	},
	["dar.subzone_enter.w23.crafts.013"] = {
		"Qualcuno qui ha detto, con tutta naturalezza, che una certa sarta è ancora considerata promettente. «Promettente», mi spiegano, vuol dire un secolo o due di cucito, più o meno.",
		"Un conciatore ha definito un collega «ancora in fase di apprendimento». Per quel che capisco, il collega impara da più tempo di quanto siano in piedi certi regni.",
	},
	["dar.subzone_enter.w23.crafts.014"] = {
		"scivola accanto a un nano che contratta con un conciatore per un paio di guanti: il nano parla moltissimo, il kaldorei quasi niente, e il prezzo non si muove.",
		"s'imbatte in uno gnomo che spiega un ordine insolito a un sarto con una gran quantità di gesti, e in un sarto che ascolta tutto con attenzione grave e senza fretta.",
	},
	["dar.subzone_enter.w23.crafts.015"] = {
		"L'odore delle vasche e delle foglie pestate dai tintori: questa terrazza sa di un lavoro che la mia gente fa da più tempo di quanto chiunque altro ricordi. Mi rimette in sesto.",
		"Di tutta la città, la terrazza dei nostri artigiani è quella che sento più casa. Mani occupate, voci basse, niente fatto di fretta.",
		"Concia, filo, l'odore verde degli steli tagliati. Qualunque cosa abbiamo perso a Hyjal, questo l'abbiamo tenuto.",
	},
	["dar.subzone_enter.w23.crafts.016"] = {
		"scavalca con cura una pezza di stoffa chiara srotolata sul sentiero per essere misurata, e riceve un piccolo cenno dal sarto all'altro capo.",
		"aspetta mentre due kaldorei portano un telo attraverso la terrazza, uno per capo, teso e in piano come qualcosa che non deve toccare terra.",
	},
	["dar.subzone_enter.w23.crafts.017"] = {
		"Cuoio, erbe e qualcosa che un alchimista giurerà essere perfettamente innocuo. Odore di bottega vera.",
		"Ah, l'odore di gente che fa le cose come si deve. E di qualunque cosa ci sia in quella fiasca verde.",
		"Pelle conciata e foglie pestate. Il naso sa dove sono prima di me.",
	},
	["dar.subzone_enter.w23.crafts.018"] = {
		"Cuoio migliore di tutto quello che si vende nei mercati dell'Orda, e non posso dire a nessuno dove l'ho visto.",
		"Questi kaldorei tagliano e cuciono come se pregassero. Cappuccio calato, bocca chiusa, e l'ammirazione me la tengo tutta per me.",
	},
	["dar.subzone_enter.w23.crafts.019"] = {
		"Il lavoro finito resta sui banchi senza nessuno a sorvegliarlo. O i kaldorei si fidano di tutti, o sanno benissimo chi oserebbe.",
		"Nessuno fa la guardia alle rastrelliere della merce pronta. Altrove sarebbe un invito. Qui sembra una prova che preferirei non fallire.",
	},
	["dar.subzone_enter.w23.crafts.020"] = {
		"passa una mano su un banco da lavoro dal legno ancora chiaro e liscio, appena segnato, come se la terrazza avesse finito da poco di crescere.",
		"nota quanto poco siano consumati i banchi: poche bruciature, pochi segni di coltello, il legno ancora chiaro. I mestieri sono antichi; la terrazza no.",
	},
	["dar.subzone_enter.w23.enclave.001"] = {
		"entra nel Cenarion Enclave accanto a un druido che divide semi in piccole coppe d'argilla, uno per coppa, ognuno guardato controluce prima.",
		"arriva nell'Enclave mentre una druida si passa una manciata di semi da un palmo all'altro, scegliendoli secondo una regola che resta un mistero.",
	},
	["dar.subzone_enter.w23.enclave.002"] = {
		"Terriccio umido e foglie schiacciate. L'Enclave ha l'odore di un'aiuola appena rivoltata a mani nude.",
		"Il Cenarion Enclave sa di terra smossa: un odore strano, in cima a un albero.",
		"Terra, foglie marce, linfa verde. Fra tutti gli angoli di Darnassus, l'Enclave è quello che sa di lavoro.",
	},
	["dar.subzone_enter.w23.enclave.003"] = {
		"Scusate. Permesso. Pardon. C'è qualcuno, in questo Enclave, che cammini su due gambe?",
		"Un gatto, un orso e qualcosa con le corna, tutti nella stessa direzione. Seguo i druidi, chiunque siano.",
		"Mi scusi, signore. Signora. Orso. Chiunque lei sia, perdoni.",
	},
	["dar.subzone_enter.w23.enclave.004"] = {
		"Quando parlano, i druidi dell'Enclave lasciano una pausa, uno spazio a forma di qualcuno che manca. Malfurion, immagino, addormentato nel Sogno.",
		"Ogni druido del Cenarion Enclave sembra custodire qualcosa per qualcuno che un giorno si sveglierà e lo vorrà trovare esattamente com'era.",
	},
	["dar.subzone_enter.w23.enclave.005"] = {
		"entra nell'Enclave nel mormorio di un giovane druido che recita i nomi delle erbe a uno più anziano, il quale corregge una parola su tre.",
		"passa accanto a due druidi ai margini dell'Enclave: uno nomina foglie ad alta voce, l'altro ascolta a occhi chiusi e annuisce solo a quelle giuste.",
	},
	["dar.subzone_enter.w23.enclave.006"] = {
		"Abbasso la voce. Qualcosa in questo Enclave sta chiaramente cercando di crescere, e mi spiacerebbe disturbarlo.",
		"Zitti. Credo che quel muschio si stia concentrando.",
		"Silenzio, tutti. Be', tutti quelli che non sono alberi.",
	},
	["dar.subzone_enter.w23.enclave.007"] = {
		"Sopra tutto questo verde, chissà dove, siede Fandral Staghelm. I druidi che scendono dal suo seggio hanno tutti la stessa faccia attenta, come allievi all'uscita da una lezione difficile.",
		"Il seggio dell'Arcidruido è lassù, chissà dove. Quaggiù i druidi parlano degli ordini di Staghelm come i contadini parlano di una gelata: con rispetto, e un'occhiata verso l'alto.",
	},
	["dar.subzone_enter.w23.enclave.008"] = {
		"entra nel Cenarion Enclave e gira attorno a un grosso felino addormentato di traverso sul sentiero: apre un occhio, troppo pensoso per un gatto qualunque, e lo richiude.",
		"arriva nell'Enclave passando accanto a un felino assopito sui gradini, le cui orecchie seguono ogni passo con un'attenzione che nessun animale comune si prenderebbe la briga di avere.",
		"rallenta ai margini dell'Enclave per lasciar passare per primo un felino dal muso grigio, che attraversa senza fretta con l'aria di un anziano che tiene aperta una porta.",
	},
	["dar.subzone_enter.w23.enclave.009"] = {
		"Ogni mano che vedo nell'Enclave ha terra sotto le unghie. Nel resto di Darnassus sarebbe uno scandalo; qui sembra un distintivo.",
		"Vesti pulite, mani sporche di terra. È così che si distingue un druido dell'Enclave dal resto di questa città così in ordine.",
		"Un druido mi ha stretto la mano lasciandoci dentro mezzo orto. Non mi dispiace: è la stretta di mano più sincera della città.",
	},
	["dar.subzone_enter.w23.enclave.010"] = {
		"entra nell'Enclave, dove un cerchio di druidi siede attorno a un alberello in un vaso di pietra senza dire nulla, come in attesa che finisca una frase.",
		"si ferma ai margini del Cenarion Enclave accanto a tre druidi chini su un alberello malaticcio, che gli parlano a turno, piano e con molta pazienza.",
	},
	["dar.subzone_enter.w23.enclave.011"] = {
		"Questi druidi hanno dormito per secoli nel Sogno, mentre le Sentinelle difendevano le foreste. A vederli affaccendarsi nell'Enclave, direi che stanno recuperando.",
		"Intere epoche del mondo sono passate mentre i druidi di questo Circolo sognavano. Forse per questo l'Enclave sembra così operoso, per un luogo kaldorei: tempo perduto da restituire.",
	},
	["dar.subzone_enter.w23.enclave.012"] = {
		"Non toccare niente, non cogliere niente, non calpestare niente che possa essere un druido. Ricevuto.",
		"In questo Enclave tutto è una pianta, un druido, o un druido che fa finta di essere una pianta.",
		"Se sto immobile abbastanza a lungo in questo Enclave, qualcuno finirà per annaffiarmi.",
	},
	["dar.subzone_enter.w23.enclave.013"] = {
		"arriva nell'Enclave mentre un druido lega una stecca alla zampa posteriore di una lepre con un filo d'erba; la lepre, per nulla agitata, lascia fare.",
		"passa accanto a una druida che, sui gradini dell'Enclave, sistema l'ala di un uccellino fra due rametti canticchiando qualcosa di troppo basso per capirlo.",
	},
	["dar.subzone_enter.w23.enclave.014"] = {
		"Due druidi ai margini dell'Enclave smettono di parlare quando passo. Uno teneva una mano sulla parete viva, con l'espressione di un contadino a cui non piace il colore di un campo.",
		"Nell'Enclave parlano di Teldrassil con amore, e ogni tanto con qualcos'altro. Una druida mi ha detto che l'albero «ascolta meno di quanto dovrebbe». Poi ha cambiato discorso.",
		"Un druido dell'Enclave dice che Teldrassil è cresciuto superbo. Un altro dice che gli alberi non fanno così. Nessuno dei due sembrava convinto.",
	},
	["dar.subzone_enter.w23.enclave.015"] = {
		"trova, appena dentro il Cenarion Enclave, un druido addormentato seduto contro una radice, con il muschio che già fa progetti su una manica.",
		"passa in silenzio accanto a un vecchio druido assopito contro la parete viva dell'Enclave, così immobile che un piccolo rampicante sembra stia valutando la sua spalla.",
	},
	["dar.subzone_enter.w23.enclave.016"] = {
		"Niente martelli, niente monete, niente contrattazioni. I suoni dell'Enclave sono tutti piccoli e vivi: fruscii, raspare, un grugnito basso di qualcosa di grosso che probabilmente è un druido.",
		"Quello che sento nel Cenarion Enclave: foglie che si rigirano, unghie sul legno, due voci in disaccordo molto lentamente. Nulla di fabbricato.",
		"Nell'Enclave qualcosa sta masticando, qualcosa sta scavando, e qualcuno spiega a entrambi, sottovoce, perché non dovrebbero.",
	},
	["dar.subzone_enter.w23.enclave.017"] = {
		"Ishnu-alah, druidi. Io bado ai miei piedi, voi badate alle vostre radici.",
		"Qui c'è odore di casa. Terriccio, corteccia, e il tè di qualcuno lasciato a raffreddare.",
	},
	["dar.subzone_enter.w23.enclave.018"] = {
		"entra nell'Enclave giusto in tempo per vedere un anziano druido osservare un'allieva che convince un bocciolo ad aprirsi, poi richiuderlo con un dito e farle cenno di ricominciare.",
		"si attarda presso un gradino muschioso dell'Enclave, dove un'allieva druida si sforza su un bocciolo chiuso mentre la maestra, a occhi socchiusi, aspetta che ceda.",
	},
	["dar.subzone_enter.w23.enclave.019"] = {
		"I druidi qui dicono «presto» e intendono un secolo. Ho chiesto a una di loro quando un alberello sarebbe stato pronto, e mi ha risposto «fra poco», sincerissima.",
		"Nell'Enclave, una cosa fatta in fretta è una cosa fatta nell'arco della mia vita intera. Ho smesso di chiedere quanto ci vorrà.",
		"Davanti a me un druido ha chiamato l'albero «giovane». È più alto di qualunque torre io conosca.",
	},
	["dar.subzone_enter.w23.enclave.020"] = {
		"Ha l'odore di un bosco a cui qualcuno ha appena chiesto scusa.",
		"Tutto questo Enclave sembra a metà strada dal diventare qualcos'altro. Cercherò di non essere in mezzo quando succede.",
		"Direi che questo posto è incolto, ma credo che sia cresciuto esattamente quanto voleva.",
	},
	["dar.subzone_enter.w23.gardens.001"] = {
		"si inoltra nei Temple Gardens passando accanto a un giardiniere che lega uno stelo piegato a un paletto con un filo d'erba, attento come un guaritore che fascia un dito.",
		"cammina nei Temple Gardens, dove una giardiniera kaldorei si china su un unico fiore afflosciato, lo aggiusta di un niente e poi si scosta per giudicare.",
		"entra nei giardini accanto a un'aiuola dove qualcuno ha sostenuto ogni stelo inclinato con un rametto, ciascuno tagliato esattamente della lunghezza giusta.",
	},
	["dar.subzone_enter.w23.gardens.002"] = {
		"Ogni erbaccia dei Temple Gardens è stata lasciata dov'è. O qui non sono erbacce, o i giardinieri hanno raggiunto un accordo con loro.",
		"In questi giardini non trovo una sola pianta che sembri indesiderata. Persino quelle che spuntano dal sentiero sembrano aver chiesto il permesso.",
		"Pare che qui i giardinieri non strappino niente. Convincono le piante a spostarsi, un poco a ogni stagione.",
	},
	["dar.subzone_enter.w23.gardens.003"] = {
		"Non sto cogliendo niente. Guardo e basta. Molto da vicino. Con le mani dietro la schiena.",
		"Giardini splendidi. Terrò le mani in tasca, così tutti possono stare tranquilli.",
		"Quel fiore si è chiuso appena ho avvicinato il naso. Scelgo di non prenderla sul personale.",
	},
	["dar.subzone_enter.w23.gardens.004"] = {
		"segue un sentiero dei Temple Gardens attorno a una siepe e si trova davanti il fianco bianco del tempio, più vicino di quanto sembrasse un attimo prima.",
		"rallenta fra le siepi dei Temple Gardens mentre passano due sacerdotesse al passo, parlando così piano che le parole non arrivano in fondo al sentiero.",
	},
	["dar.subzone_enter.w23.gardens.005"] = {
		"Chi ha piantato questi giardini un tempo sapeva per certo che li avrebbe visti adulti. Dopo Hyjal quella certezza non c'è più. Mi chiedo se i giardinieri piantino un po' più in fretta.",
		"A Hyjal i kaldorei hanno rinunciato al per sempre, e poi hanno piantato giardini lo stesso. Lo trovo più difficile da guardare di qualunque rovina.",
	},
	["dar.subzone_enter.w23.gardens.006"] = {
		"trova nei Temple Gardens un kaldorei che spazza i petali caduti dal sentiero e poi, invece di portarli via, li sparge a manciate sulle aiuole.",
		"osserva un giardiniere raccogliere i petali dalle pietre e farli scivolare piano sotto le siepi, come per rimettere qualcosa al suo posto.",
		"si scosta sul sentiero dei Temple Gardens per far passare un giardiniere con un cesto di talee, ciascuna avvolta nel muschio umido come una cosa preziosa.",
	},
	["dar.subzone_enter.w23.gardens.007"] = {
		"Potrei sedermi qui finché qualcuno non avrà bisogno di me. E poi un altro po'.",
		"Se qualcuno mi cerca, ditegli che mi hanno inghiottito i giardini. Con garbo.",
		"Datemi dieci minuti in questi giardini. O un'ora. Non sono esigente.",
	},
	["dar.subzone_enter.w23.gardens.008"] = {
		"Alcuni fiori dei Temple Gardens volgono la corolla verso il tempio invece che verso il cielo. Mi dicono che i giardinieri non c'entrano.",
		"Una sacerdotessa mi ha detto che certi boccioli qui si aprono solo quando qualcuno vicino sta pregando. Ne osservo uno da un po'. Nessuno, a quanto pare, prega.",
	},
	["dar.subzone_enter.w23.gardens.009"] = {
		"si fa strada con cautela nei Temple Gardens, girando attorno a un anziano addormentato sull'erba, le mani giunte e un petalo posato su una manica come un segnalibro.",
		"sente, entrando nei giardini, un vecchio kaldorei che mormora a un'aiuola con il tono che si riserva a un allievo lento a capire.",
		"si imbatte, sull'erba dei Temple Gardens, in un kaldorei che disegna un unico fiore su un pezzo di corteccia, con grande cura e assai poco talento.",
	},
	["dar.subzone_enter.w23.gardens.010"] = {
		"Un giardiniere dei Temple Gardens pota la stessa siepe da quando sono qui: una foglia, una pausa, un'altra foglia, una lunga riflessione sulla terza.",
		"Osservo i giardinieri kaldorei da un pezzo e non capisco quando finiscono. Forse non finiscono.",
		"I Temple Gardens sembrano nati da soli. Niente che sembri così spontaneo lo è mai.",
	},
	["dar.subzone_enter.w23.gardens.011"] = {
		"segue nei Temple Gardens uno stretto canale d'acqua, al passo con un petalo che galleggia, finché il petalo vince.",
		"si affianca a un rivolo sottile che attraversa i giardini e guarda un petalo scivolare oltre, verso il tempio, senza fretta come tutto il resto.",
	},
	["dar.subzone_enter.w23.gardens.012"] = {
		"A chi cura tutto questo, Ishnu-alah. Un lavoro splendido.",
		"I miei complimenti ai giardinieri. A tutti. A ogni secolo di loro.",
	},
	["dar.subzone_enter.w23.gardens.013"] = {
		"In qualunque altro posto, un giardino così bello avrebbe un muro, un cancello chiuso e qualcuno con un bastone. I Temple Gardens non hanno niente di tutto questo, e non ne hanno bisogno.",
		"Niente steccato, niente cancello, nessun custode. I kaldorei affidano ai visitatori ogni fiore di questi giardini. Non vorrei essere io a deluderli.",
		"Non manca un solo fiore dalle aiuole, eppure qui passano tutti i visitatori della città. Qualcuno, in questi giardini, deve avere uno sguardo molto persuasivo.",
	},
	["dar.subzone_enter.w23.gardens.014"] = {
		"raggiunge i Temple Gardens mentre la luce del giorno cala, e i fiori pallidi sembrano accendersi in risposta, un'aiuola dopo l'altra.",
		"percorre i giardini al crepuscolo mentre i giardinieri kaldorei, al principio della loro giornata, escono con gli attrezzi e salutano con un cenno.",
	},
	["dar.subzone_enter.w23.gardens.015"] = {
		"Nei Temple Gardens niente ha fretta, e dopo pochi passi nemmeno io. Darò la colpa alle siepi.",
		"Le spalle mi scendono di un dito appena sono fra queste aiuole. Non sapevo che fossero su.",
	},
	["dar.subzone_enter.w23.gardens.016"] = {
		"si arresta ai bordi dei Temple Gardens mentre un uccellino se ne va con lo spago di un giardiniere, che lo guarda allontanarsi con qualcosa di simile all'approvazione.",
		"giunge fra le aiuole proprio mentre uno scoiattolo dissotterra un bulbo appena piantato, e il kaldorei che l'aveva messo lo ripianta e basta, senza dire niente a nessuno.",
		"arriva fra le aiuole mentre una falena si posa sulla sua manica, resta un poco e se ne va quando decide lei.",
	},
	["dar.subzone_enter.w23.gardens.017"] = {
		"Nei Temple Gardens il raccoglimento del tempio trabocca. Lo si sente farsi più sottile a ogni passo che ci si allontana dalle porte.",
		"Qui fra i fiori il silenzio del tempio è diluito, come un tè forte allungato con l'acqua. Più facile da mandar giù.",
	},
	["dar.subzone_enter.w23.gardens.018"] = {
		"Queste siepi sono più curate di me. Di chiunque io conosca, a dirla tutta.",
		"Qualcuno qui ha potato quella siepe in una curva perfetta. Con cosa, la pazienza?",
	},
	["dar.subzone_enter.w23.temple.001"] = {
		"entra nel Temple of the Moon e trova che a parlare è soltanto la fontana; tutti gli altri hanno lasciato la parola all'acqua.",
		"sale nel tempio dove scroscia la grande fontana, e abbassa la voce prima che qualcuno debba chiederlo.",
	},
	["dar.subzone_enter.w23.temple.002"] = {
		"Osservo una sacerdotessa piegare un panno nel Temple of the Moon. Sei pieghe, ognuna spianata col palmo. Qualunque cosa preghi, la prega anche con le mani.",
		"Nel tempio una sacerdotessa raddrizza un petalo caduto sulla pietra, lo guarda, poi lo rimette dov'era. Non capisco la regola, ma scommetto che ce n'è una.",
		"Una sacerdotessa mi passa accanto con una ciotola d'acqua così piena che dovrebbe traboccare, e invece no. Fede, o polsi eccellenti.",
	},
	["dar.subzone_enter.w23.temple.003"] = {
		"Sussurrerò. Anzi, non dico proprio niente.",
		"Perfino i miei stivali sembrano maleducati su questa pietra.",
		"Da me nemmeno una parola. Ci pensa la fontana.",
	},
	["dar.subzone_enter.w23.temple.004"] = {
		"varca la soglia del Temple of the Moon, e la luce pallida del pozzo lunare si posa sul suo viso, che per un attimo sembra antico quanto quelli dei kaldorei intorno.",
		"cammina fra le sacerdotesse verso il pozzo lunare, il cui bagliore d'argento si accende su ogni fibbia e cinghia che porta addosso.",
	},
	["dar.subzone_enter.w23.temple.005"] = {
		"Questo tempio è silenzioso, ma non è inerte. Le Sentinelle salgono ferite da Ashenvale e le sacerdotesse le rimandano giù. Un ospedale da campo che ha imparato a sussurrare.",
		"Dietro il silenzio del Temple of the Moon c'è un lavoro continuo di cura: bende, unguenti, una mano posata su una spalla, una Sentinella che esce più dritta di come è entrata.",
	},
	["dar.subzone_enter.w23.temple.006"] = {
		"arriva nel tempio mentre una sacerdotessa guida le mani di una più giovane sopra un bacile d'acqua, correggendo un dito qui, un polso là, senza una parola.",
		"passa accanto a due sacerdotesse presso un bacile: la più anziana sposta le mani dell'altra di un soffio, poi di un altro, finché entrambe sembrano soddisfatte.",
		"indugia ai margini del Temple of the Moon a guardare una sacerdotessa che insegna a un'allieva a stare ferma, e l'allieva che, con grande impegno, non ci riesce.",
	},
	["dar.subzone_enter.w23.temple.007"] = {
		"L'acqua cade dalla fontana nel pozzo, ed è l'unico suono del Temple of the Moon a cui nessuno qui chiederebbe mai di abbassarsi.",
		"La fontana del tempio scorreva prima del mio arrivo e scorrerà dopo la mia partenza. È la voce più paziente di una città paziente.",
		"Acqua che cade nell'acqua, senza fretta e senza fine. Fra tutte le voci del tempio è quella di cui mi fido di più.",
	},
	["dar.subzone_enter.w23.temple.008"] = {
		"Elune-adore. Spero di averlo detto bene.",
		"Pace a questa casa, e a chi la custodisce.",
	},
	["dar.subzone_enter.w23.temple.009"] = {
		"alza lo sguardo verso le parti alte del tempio, dove si dice che l'Alta Sacerdotessa abbia il suo seggio, e incontra invece lo sguardo fermo di una Sentinella di guardia.",
		"solleva gli occhi verso l'alto del Temple of the Moon, chiedendosi se Tyrande Whisperwind sia lassù, e trova una Sentinella di guardia che non si chiede proprio nulla.",
	},
	["dar.subzone_enter.w23.temple.010"] = {
		"Nel Temple of the Moon mi ritrovo con la schiena più dritta senza sapere perché. Nessuno l'ha chiesto. Il luogo se lo aspetta e basta, come certi anziani.",
		"Qualunque cosa ciascuno creda, o non creda, il tempio lascia stare chiunque in disparte, in silenzio. Pare che conti qualcosa.",
		"Qualcosa nel Temple of the Moon mi fa mettere in ordine i pensieri, come ci si sistema il mantello prima di una visita.",
	},
	["dar.subzone_enter.w23.temple.011"] = {
		"arriva nel Temple of the Moon accanto a una sacerdotessa in ginocchio che pulisce il bordo della fontana con un panno morbido, con la delicatezza di chi lava un viso addormentato.",
		"trova una sacerdotessa che lucida l'orlo di pietra del pozzo lunare a lunghe passate lente, un lavoro chiaramente fatto ogni giorno e chiaramente mai pesato.",
		"sorprende una sacerdotessa che rifila gli stoppini delle piccole lampade a uno a uno, attenta come un gioielliere, senza lasciar fumare una sola fiamma.",
	},
	["dar.subzone_enter.w23.temple.012"] = {
		"Sorelle, Elune-adore. Terrò bassa la voce e lunghi i ringraziamenti.",
		"Un momento al pozzo, è tutto quello che ho. Elune sa che basta.",
	},
	["dar.subzone_enter.w23.temple.013"] = {
		"Dopo Hyjal, mi dicono, le sacerdotesse di questo tempio hanno cominciato a invecchiare come chiunque altro. Curano il pozzo con la calma di prima. Non so se io ci riuscirei.",
		"Una sacerdotessa del tempio mi ha detto che prima di Hyjal qui nessuno contava gli anni. Ora, ha detto, alcune sorelle hanno cominciato. L'ha detto come si accenna a uno spiffero.",
	},
	["dar.subzone_enter.w23.temple.014"] = {
		"mette piede nel Temple of the Moon mentre alcune voci si levano in un inno sommesso, così lieve che sembra salire dall'acqua.",
		"sente, appena entra nel tempio, le sacerdotesse cantare a fior di labbra: un suono sottile e d'argento, sparito prima di capire da dove venisse.",
		"sosta sulla soglia del tempio mentre una sacerdotessa canta un verso sottovoce e si interrompe, come se le avessero risposto.",
	},
	["dar.subzone_enter.w23.temple.015"] = {
		"Ho attraversato il Temple of the Moon in punta di piedi e una sacerdotessa mi ha sorriso. A quanto pare la punta di piedi non era obbligatoria.",
		"Qualcuno nel tempio ha fatto cadere una ciotola. Venti teste si sono voltate, lentissime, e la ciotola è sembrata scusarsi da sola.",
		"I kaldorei hanno un modo di camminare nel loro tempio: tallone morbido, peso in avanti. Ci ho provato poco fa. Malissimo.",
	},
	["dar.subzone_enter.w23.temple.016"] = {
		"segue una Sentinella nel Temple of the Moon e la vede appoggiare la glaive a una colonna prima di proseguire, come se lì non avesse niente da fare.",
		"sale nel tempio dietro una Sentinella e nota che lascia la glaive al limitare, poi prosegue con le mani aperte e vuote.",
	},
	["dar.subzone_enter.w23.temple.017"] = {
		"Guarda a lungo nel pozzo lunare di questo tempio e il riflesso sembra seguirti con un attimo di ritardo. Ho smesso di guardare.",
		"La superficie del pozzo trattiene la luce come una moneta stretta nel pugno. Continuo a volerci infilare la mano, e so che non devo.",
		"L'argento nel pozzo non riflette nulla di ciò che vedo. Ho alzato gli occhi due volte a cercare cosa rispecchi. Niente.",
	},
	["dar.subzone_enter.w23.temple.018"] = {
		"Nessuno mi ha chiesto silenzio. Chissà perché, è peggio.",
		"Si sentirebbe cadere uno spillo. Il mio, per la precisione. Scusate.",
		"Esiste un modo silenzioso di schiarirsi la gola? Chiedo per un amico.",
	},
	["dar.subzone_enter.w23.temple.019"] = {
		"sale nel Temple of the Moon passando accanto a un nano fermo sulla soglia, con l'elmo fra le mani, l'aria più incerta che si sia mai vista in un tempio.",
		"nota, entrando nel tempio, una pellegrina umana sul bordo della vasca, le mani giunte alla maniera della Luce, e accanto una sacerdotessa che non ci trova niente di strano.",
	},
	["dar.subzone_enter.w23.temple.020"] = {
		"Non saprei dire dove inizi il Temple of the Moon. Il silenzio comincia qualche passo prima della pietra.",
		"Il tempio non chiede niente a chi passa. Per questo mi viene voglia di dargli qualcosa: il capo chino, un passo più lento, un momento.",
	},
	["dar.subzone_enter.w23.trades.001"] = {
		"si sofferma accanto alla bilancia di un mercante, legno intagliato e pesi di pietra levigata, e guarda pesare una manciata di rame con la serietà di una sentenza.",
		"guarda un mercante posare un pesetto di pietra su una bilancia di legno, aspettare che il giogo si fermi, e solo allora dire un prezzo.",
		"si ferma a un banco dove niente si vende a occhio: ogni sacco finisce sulla bilancia, e il mercante fissa il giogo come se potesse mentire.",
	},
	["dar.subzone_enter.w23.trades.002"] = {
		"Un mercante avvolge ogni acquisto in una foglia larga e la lega con un filo d'erba ritorto. Chi compra se ne va reggendolo come un regalo.",
		"Qui perfino i pacchetti crescono: una foglia ripiegata attorno alla merce, uno stelo per spago. Al confronto la carta sembra un po' scortese.",
		"Su questa terrazza nessuno consegna la merce nuda. Tutto parte avvolto in una foglia e annodato, come se una vendita fosse una piccola cortesia.",
	},
	["dar.subzone_enter.w23.trades.003"] = {
		"Su questa terrazza c'è di sicuro un prezzo migliore di quello che sto per accettare.",
		"Tradesmen's Terrace. Dove il mio borsellino viene a imparare l'umiltà.",
		"Ogni banco, qui, è un piccolo agguato cortese.",
	},
	["dar.subzone_enter.w23.trades.004"] = {
		"Una Sentinella una volta mi ha detto che i kaldorei ricordano un debito più a lungo di quanto duri la maggior parte delle nazioni. Su una terrazza piena di registri, mi sembra un avviso da tenere a mente.",
		"Che cos'è un prestito per chi potrebbe vederlo saldato tre generazioni dopo la morte del debitore? Su questa terrazza preferisco non dovere niente a nessuno.",
		"Registri tenuti da gente che c'era, alla Guerra degli Antichi, o i cui maestri c'erano. Ho il sospetto che qui nessun conto si chiuda mai del tutto.",
	},
	["dar.subzone_enter.w23.trades.005"] = {
		"si fa strada oltre un nano e uno gnomo, alla casa d'aste, che continuano a superarsi di un solo rame, con una furia crescente e silenziosissima.",
		"aggira uno gnomo che conta monete in pile ordinate su un muretto, muovendo le labbra, sordo a tutto il resto della terrazza.",
		"sosta ai margini della folla davanti alla casa d'aste, dove un umano legge prezzi da una lista a un nano che non smette di scuotere la testa.",
	},
	["dar.subzone_enter.w23.trades.006"] = {
		"Birra nanica in un banco kaldorei, stoffa di Stormwind su una rastrelliera kaldorei. Le barche che approdano a Rut'theran portano mezzo mondo su per l'albero, cassa dopo cassa.",
		"Metà di quel che si vende qui è salito dalle barche di Rut'theran: lino umano, attrezzi nanici, cianfrusaglie gnomesche. I kaldorei lo vendono con l'aria vaga di chi maneggia una curiosità.",
		"Non tutto, qui, è cresciuto sull'albero. Stoffa umana, ferro nanico, un aggeggio gnomesco che ticchetta: il resto del mondo viene al mercato perfino a Darnassus.",
	},
	["dar.subzone_enter.w23.trades.007"] = {
		"osserva un mercante kaldorei contare il resto due volte, piano, moneta per moneta, e il compratore accettarlo senza controllare nemmeno una volta.",
		"indugia mentre un mercante conta le monete in un palmo che aspetta, ognuna posata con un piccolo scatto, nessuna di fretta.",
		"vede una moneta caduta sulla terrazza restituita da un mercante di passaggio, senza storie, prima ancora che il proprietario se ne accorgesse.",
	},
	["dar.subzone_enter.w23.trades.008"] = {
		"Qui contrattare non serve. Il mercante dice un prezzo una volta sola, poi aspetta, e l'attesa discute al posto suo.",
		"Ogni controfferta che potrei fare qui incontrerebbe lo stesso sguardo calmo, e finirei per pagare comunque il primo prezzo.",
		"I mercanti kaldorei non trattano: aspettano. È la tattica più efficace che conosca, e non c'è niente da fare.",
	},
	["dar.subzone_enter.w23.trades.009"] = {
		"Ogni popolo dell'Alleanza ha una fila o un banco su questa terrazza. Se qualcuno chiede cosa ci tiene uniti, indicherò questo posto: gli acquisti.",
		"La nostra Alleanza vista dalla Tradesmen's Terrace: nani che comprano cuoio elfico, elfi che squadrano ingranaggi gnomeschi, umani che chiedono a tutti il prezzo di tutto.",
	},
	["dar.subzone_enter.w23.trades.010"] = {
		"passa davanti alla banca e vede un banchiere girare una chiave in un cassetto intagliato con entrambe le mani, come si chiude un libro che si vuole conservare.",
		"dà un'occhiata alla banca passando: un banchiere che scrive in un registro con la penna quasi dritta, aggiungendo ogni riga come se la incidesse.",
		"nota quanto sia silenziosa la banca: nessun tintinnio di monete, solo il graffio di una penna e un cassetto che scorre su guide di legno.",
	},
	["dar.subzone_enter.w23.trades.011"] = {
		"Sacche piene, borsellino leggero. Vediamo se questa terrazza riesce a scambiarli.",
		"Troppa roba nelle sacche, troppo poco nel borsellino. Una delle due cose sta per cambiare.",
		"Vediamo cosa mi dà la Tradesmen's Terrace per tutto quanto.",
	},
	["dar.subzone_enter.w23.trades.012"] = {
		"Buio fatto, e la terrazza è affollata come sempre. Ovvio: per i kaldorei è l'ora sensata per comprare e vendere.",
		"Altrove le imposte sarebbero già abbassate. Qui i banchi sono aperti e i mercanti sembrano, semmai, più svegli sotto la luna.",
	},
	["dar.subzone_enter.w23.trades.013"] = {
		"passa lentamente davanti a un banco di cibo: pagnotte chiare, una forma di formaggio venato di blu, ceste di frutta così matura che il profumo arriva sul sentiero per primo.",
		"rallenta a un banco di frutta dove meloni e bacche scure sono impilati in piramidi ordinate che nessuno, a quanto pare, fa mai crollare.",
	},
	["dar.subzone_enter.w23.trades.014"] = {
		"Guardare il banditore, qui, è come guardare un airone che pesca: immobile, poi una nota rapida nel registro, e qualche povera offerta sparisce in un boccone.",
		"Il banditore annota ogni offerta come se l'inchiostro fosse prezioso. Probabilmente lo è. In questa città tutto sembra coltivato, raccolto o atteso a lungo.",
	},
	["dar.subzone_enter.w23.trades.015"] = {
		"Qui tutti si fidano delle bilance, dei registri e gli uni degli altri. Io tengo il cappuccio basso e le monete pronte, e mi sforzo parecchio di sembrare qualcuno del posto.",
		"Un'intera terrazza di monete dell'Alleanza che passano di mano, e io lì in mezzo con i colori sbagliati sotto il mantello. Passo lento. Non comprare niente di memorabile.",
	},
	["dar.subzone_enter.w23.trades.016"] = {
		"L'oro è oro, anche in cima a un albero. Vediamo chi compra.",
		"Mercanti, banchieri, banditori. Tutti pazienti, e tutti a caccia delle mie monete.",
		"Occhio al borsellino. Darnassus è cortese, ma non è gratis.",
	},
	["dar.subzone_enter.w23.trades.017"] = {
		"si fa da parte per una kaldorei che porta una pila di casse più alta della sua testa, così ben bilanciata che nessuna accenna a inclinarsi.",
		"lascia spazio sul sentiero a un carico di sacchi in spalla a qualcuno, posato a un banco quasi senza rumore e presto sollevato più in là.",
	},
	["dar.subzone_enter.w23.trades.018"] = {
		"Che cosa deve ancora comprare un popolo che vive da secoli? A giudicare dalle file: filo, frutta e corde per archi.",
		"Avrei pensato che un popolo così antico possedesse già tutto. E invece eccoli, a comprare filo, frutta e suole nuove per stivali vecchi, come chiunque.",
		"I kaldorei fanno la spesa come tutti: tastano la frutta, aggrottano la fronte al prezzo, la comprano lo stesso. Lo trovo più rassicurante di qualunque tempio.",
	},
	["dar.subzone_enter.w23.warriors.001"] = {
		"osserva una fila di Sentinelle eseguire insieme lo stesso esercizio, voltandosi e avanzando a un ritmo che nessuna pronuncia ad alta voce.",
		"si arresta accanto a un'esercitazione: una dozzina di Sentinelle che avanzano, ruotano e s'inginocchiano come una sola, senza che nessuna voce scandisca il tempo.",
		"si scosta mentre una colonna di Sentinelle passa al piccolo trotto, le armature appena un fruscio, e prende posto sul campo senza che venga dato un ordine.",
	},
	["dar.subzone_enter.w23.warriors.002"] = {
		"Ogni maestro su questa terrazza guarda la mia postura prima della mia faccia. Il giudizio è già dato, e sospetto che la trovi un po' storta.",
		"Basta un'occhiata di un maestro, qui, e sento la mia postura venir corretta da un capo all'altro della terrazza.",
		"Appena metto piede su questa terrazza raddrizzo la schiena. Nessuno me l'ha chiesto. È il posto che ti guarda così.",
	},
	["dar.subzone_enter.w23.warriors.003"] = {
		"sente un ronzio basso che sale sopra la testa e alza gli occhi in tempo per vedere una glaive lanciata tornare in curva nella mano tesa di una Sentinella.",
		"gira al largo da una Sentinella che si esercita con la glaive, il filo che disegna sempre lo stesso cerchio lucente nell'aria accanto a lei.",
		"guarda una glaive lasciare la mano di una Sentinella, descrivere un lungo arco sopra il campo d'addestramento e tornarle in pugno come al guinzaglio.",
	},
	["dar.subzone_enter.w23.warriors.004"] = {
		"Alcune delle Sentinelle che si addestrano qui portano cicatrici fresche. Ashenvale per loro non è una storia: è il posto dove tornano quando l'esercizio finisce.",
		"Non è allenamento per una guerra lontana. I Warsong stanno abbattendo Ashenvale proprio ora, e alcune di queste donne saranno al fronte entro il mese.",
		"L'addestramento, qui, ha un taglio duro. Tutti su questa terrazza conoscono qualcuno che da Ashenvale non è più tornato.",
	},
	["dar.subzone_enter.w23.warriors.005"] = {
		"Che nessuno guardi il mio gioco di gambe. È stata una lunga strada.",
		"Warrior's Terrace. Gomiti dentro, mento su, e cerca di non inciampare davanti alle Sentinelle.",
		"Splendido. Un'intera terrazza di gente che colpisce un bersaglio da più lontano di quanto io riesca a vederlo.",
	},
	["dar.subzone_enter.w23.warriors.006"] = {
		"aggira un grosso felino sdraiato di traverso sul sentiero accanto a un cacciatore che ripara una corda d'arco; il felino apre un occhio, valuta, lo richiude.",
		"rallenta davanti a un orso seduto sulle zampe posteriori ai margini del campo d'addestramento, intento a guardare con pazienza il suo cacciatore che ascolta un maestro.",
		"cede il passo a un gufo appollaiato sulla spalla di un cacciatore, che ruota la testa fino in fondo per {g:seguirlo|seguirla} finché non sparisce.",
	},
	["dar.subzone_enter.w23.warriors.007"] = {
		"Mi dicono che anche i ladri si addestrino su questa terrazza. Continuo a cercarli e trovo soltanto ombre che potrebbero essere solo ombre.",
		"C'è un angolo della Warrior's Terrace dove la gente diventa visibile solo quando decide di parlare. Gli giro alla larga, con rispetto.",
	},
	["dar.subzone_enter.w23.warriors.008"] = {
		"nota che il campo d'addestramento è già consumato in sentieri e conche dove i piedi hanno girato mille volte, per quanto giovane sia la città.",
		"abbassa gli occhi sul pavimento del campo, sbiadito in lunghi archi dove pochi anni di esercizi hanno già lasciato il segno.",
		"passa il pollice lungo un palo d'allenamento già intaccato e scheggiato: una terrazza giovane, un mestiere antico.",
	},
	["dar.subzone_enter.w23.warriors.009"] = {
		"Quasi tutti i campi d'addestramento che conosco suonano come una fucina che rotola giù per le scale. Questo suona come una corda d'arco e qualcuno che pensa.",
		"Neanche un grido su tutta la terrazza. I combattenti qui risparmiano la voce, come se il rumore fosse fatica sprecata.",
		"Ogni esercizio, qui, finisce in silenzio invece che con un applauso. Mi viene voglia di battere le mani, e non oso del tutto.",
	},
	["dar.subzone_enter.w23.warriors.010"] = {
		"passa accanto a un'ufficiale che percorre la fila di un'esercitazione, tirando una cinghia qui, inclinando un elmo là, senza dire nulla a chi è già in ordine.",
		"vede un'ufficiale delle Sentinelle fermarsi davanti a una delle sue, sistemare una fibbia con due dita e proseguire senza una parola né un cipiglio.",
		"guarda un'ufficiale fermare l'esercitazione con una mano alzata; tutta la fila s'immobilizza a metà passo e aspetta, in perfetto equilibrio, che la mano si abbassi.",
	},
	["dar.subzone_enter.w23.warriors.011"] = {
		"In questa città nessuno ha fretta, tranne qui. Buono a sapersi dove la tengono.",
		"Ecco dove Darnassus tiene nascosta la sua fretta.",
	},
	["dar.subzone_enter.w23.warriors.012"] = {
		"Le nostre Sentinelle si addestrano come se Ashenvale fosse la terrazza accanto. Per loro, quasi lo è.",
		"Guardando le Sentinelle allenarsi penso a quanto a lungo hanno vegliato da sole, mentre i druidi dormivano. Dobbiamo loro più di quanto questa terrazza possa contenere.",
	},
	["dar.subzone_enter.w23.warriors.013"] = {
		"Un nano si allena accanto alle Sentinelle, pestando i piedi il doppio e muovendosi con la metà del silenzio. Qui nessuno sembra farci caso. Ecco cos'è un'alleanza.",
		"Umani e nani che si esercitano su una terrazza kaldorei, e maestri kaldorei che li correggono senza ombra di disprezzo. Non molto tempo fa, nessuno di noi ci avrebbe creduto.",
	},
	["dar.subzone_enter.w23.warriors.014"] = {
		"si sofferma presso una rastrelliera di bastoni da allenamento scuriti all'impugnatura, ognuno rimesso esattamente al suo posto quando l'esercizio finisce.",
		"trova una rastrelliera di bastoni d'allenamento, ogni impugnatura scurita dalle mani, ognuno riappeso al suo gancio con una cura che somiglia quasi alla cortesia.",
		"nota i bersagli in fondo al campo, cuciti e ricuciti da qualcuno che evidentemente si rifiuta di sprecare un buon bersaglio.",
	},
	["dar.subzone_enter.w23.warriors.015"] = {
		"Potrei imparare moltissimo solo stando ai margini di questa terrazza a guardare dove le Sentinelle mettono il peso.",
		"La lezione migliore della Warrior's Terrace è gratis: guarda i piedi, mai le mani.",
		"Qui tutti si muovono come se il terreno potesse spostarsi. Visto che è un albero, forse è solo buon senso.",
	},
	["dar.subzone_enter.w23.warriors.016"] = {
		"passa vicino a una Sentinella seduta in disparte, che si fascia un polso dolorante con una striscia di stoffa e i denti, senza staccare gli occhi dall'esercizio.",
		"nota una Sentinella che salta l'esercitazione seduta su un gradino basso, flettendo una mano livida e guardando le altre con evidente impazienza di tornare tra loro.",
		"si attarda accanto a un cacciatore che si massaggia una spalla dolorante con un unguento, facendo smorfie in perfetto silenzio, come si conviene alla Warrior's Terrace.",
	},
	["dar.subzone_enter.w23.warriors.017"] = {
		"Il grande felino di una Sentinella è sdraiato accanto al campo col mento sulle zampe, e segue l'esercitazione con la noia esperta di un veterano.",
		"Perfino i grandi felini delle Sentinelle sembrano prendere appunti dal bordo del campo. Uno ha appena sbadigliato davanti alla mia postura.",
	},
	["dar.subzone_enter.w23.warriors.018"] = {
		"Se devo prendere una lezione d'umiltà su questa terrazza, tanto vale prenderla da esperti.",
		"D'accordo. Spalle indietro. Le Sentinelle guardano, e anche il mio orgoglio.",
	},
	["dar.weather_change.w23.fairsky.001"] = {
		"alza gli occhi mentre la coltre di nubi sopra la chioma si sfilaccia, e ogni varco tra le foglie si riempie di cielo aperto e pulito.",
		"nota i varchi nella volta di foglie farsi più netti, ora che le nuvole si rompono e scivolano via verso il mare.",
		"solleva lo sguardo a un'improvvisa nitidezza: sopra Teldrassil le nubi si sono strappate, e il cielo filtra tra le foglie a ritagli limpidi.",
	},
	["dar.weather_change.w23.fairsky.002"] = {
		"Le nuvole se ne sono andate, ma l'albero non se n'è accorto. Dalle foglie scivola acqua ancora a lungo, come se la chioma finisse un discorso.",
		"Sereno lassù, e quaggiù gocciola ancora. Qui il tempo cambia prima in cima, e le foglie si adeguano quando ne hanno voglia.",
		"Il cielo si è aperto da un pezzo. Teldrassil si scrolla di dosso l'ultimo umido foglia per foglia, senza alcuna fretta.",
	},
	["dar.weather_change.w23.fairsky.003"] = {
		"Niente più nuvole. Non l'avrei nemmeno notato, se un elfo non avesse alzato gli occhi con un sorriso.",
		"Cielo sgombro lassù, così dicono. Da sotto queste foglie, mi fido della parola dell'albero.",
		"Si è rimesso al bello. Sopra tutto questo fogliame, immagino.",
	},
	["dar.weather_change.w23.fairsky.004"] = {
		"osserva un artigiano ripiegare il telo cerato sopra il banco da lavoro, ora che le nubi sono passate, lisciandolo con gesti lunghi e pazienti.",
		"vede un elfo togliere la copertura cerata da un tavolo di merci appena il cielo si schiarisce, scuoterla una volta e piegarla in un quadrato preciso.",
		"si accorge dei teli che si sollevano da bancarelle e banchi da lavoro uno dopo l'altro, mentre il tempo si rasserena: come se la città aprisse le mani.",
	},
	["dar.weather_change.w23.fairsky.005"] = {
		"Senza nuvole, un varco tra le foglie mostra quanto cielo vuoto stia sopra questa città. È molto in alto, e oltre ce n'è ancora.",
		"Il sereno rende evidente l'altezza. Da uno strappo nella chioma non si vede nulla, sopra, e quel nulla continua a lungo.",
		"Tra le foglie ora solo cielo aperto, e quanto. Sotto la chioma ci si dimentica di quanto questa città stia vicina alla cima di tutto.",
	},
	["dar.weather_change.w23.fairsky.006"] = {
		"sente gli uccelletti della chioma riprendere a cantare mentre il cielo si sgombra, una dozzina di vocine sottili che saggiano l'aria.",
		"coglie un frullo tra i rami alti: gli uccelli rimasti zitti sotto le nubi si muovono e si scuotono le ali.",
		"si ferma mentre qualcosa d'alato si stacca da un ramo alto, compie un giro nell'aria tornata limpida e si riposa, soddisfatto.",
	},
	["dar.weather_change.w23.fairsky.007"] = {
		"Ho tirato giù il cappuccio appena il cielo si è aperto, e una goccia gelata mi è scivolata nel colletto da una foglia rimasta indietro.",
		"Cappuccio giù, nuvole sparite, e l'albero ha tenuto da parte un'ultima goccia per la mia nuca. Una città con il senso dell'umorismo.",
		"Ho abbassato il cappuccio appena si è rasserenato. La chioma se n'è accorta, ha preso la mira e non ha sbagliato.",
	},
	["dar.weather_change.w23.fairsky.008"] = {
		"scorge una sacerdotessa di Elune fermarsi sul sentiero mentre le nubi si aprono sopra la chioma, alzare il viso e mormorare qualcosa a voce troppo bassa per coglierla.",
		"nota due sacerdotesse fermarsi a guardare in alto mentre la coltre si rompe, come per accertarsi che qualcosa a cui tengono sia ancora al suo posto.",
		"segue con lo sguardo un'anziana sacerdotessa che solleva una mano aperta verso il cielo rasserenato, poi l'abbassa e riprende il cammino come niente fosse.",
	},
	["dar.weather_change.w23.fairsky.009"] = {
		"Ora che le nubi sono andate, la pietra chiara dei sentieri si asciuga dai bordi verso il centro, e le chiazze scure si ritirano come inchiostro che torna nel calamaio.",
		"Il tempo si apre, e la pietra bianca delle terrazze si asciuga a isole. Fra poco non resterà traccia di umido.",
		"Le nuvole sono passate, e la pietra sotto i piedi lascia andare l'umido a macchie pallide e lente. Darnassus si rimette in ordine senza che nessuno muova un dito.",
	},
	["dar.weather_change.w23.fairsky.010"] = {
		"Ecco. Le nuvole hanno mollato la presa sulla chioma.",
		"Bel tempo lassù. Bene: quando avrò attraversato la città, i sentieri saranno asciutti.",
		"Cielo sgombro su Teldrassil. Persino l'albero sembra contento.",
	},
	["dar.weather_change.w23.fairsky.011"] = {
		"Le nubi si rompono e il sole si mette dietro le grandi foglie. Illuminata così, ognuna mostra le venature, verde su verde, come una mappa di fiumi.",
		"Il sole dall'altra parte della chioma trasforma le foglie in vetrate, verdi e dorate, ogni nervatura netta come tracciata a inchiostro.",
		"Luce aperta sopra la chioma. Le foglie brillano da dietro, e le loro ombre sul sentiero hanno di nuovo dei contorni.",
	},
	["dar.weather_change.w23.fairsky.012"] = {
		"si ferma dove le nubi si sono aperte sopra la chioma, e trova le ombre delle foglie stampate nitide sul sentiero, orlate d'argento dalla luna.",
		"vede le nuvole scivolare via dalla luna sopra la chioma, e d'un tratto la terrazza si riempie di ombre che un attimo prima non aveva.",
	},
	["dar.weather_change.w23.fairsky.013"] = {
		"Un'elfa sul ponte ha riposto il mantello parecchio prima che le nubi si aprissero. O legge il cielo attraverso tutte quelle foglie, o glielo dice l'albero.",
		"Qualcuno qui sapeva che si sarebbe rasserenato. Ho visto un druido posare una ciotola di semi su un muretto ben prima che lassù si aprisse il primo varco.",
		"I kaldorei erano pronti al sereno prima che arrivasse. Ho smesso di chiedere come: qui le risposte sono sempre più lunghe delle domande.",
	},
	["dar.weather_change.w23.fairsky.014"] = {
		"Il cielo è limpido. Qualcuno lo dica al muschio: fa ancora finta di essere zuppo.",
		"Finalmente bel tempo. Io e il mio mantello ci asciughiamo con la dignitosa lentezza dei kaldorei.",
	},
	["dar.weather_change.w23.mist.001"] = {
		"osserva la nebbia salire in spire lente da un punto molto più in basso della città, insinuarsi tra i rami e farli finire, i più vicini, nel bianco.",
		"vede pallidi sbuffi di foschia risalire fra le terrazze, freschi e lenti, con un vago odore del mare che li ha mandati.",
		"resta sul bordo di una terrazza mentre la nebbia sale da sotto, e i grandi rami dell'albero svaniscono uno a uno come navi che lasciano il porto.",
	},
	["dar.weather_change.w23.mist.002"] = {
		"La foschia si posa su tutto in perline minute: le maniche, le ringhiere, una ragnatela tesa fra due foglie come la vetrina di un gioielliere.",
		"La nebbia non cade, arriva e basta. Un momento prima il mantello era asciutto, quello dopo ogni suo filo porta appesa una gocciolina.",
		"Sulla ringhiera accanto a me c'è una ragnatela, e la nebbia ha appeso una perla a ogni filo. Nessuno qui si sognerebbe di spazzarla via.",
	},
	["dar.weather_change.w23.mist.003"] = {
		"Nebbia. Le Sentinelle mi vedranno molto prima che io veda loro. Non che di solito vada diversamente.",
		"Sale la foschia. Parlate pure, chiunque siate: vedo solo i vostri stivali.",
	},
	["dar.weather_change.w23.mist.004"] = {
		"osserva la nebbia sul lago prendere il primo colore dell'alba, un rosa tenue che sembra nascere da dentro più che dal cielo.",
		"vede l'alba arrivare come un lento schiarirsi della foschia, senza un punto di luce da nessuna parte, come se fosse tutta la nebbia a svegliarsi.",
		"resta in una nebbia dell'alba così morbida che le rive del lago, i sentieri e le sale chiare si confondono in un unico chiarore tenue.",
	},
	["dar.weather_change.w23.mist.005"] = {
		"Con la nebbia sotto e intorno, la città sembra sciolta dagli ormeggi, una zattera di muschio e pietra chiara alla deriva sulle nuvole. Quasi mi aspetto di sentirla dondolare.",
		"La foschia ha nascosto tutto ciò che sta sotto le terrazze. Per quel che vedo, Darnassus galleggia, e niente la regge.",
		"So che laggiù ci sono il tronco, le radici e il mare. Con questa nebbia, avrei bisogno che qualcuno me lo ricordasse.",
	},
	["dar.weather_change.w23.mist.006"] = {
		"sente due Sentinelle, in un punto imprecisato della nebbia, scambiarsi un richiamo basso e breve, una per lato del sentiero, poi più nulla.",
		"passa accanto a una Sentinella ferma sul limite della foschia, la testa inclinata: ascolta più che guardare, la glaive piantata accanto a sé.",
	},
	["dar.weather_change.w23.shower.001"] = {
		"ode la pioggia arrivare molto prima che tocchi terra: un fruscio lieve che si allarga sulla chioma, mentre il sentiero, sotto, resta chiaro ancora un poco.",
		"alza la testa a un brusio che passa sulla volta di foglie come una folla che mormora: la pioggia ha raggiunto la cima dell'albero, e col resto se la prende comoda.",
		"coglie il primo suono della pioggia tra le foglie alte e conta, per passatempo, quanto ci mette la prima goccia a trovare la pietra ai suoi piedi.",
	},
	["dar.weather_change.w23.shower.002"] = {
		"Pioggia su una città che è già mezza acqua. I ruscelli si fanno un po' più rumorosi, e questo è tutto ciò che si nota.",
		"Piove, credo. Difficile dirlo, a Darnassus: tutto scorreva, colava e schizzava già da prima.",
		"Pioggia, in un posto costruito attorno a vasche e cascate. È come versare una tazza nel lago e chiamarla una novità.",
	},
	["dar.weather_change.w23.shower.003"] = {
		"vede un grosso felino sdraiato accanto al sentiero appiattire le orecchie alle prime gocce, alzarsi con immensa dignità e trasferirsi sotto un arco.",
		"osserva il grande felino di una Sentinella scrollarsi di dosso uno spruzzo di pioggia e fissare il cielo come se l'avesse offeso di persona.",
		"nota un gatto striato acciambellato su un muretto infilare il muso sotto la coda quando arriva la pioggia, e rifiutarsi di muoversi di un pollice in più.",
	},
	["dar.weather_change.w23.shower.004"] = {
		"Il muschio sui muri si scurisce mentre la pioggia lo impregna, e per una volta sembra meno un ornamento e più una cosa viva che ha sete.",
		"Piove, e i fiori lungo il sentiero si chiudono uno dopo l'altro, ripiegando i petali con l'ordine di un mercante che abbassa la tenda.",
		"Almeno a qualcosa la pioggia serve: il muschio si gonfia, le felci si rialzano, e tutto il bordo verde del sentiero pare sporgersi verso il cielo.",
	},
	["dar.weather_change.w23.shower.005"] = {
		"Piove dentro un albero. Non credo che debba funzionare così.",
		"Ma certo che piove, quassù. Una città così alta, speravo stesse sopra il tempo.",
		"Pioggia sulla cima di un albero. Da qualche parte un nano se la ride.",
	},
	["dar.weather_change.w23.shower.006"] = {
		"trova una sacerdotessa che posa su un muretto una ciotola d'argento bassa per raccogliere la pioggia, e poi siede lì accanto a mani giunte, in attesa che si riempia.",
		"passa accanto a una sacerdotessa a capo scoperto sotto la pioggia, occhi chiusi, che se la lascia scorrere sul viso come una cosa chiesta e finalmente avuta.",
		"si attarda mentre due novizie del tempio portano un bacile coperto sotto la pioggia e ne sollevano il coperchio, senza scambiarsi una parola.",
	},
	["dar.weather_change.w23.shower.007"] = {
		"Strano: con la pioggia mi sento meno fuori posto. Sotto quel picchiettio i miei stivali e la mia voce goffa spiccano meno.",
		"Con la pioggia che batte su tutto posso finalmente camminare al mio passo, senza sentire che ogni elfo sul sentiero lo ascolta.",
		"La pioggia è il primo rumore di Darnassus più forte di me. Le devo un favore.",
	},
	["dar.weather_change.w23.shower.008"] = {
		"nota la pioggia scivolare da un tetto ricurvo in un canale di pietra scolpito come la nervatura di una foglia, e da lì, ordinata, nel ruscello più vicino.",
		"segue un rivolo d'acqua piovana lungo il bordo del sentiero e lo trova raccolto in una canaletta incisa nella pietra, come se la città se lo aspettasse da sempre.",
		"guarda la pioggia scendere dalle gronde in tende sottili e regolari, e capisce che i tetti sono stati sagomati proprio per questo.",
	},
	["dar.weather_change.w23.shower.009"] = {
		"Ogni goccia che mi manca ha ancora un lungo viaggio da fare: giù di foglia in foglia, lungo il tronco, fino al mare. Non la invidio.",
		"Quassù la pioggia è solo all'inizio del suo cammino. Molto più in basso sta ancora cadendo lungo la corteccia, verso le onde.",
		"Penso alla pioggia che prosegue oltre la città, giù per un tronco troppo alto da immaginare, fino a tornare nel mare da cui è venuta.",
	},
	["dar.weather_change.w23.shower.010"] = {
		"Sotto quest'arco c'è posto per un altro, se le gocce non ti danno fastidio.",
		"Vieni al riparo dalla pioggia. Be', da quasi tutta.",
		"C'è foglia per tutti. Mettiti sotto prima di inzupparti.",
	},
	["dar.weather_change.w23.shower.011"] = {
		"vede uno gnomo trotterellare lungo il sentiero sotto un'enorme foglia tenuta alta come un parasole, asciuttissimo e molto fiero di sé.",
		"scorge un nano sotto un arco gocciolante che borbotta contro la pioggia nella sua lingua, mentre accanto a lui un kaldorei sembra ascoltarla con piacere.",
		"nota un visitatore umano che strizza una manica in riva all'acqua, e l'elfo accanto che con garbo finge di non vedere.",
	},
	["dar.weather_change.w23.shower.012"] = {
		"Sotto la pioggia ogni lampada lungo il sentiero porta un piccolo alone, viola e morbido, e le gocce che lo attraversano sembrano scintille che hanno scordato di bruciare.",
		"La pioggia sfuma le lampade della città in cerchi viola. Camminarci in mezzo è come attraversare il sogno di qualcun altro.",
		"Ogni lampada che supero ha la pioggia che le cade nel bagliore, un velo sottile e chiaro che si muove quando nient'altro si muove.",
	},
	["dar.weather_change.w23.tempest.001"] = {
		"alza gli occhi mentre un lampo divampa sopra la chioma, e per un istante bianco ogni foglia si stampa nera contro il cielo.",
		"vede la volta di foglie accesa dall'alto da un bagliore: tutto l'immenso intreccio dei rami si staglia netto, poi torna nel buio.",
		"sussulta a un lampo alto sopra l'albero; in quell'attimo i rami in alto mostrano ogni nodo e ogni biforcazione, come un disegno tracciato in fretta.",
	},
	["dar.weather_change.w23.tempest.002"] = {
		"Un temporale, e io sto in cima all'albero più alto del mondo. Tutto quello che ho mai imparato sui fulmini mi grida nelle orecchie, tutto insieme.",
		"I fulmini amano le cose alte. Cerco di non pensare a quanto sia alta la cosa che ho sotto gli stivali.",
		"Tuona lassù, e i kaldorei restano calmi. O i druidi hanno un accordo col cielo, o qui nessuno ha fatto due conti.",
	},
	["dar.weather_change.w23.tempest.003"] = {
		"Quello ha fatto tremare il ponte. Splendido. Io sto qui, vicino a qualcosa di basso.",
		"Tuoni sulla chioma. Mi dicono che l'albero è già stato colpito senza accorgersene. Io me ne accorgerei.",
	},
	["dar.weather_change.w23.tempest.004"] = {
		"nota che gli ippogrifi che volteggiano sopra la chioma sono spariti tutti all'arrivo del tuono, e il cielo sopra le foglie è rimasto alla tempesta.",
		"vede una civetta scendere da un ramo scoperto in una cavità della corteccia al primo lungo brontolio del tuono, e affacciarsi da lì con aria di grande disapprovazione.",
		"osserva due falene, spinte in basso dalla tempesta, posarsi su una lampada e restarvi aggrappate a ogni rombo di tuono.",
	},
	["dar.weather_change.w23.tempest.005"] = {
		"Una druida accanto a me ha ascoltato il tuono a occhi chiusi, come un guaritore al capezzale. Quando gliel'ho chiesto, ha detto solo che l'albero è giovane per affrontare le tempeste.",
		"Qualche druido qui dice che il temporale è il modo in cui il cielo mette alla prova un albero nuovo. Non dicono che cosa capita a quelli che non la superano.",
		"I più anziani dell'Enclave, mi dicono, contano i tuoni su Teldrassil come altri contano i giorni di una febbre. A cosa serva il conto, nessuno me lo spiega.",
	},
	["dar.weather_change.w23.tempest.006"] = {
		"nota una Sentinella che si ferma a metà passo a uno schianto di tuono, lancia un'occhiata al cielo come un ufficiale che annota un ritardatario, e riprende il giro.",
		"scorge le Sentinelle lungo la terrazza alzare la testa tutte insieme a un lungo rombo, poi riabbassarla insieme, come d'accordo che non meritasse altro.",
	},
]==])
